INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51774, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物や人を、ある場所にどのように置いたり、並べたりするかという、そのときの位置や並べ方の計画。", "primary_collocate": null, "pronunciation": "はいち", "ipa": "haitɕi", "syllable_count": 3, "sentences": [{"text": "これは、日照や風通しなどの環境データを変数としてアルゴリズムに入力し、最適な街区配置を自動的に生成する手法です。", "target_word": "配置", "complexity_tier": "T4", "furigana": "これは、日照[にっしょう]や風通[かぜとお]しなどの環境[かんきょう]データを変数[へんすう]としてアルゴリズムに入力[にゅうりょく]し、最適[さいてき]な街区配置[がいくはいち]を自動的[じどうてき]に生成[せいせい]する手法[しゅほう]です。", "sentence_source": "mined"}, {"text": "部屋の家具の配置を変えたら、ずっと広く見えるようになった。", "target_word": "配置", "complexity_tier": "T2", "furigana": "部屋[へや]の家具[かぐ]の配置[はいち]を変[か]えたら、ずっと広[ひろ]く見[み]えるようになった。", "sentence_source": "generated"}, {"text": "試合の前に、監督は選手の配置を細かく決めた。", "target_word": "配置", "complexity_tier": "T3", "furigana": "試合[しあい]の前[まえ]に、監督[かんとく]は選手[せんしゅ]の配置[はいち]を細[こま]かく決[き]めた。", "sentence_source": "generated"}, {"text": "店内の商品の配置が分かりにくく、客が目当ての物を探せなかった。", "target_word": "配置", "complexity_tier": "T3", "furigana": "店内[てんない]の商品[しょうひん]の配置[はいち]が分[わ]かりにくく、客[きゃく]が目当[めあ]ての物[もの]を探[さが]せなかった。", "sentence_source": "generated"}, {"text": "この図は、非常口と消火器の配置を示しています。", "target_word": "配置", "complexity_tier": "T3", "furigana": "この図[ず]は、非常口[ひじょうぐち]と消火器[しょうかき]の配置[はいち]を示[しめ]しています。", "sentence_source": "generated"}, {"text": "新しい部署への配置が決まり、来月から大阪で働く。", "target_word": "配置", "complexity_tier": "T3", "furigana": "新[あたら]しい部署[ぶしょ]への配置[はいち]が決[き]まり、来月[らいげつ]から大阪[おおさか]で働[はたら]く。", "sentence_source": "generated"}, {"text": "机の配置を工夫して、先生が全員の顔を見られるようにした。", "target_word": "配置", "complexity_tier": "T3", "furigana": "机[つくえ]の配置[はいち]を工夫[くふう]して、先生[せんせい]が全員[ぜんいん]の顔[かお]を見[み]られるようにした。", "sentence_source": "generated"}, {"text": "庭の木の配置は、景色の美しさを考えて決められている。", "target_word": "配置", "complexity_tier": "T3", "furigana": "庭[にわ]の木[き]の配置[はいち]は、景色[けしき]の美[うつく]しさを考[かんが]えて決[き]められている。", "sentence_source": "generated"}, {"text": "警備員の配置が偏っていたため、会場の入口だけが混雑した。", "target_word": "配置", "complexity_tier": "T4", "furigana": "警備員[けいびいん]の配置[はいち]が偏[かたよ]っていたため、会場[かいじょう]の入口[いりぐち]だけが混雑[こんざつ]した。", "sentence_source": "generated"}, {"text": "駅のホームでは、ベンチの配置によって人の流れが変わる。", "target_word": "配置", "complexity_tier": "T3", "furigana": "駅[えき]のホームでは、ベンチの配置[はいち]によって人[ひと]の流[なが]れが変[か]わる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "配置", "label": "基本形"}, {"form": "配置する", "label": "サ変動詞"}, {"form": "配置した", "label": "過去形"}, {"form": "配置される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "配置:物や人を場所ごとにどう置き並べるかという位置や並べ方の計画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3fc8dda-ecbc-44cb-ad7d-8ba49e39de78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51774, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配置", "is_correct": true, "explanation": "街区の建物や道路を場所ごとに並べる計画を指すので、「街区〜を生成」に合う。"}, {"text": "配線", "is_correct": false, "explanation": "電気の線を通す意味で、街区の並べ方の計画には合わない。"}, {"text": "配膳", "is_correct": false, "explanation": "料理を各席に配る意味で、街区の計画には当てはまらない。"}, {"text": "配送", "is_correct": false, "explanation": "荷物を届ける意味で、場所に並べる計画を表さない。"}], "explanations": {"配置": "街区の建物や道路を場所ごとに並べる計画を指すので、「街区〜を生成」に合う。", "配線": "電気の線を通す意味で、街区の並べ方の計画には合わない。", "配膳": "料理を各席に配る意味で、街区の計画には当てはまらない。", "配送": "荷物を届ける意味で、場所に並べる計画を表さない。"}, "sentence_index": 0, "correct_answer": "配置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は相手の気持ちへの配置が足りず、場の空気を読めなかった。", "explanation": "〈配慮〉の意味。相手を思いやる気持ちには使わず、配置は物や人を場所に置く計画を指す。"}, {"text": "毎朝、新聞を各家庭に配置している。", "explanation": "〈配達〉の意味。品物を家に届ける意味で、配置は場所に物や人を置く計画を指すので合わない。"}, {"text": "テストの配置は、各問十点だ。", "explanation": "〈配点〉の意味。問題ごとの点数の割り振りで、配置は場所の並べ方なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51774, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配置", "is_correct": true, "explanation": "机をどこに置き、どう並べるかという計画を指すので、「机の〜を工夫」に合う。"}, {"text": "配車", "is_correct": false, "explanation": "車両を配置する意味で、机の並べ方には当てはまらない。"}, {"text": "配布", "is_correct": false, "explanation": "資料などを配って渡す意味で、机の並べ方を表さない。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届ける意味で、机を並べる工夫とは関係しない。"}], "explanations": {"配置": "机をどこに置き、どう並べるかという計画を指すので、「机の〜を工夫」に合う。", "配車": "車両を配置する意味で、机の並べ方には当てはまらない。", "配布": "資料などを配って渡す意味で、机の並べ方を表さない。", "配達": "品物を届ける意味で、机を並べる工夫とは関係しない。"}, "sentence_index": 6, "correct_answer": "配置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社は利益を株主に配置した。", "explanation": "〈配当〉の意味。利益を分けて渡す意味で、物を場所に置く計画の配置とは違う。"}, {"text": "この映画の配置は豪華だ。", "explanation": "〈配役〉の意味。出演者の役割を決める意味で、配置は場所に置く計画を指す。"}, {"text": "会場の入口で、来場者にチラシを一人ずつ配置した。", "explanation": "〈配布〉の意味。ものを広く人に渡す意味で、配置は場所に物を置く計画を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51774, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家具の配置の決めるのは難しい。", "corrected_sentence": "家具の配置を決めるのは難しい。", "error_description": "「配置の」は名詞に付く「の」で、動詞「決める」の目的語には「を」が必要。正しくは「配置を決める」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51774, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "椅子を窓際を配置する。", "corrected_sentence": "椅子を窓際に配置する。", "error_description": "「窓際を」は場所を示す「に」にすべきで、「を」が二つ重なって不自然。正しくは「椅子を窓際に配置する」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af8028b9-294e-4771-9648-4e7777551926') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51775, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "〈画用は〉の〈は〉で、話題の「画用」を主題として示す。正解。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示すが、ここは話題を立てる文なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は場所や相手を示す格で、主題を述べる文には合わない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示す格で、ここでは合わない。"}], "correct_answer": "は", "explanations": {"は": "〈画用は〉の〈は〉で、話題の「画用」を主題として示す。正解。", "を": "〈を〉は目的語を示すが、ここは話題を立てる文なので合わない。", "に": "〈に〉は場所や相手を示す格で、主題を述べる文には合わない。", "で": "〈で〉は手段や場所を示す格で、ここでは合わない。"}, "error_tags": {"を": "目的語の格で、話題の「画用」には付かない", "に": "場所や相手を示す格で、ここでは合わない", "で": "手段や場所を示す格で、ここでは合わない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51775, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈画用を小さく切って〉の〈を〉で、切る動作の対象を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示すので、切る対象の画用は表せない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は方向や相手を示すので、切る対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す格で、切る対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "〈画用を小さく切って〉の〈を〉で、切る動作の対象を示す。正解。", "が": "〈が〉は主語を示すので、切る対象の画用は表せない。", "に": "〈に〉は方向や相手を示すので、切る対象を表せない。", "へ": "〈へ〉は方向を示す格で、切る対象にはならない。"}, "error_tags": {"が": "主語を示す格で、切る対象にはならない", "に": "切る対象を示す格ではない", "へ": "方向を示す格で、ここでは合わない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51775, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "絵をかいたりするための、白い紙のことです。", "primary_collocate": null, "pronunciation": "がよう", "ipa": "ɡajoː", "syllable_count": 3, "sentences": [{"text": "美術の時間に使うので、画用を十枚買ってきた。", "target_word": "画用", "complexity_tier": "T3", "furigana": "美術[びじゅつ]の時間[じかん]に使[つか]うので、画用[がよう]を十枚[じゅうまい]買[か]ってきた。", "sentence_source": "generated"}, {"text": "画用は表面が少しざらざらしていて、絵の具がのりやすい。", "target_word": "画用", "complexity_tier": "T4", "furigana": "画用[がよう]は表面[ひょうめん]が少[すこ]しざらざらしていて、絵[え]の具[ぐ]がのりやすい。", "sentence_source": "generated"}, {"text": "文房具店で、白くて厚い画用を選んだ。", "target_word": "画用", "complexity_tier": "T3", "furigana": "文房具店[ぶんぼうぐてん]で、白[しろ]くて厚[あつ]い画用[がよう]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "画用の上に、鉛筆で下書きをした。", "target_word": "画用", "complexity_tier": "T3", "furigana": "画用[がよう]の上[うえ]に、鉛筆[えんぴつ]で下書[したが]きをした。", "sentence_source": "generated"}, {"text": "水彩画には、水に強い画用が向いている。", "target_word": "画用", "complexity_tier": "T4", "furigana": "水彩画[すいさいが]には、水[みず]に強[つよ]い画用[がよう]が向[む]いている。", "sentence_source": "generated"}, {"text": "画用が足りなくなったので、店にもう一度行った。", "target_word": "画用", "complexity_tier": "T3", "furigana": "画用[がよう]が足[た]りなくなったので、店[みせ]にもう一度[いちど]行[い]った。", "sentence_source": "generated"}, {"text": "兄は画用を丸めて、リュックの横に入れた。", "target_word": "画用", "complexity_tier": "T3", "furigana": "兄[あに]は画用[がよう]を丸[まる]めて、リュックの横[よこ]に入[い]れた。", "sentence_source": "generated"}, {"text": "画用を小さく切って、友達にカードを作った。", "target_word": "画用", "complexity_tier": "T3", "furigana": "画用[がよう]を小[ちい]さく切[き]って、友達[ともだち]にカードを作[つく]った。", "sentence_source": "generated"}, {"text": "この画用は大きいから、教室の壁に貼る絵にちょうどいい。", "target_word": "画用", "complexity_tier": "T3", "furigana": "この画用[がよう]は大[おお]きいから、教室[きょうしつ]の壁[かべ]に貼[は]る絵[え]にちょうどいい。", "sentence_source": "generated"}, {"text": "雨にぬれると、画用がふにゃふにゃになってしまう。", "target_word": "画用", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれると、画用[がよう]がふにゃふにゃになってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "画用", "label": "基本形"}, {"form": "画用を", "label": "を格"}, {"form": "画用に", "label": "に格"}], "register": "colloquial", "sense_fingerprint": "絵を描くための白い厚手の紙(画用紙の略)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: ざらざら (Zipf 2.37)','sentence 9 above tier T2: contains vocabulary far above tier T2: ぬれる (Zipf 1.65), ふにゃふにゃ (Zipf 2.46)']::text[], '0b8c837d-2fe6-4e39-ac26-de108440b430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51775, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "画用", "is_correct": true, "explanation": "枚で数える薄い紙で、美術の時間に使う用紙として自然に入る。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は本で数えるので、「十枚」とは合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は冊で数えるので、「十枚」とは合わない。"}, {"text": "絵の具", "is_correct": false, "explanation": "絵の具は箱や本で数えるので、「十枚」とは合わない。"}], "explanations": {"画用": "枚で数える薄い紙で、美術の時間に使う用紙として自然に入る。", "鉛筆": "鉛筆は本で数えるので、「十枚」とは合わない。", "辞書": "辞書は冊で数えるので、「十枚」とは合わない。", "絵の具": "絵の具は箱や本で数えるので、「十枚」とは合わない。"}, "sentence_index": 0, "correct_answer": "画用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの画用は、有名な美術館で、毎日お客さんに道を教えている。", "explanation": "ここは〈案内係〉の意味。道を教えるのは人で、画用は紙なので合わない。"}, {"text": "牛乳は画用に入れて届けられる。", "explanation": "ここは〈瓶〉の意味。牛乳を入れて届けるのは瓶で、画用は絵をかく紙なので合わない。"}, {"text": "画用の時間に、粘土で人形を作った。", "explanation": "ここは〈図画〉の意味。授業の名前として「図画の時間」と言い、画用は紙を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51775, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "画用", "is_correct": true, "explanation": "丸めて入れられる薄い紙で、リュックに入れる文脈に合う。"}, {"text": "財布", "is_correct": false, "explanation": "財布は丸めて入れる物ではなく、丸めるという動作と合わない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は丸めてリュックに入れる物ではなく、文脈に合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は丸めると傷むので、丸めて入れる物として不自然。"}], "explanations": {"画用": "丸めて入れられる薄い紙で、リュックに入れる文脈に合う。", "財布": "財布は丸めて入れる物ではなく、丸めるという動作と合わない。", "座布団": "座布団は丸めてリュックに入れる物ではなく、文脈に合わない。", "教科書": "教科書は丸めると傷むので、丸めて入れる物として不自然。"}, "sentence_index": 6, "correct_answer": "画用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妹は一日中、部屋で画用をしている。", "explanation": "ここは〈絵書き〉の意味（描く行為）。画用は紙のことなので、「画用をする」とは言わない。"}, {"text": "雨の日は、画用をはいて出かけた。", "explanation": "ここは〈長靴〉の意味。足にはくのは長靴で、画用は紙なので合わない。"}, {"text": "雨が降ってきたので、画用をさした。", "explanation": "ここは〈傘〉の意味。雨の日にさすのは傘で、画用は絵をかく紙なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51775, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "図工の授業で使うので、画用が五枚買ってきた。", "corrected_sentence": "図工の授業で使うので、画用を五枚買ってきた。", "error_description": "「買ってきた」の対象である画用は目的語なので「を」が必要。「が」は主語を示すため、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51775, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友達の誕生日に、画用へ小さく切って、カードを作った。", "corrected_sentence": "友達の誕生日に、画用を小さく切って、カードを作った。", "error_description": "「切る」の対象である画用は目的語なので「を」が必要。「へ」は方向を示す格で、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51779, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "長い", "is_correct": true, "explanation": "長さの反対語。国語辞典で対義語として挙げられる。"}, {"text": "高い", "is_correct": false, "explanation": "高さを表す語で、長さの反対語ではない。"}, {"text": "太い", "is_correct": false, "explanation": "太さを表す語で、長さの反対語ではない。"}, {"text": "重い", "is_correct": false, "explanation": "重さを表す語で、長さの反対語ではない。"}], "correct_answer": "長い", "explanations": {"長い": "長さの反対語。国語辞典で対義語として挙げられる。", "高い": "高さを表す語で、長さの反対語ではない。", "太い": "太さを表す語で、長さの反対語ではない。", "重い": "重さを表す語で、長さの反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51779, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "長い", "is_correct": true, "explanation": "長さの反対語。定義上この意味の対義語として挙げられる。"}, {"text": "厚い", "is_correct": false, "explanation": "厚さを表す語で、長さの反対語ではない。"}, {"text": "広い", "is_correct": false, "explanation": "面積の大きさを表す語で、長さの反対語ではない。"}, {"text": "深い", "is_correct": false, "explanation": "深さを表す語で、長さの反対語ではない。"}], "correct_answer": "長い", "explanations": {"長い": "長さの反対語。定義上この意味の対義語として挙げられる。", "厚い": "厚さを表す語で、長さの反対語ではない。", "広い": "面積の大きさを表す語で、長さの反対語ではない。", "深い": "深さを表す語で、長さの反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51779, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "短いというのは、ものの長さが小さいことです。", "primary_collocate": null, "pronunciation": "みじかい", "ipa": "midʑikai", "syllable_count": 4, "sentences": [{"text": "このひもは短いので、箱に結べません。", "target_word": "短い", "complexity_tier": "T3", "furigana": "このひもは短[みじか]いので、箱[はこ]に結[むす]べません。", "sentence_source": "generated"}, {"text": "弟の腕は短くて、棚の上に手が届かない。", "target_word": "短く", "complexity_tier": "T3", "furigana": "弟[おとうと]の腕[うで]は短[みじか]くて、棚[たな]の上[うえ]に手[て]が届[とど]かない。", "sentence_source": "generated"}, {"text": "兄は髪が短く、いつも帽子をかぶっている。", "target_word": "短く", "complexity_tier": "T3", "furigana": "兄[あに]は髪[かみ]が短[みじか]く、いつも帽子[ぼうし]をかぶっている。", "sentence_source": "generated"}, {"text": "短い鉛筆を、ペン立てに入れた。", "target_word": "短い", "complexity_tier": "T2", "furigana": "短[みじか]い鉛筆[えんぴつ]を、ペン立[た]てに入[い]れた。", "sentence_source": "generated"}, {"text": "この定規は十センチしかなく、短い。", "target_word": "短い", "complexity_tier": "T3", "furigana": "この定規[じょうぎ]は十[じゅう]センチしかなく、短[みじか]い。", "sentence_source": "generated"}, {"text": "ズボンが短くなったので、新しいものを買った。", "target_word": "短く", "complexity_tier": "T3", "furigana": "ズボンが短[みじか]くなったので、新[あたら]しいものを買[か]った。", "sentence_source": "generated"}, {"text": "犬のしっぽが短くて、振っても目立たない。", "target_word": "短く", "complexity_tier": "T4", "furigana": "犬[いぬ]のしっぽが短[みじか]くて、振[ふ]っても目立[めだ]たない。", "sentence_source": "generated"}, {"text": "短い橋を渡ると、目の前に小さな神社が見えた。", "target_word": "短い", "complexity_tier": "T4", "furigana": "短[みじか]い橋[はし]を渡[わた]ると、目[め]の前[まえ]に小[ちい]さな神社[じんじゃ]が見[み]えた。", "sentence_source": "generated"}, {"text": "ロープが短かったので、木の上まで届かなかった。", "target_word": "短かった", "complexity_tier": "T4", "furigana": "ロープが短[みじか]かったので、木[き]の上[うえ]まで届[とど]かなかった。", "sentence_source": "generated"}, {"text": "脚が短い机は、床に座って使うのに向いている。", "target_word": "短い", "complexity_tier": "T4", "furigana": "脚[あし]が短[みじか]い机[つくえ]は、床[ゆか]に座[すわ]って使[つか]うのに向[む]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "短い", "label": "基本形"}, {"form": "短く", "label": "連用形"}, {"form": "短かった", "label": "過去形"}, {"form": "短くない", "label": "否定形"}, {"form": "短ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "ものの長さが小さいことを表す形容詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8c15191-2253-47bd-9d8a-2b9974970fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51779, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短い", "is_correct": true, "explanation": "基本形。「短いので」と理由を表し、ひもの長さが足りない理由になる。"}, {"text": "短く", "is_correct": false, "explanation": "連用形。「短くので」とは続かず、『ので』の前に入らない。"}, {"text": "短くて", "is_correct": false, "explanation": "て形。「短くてので」は続かず、『ので』には接続しない。"}, {"text": "短ければ", "is_correct": false, "explanation": "仮定形。「短ければので」は不自然で、『ので』の前に入らない。"}], "explanations": {"短い": "基本形。「短いので」と理由を表し、ひもの長さが足りない理由になる。", "短く": "連用形。「短くので」とは続かず、『ので』の前に入らない。", "短くて": "て形。「短くてので」は続かず、『ので』には接続しない。", "短ければ": "仮定形。「短ければので」は不自然で、『ので』の前に入らない。"}, "sentence_index": 0, "correct_answer": "短い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "参加者が短い。", "explanation": "ここは〈少ない〉の意味。人数の少なさには少ないを使い、短いは長さに使うので合わない。"}, {"text": "この天井は短いので、背の高い人は頭をぶつけてしまう。", "explanation": "ここは〈低い〉の意味。天井の高さには低いを使い、短いは長さに使う。"}, {"text": "この池は短くて、子どもが入ると危ない。", "explanation": "ここは〈浅い〉の意味。水の深さには浅いを使い、短いは長さに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51779, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短く", "is_correct": true, "explanation": "連用形。「短くて」の前半で、しっぽが短いという状態を『て』に続けて述べる。"}, {"text": "短い", "is_correct": false, "explanation": "基本形。「短いて」とは続かず、空欄に入らない。"}, {"text": "短かった", "is_correct": false, "explanation": "過去形。「短かってて」となり不自然で、『て』に続かない。"}, {"text": "短くない", "is_correct": false, "explanation": "否定形。「短くないて」は続かず、『て』の前に入らない。"}], "explanations": {"短く": "連用形。「短くて」の前半で、しっぽが短いという状態を『て』に続けて述べる。", "短い": "基本形。「短いて」とは続かず、空欄に入らない。", "短かった": "過去形。「短かってて」となり不自然で、『て』に続かない。", "短くない": "否定形。「短くないて」は続かず、『て』の前に入らない。"}, "sentence_index": 6, "correct_answer": "短く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この荷物は短いので、持つと腕が疲れてしまう。", "explanation": "ここは〈重い〉の意味。荷物の重さには重いを使い、短いは長さに使う。"}, {"text": "この庭は広さが短くて、子どもが走り回れない。", "explanation": "ここは〈狭い〉の意味。面積の狭さには狭いを使い、短いは長さに使うので合わない。"}, {"text": "このシートは短くて、光がすっかり透けてしまう。", "explanation": "ここは〈薄い〉の意味。厚さには薄いを使い、短いは長さや時間に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51779, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この鉛筆は短くので、ペン立てに入らない。", "corrected_sentence": "この鉛筆は短いので、ペン立てに入らない。", "error_description": "『短くので』は誤り。理由の『ので』の前は基本形の『短いので』が正しい。対象語『短い』の活用形の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "短く", "is_correct": true, "explanation": "連用形。「短くて」の前半『短く』で、『て』に続けて腕が短い状態を述べる。"}, {"text": "短い", "is_correct": false, "explanation": "基本形。「腕は短いて」とは続かず、『て』の前には入らない。"}, {"text": "短かった", "is_correct": false, "explanation": "過去形。「短かったて」とは続かず、『て』に接続しない。"}, {"text": "短くない", "is_correct": false, "explanation": "否定形。「短くないて」は続かず、『て』の前に入らない。"}], "correct_form": "短く", "base_form": "短い", "form_label": "連用形", "sentence_index": 1, "explanations": {"短く": "連用形。「短くて」の前半『短く』で、『て』に続けて腕が短い状態を述べる。", "短い": "基本形。「腕は短いて」とは続かず、『て』の前には入らない。", "短かった": "過去形。「短かったて」とは続かず、『て』に接続しない。", "短くない": "否定形。「短くないて」は続かず、『て』の前に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51779, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ロープは短いくて、木の上まで届かなかった。", "corrected_sentence": "ロープは短くて、木の上まで届かなかった。", "error_description": "『短いくて』は誤り。形容詞の連用形『短く』に『て』が続く『短くて』が正しい。対象語『短い』の活用形の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "短い", "is_correct": true, "explanation": "基本形。名詞「橋」に直接続けて『短い橋』と橋の長さを表す。"}, {"text": "短く", "is_correct": false, "explanation": "連用形。名詞には直接つかず、「短く橋」とは続かない。"}, {"text": "短くて", "is_correct": false, "explanation": "て形。名詞を修飾できず、「短くて橋」とは続かない。"}, {"text": "短ければ", "is_correct": false, "explanation": "仮定形。名詞を修飾できず、「短ければ橋」の形にはならない。"}], "correct_form": "短い", "base_form": "短い", "form_label": "基本形", "sentence_index": 7, "explanations": {"短い": "基本形。名詞「橋」に直接続けて『短い橋』と橋の長さを表す。", "短く": "連用形。名詞には直接つかず、「短く橋」とは続かない。", "短くて": "て形。名詞を修飾できず、「短くて橋」とは続かない。", "短ければ": "仮定形。名詞を修飾できず、「短ければ橋」の形にはならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51780, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "長い", "is_correct": true, "explanation": "定義に『反対は「長い」』とあり、長さ・時間の反対語。"}, {"text": "狭い", "is_correct": false, "explanation": "幅の小ささを表す語で、この意味の反対語ではない。"}, {"text": "厚い", "is_correct": false, "explanation": "厚さの大きさを表す語で、長さの反対語ではない。"}, {"text": "軽い", "is_correct": false, "explanation": "重さが小さいことを表す語で、この意味の反対語ではない。"}], "correct_answer": "長い", "explanations": {"長い": "定義に『反対は「長い」』とあり、長さ・時間の反対語。", "狭い": "幅の小ささを表す語で、この意味の反対語ではない。", "厚い": "厚さの大きさを表す語で、長さの反対語ではない。", "軽い": "重さが小さいことを表す語で、この意味の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
