INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51780, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "長さや時間などが十分でないこと。反対は「長い」。", "primary_collocate": null, "pronunciation": "みじかい", "ipa": "midʑikai", "syllable_count": 4, "sentences": [{"text": "課題は自由な「お絵描き」だが、手には短くなった赤いクレヨンが握られている。", "target_word": "短く", "complexity_tier": "T4", "furigana": "課題[かだい]は自由[じゆう]な「お絵描[えか]き」だが、手[て]には短[みじか]くなった赤[あか]いクレヨンが握[にぎ]られている。", "sentence_source": "mined"}, {"text": "冬は日が短いので、五時には暗くなります。", "target_word": "短い", "complexity_tier": "T3", "furigana": "冬[ふゆ]は日[ひ]が短[みじか]いので、五時[ごじ]には暗[くら]くなります。", "sentence_source": "generated"}, {"text": "夏休みは短くて、宿題が終わらなかった。", "target_word": "短く", "complexity_tier": "T3", "furigana": "夏休[なつやす]みは短[みじか]くて、宿題[しゅくだい]が終[お]わらなかった。", "sentence_source": "generated"}, {"text": "約束の時間が短くて、準備が間に合わない。", "target_word": "短くて", "complexity_tier": "T3", "furigana": "約束[やくそく]の時間[じかん]が短[みじか]くて、準備[じゅんび]が間[ま]に合[あ]わない。", "sentence_source": "generated"}, {"text": "時間が短いので、要点だけを話してください。", "target_word": "短い", "complexity_tier": "T3", "furigana": "時間[じかん]が短[みじか]いので、要点[ようてん]だけを話[はな]してください。", "sentence_source": "generated"}, {"text": "この鉛筆はもう短いので、新しいのを買おう。", "target_word": "短い", "complexity_tier": "T3", "furigana": "この鉛筆[えんぴつ]はもう短[みじか]いので、新[あたら]しいのを買[か]おう。", "sentence_source": "generated"}, {"text": "彼のスピーチは短かったが、心に残った。", "target_word": "短かった", "complexity_tier": "T4", "furigana": "彼[かれ]のスピーチは短[みじか]かったが、心[こころ]に残[のこ]った。", "sentence_source": "generated"}, {"text": "試験までの日数が短くて、復習が追いつかない。", "target_word": "短くて", "complexity_tier": "T3", "furigana": "試験[しけん]までの日数[にっすう]が短[みじか]くて、復習[ふくしゅう]が追[お]いつかない。", "sentence_source": "generated"}, {"text": "昼休みが短く、ゆっくり食事をする余裕がない。", "target_word": "短く", "complexity_tier": "T4", "furigana": "昼休[ひるやす]みが短[みじか]く、ゆっくり食事[しょくじ]をする余裕[よゆう]がない。", "sentence_source": "generated"}, {"text": "待ち合わせまでの時間が短かったので、走って駅へ向かった。", "target_word": "短かった", "complexity_tier": "T4", "furigana": "待[ま]ち合[あ]わせまでの時間[じかん]が短[みじか]かったので、走[はし]って駅[えき]へ向[む]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "短い", "label": "基本形"}, {"form": "短く", "label": "連用形"}, {"form": "短かった", "label": "過去形"}, {"form": "短くない", "label": "否定形"}, {"form": "短ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "長さ・時間などが小さい・足りない様子を表す形容詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8c15191-2253-47bd-9d8a-2b9974970fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51780, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短く", "is_correct": true, "explanation": "「短くなった」の『短く』。形容詞の連用形で、『なった』に続けて変化を表す。"}, {"text": "短い", "is_correct": false, "explanation": "基本形。「短いなった」とは続かず、空欄に入らない。"}, {"text": "短かった", "is_correct": false, "explanation": "過去形。「短かったなった」の形になり、『なった』に続かない。"}, {"text": "短ければ", "is_correct": false, "explanation": "仮定形。「短ければなった」は不自然で、『なった』の前に入らない。"}], "explanations": {"短く": "「短くなった」の『短く』。形容詞の連用形で、『なった』に続けて変化を表す。", "短い": "基本形。「短いなった」とは続かず、空欄に入らない。", "短かった": "過去形。「短かったなった」の形になり、『なった』に続かない。", "短ければ": "仮定形。「短ければなった」は不自然で、『なった』の前に入らない。"}, "sentence_index": 0, "correct_answer": "短く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今月は食費の額が短くて、貯金がほとんどできない。", "explanation": "ここは〈少ない〉の意味。金額の少なさには少ないを使い、短いは長さや時間に使うので合わない。"}, {"text": "今年の雨の量は短い。", "explanation": "ここは〈少ない〉の意味。量の少なさには少ないを使い、短いは長さや時間に使う。"}, {"text": "この部屋は広さが短いので、ベッドを二つ入れられない。", "explanation": "ここは〈狭い〉の意味。部屋の広さには狭いを使い、短いは長さや時間に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51780, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短かった", "is_correct": true, "explanation": "過去形の『短かった』。「彼のスピーチは短かったが」で、過去の状態を表す。"}, {"text": "短く", "is_correct": false, "explanation": "連用形。「短くが」とは続かず、『が』の前に入らない。"}, {"text": "短くて", "is_correct": false, "explanation": "て形。「短くてが」は続かず、『が』の前に入らない。"}, {"text": "短かったら", "is_correct": false, "explanation": "条件の『たら』形。「短かったらが」は続かず、『が』の前に入らない。"}], "explanations": {"短かった": "過去形の『短かった』。「彼のスピーチは短かったが」で、過去の状態を表す。", "短く": "連用形。「短くが」とは続かず、『が』の前に入らない。", "短くて": "て形。「短くてが」は続かず、『が』の前に入らない。", "短かったら": "条件の『たら』形。「短かったらが」は続かず、『が』の前に入らない。"}, "sentence_index": 6, "correct_answer": "短かった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この池は短いので、子どもが遊んでも安心だ。", "explanation": "ここは〈浅い〉の意味。水の深さには浅いを使い、短いは長さや時間に使う。"}, {"text": "弟は身長が短いので、まだ幼稚園に通っている。", "explanation": "ここは〈低い〉の意味。背の高さには低いを使い、短いは長さに使う。"}, {"text": "この紙は短くて、字を書くと透けてしまう。", "explanation": "ここは〈薄い〉の意味。紙の厚さには薄いを使い、短いは長さや時間に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51780, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は短いで、映画を見る時間がなかった。", "corrected_sentence": "週末は短くて、映画を見る時間がなかった。", "error_description": "『短いで』は誤り。『で』の前は『短くて』（連用形＋て）が正しい。誤りは対象語『短い』の活用形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "短い", "is_correct": true, "explanation": "基本形。『ので』の前に基本形を置き、理由を表す。"}, {"text": "短く", "is_correct": false, "explanation": "連用形。「日が短くので」は続かず、『ので』の前には入らない。"}, {"text": "短くて", "is_correct": false, "explanation": "て形。『ので』の前にはつかず、理由の文にならない。"}, {"text": "短ければ", "is_correct": false, "explanation": "仮定形。「短ければので」は不自然で、『ので』の前に入らない。"}], "correct_form": "短い", "base_form": "短い", "form_label": "基本形", "sentence_index": 1, "explanations": {"短い": "基本形。『ので』の前に基本形を置き、理由を表す。", "短く": "連用形。「日が短くので」は続かず、『ので』の前には入らない。", "短くて": "て形。『ので』の前にはつかず、理由の文にならない。", "短ければ": "仮定形。「短ければので」は不自然で、『ので』の前に入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51780, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昼休みは短かく、ゆっくり昼食をとる時間がない。", "corrected_sentence": "昼休みは短く、ゆっくり昼食をとる時間がない。", "error_description": "『短かく』は誤り。形容詞『短い』の連用形は『短く』で、『短かく』という語形はない。対象語の活用形の誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "短い", "is_correct": false, "explanation": "基本形。「日数が短いて」とは続かず、『て』の前には入らない。"}, {"text": "短かった", "is_correct": false, "explanation": "過去形。「短かったて」とは続かず、『て』の前に入らない。"}, {"text": "短くない", "is_correct": false, "explanation": "否定形。「短くないて」の形では続かず、『て』に接続しない。"}, {"text": "短くて", "is_correct": true, "explanation": "て形。「試験までの日数が短くて、復習が追いつかない」と『て』で後ろに状況を続ける形。"}], "correct_form": "短くて", "base_form": "短い", "form_label": "て形", "sentence_index": 7, "explanations": {"短い": "基本形。「日数が短いて」とは続かず、『て』の前には入らない。", "短かった": "過去形。「短かったて」とは続かず、『て』の前に入らない。", "短くない": "否定形。「短くないて」の形では続かず、『て』に接続しない。", "短くて": "て形。「試験までの日数が短くて、復習が追いつかない」と『て』で後ろに状況を続ける形。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '312f083b-38fc-4a15-a667-474429186e73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51781, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "〈絵書きになる〉の〈に〉で、なる対象を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示すので、「なる」の相手にはならない。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示すので、「なる」には付かない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示す格で、ここでは合わない。"}], "correct_answer": "に", "explanations": {"に": "〈絵書きになる〉の〈に〉で、なる対象を示す。正解。", "が": "〈が〉は主語を示すので、「なる」の相手にはならない。", "を": "〈を〉は目的語を示すので、「なる」には付かない。", "で": "〈で〉は手段や場所を示す格で、ここでは合わない。"}, "error_tags": {"が": "主語を示す格で、「なる」の相手にはならない", "を": "目的語の格で、「なる」には付かない", "で": "手段や場所を示す格で、ここでは合わない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51781, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "〈絵書きが似顔絵をかいていた〉の〈が〉で、動作主の主語を示す。正解。"}, {"text": "を", "is_correct": false, "explanation": "〈を〉は目的語を示すので、主語にはならない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は場所や相手を示す格で、主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示す格で、主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "〈絵書きが似顔絵をかいていた〉の〈が〉で、動作主の主語を示す。正解。", "を": "〈を〉は目的語を示すので、主語にはならない。", "に": "〈に〉は場所や相手を示す格で、主語にはならない。", "で": "〈で〉は手段や場所を示す格で、主語にはならない。"}, "error_tags": {"を": "目的語の格で、主語にはならない", "に": "場所や相手を示す格で、主語にはならない", "で": "手段や場所を示す格で、主語にはならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51781, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "えをかくひと。", "primary_collocate": null, "pronunciation": "えかき", "ipa": "ekaki", "syllable_count": 3, "sentences": [{"text": "父は若いころ、町で有名な絵書きだった。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "父[ちち]は若[わか]いころ、町[まち]で有名[ゆうめい]な絵書[えか]きだった。", "sentence_source": "generated"}, {"text": "彼は絵書きになるために、東京の美術学校に入った。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "彼[かれ]は絵書[えか]きになるために、東京[とうきょう]の美術学校[びじゅつがっこう]に入[はい]った。", "sentence_source": "generated"}, {"text": "絵書きの友人が、私の家族の絵をかいてくれた。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "絵書[えか]きの友人[ゆうじん]が、私[わたし]の家族[かぞく]の絵[え]をかいてくれた。", "sentence_source": "generated"}, {"text": "あの絵書きは、一日中、窓のそばで絵筆を動かしている。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "あの絵書[えか]きは、一日中[いちにちじゅう]、窓[まど]のそばで絵筆[えふで]を動[うご]かしている。", "sentence_source": "generated"}, {"text": "祖父は絵書きだったので、家には絵の具の匂いがした。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "祖父[そふ]は絵書[えか]きだったので、家[いえ]には絵[え]の具[ぐ]の匂[にお]いがした。", "sentence_source": "generated"}, {"text": "あの絵書きは、山の景色ばかりを描くことで知られている。", "target_word": "絵書き", "complexity_tier": "T4", "furigana": "あの絵書[えか]きは、山[やま]の景色[けしき]ばかりを描[えが]くことで知[し]られている。", "sentence_source": "generated"}, {"text": "売れない絵書きでも、毎日の練習は欠かさない。", "target_word": "絵書き", "complexity_tier": "T4", "furigana": "売[う]れない絵書[えか]きでも、毎日[まいにち]の練習[れんしゅう]は欠[か]かさない。", "sentence_source": "generated"}, {"text": "駅の前で、一人の絵書きが似顔絵をかいていた。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "駅[えき]の前[まえ]で、一人[ひとり]の絵書[えか]きが似顔絵[にがおえ]をかいていた。", "sentence_source": "generated"}, {"text": "絵書きの仕事は、色と形で気持ちを伝えることだ。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "絵書[えか]きの仕事[しごと]は、色[いろ]と形[かたち]で気持[きも]ちを伝[つた]えることだ。", "sentence_source": "generated"}, {"text": "私の夢は、世界中を旅する絵書きになることです。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "私[わたし]の夢[ゆめ]は、世界中[せかいじゅう]を旅[たび]する絵書[えか]きになることです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絵書き", "label": "基本形"}, {"form": "絵書きの", "label": "連体格"}, {"form": "絵書きに", "label": "に格"}], "register": "colloquial", "sense_fingerprint": "絵を描くことを仕事や生きがいにする人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: 絵筆 (Zipf 2.35)']::text[], '0b8c837d-2fe6-4e39-ac26-de108440b430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51781, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絵書き", "is_correct": true, "explanation": "絵を描く人を指し、「有名な〜だった」で父の身分を述べる文に合う。"}, {"text": "額縁", "is_correct": false, "explanation": "額縁は人ではないので、「父は…だった」の補語にならない。"}, {"text": "絵の具", "is_correct": false, "explanation": "絵の具は人ではないので、父の身分を述べる文に入らない。"}, {"text": "絵筆", "is_correct": false, "explanation": "絵筆は道具で、人を表す語にはならないので合わない。"}], "explanations": {"絵書き": "絵を描く人を指し、「有名な〜だった」で父の身分を述べる文に合う。", "額縁": "額縁は人ではないので、「父は…だった」の補語にならない。", "絵の具": "絵の具は人ではないので、父の身分を述べる文に入らない。", "絵筆": "絵筆は道具で、人を表す語にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "絵書き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの絵書きは、美術館の壁に長く飾られている。", "explanation": "ここは〈作品〉の意味。絵書きは絵を描く人のことで、完成した絵は指さないので合わない。"}, {"text": "絵書きは、石を削って作品を作る。", "explanation": "ここは〈彫刻家〉の意味。石を削る人は彫刻家で、絵を描く絵書きは合わない。"}, {"text": "絵書きは、物語を書いて本を出す。", "explanation": "ここは〈作家〉の意味。物語を書く人は作家で、絵を描く絵書きは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51781, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絵書き", "is_correct": true, "explanation": "人を表し、「売れない〜でも、練習は欠かさない」の主語として自然に入る。"}, {"text": "教室", "is_correct": false, "explanation": "教室は場所で、「売れない」の主語にならない。"}, {"text": "窓枠", "is_correct": false, "explanation": "窓枠は物で、人の立場を表す語にならないので合わない。"}, {"text": "黒板", "is_correct": false, "explanation": "黒板は物で、「売れない」の主語にならないので合わない。"}], "explanations": {"絵書き": "人を表し、「売れない〜でも、練習は欠かさない」の主語として自然に入る。", "教室": "教室は場所で、「売れない」の主語にならない。", "窓枠": "窓枠は物で、人の立場を表す語にならないので合わない。", "黒板": "黒板は物で、「売れない」の主語にならないので合わない。"}, "sentence_index": 6, "correct_answer": "絵書き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "絵書きは、楽器を使って曲を作る。", "explanation": "ここは〈音楽家〉の意味。楽器で曲を作る人は音楽家で、絵を描く絵書きは合わない。"}, {"text": "絵書きは、墨で文字を書く。", "explanation": "ここは〈書道家〉の意味。墨で文字を書く人は書道家で、絵書きは合わない。"}, {"text": "絵書きは、アニメで声を当てる。", "explanation": "ここは〈声優〉の意味。アニメで声を当てる人は声優で、絵書きは絵を描く人なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51781, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は絵書きに目指して、美大に入った。", "corrected_sentence": "彼女は絵書きを目指して、美大に入った。", "error_description": "「目指す」の対象である絵書きは目的語なので「を」が必要。「に」は合わず、正しくは「絵書きを目指して」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51781, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は退職してから、毎日窓辺で絵書きを描いている。", "corrected_sentence": "祖母は退職してから、毎日窓辺で絵書きとして絵を描いている。", "error_description": "「絵書き」は人を表すので「絵書きとして絵を描く」と言う。「描く」は絵を目的語に取るので、「絵書きを描く」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51782, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈絵書きをして〉の〈を〉で、する行為の対象を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示すので、する対象にはならない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は場所や相手を示す格で、する対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す格で、ここでは合わない。"}], "correct_answer": "を", "explanations": {"を": "〈絵書きをして〉の〈を〉で、する行為の対象を示す。正解。", "が": "〈が〉は主語を示すので、する対象にはならない。", "に": "〈に〉は場所や相手を示す格で、する対象にはならない。", "へ": "〈へ〉は方向を示す格で、ここでは合わない。"}, "error_tags": {"が": "主語を示す格で、する対象にはならない", "に": "場所や相手を示す格で、する対象にはならない", "へ": "方向を示す格で、ここでは合わない"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
