INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51782, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "絵を描くこと。", "primary_collocate": null, "pronunciation": "えかき", "ipa": "ekaki", "syllable_count": 3, "sentences": [{"text": "弟は絵書きが大好きで、毎日ノートに何か描いている。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "弟[おとうと]は絵書[えか]きが大好[だいす]きで、毎日[まいにち]ノートに何[なに]か描[か]いている。", "sentence_source": "generated"}, {"text": "雨の日は外で遊べないので、家で絵書きをして過ごした。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は外[そと]で遊[あそ]べないので、家[いえ]で絵書[えか]きをして過[す]ごした。", "sentence_source": "generated"}, {"text": "絵書きに夢中になって、夕ごはんの時間を忘れてしまった。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "絵書[えか]きに夢中[むちゅう]になって、夕[ゆう]ごはんの時間[じかん]を忘[わす]れてしまった。", "sentence_source": "generated"}, {"text": "絵書きは集中力が必要なので、静かな部屋でするほうがいい。", "target_word": "絵書き", "complexity_tier": "T4", "furigana": "絵書[えか]きは集中力[しゅうちゅうりょく]が必要[ひつよう]なので、静[しず]かな部屋[へや]でするほうがいい。", "sentence_source": "generated"}, {"text": "保育園では、午前中に絵書きの時間がある。", "target_word": "絵書き", "complexity_tier": "T2", "furigana": "保育園[ほいくえん]では、午前中[ごぜんちゅう]に絵書[えか]きの時間[じかん]がある。", "sentence_source": "generated"}, {"text": "姉の絵書きの腕前は、クラスでも一番だ。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "姉[あね]の絵書[えか]きの腕前[うでまえ]は、クラスでも一番[いちばん]だ。", "sentence_source": "generated"}, {"text": "絵書きを始めてから、色の違いによく気づくようになった。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "絵書[えか]きを始[はじ]めてから、色[いろ]の違[ちが]いによく気[き]づくようになった。", "sentence_source": "generated"}, {"text": "旅行先で絵書きを楽しむため、小さな絵の具を持っていった。", "target_word": "絵書き", "complexity_tier": "T4", "furigana": "旅行先[りょこうさき]で絵書[えか]きを楽[たの]しむため、小[ちい]さな絵[え]の具[ぐ]を持[も]っていった。", "sentence_source": "generated"}, {"text": "公園では、絵書きをしている人が何人もいた。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "公園[こうえん]では、絵書[えか]きをしている人[ひと]が何人[なんにん]もいた。", "sentence_source": "generated"}, {"text": "妹は絵書きが好きで、週末はいつも部屋にこもって描いている。", "target_word": "絵書き", "complexity_tier": "T3", "furigana": "妹[いもうと]は絵書[えか]きが好[す]きで、週末[しゅうまつ]はいつも部屋[へや]にこもって描[か]いている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絵書き", "label": "基本形"}, {"form": "絵書きを", "label": "を格"}, {"form": "絵書きの", "label": "連体格"}], "register": "colloquial", "sense_fingerprint": "絵を描く行為、またそれを楽しむこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T2: contains vocabulary far above tier T2: 夕ごはん (Zipf 1.84)']::text[], '0b8c837d-2fe6-4e39-ac26-de108440b430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51782, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絵書き", "is_correct": true, "explanation": "描く行為を指し、ノートに何かを描く文脈と合う。"}, {"text": "掃除", "is_correct": false, "explanation": "掃除は描く行為ではなく、ノートに描く文脈と合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は物で、大好きな活動として不自然。"}, {"text": "散歩", "is_correct": false, "explanation": "散歩は描く行為ではなく、ノートに描く文脈と合わない。"}], "explanations": {"絵書き": "描く行為を指し、ノートに何かを描く文脈と合う。", "掃除": "掃除は描く行為ではなく、ノートに描く文脈と合わない。", "辞書": "辞書は物で、大好きな活動として不自然。", "散歩": "散歩は描く行為ではなく、ノートに描く文脈と合わない。"}, "sentence_index": 0, "correct_answer": "絵書き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "絵書きは、ボールを蹴ってゴールを決めることだ。", "explanation": "ここは〈サッカー〉の意味。ボールを蹴ってゴールを決めるのはサッカーで、絵を描く絵書きは合わない。"}, {"text": "絵書きは、石や木を削って形を作ることだ。", "explanation": "ここは〈彫刻〉の意味。石や木を削って形を作るのは彫刻で、絵書きは絵を描く行為なので合わない。"}, {"text": "絵書きは、紙や箱を切って組み立てることだ。", "explanation": "ここは〈工作〉の意味。紙や箱を組み立てるのは工作で、絵書きは描く行為なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51782, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絵書き", "is_correct": true, "explanation": "描く活動を始めると色の違いに気づく、という流れに合う。"}, {"text": "計算", "is_correct": false, "explanation": "計算は色と関係がなく、色の違いに気づく流れに合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "洗濯は色の違いに気づく流れと結びつかないので合わない。"}, {"text": "登山", "is_correct": false, "explanation": "登山は色の違いに気づく流れと結びつかないので合わない。"}], "explanations": {"絵書き": "描く活動を始めると色の違いに気づく、という流れに合う。", "計算": "計算は色と関係がなく、色の違いに気づく流れに合わない。", "洗濯": "洗濯は色の違いに気づく流れと結びつかないので合わない。", "登山": "登山は色の違いに気づく流れと結びつかないので合わない。"}, "sentence_index": 6, "correct_answer": "絵書き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "絵書きは、粘土をこねて器を作ることだ。", "explanation": "ここは〈陶芸〉の意味。粘土で器を作るのは陶芸で、絵書きは描く行為なので合わない。"}, {"text": "絵書きは、カメラで光を切り取ることだ。", "explanation": "ここは〈写真〉の意味。カメラで光を記録するのは写真で、絵書きは描く行為なので合わない。"}, {"text": "絵書きは、布や糸で小物を作ることだ。", "explanation": "ここは〈手芸〉の意味。布や糸で小物を作るのは手芸で、絵書きは絵を描く行為なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51782, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は休日になると、絵書きに楽しんでいる。", "corrected_sentence": "姉は休日になると、絵書きを楽しんでいる。", "error_description": "「楽しむ」は「を」で対象を示すので「絵書きを楽しむ」が正しい。「に」は合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51782, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は、退職してから絵書きに趣味にしている。", "corrected_sentence": "祖母は、退職してから絵書きを趣味にしている。", "error_description": "「趣味にする」は「AをBにする」の形で、Aには「を」が付く。「に」は合わないので、正しくは「絵書きを趣味にしている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51785, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段を示す助詞。「両手で握って」で、握る動作の手段を表す。"}, {"text": "に", "is_correct": false, "explanation": "「両手に握って」では手段を示せず、不自然で文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞で、「両手へ握って」は成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列を示す助詞で、「両手と握って」では文の関係が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "手段を示す助詞。「両手で握って」で、握る動作の手段を表す。", "に": "「両手に握って」では手段を示せず、不自然で文が成り立たない。", "へ": "方向を示す助詞で、「両手へ握って」は成り立たない。", "と": "並列を示す助詞で、「両手と握って」では文の関係が成り立たない。"}, "error_tags": {"に": "場所・相手", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放す", "is_correct": true, "explanation": "握っていたものから手を離す動作。「握る」の対義の関係にある。"}, {"text": "投げる", "is_correct": false, "explanation": "物を遠くへ飛ばす動作で、握る動作の対義語ではない。"}, {"text": "引く", "is_correct": false, "explanation": "物を自分の方へ動かす動作で、握るの対義語ではない。"}, {"text": "結ぶ", "is_correct": false, "explanation": "ひもなどを固定する動作で、握るとは対義の関係にない。"}], "correct_answer": "放す", "explanations": {"放す": "握っていたものから手を離す動作。「握る」の対義の関係にある。", "投げる": "物を遠くへ飛ばす動作で、握る動作の対義語ではない。", "引く": "物を自分の方へ動かす動作で、握るの対義語ではない。", "結ぶ": "ひもなどを固定する動作で、握るとは対義の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51785, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放す", "is_correct": true, "explanation": "握っていたものから手を離す動作。「握る」の対義の関係にある。"}, {"text": "包む", "is_correct": false, "explanation": "物を覆って囲む動作で、握るの対義語ではない。"}, {"text": "叩く", "is_correct": false, "explanation": "物に強く打ちつける動作で、握るの対義語ではない。"}, {"text": "振る", "is_correct": false, "explanation": "物を揺り動かす動作で、握るとは対義の関係にない。"}], "correct_answer": "放す", "explanations": {"放す": "握っていたものから手を離す動作。「握る」の対義の関係にある。", "包む": "物を覆って囲む動作で、握るの対義語ではない。", "叩く": "物に強く打ちつける動作で、握るの対義語ではない。", "振る": "物を揺り動かす動作で、握るとは対義の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51785, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手で物をしっかり持つこと。", "primary_collocate": null, "pronunciation": "にぎる", "ipa": "nʲiɡiɾɯ", "syllable_count": 3, "sentences": [{"text": "私は右手でペンを握って、名前を書いた。", "target_word": "握って", "complexity_tier": "T2", "furigana": "私[わたし]は右手[みぎて]でペンを握[にぎ]って、名前[なまえ]を書[か]いた。", "sentence_source": "generated"}, {"text": "冬は寒くて、コップを両手で握って温かいお茶を飲む。", "target_word": "握って", "complexity_tier": "T3", "furigana": "冬[ふゆ]は寒[さむ]くて、コップを両手[りょうて]で握[にぎ]って温[あたた]かいお茶[ちゃ]を飲[の]む。", "sentence_source": "generated"}, {"text": "バットを握る位置を変えたら、ボールがよく飛ぶようになった。", "target_word": "握る", "complexity_tier": "T3", "furigana": "バットを握[にぎ]る位置[いち]を変[か]えたら、ボールがよく飛[と]ぶようになった。", "sentence_source": "generated"}, {"text": "母は財布を握ったまま、店の前で長い間考えていた。", "target_word": "握った", "complexity_tier": "T3", "furigana": "母[はは]は財布[さいふ]を握[にぎ]ったまま、店[みせ]の前[まえ]で長[なが]い間[あいだ]考[かんが]えていた。", "sentence_source": "generated"}, {"text": "小さな子が、お父さんの手を握って道を渡っている。", "target_word": "握って", "complexity_tier": "T2", "furigana": "小[ちい]さな子[こ]が、お父[とう]さんの手[て]を握[にぎ]って道[みち]を渡[わた]っている。", "sentence_source": "generated"}, {"text": "ロープをしっかり握っていれば、川に流されることはない。", "target_word": "握って", "complexity_tier": "T3", "furigana": "ロープをしっかり握[にぎ]っていれば、川[かわ]に流[なが]されることはない。", "sentence_source": "generated"}, {"text": "先生はチョークを握って、黒板に大きな円を書いた。", "target_word": "握って", "complexity_tier": "T3", "furigana": "先生[せんせい]はチョークを握[にぎ]って、黒板[こくばん]に大[おお]きな円[えん]を書[か]いた。", "sentence_source": "generated"}, {"text": "手が汗でぬれて、握っていたペットボトルがすべりそうになった。", "target_word": "握って", "complexity_tier": "T4", "furigana": "手[て]が汗[あせ]でぬれて、握[にぎ]っていたペットボトルがすべりそうになった。", "sentence_source": "generated"}, {"text": "自転車のハンドルを握ると、風の中を走るのが楽しみになる。", "target_word": "握る", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]のハンドルを握[にぎ]ると、風[かぜ]の中[なか]を走[はし]るのが楽[たの]しみになる。", "sentence_source": "generated"}, {"text": "ゴルフクラブを握ったことがないので、最初は不安だった。", "target_word": "握った", "complexity_tier": "T3", "furigana": "ゴルフクラブを握[にぎ]ったことがないので、最初[さいしょ]は不安[ふあん]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "握る", "label": "終止形・連体形"}, {"form": "握ら", "label": "未然形"}, {"form": "握り", "label": "連用形"}, {"form": "握って", "label": "て形"}, {"form": "握った", "label": "た形"}, {"form": "握れば", "label": "仮定形"}, {"form": "握れ", "label": "命令形"}, {"form": "握ろう", "label": "意志形"}, {"form": "握られる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "手で物をしっかり持つこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75dc4a76-6e0c-4270-8be6-dbde762e7e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51785, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "握って", "is_correct": true, "explanation": "て形。「握って、名前を書いた」と動作を続けて述べている。"}, {"text": "握る", "is_correct": false, "explanation": "終止形。「握る、名前を書いた」と読点で続けられない。"}, {"text": "握れ", "is_correct": false, "explanation": "命令形。「握れ、名前を書いた」は命令文になり、文意が合わない。"}, {"text": "握ろう", "is_correct": false, "explanation": "意志形。「握ろう、名前を書いた」は意味が通らない。"}], "explanations": {"握って": "て形。「握って、名前を書いた」と動作を続けて述べている。", "握る": "終止形。「握る、名前を書いた」と読点で続けられない。", "握れ": "命令形。「握れ、名前を書いた」は命令文になり、文意が合わない。", "握ろう": "意志形。「握ろう、名前を書いた」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "握って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は重い段ボールを肩で握って、二階まで運んだ。", "explanation": "ここは〈担ぐ〉の意味。肩に載せて運ぶ動作は「握る」とは言わない。"}, {"text": "彼は眠る前に目を握って、そっと閉じた。", "explanation": "ここは〈閉じる〉の意味。目は握るものではなく閉じるものなので、「握る」は合わない。"}, {"text": "彼は上司の機嫌を握って、にこにこ笑っていた。", "explanation": "ここは〈機嫌を取る〉の意味。機嫌は握るものではなく取るものなので、「握る」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51785, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "握って", "is_correct": true, "explanation": "て形。「握って、黒板に大きな円を書いた」と動作を続けて述べている。"}, {"text": "握ら", "is_correct": false, "explanation": "未然形。「握ら、黒板に」と文を続けられない。"}, {"text": "握れる", "is_correct": false, "explanation": "可能の終止形。「握れる、黒板に」と続けると文意が合わない。"}, {"text": "握られ", "is_correct": false, "explanation": "受身の連用形。「先生はチョークを握られ」では先生が握る主体にならず、文意が合わない。"}], "explanations": {"握って": "て形。「握って、黒板に大きな円を書いた」と動作を続けて述べている。", "握ら": "未然形。「握ら、黒板に」と文を続けられない。", "握れる": "可能の終止形。「握れる、黒板に」と続けると文意が合わない。", "握られ": "受身の連用形。「先生はチョークを握られ」では先生が握る主体にならず、文意が合わない。"}, "sentence_index": 6, "correct_answer": "握って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は痛むおなかを、やさしく握っていた。", "explanation": "ここは〈さする〉の意味。手のひらで軽くなでる動作は「握る」とは言わない。"}, {"text": "父は泣いている子を握って、背中をとんとん叩いた。", "explanation": "ここは〈抱く〉の意味。子どもを腕で支えることは「握る」とは言わない。"}, {"text": "彼は手で傷口を握って、血を止めた。", "explanation": "ここは〈押さえる〉の意味。傷口を押さえて止血することは「握る」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51785, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ハンドルをしっかり握っ、ゆっくり曲がった。", "corrected_sentence": "ハンドルをしっかり握って、ゆっくり曲がった。", "error_description": "「握って」（て形）で続けるべき箇所を、「握っ」で切ってしまっている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "握って", "is_correct": true, "explanation": "て形。「両手で握って」と動作を並べ、「温かいお茶を飲む」へつなげている。"}, {"text": "握り", "is_correct": false, "explanation": "連用形。「握り温かい」と続けると文が成り立たない。"}, {"text": "握れ", "is_correct": false, "explanation": "命令形。文の流れに命令の意味がない。"}, {"text": "握ろう", "is_correct": false, "explanation": "意志形。「握ろう温かい」とは続かない。"}], "correct_form": "握って", "base_form": "握る", "form_label": "て形", "sentence_index": 1, "explanations": {"握って": "て形。「両手で握って」と動作を並べ、「温かいお茶を飲む」へつなげている。", "握り": "連用形。「握り温かい」と続けると文が成り立たない。", "握れ": "命令形。文の流れに命令の意味がない。", "握ろう": "意志形。「握ろう温かい」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51785, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもは木の棒をしっかり握りまま、走り回った。", "corrected_sentence": "子どもは木の棒をしっかり握ったまま、走り回った。", "error_description": "「まま」の前は「握った」（た形）が必要。「握り」（連用形）では「まま」に続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "握って", "is_correct": true, "explanation": "て形。「握っていた」の形で、ペットボトルを持ち続けていた状態を表す。"}, {"text": "握る", "is_correct": false, "explanation": "終止形。「握るていた」とは続かない。"}, {"text": "握った", "is_correct": false, "explanation": "た形。「握ったていた」とは続かず、「握っていた」の形にならない。"}, {"text": "握ら", "is_correct": false, "explanation": "未然形。「握らていた」とは続かない。"}], "correct_form": "握って", "base_form": "握る", "form_label": "て形", "sentence_index": 7, "explanations": {"握って": "て形。「握っていた」の形で、ペットボトルを持ち続けていた状態を表す。", "握る": "終止形。「握るていた」とは続かない。", "握った": "た形。「握ったていた」とは続かず、「握っていた」の形にならない。", "握ら": "未然形。「握らていた」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51786, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放す", "is_correct": true, "explanation": "握っていたものから手を離す動作。「握る」の対義の関係にある。"}, {"text": "投げる", "is_correct": false, "explanation": "物を遠くへ飛ばす動作で、握る動作の対義語ではない。"}, {"text": "引く", "is_correct": false, "explanation": "物を自分の方へ動かす動作で、握るの対義語ではない。"}, {"text": "結ぶ", "is_correct": false, "explanation": "ひもなどを固定する動作で、握るとは対義の関係にない。"}], "correct_answer": "放す", "explanations": {"放す": "握っていたものから手を離す動作。「握る」の対義の関係にある。", "投げる": "物を遠くへ飛ばす動作で、握る動作の対義語ではない。", "引く": "物を自分の方へ動かす動作で、握るの対義語ではない。", "結ぶ": "ひもなどを固定する動作で、握るとは対義の関係にない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51786, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「握る」の対象（鉛筆）を示す目的格。"}, {"text": "と", "is_correct": false, "explanation": "「鉛筆と握る」では握る対象を示せず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す助詞で、「鉛筆から握る」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す助詞。「鉛筆へ握る力」は成り立たず、文として不自然。"}], "correct_answer": "を", "explanations": {"を": "「握る」の対象（鉛筆）を示す目的格。", "と": "「鉛筆と握る」では握る対象を示せず、文が成り立たない。", "から": "起点を示す助詞で、「鉛筆から握る」は意味が通らない。", "へ": "方向を示す助詞。「鉛筆へ握る力」は成り立たず、文として不自然。"}, "error_tags": {"と": "並列・相手", "から": "起点", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放す", "is_correct": true, "explanation": "握っていたものから手を離す動作。「握る」の対義の関係にある。"}, {"text": "押す", "is_correct": false, "explanation": "力を加えて遠ざける動作で、握るの対義語ではない。"}, {"text": "置く", "is_correct": false, "explanation": "物を一定の場所に据える動作で、握るとは対義の関係にない。"}, {"text": "渡す", "is_correct": false, "explanation": "相手に物を届ける動作で、握るの対義語ではない。"}], "correct_answer": "放す", "explanations": {"放す": "握っていたものから手を離す動作。「握る」の対義の関係にある。", "押す": "力を加えて遠ざける動作で、握るの対義語ではない。", "置く": "物を一定の場所に据える動作で、握るとは対義の関係にない。", "渡す": "相手に物を届ける動作で、握るの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51786, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "手や指で物をしっかりとつかんで、離さないようにすること。", "primary_collocate": null, "pronunciation": "にぎる", "ipa": "nʲiɡiɾɯ", "syllable_count": 3, "sentences": [{"text": "課題は自由な「お絵描き」だが、手には短くなった赤いクレヨンが握られている。", "target_word": "握られ", "complexity_tier": "T4", "furigana": "課題[かだい]は自由[じゆう]な「お絵描[えか]き」だが、手[て]には短[みじか]くなった赤[あか]いクレヨンが握[にぎ]られている。", "sentence_source": "mined"}, {"text": "子どもは迷子にならないように、母の手をぎゅっと握って歩いた。", "target_word": "握って", "complexity_tier": "T3", "furigana": "子[こ]どもは迷子[まいご]にならないように、母[はは]の手[て]をぎゅっと握[にぎ]って歩[ある]いた。", "sentence_source": "generated"}, {"text": "寒い日に、彼は手袋をしたままハンドルを強く握っていた。", "target_word": "握って", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]に、彼[かれ]は手袋[てぶくろ]をしたままハンドルを強[つよ]く握[にぎ]っていた。", "sentence_source": "generated"}, {"text": "赤ちゃんは私の指を小さな手で握って、なかなか離さなかった。", "target_word": "握って", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは私[わたし]の指[ゆび]を小[ちい]さな手[て]で握[にぎ]って、なかなか離[はな]さなかった。", "sentence_source": "generated"}, {"text": "転ばないように、階段では手すりをしっかり握ってください。", "target_word": "握って", "complexity_tier": "T3", "furigana": "転[ころ]ばないように、階段[かいだん]では手[て]すりをしっかり握[にぎ]ってください。", "sentence_source": "generated"}, {"text": "彼女は台本を握り、緊張した顔で舞台に立った。", "target_word": "握り", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は台本[だいほん]を握[にぎ]り、緊張[きんちょう]した顔[かお]で舞台[ぶたい]に立[た]った。", "sentence_source": "generated"}, {"text": "風が強かったので、飛ばされないように帽子を握ったまま走った。", "target_word": "握った", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]かったので、飛[と]ばされないように帽子[ぼうし]を握[にぎ]ったまま走[はし]った。", "sentence_source": "generated"}, {"text": "鉛筆を握る力が弱いと、字がうまく書けない。", "target_word": "握る", "complexity_tier": "T3", "furigana": "鉛筆[えんぴつ]を握[にぎ]る力[ちから]が弱[よわ]いと、字[じ]がうまく書[か]けない。", "sentence_source": "generated"}, {"text": "電車が揺れたので、私はつり革を握った。", "target_word": "握った", "complexity_tier": "T2", "furigana": "電車[でんしゃ]が揺[ゆ]れたので、私[わたし]はつり革[かわ]を握[にぎ]った。", "sentence_source": "generated"}, {"text": "彼は大切な切符を握ったまま、改札の前で友達を待っていた。", "target_word": "握った", "complexity_tier": "T3", "furigana": "彼[かれ]は大切[たいせつ]な切符[きっぷ]を握[にぎ]ったまま、改札[かいさつ]の前[まえ]で友達[ともだち]を待[ま]っていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "握る", "label": "終止形・連体形"}, {"form": "握ら", "label": "未然形"}, {"form": "握り", "label": "連用形"}, {"form": "握って", "label": "て形"}, {"form": "握った", "label": "た形"}, {"form": "握れば", "label": "仮定形"}, {"form": "握れ", "label": "命令形"}, {"form": "握ろう", "label": "意志形"}, {"form": "握られる", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "手や指で物を強くつかんで離さない動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75dc4a76-6e0c-4270-8be6-dbde762e7e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51786, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "握られ", "is_correct": true, "explanation": "受身の連用形。「握られている」で、赤いクレヨンが手に握られた状態を表す。"}, {"text": "握る", "is_correct": false, "explanation": "終止形。「握るている」とは続かない。能動の「握っている」なら主語が手になり、文の意味が合わない。"}, {"text": "握ろう", "is_correct": false, "explanation": "意志形。「握ろうている」とは続かず、受身の状態を表せない。"}, {"text": "握れ", "is_correct": false, "explanation": "命令形。「握れている」は受身の状態を表せず、文に合わない。"}], "explanations": {"握られ": "受身の連用形。「握られている」で、赤いクレヨンが手に握られた状態を表す。", "握る": "終止形。「握るている」とは続かない。能動の「握っている」なら主語が手になり、文の意味が合わない。", "握ろう": "意志形。「握ろうている」とは続かず、受身の状態を表せない。", "握れ": "命令形。「握れている」は受身の状態を表せず、文に合わない。"}, "sentence_index": 0, "correct_answer": "握られ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "エレベーターのボタンを握って、五階まで行った。", "explanation": "ここは〈押す〉の意味。ボタンは指で押して操作するもので、物を握って離さないという定義とは合わない。"}, {"text": "彼は重い箱を肩で握って、駅まで運んだ。", "explanation": "ここは〈担ぐ〉の意味。肩に載せて運ぶ動作は「握る」とは言わない。"}, {"text": "彼女は涙を握って、そっと拭った。", "explanation": "ここは〈拭う〉の意味。涙は握るものではなく拭うものなので、「握る」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51786, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "握った", "is_correct": true, "explanation": "た形。「握ったまま」で、帽子をつかんだ状態を保って走ったことを表す。"}, {"text": "握って", "is_correct": false, "explanation": "て形。「握ってまま」とは続かない。"}, {"text": "握り", "is_correct": false, "explanation": "連用形。「握りまま」とは続かない。"}, {"text": "握らず", "is_correct": false, "explanation": "未然形に「ず」。「握らずまま」は文が成り立たない。"}], "explanations": {"握った": "た形。「握ったまま」で、帽子をつかんだ状態を保って走ったことを表す。", "握って": "て形。「握ってまま」とは続かない。", "握り": "連用形。「握りまま」とは続かない。", "握らず": "未然形に「ず」。「握らずまま」は文が成り立たない。"}, "sentence_index": 6, "correct_answer": "握った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は両手で顔を握って、しばらく泣いていた。", "explanation": "ここは〈包む〉の意味。顔を両手で覆う動作は「握る」とは言わない。"}, {"text": "彼は音楽を握って、静かに聴いていた。", "explanation": "ここは〈聴く〉の意味。音楽は手で握れないので、「握る」とは言わない。"}, {"text": "母は赤ちゃんを握って、やさしく揺らした。", "explanation": "ここは〈抱く〉の意味。人を腕で支えることは「握る」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51786, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女はリモコンを握れ、テレビをつけた。", "corrected_sentence": "彼女はリモコンを握り、テレビをつけた。", "error_description": "「握り」（連用形）で続けるべき箇所に、命令形「握れ」を使っている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "握って", "is_correct": true, "explanation": "て形。「ぎゅっと握って」と動作を並べ、「歩いた」へつなげている。"}, {"text": "握った", "is_correct": false, "explanation": "た形。ここで文が終わってしまい、「歩いた」と続けられない。"}, {"text": "握る", "is_correct": false, "explanation": "終止形。「握る歩いた」とは続かない。"}, {"text": "握れ", "is_correct": false, "explanation": "命令形。文中に命令の意味がなく、「握れ歩いた」は成り立たない。"}], "correct_form": "握って", "base_form": "握る", "form_label": "て形", "sentence_index": 1, "explanations": {"握って": "て形。「ぎゅっと握って」と動作を並べ、「歩いた」へつなげている。", "握った": "た形。ここで文が終わってしまい、「歩いた」と続けられない。", "握る": "終止形。「握る歩いた」とは続かない。", "握れ": "命令形。文中に命令の意味がなく、「握れ歩いた」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51786, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は紙袋の持ち手を握らたまま、駅まで歩いた。", "corrected_sentence": "彼女は紙袋の持ち手を握ったまま、駅まで歩いた。", "error_description": "「握る」のた形は「握った」。「握らた」は活用を誤った形。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "握る", "is_correct": true, "explanation": "連体形。後ろの名詞「力」を修飾している。"}, {"text": "握って", "is_correct": false, "explanation": "て形。名詞「力」を直接修飾できない。"}, {"text": "握れ", "is_correct": false, "explanation": "命令形。名詞を修飾できず、文が成り立たない。"}, {"text": "握ろう", "is_correct": false, "explanation": "意志形。「握ろう力」とは続かない。"}], "correct_form": "握る", "base_form": "握る", "form_label": "連体形", "sentence_index": 7, "explanations": {"握る": "連体形。後ろの名詞「力」を修飾している。", "握って": "て形。名詞「力」を直接修飾できない。", "握れ": "命令形。名詞を修飾できず、文が成り立たない。", "握ろう": "意志形。「握ろう力」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
