INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51787, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "子どもの、おとなになっていない。", "primary_collocate": null, "pronunciation": "おさない", "ipa": "osanai", "syllable_count": 4, "sentences": [{"text": "幼い妹は、まだ一人で靴をはくことができない。", "target_word": "幼い", "complexity_tier": "T3", "furigana": "幼[おさな]い妹[いもうと]は、まだ一人[ひとり]で靴[くつ]をはくことができない。", "sentence_source": "generated"}, {"text": "彼は幼いころ、祖父母の家で夏を過ごした。", "target_word": "幼い", "complexity_tier": "T3", "furigana": "彼[かれ]は幼[おさな]いころ、祖父母[そふぼ]の家[いえ]で夏[なつ]を過[す]ごした。", "sentence_source": "generated"}, {"text": "幼い子どもの手を引いて、横断歩道をわたった。", "target_word": "幼い", "complexity_tier": "T3", "furigana": "幼[おさな]い子[こ]どもの手[て]を引[ひ]いて、横断歩道[おうだんほどう]をわたった。", "sentence_source": "generated"}, {"text": "幼かったので、その日のことはほとんど覚えていない。", "target_word": "幼かった", "complexity_tier": "T3", "furigana": "幼[おさな]かったので、その日[ひ]のことはほとんど覚[おぼ]えていない。", "sentence_source": "generated"}, {"text": "彼女は幼い顔をしているが、実は私より三つ年上だ。", "target_word": "幼い", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は幼[おさな]い顔[かお]をしているが、実[じつ]は私[わたし]より三[みっ]つ年上[としうえ]だ。", "sentence_source": "generated"}, {"text": "幼い弟が泣き出したので、母が急いで抱き上げた。", "target_word": "幼い", "complexity_tier": "T3", "furigana": "幼[おさな]い弟[おとうと]が泣[な]き出[だ]したので、母[はは]が急[いそ]いで抱[だ]き上[あ]げた。", "sentence_source": "generated"}, {"text": "幼い兄弟だけで留守番をするのは心配だ。", "target_word": "幼い", "complexity_tier": "T3", "furigana": "幼[おさな]い兄弟[きょうだい]だけで留守番[るすばん]をするのは心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "幼いながらも、彼女は家族のために料理を作った。", "target_word": "幼い", "complexity_tier": "T4", "furigana": "幼[おさな]いながらも、彼女[かのじょ]は家族[かぞく]のために料理[りょうり]を作[つく]った。", "sentence_source": "generated"}, {"text": "幼い鳥が、巣の中で親の帰りを待っている。", "target_word": "幼い", "complexity_tier": "T3", "furigana": "幼[おさな]い鳥[とり]が、巣[す]の中[なか]で親[おや]の帰[かえ]りを待[ま]っている。", "sentence_source": "generated"}, {"text": "この絵本は、幼い子どもでも楽しめるように作られている。", "target_word": "幼い", "complexity_tier": "T3", "furigana": "この絵本[えほん]は、幼[おさな]い子[こ]どもでも楽[たの]しめるように作[つく]られている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "幼い", "label": "終止形"}, {"form": "幼かった", "label": "過去形"}, {"form": "幼く", "label": "連用形"}, {"form": "幼くない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "年が小さく、まだおとなになっていない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b8c837d-2fe6-4e39-ac26-de108440b430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51787, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幼い", "is_correct": true, "explanation": "子どもの年齢を表し、まだ一人で靴をはけない文脈に合う。"}, {"text": "重い", "is_correct": false, "explanation": "重いは物の重さを表し、人の年齢を述べる文には合わない。"}, {"text": "赤い", "is_correct": false, "explanation": "赤いは色を表し、靴をはけないことと結びつかない。"}, {"text": "硬い", "is_correct": false, "explanation": "硬いは物の性質を表し、妹を修飾すると意味が通らない。"}], "explanations": {"幼い": "子どもの年齢を表し、まだ一人で靴をはけない文脈に合う。", "重い": "重いは物の重さを表し、人の年齢を述べる文には合わない。", "赤い": "赤いは色を表し、靴をはけないことと結びつかない。", "硬い": "硬いは物の性質を表し、妹を修飾すると意味が通らない。"}, "sentence_index": 0, "correct_answer": "幼い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は幼いので、毎朝の散歩を欠かさない。", "explanation": "ここは〈子どもっぽい〉の意味。大人の祖父には使えず、子どもの意味とは合わない。"}, {"text": "彼女は幼いのに、もう会社の部長だ。", "explanation": "ここは〈若い〉の意味。大人の若さを表すには若いを使い、幼いは合わない。"}, {"text": "この箱は幼いので、ポケットに入る。", "explanation": "ここは〈小さい〉の意味。物の大きさには幼いは使わず、小さいを使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51787, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幼い", "is_correct": true, "explanation": "子どもの年齢を表し、留守番を心配する文脈に合う。"}, {"text": "高い", "is_correct": false, "explanation": "高いは背の高さなどを表し、兄弟を修飾すると意味が通らないので合わない。"}, {"text": "冷たい", "is_correct": false, "explanation": "冷たいは人の性格や温度を表し、留守番の心配とは結びつかない。"}, {"text": "遠い", "is_correct": false, "explanation": "遠いは距離を表し、兄弟を修飾すると意味が通らないので合わない。"}], "explanations": {"幼い": "子どもの年齢を表し、留守番を心配する文脈に合う。", "高い": "高いは背の高さなどを表し、兄弟を修飾すると意味が通らないので合わない。", "冷たい": "冷たいは人の性格や温度を表し、留守番の心配とは結びつかない。", "遠い": "遠いは距離を表し、兄弟を修飾すると意味が通らないので合わない。"}, "sentence_index": 6, "correct_answer": "幼い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この問題は幼いので、誰でも解ける。", "explanation": "ここは〈易しい〉の意味。問題の易しさには幼いは使わず、易しいを使うので合わない。"}, {"text": "この布は幼いので、光がよく透ける。", "explanation": "ここは〈薄い〉の意味。布の薄さを表すには薄いを使い、幼いは合わない。"}, {"text": "この通りは幼いので、車がすれ違えない。", "explanation": "ここは〈狭い〉の意味。道幅には幼いは使わず、狭いを使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51787, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "幼く子どもは、まだ字がうまく書けない。", "corrected_sentence": "幼い子どもは、まだ字がうまく書けない。", "error_description": "名詞を修飾するので連体形の「幼い」が必要。「幼く」は連用形で、名詞を直接修飾できないので合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "幼い", "is_correct": true, "explanation": "「幼いころ」で名詞を修飾する連体形で、文の形と合う。"}, {"text": "幼く", "is_correct": false, "explanation": "連用形で、「幼くころ」と名詞を直接修飾できないので合わない。"}, {"text": "幼かろう", "is_correct": false, "explanation": "推量形で、「幼かろうころ」では名詞を修飾できないので合わない。"}, {"text": "幼ければ", "is_correct": false, "explanation": "仮定形で、「幼ければころ」では名詞を修飾できないので合わない。"}], "correct_form": "幼い", "base_form": "幼い", "form_label": "連体形", "sentence_index": 1, "explanations": {"幼い": "「幼いころ」で名詞を修飾する連体形で、文の形と合う。", "幼く": "連用形で、「幼くころ」と名詞を直接修飾できないので合わない。", "幼かろう": "推量形で、「幼かろうころ」では名詞を修飾できないので合わない。", "幼ければ": "仮定形で、「幼ければころ」では名詞を修飾できないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51787, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "幼いて弟は、まだ一人で電車に乗れない。", "corrected_sentence": "幼い弟は、まだ一人で電車に乗れない。", "error_description": "形容詞「幼い」の連用形は「幼く」なので、「て」を付けるなら「幼くて」となる。「幼いて」は誤り。名詞「弟」を修飾するので「幼い弟」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "幼い", "is_correct": true, "explanation": "「〜ながら」は終止形に付くので、終止形の「幼い」が正しい。"}, {"text": "幼くて", "is_correct": false, "explanation": "て形で、「幼くてながらも」では文の形が成り立たないので合わない。"}, {"text": "幼かった", "is_correct": false, "explanation": "過去形で、「〜ながら」に続けると文が成り立たないので合わない。"}, {"text": "幼くなかった", "is_correct": false, "explanation": "過去の否定形で、「〜ながら」に続けると意味が通らないので合わない。"}], "correct_form": "幼い", "base_form": "幼い", "form_label": "終止形", "sentence_index": 7, "explanations": {"幼い": "「〜ながら」は終止形に付くので、終止形の「幼い」が正しい。", "幼くて": "て形で、「幼くてながらも」では文の形が成り立たないので合わない。", "幼かった": "過去形で、「〜ながら」に続けると文が成り立たないので合わない。", "幼くなかった": "過去の否定形で、「〜ながら」に続けると意味が通らないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51789, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈百円玉を握り締めて〉の〈を〉で、握る動作の対象を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示すので、握っているのは子どもであり百円玉ではない。対象を示す〈を〉が必要。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は方向や相手を示すので、握る動作の対象を表せない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示すので、握る対象を表すことができない。"}], "correct_answer": "を", "explanations": {"を": "〈百円玉を握り締めて〉の〈を〉で、握る動作の対象を示す。正解。", "が": "〈が〉は主語を示すので、握っているのは子どもであり百円玉ではない。対象を示す〈を〉が必要。", "に": "〈に〉は方向や相手を示すので、握る動作の対象を表せない。", "で": "〈で〉は手段や場所を示すので、握る対象を表すことができない。"}, "error_tags": {"が": "主格", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51789, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈お守りを握り締め〉の〈を〉で、握る動作の対象を示す。正解。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示す格で、握る動作の対象は表せない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を示す格で、握る対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較を示す格で、握る対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "〈お守りを握り締め〉の〈を〉で、握る動作の対象を示す。正解。", "へ": "〈へ〉は方向を示す格で、握る動作の対象は表せない。", "から": "〈から〉は起点を示す格で、握る対象を表せない。", "より": "〈より〉は比較を示す格で、握る対象にはならない。"}, "error_tags": {"へ": "方向を示す格で、握る対象にはならない", "から": "起点を示す格で、握る対象を表せない", "より": "比較を示す格で、握る対象にはならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51789, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物を強くにぎること。", "primary_collocate": null, "pronunciation": "にぎりしめる", "ipa": "niɡiɾiɕimeɾɯ", "syllable_count": 6, "sentences": [{"text": "彼は悔しさのあまり、こぶしを握り締めた。", "target_word": "握り締めた", "complexity_tier": "T3", "furigana": "彼[かれ]は悔[くや]しさのあまり、こぶしを握[にぎ]り締[し]めた。", "sentence_source": "generated"}, {"text": "子どもは母からもらった百円玉を握り締めて、店に走った。", "target_word": "握り締めて", "complexity_tier": "T3", "furigana": "子[こ]どもは母[はは]からもらった百円玉[ひゃくえんだま]を握[にぎ]り締[し]めて、店[みせ]に走[はし]った。", "sentence_source": "generated"}, {"text": "寒い日は、ポケットの中でカイロを握り締めている。", "target_word": "握り締めて", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は、ポケットの中[なか]でカイロを握[にぎ]り締[し]めている。", "sentence_source": "generated"}, {"text": "彼女は涙をこらえて、スカートの端を握り締めた。", "target_word": "握り締めた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は涙[なみだ]をこらえて、スカートの端[はし]を握[にぎ]り締[し]めた。", "sentence_source": "generated"}, {"text": "強く握り締めすぎて、手紙がしわだらけになってしまった。", "target_word": "握り締めすぎて", "complexity_tier": "T4", "furigana": "強[つよ]く握[にぎ]り締[し]めすぎて、手紙[てがみ]がしわだらけになってしまった。", "sentence_source": "generated"}, {"text": "高いところが怖くて、手すりを握り締めたまま動けなかった。", "target_word": "握り締めた", "complexity_tier": "T4", "furigana": "高[たか]いところが怖[こわ]くて、手[て]すりを握[にぎ]り締[し]めたまま動[うご]けなかった。", "sentence_source": "generated"}, {"text": "優勝のメダルを握り締めて、彼は静かに泣いた。", "target_word": "握り締めて", "complexity_tier": "T3", "furigana": "優勝[ゆうしょう]のメダルを握[にぎ]り締[し]めて、彼[かれ]は静[しず]かに泣[な]いた。", "sentence_source": "generated"}, {"text": "彼はお守りを握り締め、試験会場に入っていった。", "target_word": "握り締め", "complexity_tier": "T4", "furigana": "彼[かれ]はお守[まも]りを握[にぎ]り締[し]め、試験会場[しけんかいじょう]に入[はい]っていった。", "sentence_source": "generated"}, {"text": "手のひらに跡が残るほど、鍵を握り締めていた。", "target_word": "握り締めて", "complexity_tier": "T4", "furigana": "手[て]のひらに跡[あと]が残[のこ]るほど、鍵[かぎ]を握[にぎ]り締[し]めていた。", "sentence_source": "generated"}, {"text": "赤ちゃんは小さな手で、私の指を握り締めた。", "target_word": "握り締めた", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは小[ちい]さな手[て]で、私[わたし]の指[ゆび]を握[にぎ]り締[し]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "握り締める", "label": "終止形"}, {"form": "握り締めて", "label": "て形"}, {"form": "握り締めた", "label": "た形"}, {"form": "握り締めない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "感情や不安を込めて物や拳を強くにぎる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b8c837d-2fe6-4e39-ac26-de108440b430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51789, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "握り締めた", "is_correct": true, "explanation": "「悔しさのあまり」に続く、こぶしを強くにぎる動作の過去形。文の述語として正しい。"}, {"text": "編んだ", "is_correct": false, "explanation": "〈編む〉は糸を組む動作なので、こぶしを対象にできない。"}, {"text": "織った", "is_correct": false, "explanation": "〈織る〉は布を作る動作なので、体の部位には使えない。"}, {"text": "煮た", "is_correct": false, "explanation": "〈煮る〉は火で食材を加熱する動作なので、こぶしには合わない。"}], "explanations": {"握り締めた": "「悔しさのあまり」に続く、こぶしを強くにぎる動作の過去形。文の述語として正しい。", "編んだ": "〈編む〉は糸を組む動作なので、こぶしを対象にできない。", "織った": "〈織る〉は布を作る動作なので、体の部位には使えない。", "煮た": "〈煮る〉は火で食材を加熱する動作なので、こぶしには合わない。"}, "sentence_index": 0, "correct_answer": "握り締めた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は悔しくて、歯を握り締めた。", "explanation": "ここは〈歯を食いしばる〉の場面。歯は手で握る物ではないので、〈握り締める〉は合わない。"}, {"text": "彼は足元の水たまりを握り締めた。", "explanation": "ここは〈すくう〉の場面。水は手の中に握って持つことができないので、〈握り締める〉は合わない。"}, {"text": "彼は広い海原を握り締めて、船を進めた。", "explanation": "海は手で握れない大きな物なので、〈握り締める〉は合わない。ここは〈渡る〉の場面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51789, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "握り締めて", "is_correct": true, "explanation": "〈メダルを握り締めて、彼は静かに泣いた〉の形で、握る動作と泣く動作をつなぐ〈て形〉。正解。"}, {"text": "握り締めに", "is_correct": false, "explanation": "〈握り締めに〉は活用として成り立たず、後ろに続けられない。"}, {"text": "握り締める", "is_correct": false, "explanation": "終止形を置くと、後ろの〈彼は静かに泣いた〉とつながらず文が崩れる。"}, {"text": "握り締めれ", "is_correct": false, "explanation": "〈握り締めれ〉は仮定や命令の形として文脈に合わず、文が成立しない。"}], "explanations": {"握り締めて": "〈メダルを握り締めて、彼は静かに泣いた〉の形で、握る動作と泣く動作をつなぐ〈て形〉。正解。", "握り締めに": "〈握り締めに〉は活用として成り立たず、後ろに続けられない。", "握り締める": "終止形を置くと、後ろの〈彼は静かに泣いた〉とつながらず文が崩れる。", "握り締めれ": "〈握り締めれ〉は仮定や命令の形として文脈に合わず、文が成立しない。"}, "sentence_index": 6, "correct_answer": "握り締めて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は引っ越しの途中で、本棚を握り締めたまま階段を下りた。", "explanation": "本棚は手に収まらない大きな物なので、〈握り締める〉は合わない。ここは〈運ぶ〉の場面。"}, {"text": "彼はエレベーターのボタンを握り締めて、階段へ向かった。", "explanation": "ボタンは押すものなので、ここは〈押す〉の場面。〈握り締める〉はボタンを押す動作には合わない。"}, {"text": "彼は窓を閉めようとして、吹き込む風を握り締めた。", "explanation": "風は手で握ることができないので、〈握り締める〉は合わない。ここは〈押さえる〉の場面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51789, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女は手紙を握り締めに、郵便局に走った。", "corrected_sentence": "彼女は手紙を握り締めて、郵便局に走った。", "error_description": "並列の〈て形〉にすべきところを〈に〉にしている。〈握り締めに〉は活用として成り立たず、〈握り締めて〉が正しい形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "握り締めて", "is_correct": true, "explanation": "〈握り締めて、店に走った〉の並列を表す〈て形〉。正解。"}, {"text": "握り締めた", "is_correct": false, "explanation": "過去形なので、後ろの〈走った〉と並べると文のつながりが崩れる。"}, {"text": "握り締めない", "is_correct": false, "explanation": "否定形なので、握るという動作を打ち消してしまい、文の意味が変わる。"}, {"text": "握り締める", "is_correct": false, "explanation": "終止形なので、文の途中で後ろに続けるつなぎの形としては使えない。"}], "correct_form": "握り締めて", "base_form": "握り締める", "form_label": "て形", "sentence_index": 1, "explanations": {"握り締めて": "〈握り締めて、店に走った〉の並列を表す〈て形〉。正解。", "握り締めた": "過去形なので、後ろの〈走った〉と並べると文のつながりが崩れる。", "握り締めない": "否定形なので、握るという動作を打ち消してしまい、文の意味が変わる。", "握り締める": "終止形なので、文の途中で後ろに続けるつなぎの形としては使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51789, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は祖父の形見の時計と握り締め、静かに目を閉じた。", "corrected_sentence": "彼は祖父の形見の時計を握り締め、静かに目を閉じた。", "error_description": "対象を示す〈を〉を〈と〉にしている。〈と〉は〈〜と一緒に〉の意味になり、〈握り締める〉の対象は〈を〉で示す必要がある。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "握り締め", "is_correct": true, "explanation": "〈お守りを握り締め、試験会場に入っていった〉の中止を表す〈連用形〉。正解。"}, {"text": "握り締めれば", "is_correct": false, "explanation": "仮定の〈ば〉の形で条件を表すので、事実を述べる後ろの〈入っていった〉とは合わない。"}, {"text": "握り締めよう", "is_correct": false, "explanation": "意志形なので、自分の意向を表し、実際に試験会場に入った文と合わない。"}, {"text": "握り締められた", "is_correct": false, "explanation": "受身・可能の形なので、握られる側の意味になり、お守りを握る主体の文と合わない。"}], "correct_form": "握り締め", "base_form": "握り締める", "form_label": "連用形", "sentence_index": 7, "explanations": {"握り締め": "〈お守りを握り締め、試験会場に入っていった〉の中止を表す〈連用形〉。正解。", "握り締めれば": "仮定の〈ば〉の形で条件を表すので、事実を述べる後ろの〈入っていった〉とは合わない。", "握り締めよう": "意志形なので、自分の意向を表し、実際に試験会場に入った文と合わない。", "握り締められた": "受身・可能の形なので、握られる側の意味になり、お守りを握る主体の文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51790, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈財布をしっかり握り締めて〉の〈を〉で、握る動作の対象を示す。正解。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示すので、握る対象の財布を表すことができない。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は方向や相手を示すので、握る動作の対象には使えない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示すので、握る対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "〈財布をしっかり握り締めて〉の〈を〉で、握る動作の対象を示す。正解。", "が": "〈が〉は主語を示すので、握る対象の財布を表すことができない。", "に": "〈に〉は方向や相手を示すので、握る動作の対象には使えない。", "で": "〈で〉は手段や場所を示すので、握る対象を表せない。"}, "error_tags": {"が": "主格", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51790, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈ペンを握り締めても〉の〈を〉で、握る動作の対象を示す。正解。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向を示すので、握る動作の対象を表すことができない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を示すので、〈ペンから握り締めても〉は意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は所有や修飾を示すので、動詞〈握り締めても〉の対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "〈ペンを握り締めても〉の〈を〉で、握る動作の対象を示す。正解。", "へ": "〈へ〉は方向を示すので、握る動作の対象を表すことができない。", "から": "〈から〉は起点を示すので、〈ペンから握り締めても〉は意味が通らない。", "の": "〈の〉は所有や修飾を示すので、動詞〈握り締めても〉の対象を表せない。"}, "error_tags": {"へ": "方向・相手", "から": "起点・理由", "の": "所属・修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51790, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "指をしっかりと閉じて、物を手の中にしっかりと持つこと。", "primary_collocate": null, "pronunciation": "にぎりしめる", "ipa": "niɡiɾiɕimeɾɯ", "syllable_count": 6, "sentences": [{"text": "電車が揺れたので、彼女は吊り革を握り締めて体を支えた。", "target_word": "握り締めて", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が揺[ゆ]れたので、彼女[かのじょ]は吊[つ]り革[かわ]を握[にぎ]り締[し]めて体[からだ]を支[ささ]えた。", "sentence_source": "generated"}, {"text": "彼は財布をしっかり握り締めて、人ごみの中を進んだ。", "target_word": "握り締めて", "complexity_tier": "T3", "furigana": "彼[かれ]は財布[さいふ]をしっかり握[にぎ]り締[し]めて、人[ひと]ごみの中[なか]を進[すす]んだ。", "sentence_source": "generated"}, {"text": "子どもは拾った貝を、手の中に握り締めて持って帰った。", "target_word": "握り締めて", "complexity_tier": "T3", "furigana": "子[こ]どもは拾[ひろ]った貝[かい]を、手[て]の中[なか]に握[にぎ]り締[し]めて持[も]って帰[かえ]った。", "sentence_source": "generated"}, {"text": "風が強かったので、帽子を握り締めたまま走った。", "target_word": "握り締めた", "complexity_tier": "T3", "furigana": "風[かぜ]が強[つよ]かったので、帽子[ぼうし]を握[にぎ]り締[し]めたまま走[はし]った。", "sentence_source": "generated"}, {"text": "落とさないように、指をしっかり閉じてコインを握り締めた。", "target_word": "握り締めた", "complexity_tier": "T4", "furigana": "落[お]とさないように、指[ゆび]をしっかり閉[と]じてコインを握[にぎ]り締[し]めた。", "sentence_source": "generated"}, {"text": "彼女はチケットを握り締めたまま、開場を待っていた。", "target_word": "握り締めた", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はチケットを握[にぎ]り締[し]めたまま、開場[かいじょう]を待[ま]っていた。", "sentence_source": "generated"}, {"text": "兄は釣り竿を握り締め、魚が引くのをじっと待った。", "target_word": "握り締め", "complexity_tier": "T4", "furigana": "兄[あに]は釣[つ]り竿[ざお]を握[にぎ]り締[し]め、魚[さかな]が引[ひ]くのをじっと待[ま]った。", "sentence_source": "generated"}, {"text": "手がぬれていて、ペンを握り締めても滑ってしまう。", "target_word": "握り締めて", "complexity_tier": "T4", "furigana": "手[て]がぬれていて、ペンを握[にぎ]り締[し]めても滑[すべ]ってしまう。", "sentence_source": "generated"}, {"text": "彼は受け取った鍵を、手の中に握り締めて家に帰った。", "target_word": "握り締めて", "complexity_tier": "T3", "furigana": "彼[かれ]は受[う]け取[と]った鍵[かぎ]を、手[て]の中[なか]に握[にぎ]り締[し]めて家[いえ]に帰[かえ]った。", "sentence_source": "generated"}, {"text": "ロープを握り締めたまま、彼は崖をゆっくり降りた。", "target_word": "握り締めた", "complexity_tier": "T4", "furigana": "ロープを握[にぎ]り締[し]めたまま、彼[かれ]は崖[がけ]をゆっくり降[お]りた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "握り締める", "label": "終止形"}, {"form": "握り締めて", "label": "て形"}, {"form": "握り締めた", "label": "た形"}, {"form": "握り締めない", "label": "ない形"}], "register": "neutral", "sense_fingerprint": "落とさないよう指を閉じて物を手の中に持つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b8c837d-2fe6-4e39-ac26-de108440b430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51790, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "握り締めて", "is_correct": true, "explanation": "〈吊り革を握り締めて体を支えた〉の並列を表す〈て形〉。正解。"}, {"text": "握り締めに", "is_correct": false, "explanation": "〈握り締めに〉は活用として成り立たず、後ろの〈体を支えた〉に続けられない。"}, {"text": "握り締めれ", "is_correct": false, "explanation": "〈握り締めれ〉は仮定や命令の形で、ここでは文が成立しない。"}, {"text": "握り締める", "is_correct": false, "explanation": "終止形では後ろの〈体を支えた〉と続かず、文の構造が崩れる。"}], "explanations": {"握り締めて": "〈吊り革を握り締めて体を支えた〉の並列を表す〈て形〉。正解。", "握り締めに": "〈握り締めに〉は活用として成り立たず、後ろの〈体を支えた〉に続けられない。", "握り締めれ": "〈握り締めれ〉は仮定や命令の形で、ここでは文が成立しない。", "握り締める": "終止形では後ろの〈体を支えた〉と続かず、文の構造が崩れる。"}, "sentence_index": 0, "correct_answer": "握り締めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は冷たい空気を握り締めて、深呼吸した。", "explanation": "空気は握れないので、〈握り締める〉は合わない。ここは〈吸う〉の場面。"}, {"text": "彼は大きな看板を握り締めたまま、店の前まで運んだ。", "explanation": "〈握り締める〉は手で小さな物を強くにぎる意味。看板のように手に収まらない大きな物には、〈抱える〉か〈運ぶ〉を使うべき。"}, {"text": "突然の揺れに、彼は天井を握り締めた。", "explanation": "天井は手の中に持てない大きな物なので、〈握り締める〉は合わない。ここは〈つかまる〉の場面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51790, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "握り締め", "is_correct": true, "explanation": "〈釣り竿を握り締め、魚が引くのを待った〉の中止を表す形。正解。"}, {"text": "握り締めまい", "is_correct": false, "explanation": "打ち消しの意志の形で、〈待った〉へ続く中止の流れに合わず、釣り竿を握る動作と矛盾する。"}, {"text": "握り締めます", "is_correct": false, "explanation": "丁寧語の形で、地の文の普通体〈待った〉と文体が合わず、中止の形にならない。"}, {"text": "握り締めさせ", "is_correct": false, "explanation": "使役の形なので、〈兄が〉握る主体と合わず、別の人に握らせる意味になってしまう。"}], "explanations": {"握り締め": "〈釣り竿を握り締め、魚が引くのを待った〉の中止を表す形。正解。", "握り締めまい": "打ち消しの意志の形で、〈待った〉へ続く中止の流れに合わず、釣り竿を握る動作と矛盾する。", "握り締めます": "丁寧語の形で、地の文の普通体〈待った〉と文体が合わず、中止の形にならない。", "握り締めさせ": "使役の形なので、〈兄が〉握る主体と合わず、別の人に握らせる意味になってしまう。"}, "sentence_index": 6, "correct_answer": "握り締め"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は非常ベルを握り締めて、廊下を走った。", "explanation": "ここは〈押す〉の場面。ベルは押して鳴らす物なので、〈握り締める〉は合わない。"}, {"text": "彼は痛みに耐えて、唇を握り締めた。", "explanation": "唇は手で握れないので、〈握り締める〉は合わない。ここは〈噛む〉の場面。"}, {"text": "彼は大きな岩山を握り締めたまま、山道を登った。", "explanation": "岩山は手に収まらない大きな物なので、〈握り締める〉は合わない。ここは〈よじ登る〉の場面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51790, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもは回転木馬の柵に握り締めて、大声で笑った。", "corrected_sentence": "子どもは回転木馬の柵を握り締めて、大声で笑った。", "error_description": "握る対象を示す〈を〉を〈に〉にしている。〈に〉では柵に握りつけるという不自然な意味になり、〈握り締める〉の対象は〈を〉で示す必要がある。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "握り締めて", "is_correct": true, "explanation": "〈財布をしっかり握り締めて、人ごみの中を進んだ〉の並列を表す〈て形〉。正解。"}, {"text": "握り締めた", "is_correct": false, "explanation": "過去形なので、後ろの〈進んだ〉と並べると文のつながりが崩れる。"}, {"text": "握り締めない", "is_correct": false, "explanation": "否定形なので、財布を握るという動作を打ち消してしまい、文の意味が変わる。"}, {"text": "握り締める", "is_correct": false, "explanation": "終止形なので、文の途中で後ろに続けるつなぎの形としては使えない。"}], "correct_form": "握り締めて", "base_form": "握り締める", "form_label": "て形", "sentence_index": 1, "explanations": {"握り締めて": "〈財布をしっかり握り締めて、人ごみの中を進んだ〉の並列を表す〈て形〉。正解。", "握り締めた": "過去形なので、後ろの〈進んだ〉と並べると文のつながりが崩れる。", "握り締めない": "否定形なので、財布を握るという動作を打ち消してしまい、文の意味が変わる。", "握り締める": "終止形なので、文の途中で後ろに続けるつなぎの形としては使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51790, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母はお茶碗と握り締めて、静かに話を聞いた。", "corrected_sentence": "祖母はお茶碗を握り締めて、静かに話を聞いた。", "error_description": "対象を示す〈を〉を〈と〉にしている。〈と〉は〈〜と一緒に〉の意味になり、〈握り締める〉の対象は〈を〉で示す必要がある。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "握り締めて", "is_correct": true, "explanation": "〈ペンを握り締めても滑ってしまう〉で、後ろの〈も〉につながる〈て形〉。正解。"}, {"text": "握り締めた", "is_correct": false, "explanation": "過去形なので、〜ても の前には続かず、文が成り立たない。"}, {"text": "握り締めよう", "is_correct": false, "explanation": "意志の形なので、〈〜ても滑ってしまう〉という事実を述べる文と合わない。"}, {"text": "握り締めろ", "is_correct": false, "explanation": "命令の形なので、〈〜ても滑ってしまう〉の結果を述べる文と合わない。"}], "correct_form": "握り締めて", "base_form": "握り締める", "form_label": "て形", "sentence_index": 7, "explanations": {"握り締めて": "〈ペンを握り締めても滑ってしまう〉で、後ろの〈も〉につながる〈て形〉。正解。", "握り締めた": "過去形なので、〜ても の前には続かず、文が成り立たない。", "握り締めよう": "意志の形なので、〈〜ても滑ってしまう〉という事実を述べる文と合わない。", "握り締めろ": "命令の形なので、〈〜ても滑ってしまう〉の結果を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51791, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "角張った", "is_correct": true, "explanation": "かどがあって四角ばった形を表す。角がない丸い形の対義語。"}, {"text": "重い", "is_correct": false, "explanation": "形ではなく重さを表すので、対義語ではない。"}, {"text": "長い", "is_correct": false, "explanation": "長さを表す語で、丸いの対義語ではない。"}, {"text": "細い", "is_correct": false, "explanation": "幅が狭いことを表す語で、丸いの対義語ではない。"}], "correct_answer": "角張った", "explanations": {"角張った": "かどがあって四角ばった形を表す。角がない丸い形の対義語。", "重い": "形ではなく重さを表すので、対義語ではない。", "長い": "長さを表す語で、丸いの対義語ではない。", "細い": "幅が狭いことを表す語で、丸いの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51791, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "角張った", "is_correct": true, "explanation": "かどのある形を表す。角がない丸い形の対義語。"}, {"text": "赤い", "is_correct": false, "explanation": "色を表す語で、丸いの対義語ではない。"}, {"text": "硬い", "is_correct": false, "explanation": "材質の性質を表す語で、丸いの対義語ではない。"}, {"text": "薄い", "is_correct": false, "explanation": "厚みを表す語で、丸いの対義語ではない。"}], "correct_answer": "角張った", "explanations": {"角張った": "かどのある形を表す。角がない丸い形の対義語。", "赤い": "色を表す語で、丸いの対義語ではない。", "硬い": "材質の性質を表す語で、丸いの対義語ではない。", "薄い": "厚みを表す語で、丸いの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51791, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "まるい形のこと。ボールみたいに、かどがない形。", "primary_collocate": null, "pronunciation": "まるい", "ipa": "maɾɯi", "syllable_count": 3, "sentences": [{"text": "ボールは丸いので、坂の上に置くと転がっていく。", "target_word": "丸い", "complexity_tier": "T2", "furigana": "ボールは丸[まる]いので、坂[さか]の上[うえ]に置[お]くと転[ころ]がっていく。", "sentence_source": "generated"}, {"text": "このクッキーは丸い形で、角がありません。", "target_word": "丸い", "complexity_tier": "T2", "furigana": "このクッキーは丸[まる]い形[かたち]で、角[かど]がありません。", "sentence_source": "generated"}, {"text": "丸い机は角がないので、子どもがぶつかっても安全だ。", "target_word": "丸い", "complexity_tier": "T3", "furigana": "丸[まる]い机[つくえ]は角[かど]がないので、子[こ]どもがぶつかっても安全[あんぜん]だ。", "sentence_source": "generated"}, {"text": "地球は丸いと、昔の人はなかなか信じなかった。", "target_word": "丸い", "complexity_tier": "T3", "furigana": "地球[ちきゅう]は丸[まる]いと、昔[むかし]の人[ひと]はなかなか信[しん]じなかった。", "sentence_source": "generated"}, {"text": "弟は丸いパンを半分に切って、私にくれた。", "target_word": "丸い", "complexity_tier": "T2", "furigana": "弟[おとうと]は丸[まる]いパンを半分[はんぶん]に切[き]って、私[わたし]にくれた。", "sentence_source": "generated"}, {"text": "りんごは丸い果物で、赤いものも黄色いものもある。", "target_word": "丸い", "complexity_tier": "T3", "furigana": "りんごは丸[まる]い果物[くだもの]で、赤[あか]いものも黄色[きいろ]いものもある。", "sentence_source": "generated"}, {"text": "猫が丸い毛糸の玉で遊んでいる。", "target_word": "丸い", "complexity_tier": "T2", "furigana": "猫[ねこ]が丸[まる]い毛糸[けいと]の玉[たま]で遊[あそ]んでいる。", "sentence_source": "generated"}, {"text": "鉛筆の先が丸いと、細い線が書きにくい。", "target_word": "丸い", "complexity_tier": "T3", "furigana": "鉛筆[えんぴつ]の先[さき]が丸[まる]いと、細[ほそ]い線[せん]が書[か]きにくい。", "sentence_source": "generated"}, {"text": "丸い風船が空に上がって、だんだん見えなくなった。", "target_word": "丸い", "complexity_tier": "T3", "furigana": "丸[まる]い風船[ふうせん]が空[そら]に上[あ]がって、だんだん見[み]えなくなった。", "sentence_source": "generated"}, {"text": "四角いお皿より、丸いお皿のほうが好きだ。", "target_word": "丸い", "complexity_tier": "T2", "furigana": "四角[しかく]いお皿[さら]より、丸[まる]いお皿[さら]のほうが好[す]きだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "丸い", "label": "終止形・連体形"}, {"form": "丸く", "label": "連用形"}, {"form": "丸かった", "label": "過去形"}, {"form": "丸くない", "label": "否定形"}, {"form": "丸ければ", "label": "仮定形"}, {"form": "丸さ", "label": "名詞化"}], "register": "neutral", "sense_fingerprint": "ボールのように角がなく、まるい形をしている", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75dc4a76-6e0c-4270-8be6-dbde762e7e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51791, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丸い", "is_correct": true, "explanation": "終止形。「丸いので」と理由を続けている。"}, {"text": "丸く", "is_correct": false, "explanation": "連用形。「丸くので」とは続かない。"}, {"text": "丸さ", "is_correct": false, "explanation": "名詞化。「丸さので」は成り立たない。"}, {"text": "丸ければ", "is_correct": false, "explanation": "仮定形。「丸ければので」とは続かない。"}], "explanations": {"丸い": "終止形。「丸いので」と理由を続けている。", "丸く": "連用形。「丸くので」とは続かない。", "丸さ": "名詞化。「丸さので」は成り立たない。", "丸ければ": "仮定形。「丸ければので」とは続かない。"}, "sentence_index": 0, "correct_answer": "丸い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "丸い六角形のナットを、工具箱にしまった。", "explanation": "ここは〈六角形〉の意味。六角形は角がある形なので、かどがない形を表す「丸い」とは合わない。"}, {"text": "彼は丸い三年を、ずっと海外で過ごした。", "explanation": "ここは〈まる三年〉の意味。「丸い」は形を表すので、期間を表す「まる三年」の代わりには使えない。"}, {"text": "丸い長方形のメモ帳を、かばんにしまった。", "explanation": "ここは〈長方形〉の意味。長方形は角がある形なので、かどがない形を表す「丸い」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51791, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丸い", "is_correct": true, "explanation": "連体形。名詞「毛糸の玉」を修飾している。"}, {"text": "丸め", "is_correct": false, "explanation": "「丸める」の連用形。名詞を修飾できない。"}, {"text": "丸み", "is_correct": false, "explanation": "名詞。「丸み毛糸」とは続かない。"}, {"text": "丸味", "is_correct": false, "explanation": "名詞。「丸味毛糸」とは続かない。"}], "explanations": {"丸い": "連体形。名詞「毛糸の玉」を修飾している。", "丸め": "「丸める」の連用形。名詞を修飾できない。", "丸み": "名詞。「丸み毛糸」とは続かない。", "丸味": "名詞。「丸味毛糸」とは続かない。"}, "sentence_index": 6, "correct_answer": "丸い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "丸い魔法のように、部屋がみるみるきれいになった。", "explanation": "ここは〈まるで〜のようだ〉の比喩の意味。〈丸い〉は形を表すので、この使い方はできない。"}, {"text": "丸いひし形の凧が、空に高く上がっていた。", "explanation": "ここは〈ひし形〉の意味。ひし形は角がある形なので、かどがない形を表す「丸い」とは合わない。"}, {"text": "彼は丸い星型のクッキーを、オーブンで焼いた。", "explanation": "ここは〈星の形〉の意味。星の形には尖った角があるので、かどがない形を表す「丸い」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51791, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "箱の中には丸くビー玉が並んでいた。", "corrected_sentence": "箱の中には丸いビー玉が並んでいた。", "error_description": "名詞「ビー玉」を修飾する連体形「丸い」が必要なのに、連用形「丸く」を使っている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "丸い", "is_correct": true, "explanation": "連体形。名詞「形」を修飾している。"}, {"text": "丸く", "is_correct": false, "explanation": "連用形。「丸く形」と名詞に直接続かない。"}, {"text": "丸さ", "is_correct": false, "explanation": "名詞化。「丸さ形」は成り立たない。"}, {"text": "丸ければ", "is_correct": false, "explanation": "仮定形。「丸ければ形で」と続かない。"}], "correct_form": "丸い", "base_form": "丸い", "form_label": "連体形", "sentence_index": 1, "explanations": {"丸い": "連体形。名詞「形」を修飾している。", "丸く": "連用形。「丸く形」と名詞に直接続かない。", "丸さ": "名詞化。「丸さ形」は成り立たない。", "丸ければ": "仮定形。「丸ければ形で」と続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51791, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子どもが丸ければボールを蹴って、公園を走り回った。", "corrected_sentence": "子どもが丸いボールを蹴って、公園を走り回った。", "error_description": "名詞「ボール」を修飾する連体形「丸い」が必要で、仮定形「丸ければ」は文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "丸い", "is_correct": true, "explanation": "終止形。「丸いと」と、条件を示す「と」に続いている。"}, {"text": "丸かった", "is_correct": false, "explanation": "過去形。「丸かったと」では文の条件が成り立たない。"}, {"text": "丸く", "is_correct": false, "explanation": "連用形。「丸くと」とは続かず、条件の文として成り立たない。"}, {"text": "丸くて", "is_correct": false, "explanation": "て形。「丸くてと」とは続かない。"}], "correct_form": "丸い", "base_form": "丸い", "form_label": "終止形", "sentence_index": 7, "explanations": {"丸い": "終止形。「丸いと」と、条件を示す「と」に続いている。", "丸かった": "過去形。「丸かったと」では文の条件が成り立たない。", "丸く": "連用形。「丸くと」とは続かず、条件の文として成り立たない。", "丸くて": "て形。「丸くてと」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51792, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "四角い", "is_correct": true, "explanation": "円形の反対で、角のある形を表す。対義語の関係にある。"}, {"text": "重い", "is_correct": false, "explanation": "形ではなく重さを表すので、円形の対義語ではない。"}, {"text": "長い", "is_correct": false, "explanation": "長さを表す語で、円形の対義語ではない。"}, {"text": "細い", "is_correct": false, "explanation": "幅が狭いことを表す語で、円形の対義語ではない。"}], "correct_answer": "四角い", "explanations": {"四角い": "円形の反対で、角のある形を表す。対義語の関係にある。", "重い": "形ではなく重さを表すので、円形の対義語ではない。", "長い": "長さを表す語で、円形の対義語ではない。", "細い": "幅が狭いことを表す語で、円形の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51792, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "四角い", "is_correct": true, "explanation": "円形の反対で、角のある形を表す。対義語の関係にある。"}, {"text": "赤い", "is_correct": false, "explanation": "色を表す語で、円形の対義語ではない。"}, {"text": "硬い", "is_correct": false, "explanation": "材質の性質を表す語で、円形の対義語ではない。"}, {"text": "薄い", "is_correct": false, "explanation": "厚みを表す語で、円形の対義語ではない。"}], "correct_answer": "四角い", "explanations": {"四角い": "円形の反対で、角のある形を表す。対義語の関係にある。", "赤い": "色を表す語で、円形の対義語ではない。", "硬い": "材質の性質を表す語で、円形の対義語ではない。", "薄い": "厚みを表す語で、円形の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51792, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "円形であるさま。曲線で囲まれた形。球形や円形の様子。", "primary_collocate": null, "pronunciation": "まるい", "ipa": "maɾɯi", "syllable_count": 3, "sentences": [{"text": "私はそのクレヨンで、紙の中央に大きな丸い太陽を描き始めた。", "target_word": "丸い", "complexity_tier": "T3", "furigana": "私[わたし]はそのクレヨンで、紙[かみ]の中央[ちゅうおう]に大[おお]きな丸[まる]い太陽[たいよう]を描[えが]き始[はじ]めた。", "sentence_source": "mined"}, {"text": "机の上に、丸い皿が三枚並べてある。", "target_word": "丸い", "complexity_tier": "T2", "furigana": "机[つくえ]の上[うえ]に、丸[まる]い皿[さら]が三枚[さんまい]並[なら]べてある。", "sentence_source": "generated"}, {"text": "満月の夜は、空に丸い月がきれいに見える。", "target_word": "丸い", "complexity_tier": "T2", "furigana": "満月[まんげつ]の夜[よる]は、空[そら]に丸[まる]い月[つき]がきれいに見[み]える。", "sentence_source": "generated"}, {"text": "この町には、丸い屋根の古い教会がある。", "target_word": "丸い", "complexity_tier": "T3", "furigana": "この町[まち]には、丸[まる]い屋根[やね]の古[ふる]い教会[きょうかい]がある。", "sentence_source": "generated"}, {"text": "赤ちゃんの顔は、丸くてとてもかわいい。", "target_word": "丸く", "complexity_tier": "T2", "furigana": "赤[あか]ちゃんの顔[かお]は、丸[まる]くてとてもかわいい。", "sentence_source": "generated"}, {"text": "この部屋のテーブルは丸いので、どこに座っても顔がよく見える。", "target_word": "丸い", "complexity_tier": "T3", "furigana": "この部屋[へや]のテーブルは丸[まる]いので、どこに座[すわ]っても顔[かお]がよく見[み]える。", "sentence_source": "generated"}, {"text": "犬は丸い目で私を見上げて、えさを待っていた。", "target_word": "丸い", "complexity_tier": "T3", "furigana": "犬[いぬ]は丸[まる]い目[め]で私[わたし]を見上[みあ]げて、えさを待[ま]っていた。", "sentence_source": "generated"}, {"text": "川の石は、長い間水に流されて、丸くなっている。", "target_word": "丸く", "complexity_tier": "T3", "furigana": "川[かわ]の石[いし]は、長[なが]い間[あいだ]水[みず]に流[なが]されて、丸[まる]くなっている。", "sentence_source": "generated"}, {"text": "彼女は丸い眼鏡をかけていて、先生のように見えた。", "target_word": "丸い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は丸[まる]い眼鏡[めがね]をかけていて、先生[せんせい]のように見[み]えた。", "sentence_source": "generated"}, {"text": "雨のあと、道に丸い水たまりがいくつもできていた。", "target_word": "丸い", "complexity_tier": "T3", "furigana": "雨[あめ]のあと、道[みち]に丸[まる]い水[みず]たまりがいくつもできていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "丸い", "label": "終止形・連体形"}, {"form": "丸く", "label": "連用形"}, {"form": "丸かった", "label": "過去形"}, {"form": "丸くない", "label": "否定形"}, {"form": "丸ければ", "label": "仮定形"}, {"form": "丸さ", "label": "名詞化"}], "register": "neutral", "sense_fingerprint": "円形や球形の、曲線で囲まれた形をしている様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75dc4a76-6e0c-4270-8be6-dbde762e7e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51792, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丸い", "is_correct": true, "explanation": "連体形。名詞「太陽」を修飾している。"}, {"text": "丸く", "is_correct": false, "explanation": "連用形。「大きな丸く太陽」と名詞に直接続かない。"}, {"text": "丸さ", "is_correct": false, "explanation": "名詞化。「大きな丸さ太陽」は成り立たない。"}, {"text": "丸め", "is_correct": false, "explanation": "「丸める」の連用形。「大きな丸め太陽」は成り立たない。"}], "explanations": {"丸い": "連体形。名詞「太陽」を修飾している。", "丸く": "連用形。「大きな丸く太陽」と名詞に直接続かない。", "丸さ": "名詞化。「大きな丸さ太陽」は成り立たない。", "丸め": "「丸める」の連用形。「大きな丸め太陽」は成り立たない。"}, "sentence_index": 0, "correct_answer": "丸い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は丸い三角のお皿を、テーブルの上に並べた。", "explanation": "ここは〈三角形〉の意味。三角形は角がある形なので、角がない形を表す「丸い」とは合わない。"}, {"text": "そのお店は丸い一日、ずっと空いていた。", "explanation": "ここは〈まる一日〉の意味。「丸い」は形を表すので、期間を表す「丸一日」の代わりには使えない。"}, {"text": "丸い四角形の箱が、棚の上に並んでいた。", "explanation": "ここは〈四角形〉の意味。四角形は角がある形なので、角がない形を表す「丸い」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51792, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丸い", "is_correct": true, "explanation": "連体形。名詞「目」を修飾している。"}, {"text": "丸ければ", "is_correct": false, "explanation": "仮定形。「丸ければ目で」と続かない。"}, {"text": "丸み", "is_correct": false, "explanation": "名詞。「丸み目」とは修飾できない。"}, {"text": "丸味", "is_correct": false, "explanation": "名詞。「丸味目」は成り立たない。"}], "explanations": {"丸い": "連体形。名詞「目」を修飾している。", "丸ければ": "仮定形。「丸ければ目で」と続かない。", "丸み": "名詞。「丸み目」とは修飾できない。", "丸味": "名詞。「丸味目」は成り立たない。"}, "sentence_index": 6, "correct_answer": "丸い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "丸い夢のように美しい景色が、目の前に広がっていた。", "explanation": "ここは〈まるで〜のようだ〉の比喩の意味。〈丸い〉は形を表すので、この使い方はできない。"}, {"text": "彼は丸い直線を、定規で一本引いた。", "explanation": "ここは〈まっすぐな線〉の意味（直線）。曲線で囲まれた形を表す「丸い」は、まっすぐな線には使えないので合わない。"}, {"text": "夜空には、丸い三日月が細く光っていた。", "explanation": "ここは〈細い弧〉の意味（三日月）。三日月は円形ではないので、円形を表す「丸い」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51792, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭に丸くテーブルを置いて、お茶を飲んだ。", "corrected_sentence": "庭に丸いテーブルを置いて、お茶を飲んだ。", "error_description": "名詞「テーブル」を修飾する連体形「丸い」が必要なのに、連用形「丸く」を使っている。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "丸い", "is_correct": true, "explanation": "連体形。名詞「皿」を修飾している。"}, {"text": "丸く", "is_correct": false, "explanation": "連用形。「丸く皿」と名詞に直接続かない。"}, {"text": "丸さ", "is_correct": false, "explanation": "名詞化。「丸さ皿」は成り立たない。"}, {"text": "丸ければ", "is_correct": false, "explanation": "仮定形。「丸ければ皿が」と文が続かない。"}], "correct_form": "丸い", "base_form": "丸い", "form_label": "連体形", "sentence_index": 1, "explanations": {"丸い": "連体形。名詞「皿」を修飾している。", "丸く": "連用形。「丸く皿」と名詞に直接続かない。", "丸さ": "名詞化。「丸さ皿」は成り立たない。", "丸ければ": "仮定形。「丸ければ皿が」と文が続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51792, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窓辺に丸ければ鉢植えを置いて、水をやった。", "corrected_sentence": "窓辺に丸い鉢植えを置いて、水をやった。", "error_description": "名詞「鉢植え」を修飾する連体形「丸い」が必要で、仮定形「丸ければ」は文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "丸く", "is_correct": true, "explanation": "連用形。「丸くなる」の形を作っている。"}, {"text": "丸い", "is_correct": false, "explanation": "終止形。「丸いなっている」とは続かない。"}, {"text": "丸かった", "is_correct": false, "explanation": "過去形。「丸かったなっている」は成り立たない。"}, {"text": "丸くない", "is_correct": false, "explanation": "否定形。「丸くないなっている」は不自然で、文が成り立たない。"}], "correct_form": "丸く", "base_form": "丸い", "form_label": "連用形", "sentence_index": 7, "explanations": {"丸く": "連用形。「丸くなる」の形を作っている。", "丸い": "終止形。「丸いなっている」とは続かない。", "丸かった": "過去形。「丸かったなっている」は成り立たない。", "丸くない": "否定形。「丸くないなっている」は不自然で、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
