INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51793, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "ものが見えるときの、明るさや暗さ、赤や青などのことです。", "primary_collocate": null, "pronunciation": "いろ", "ipa": "iɾo", "syllable_count": 2, "sentences": [{"text": "空の色が、夕方になると赤く変わっていく。", "target_word": "色", "complexity_tier": "T2", "furigana": "空[そら]の色[いろ]が、夕方[ゆうがた]になると赤[あか]く変[か]わっていく。", "sentence_source": "generated"}, {"text": "この服は、色が明るくて春らしい。", "target_word": "色", "complexity_tier": "T2", "furigana": "この服[ふく]は、色[いろ]が明[あか]るくて春[はる]らしい。", "sentence_source": "generated"}, {"text": "好きな色を一つ選んで、紙に塗ってください。", "target_word": "色", "complexity_tier": "T2", "furigana": "好[す]きな色[いろ]を一[ひと]つ選[えら]んで、紙[かみ]に塗[ぬ]ってください。", "sentence_source": "generated"}, {"text": "雨にぬれて、カーテンの色が濃くなった。", "target_word": "色", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれて、カーテンの色[いろ]が濃[こ]くなった。", "sentence_source": "generated"}, {"text": "壁の色を白から青に変えたら、部屋が涼しく見えた。", "target_word": "色", "complexity_tier": "T3", "furigana": "壁[かべ]の色[いろ]を白[しろ]から青[あお]に変[か]えたら、部屋[へや]が涼[すず]しく見[み]えた。", "sentence_source": "generated"}, {"text": "信号の色が赤に変わったら、止まらなければならない。", "target_word": "色", "complexity_tier": "T3", "furigana": "信号[しんごう]の色[いろ]が赤[あか]に変[か]わったら、止[と]まらなければならない。", "sentence_source": "generated"}, {"text": "秋になると、山の木々の色が少しずつ変わる。", "target_word": "色", "complexity_tier": "T3", "furigana": "秋[あき]になると、山[やま]の木々[きぎ]の色[いろ]が少[すこ]しずつ変[か]わる。", "sentence_source": "generated"}, {"text": "洗濯したら、シャツの色が薄くなってしまった。", "target_word": "色", "complexity_tier": "T3", "furigana": "洗濯[せんたく]したら、シャツの色[いろ]が薄[うす]くなってしまった。", "sentence_source": "generated"}, {"text": "この絵は、色の使い方がとてもきれいだ。", "target_word": "色", "complexity_tier": "T3", "furigana": "この絵[え]は、色[いろ]の使[つか]い方[かた]がとてもきれいだ。", "sentence_source": "generated"}, {"text": "夜は暗くて、ものの色がよく見えない。", "target_word": "色", "complexity_tier": "T3", "furigana": "夜[よる]は暗[くら]くて、ものの色[いろ]がよく見[み]えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "色", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ものの見える明るさ・暗さや赤・青などの色合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T1: 3 words above tier T1 (max 2): ぬれ (Zipf 3.24), カーテン (Zipf 3.84), 濃く (Zipf 3.74)']::text[], '0b8c837d-2fe6-4e39-ac26-de108440b430') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51793, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "色", "is_correct": true, "explanation": "〈空の色が、夕方になると赤く変わっていく〉の主語で、見えるときの色合いを表す。正解。"}, {"text": "匂い", "is_correct": false, "explanation": "匂いは嗅覚で感じるもので、赤く変わるという見た目の変化には合わない。"}, {"text": "音", "is_correct": false, "explanation": "音は聴覚で感じるもので、夕方に赤く変わるという文の意味に合わない。"}, {"text": "味", "is_correct": false, "explanation": "味は味覚で感じるもので、赤く変わるという見た目の変化とは結びつかない。"}], "explanations": {"色": "〈空の色が、夕方になると赤く変わっていく〉の主語で、見えるときの色合いを表す。正解。", "匂い": "匂いは嗅覚で感じるもので、赤く変わるという見た目の変化には合わない。", "音": "音は聴覚で感じるもので、夕方に赤く変わるという文の意味に合わない。", "味": "味は味覚で感じるもので、赤く変わるという見た目の変化とは結びつかない。"}, "sentence_index": 0, "correct_answer": "色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は色が辛くて、お酒によく合う。", "explanation": "ここは〈味〉の場面。辛さは味覚について言うので、〈色〉は合わない。"}, {"text": "この服は色が細かくて、大人っぽい。", "explanation": "ここは〈模様〉の場面。細かさは図柄について言うので、〈色〉を入れると合わない。"}, {"text": "この楽器は色が澄んでいて、遠くまで届く。", "explanation": "ここは〈音〉の場面。澄んだ響きは音について言うので、〈色〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51793, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "色", "is_correct": true, "explanation": "〈山の木々の色が少しずつ変わる〉の主語で、秋に変化する色合いを表す。正解。"}, {"text": "味", "is_correct": false, "explanation": "味は味覚で感じるもので、木々が変わるという見た目の変化には合わない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は生き物の重さを表すので、山の木々の変化には合わない。"}, {"text": "住所", "is_correct": false, "explanation": "住所は人や建物の所在を表すもので、木々が変わるという文の意味に合わない。"}], "explanations": {"色": "〈山の木々の色が少しずつ変わる〉の主語で、秋に変化する色合いを表す。正解。", "味": "味は味覚で感じるもので、木々が変わるという見た目の変化には合わない。", "体重": "体重は生き物の重さを表すので、山の木々の変化には合わない。", "住所": "住所は人や建物の所在を表すもので、木々が変わるという文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱は、色が丸くて持ちやすい。", "explanation": "ここは〈形〉の場面。丸さや四角さは形について言うので、〈色〉は合わない。"}, {"text": "この箱は色が重くて、運ぶのが大変だ。", "explanation": "ここは〈目方〉の場面。物の重さは目方で言うので、色には使えず合わない。"}, {"text": "窓から、夕焼けの色が部屋に香った。", "explanation": "ここは〈におい〉の場面。におい（匂い）は鼻で感じるもので、色には使えないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51793, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は絵の具の色が混ぜて、新しい色を作った。", "corrected_sentence": "彼は絵の具の色を混ぜて、新しい色を作った。", "error_description": "〈混ぜる〉の対象を示す〈を〉を〈が〉にしている。〈色が〉は主語になり、混ぜる動作の対象として文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51793, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この服は、洗うたびに色が薄いなっていく。", "corrected_sentence": "この服は、洗うたびに色が薄くなっていく。", "error_description": "形容詞〈薄い〉の連用形〈薄く〉が必要な場所で〈薄いな〉と活用させている。〈色が薄くなる〉の形で、〈なる〉に続けるには〈薄く〉が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd208385-18cd-4fc0-9a5f-d7237fb8935b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
