INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51795, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "みかんのような色のことです。", "primary_collocate": null, "pronunciation": "だいだいいろ", "ipa": "daidaiiɾo", "syllable_count": 6, "sentences": [{"text": "にんじんは橙色の野菜で、スープに入れるときれいだ。", "target_word": "橙色", "complexity_tier": "T2", "furigana": "にんじんは橙色[だいだいいろ]の野菜[やさい]で、スープに入[い]れるときれいだ。", "sentence_source": "generated"}, {"text": "私の好きな色は、みかんの皮のような橙色だ。", "target_word": "橙色", "complexity_tier": "T2", "furigana": "私[わたし]の好[す]きな色[いろ]は、みかんの皮[かわ]のような橙色[だいだいいろ]だ。", "sentence_source": "generated"}, {"text": "橙色のクレヨンで、かぼちゃの絵を描いた。", "target_word": "橙色", "complexity_tier": "T2", "furigana": "橙色[だいだいいろ]のクレヨンで、かぼちゃの絵[え]を描[か]いた。", "sentence_source": "generated"}, {"text": "弟は橙色の帽子をかぶって、公園へ遊びに行った。", "target_word": "橙色", "complexity_tier": "T2", "furigana": "弟[おとうと]は橙色[だいだいいろ]の帽子[ぼうし]をかぶって、公園[こうえん]へ遊[あそ]びに行[い]った。", "sentence_source": "generated"}, {"text": "柿が熟すと、緑色から橙色になる。", "target_word": "橙色", "complexity_tier": "T3", "furigana": "柿[かき]が熟[じゅく]すと、緑色[みどりいろ]から橙色[だいだいいろ]になる。", "sentence_source": "generated"}, {"text": "橙色のランドセルは、教室の中でもよく目立つ。", "target_word": "橙色", "complexity_tier": "T3", "furigana": "橙色[だいだいいろ]のランドセルは、教室[きょうしつ]の中[なか]でもよく目立[めだ]つ。", "sentence_source": "generated"}, {"text": "このジュースは橙色をしているが、味はりんごだ。", "target_word": "橙色", "complexity_tier": "T3", "furigana": "このジュースは橙色[だいだいいろ]をしているが、味[あじ]はりんごだ。", "sentence_source": "generated"}, {"text": "夕日が橙色に見えるのは、空気が光を変えるからだ。", "target_word": "橙色", "complexity_tier": "T4", "furigana": "夕日[ゆうひ]が橙色[だいだいいろ]に見[み]えるのは、空気[くうき]が光[ひかり]を変[か]えるからだ。", "sentence_source": "generated"}, {"text": "橙色の花が庭に咲いて、ミツバチが集まってきた。", "target_word": "橙色", "complexity_tier": "T3", "furigana": "橙色[だいだいいろ]の花[はな]が庭[にわ]に咲[さ]いて、ミツバチが集[あつ]まってきた。", "sentence_source": "generated"}, {"text": "赤と黄色の絵の具を混ぜたら、橙色になった。", "target_word": "橙色", "complexity_tier": "T3", "furigana": "赤[あか]と黄色[きいろ]の絵[え]の具[ぐ]を混[ま]ぜたら、橙色[だいだいいろ]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "橙色", "label": "基本形"}, {"form": "橙色の", "label": "連体形（の）"}, {"form": "橙色に", "label": "連用形（に）"}, {"form": "橙色だ", "label": "断定形"}], "register": "neutral", "sense_fingerprint": "みかんのような色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75dc4a76-6e0c-4270-8be6-dbde762e7e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51795, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "橙色", "is_correct": true, "explanation": "「の野菜」を修飾する名詞の基本形。にんじんの色を表す。"}, {"text": "橙色の", "is_correct": false, "explanation": "「の」が二つ続くことになり、「橙色のの野菜」は成り立たない。"}, {"text": "橙色を", "is_correct": false, "explanation": "「を」は目的語を示す。「は橙色をの野菜」では名詞を修飾できない。"}, {"text": "橙色が", "is_correct": false, "explanation": "「が」は主語を示す。「は橙色がの野菜」では「の野菜」が続かない。"}], "explanations": {"橙色": "「の野菜」を修飾する名詞の基本形。にんじんの色を表す。", "橙色の": "「の」が二つ続くことになり、「橙色のの野菜」は成り立たない。", "橙色を": "「を」は目的語を示す。「は橙色をの野菜」では名詞を修飾できない。", "橙色が": "「が」は主語を示す。「は橙色がの野菜」では「の野菜」が続かない。"}, "sentence_index": 0, "correct_answer": "橙色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この橙色は酸っぱくて、料理のソースに使える。", "explanation": "ここは果物の〈橙〉の意味。橙色は色の名前なので、酸っぱさや料理への使い道は表せない。"}, {"text": "友達の橙色の声が、教室の端まで響いた。", "explanation": "ここは〈黄色い声〉（甲高い声）の意味。橙色は色の名前なので、声の高さは表せない。"}, {"text": "あの人の言い訳は、橙色の嘘ばかりだ。", "explanation": "ここは〈真っ赤な嘘〉（明白な嘘）の慣用句の意味。橙色では嘘の明白さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51795, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "橙色", "is_correct": true, "explanation": "「をしている」の前に置く名詞の基本形。ジュースの色を表す。"}, {"text": "橙色に", "is_correct": false, "explanation": "「に」の後に「をしている」は続かない。「橙色にをしている」は成り立たない。"}, {"text": "橙色で", "is_correct": false, "explanation": "「で」は手段や場所を表す。「橙色でをしている」では「をしている」が続かない。"}, {"text": "橙色と", "is_correct": false, "explanation": "「と」は並列や引用を表す。「橙色とをしている」では文が成り立たない。"}], "explanations": {"橙色": "「をしている」の前に置く名詞の基本形。ジュースの色を表す。", "橙色に": "「に」の後に「をしている」は続かない。「橙色にをしている」は成り立たない。", "橙色で": "「で」は手段や場所を表す。「橙色でをしている」では「をしている」が続かない。", "橙色と": "「と」は並列や引用を表す。「橙色とをしている」では文が成り立たない。"}, "sentence_index": 6, "correct_answer": "橙色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は橙色の夢想に浸り、授業が耳に入らなかった。", "explanation": "ここは〈桃色の妄想〉（色恋の空想）の意味。橙色は色の名前なので、恋の空想の意味にはならない。"}, {"text": "この件は橙色に戻して、もう一度最初から練り直そう。", "explanation": "ここは〈白紙に戻す〉（なかったことにする）の意味。橙色は色名なので、白紙に戻す意味は表せない。"}, {"text": "今期の損益は橙色で、会社は大きく落ち込んだ。", "explanation": "ここは〈赤字〉（損失）の意味。損失の表現は〈赤〉で、橙色の色名は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51795, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方の山が橙色で染まり、とても静かだった。", "corrected_sentence": "夕方の山が橙色に染まり、とても静かだった。", "error_description": "誤りは「で」。染まる結果の色を表す「に」が正しい形。「で」は場所や手段を表すので、染まる先の色には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51795, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕焼けの空が橙色く燃えていた。", "corrected_sentence": "夕焼けの空が橙色に燃えていた。", "error_description": "誤りは「く」。「橙色」は名詞なので、様子を表すには「に」が必要。「く」は形容詞の活用で、名詞には付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
