INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51796, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "赤と黄色の間の色で、みかんの皮のような色。", "primary_collocate": null, "pronunciation": "だいだいいろ", "ipa": "daidaiiɾo", "syllable_count": 6, "sentences": [{"text": "現実の太陽は橙色だが、私が記憶の中で求める太陽は、情熱的で切ない赤色でなければならない。", "target_word": "橙色", "complexity_tier": "T4", "furigana": "現実[げんじつ]の太陽[たいよう]は橙色[だいだいいろ]だが、私[わたし]が記憶[きおく]の中[なか]で求[もと]める太陽[たいよう]は、情熱的[じょうねつてき]で切[せつ]ない赤色[あかいろ]でなければならない。", "sentence_source": "mined"}, {"text": "秋になると、公園の木の葉が橙色に変わる。", "target_word": "橙色", "complexity_tier": "T3", "furigana": "秋[あき]になると、公園[こうえん]の木[き]の葉[は]が橙色[だいだいいろ]に変[か]わる。", "sentence_source": "generated"}, {"text": "橙色のセーターを着ると、顔が明るく見える。", "target_word": "橙色", "complexity_tier": "T3", "furigana": "橙色[だいだいいろ]のセーターを着[き]ると、顔[かお]が明[あか]るく見[み]える。", "sentence_source": "generated"}, {"text": "夕方、空が橙色に染まって、街が静かになった。", "target_word": "橙色", "complexity_tier": "T3", "furigana": "夕方[ゆうがた]、空[そら]が橙色[だいだいいろ]に染[そ]まって、街[まち]が静[しず]かになった。", "sentence_source": "generated"}, {"text": "工事の人は、遠くからでも見えるように橙色の服を着ている。", "target_word": "橙色", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]は、遠[とお]くからでも見[み]えるように橙色[だいだいいろ]の服[ふく]を着[き]ている。", "sentence_source": "generated"}, {"text": "絵の具の赤と黄色を混ぜると、橙色ができる。", "target_word": "橙色", "complexity_tier": "T3", "furigana": "絵[え]の具[ぐ]の赤[あか]と黄色[きいろ]を混[ま]ぜると、橙色[だいだいいろ]ができる。", "sentence_source": "generated"}, {"text": "橙色のカーテンをつけたら、部屋が明るく暖かい感じになった。", "target_word": "橙色", "complexity_tier": "T3", "furigana": "橙色[だいだいいろ]のカーテンをつけたら、部屋[へや]が明[あか]るく暖[あたた]かい感[かん]じになった。", "sentence_source": "generated"}, {"text": "彼女は橙色のマフラーを巻いて、雪の中を歩いていた。", "target_word": "橙色", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は橙色[だいだいいろ]のマフラーを巻[ま]いて、雪[ゆき]の中[なか]を歩[ある]いていた。", "sentence_source": "generated"}, {"text": "金魚は赤いものより、橙色のものが好きだ。", "target_word": "橙色", "complexity_tier": "T2", "furigana": "金魚[きんぎょ]は赤[あか]いものより、橙色[だいだいいろ]のものが好[す]きだ。", "sentence_source": "generated"}, {"text": "橙色の灯りがついて、トンネルの中が少し明るくなった。", "target_word": "橙色", "complexity_tier": "T3", "furigana": "橙色[だいだいいろ]の灯[あか]りがついて、トンネルの中[なか]が少[すこ]し明[あか]るくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "橙色", "label": "基本形"}, {"form": "橙色の", "label": "連体形（の）"}, {"form": "橙色に", "label": "連用形（に）"}, {"form": "橙色だ", "label": "断定形"}], "register": "neutral", "sense_fingerprint": "赤と黄色の中間にある、みかんの皮のような色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75dc4a76-6e0c-4270-8be6-dbde762e7e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51796, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "橙色", "is_correct": true, "explanation": "「現実の太陽は〜だが」に入る名詞の基本形。太陽の色を表す。"}, {"text": "橙色の", "is_correct": false, "explanation": "連体形の「の」は後ろに名詞が続く形。「は橙色のだが」では文が成り立たない。"}, {"text": "橙色に", "is_correct": false, "explanation": "連用形の「に」は動詞や形容詞に続く形。「は橙色にだが」では続かない。"}, {"text": "橙色で", "is_correct": false, "explanation": "「で」は場所や手段を表す。「は橙色でだが」では文として続かない。"}], "explanations": {"橙色": "「現実の太陽は〜だが」に入る名詞の基本形。太陽の色を表す。", "橙色の": "連体形の「の」は後ろに名詞が続く形。「は橙色のだが」では文が成り立たない。", "橙色に": "連用形の「に」は動詞や形容詞に続く形。「は橙色にだが」では続かない。", "橙色で": "「で」は場所や手段を表す。「は橙色でだが」では文として続かない。"}, "sentence_index": 0, "correct_answer": "橙色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この橙色は皮が厚くて、ジャムに向いている。", "explanation": "ここは果物の〈橙〉の意味。橙色は色の名前なので、皮の厚さやジャムの話には合わない。"}, {"text": "彼女の橙色の声が、教室中に響き渡った。", "explanation": "ここは〈黄色い声〉（甲高い声）の意味。橙色は色の名前なので、声の高さは表せない。"}, {"text": "彼は橙色の嘘をつき、誰も疑わなかった。", "explanation": "ここは〈真っ赤な嘘〉（明白な嘘）の慣用句の意味。橙色では嘘の明白さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51796, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "橙色", "is_correct": true, "explanation": "「のカーテン」を修飾する名詞の基本形。カーテンの色を表す。"}, {"text": "橙色を", "is_correct": false, "explanation": "「を」は動詞の目的語を示す。「橙色をのカーテン」では名詞を修飾できない。"}, {"text": "橙色が", "is_correct": false, "explanation": "「が」は主語を示す格助詞。「橙色がのカーテン」では名詞を修飾できない。"}, {"text": "橙色は", "is_correct": false, "explanation": "「は」は主題を示す。「橙色はのカーテン」では名詞を修飾できない。"}], "explanations": {"橙色": "「のカーテン」を修飾する名詞の基本形。カーテンの色を表す。", "橙色を": "「を」は動詞の目的語を示す。「橙色をのカーテン」では名詞を修飾できない。", "橙色が": "「が」は主語を示す格助詞。「橙色がのカーテン」では名詞を修飾できない。", "橙色は": "「は」は主題を示す。「橙色はのカーテン」では名詞を修飾できない。"}, "sentence_index": 6, "correct_answer": "橙色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は橙色の妄想ばかりして、仕事が手につかなかった。", "explanation": "ここは〈桃色の妄想〉（色恋の空想）の意味。橙色は色の名前なので、恋の空想の意味にはならない。"}, {"text": "計画を一度橙色に戻し、最初から考え直すことにした。", "explanation": "ここは〈白紙に戻す〉（なかったことにする）の意味。橙色は色名なので、計画を白紙にする意味は表せない。"}, {"text": "今年の決算は橙色だった。", "explanation": "ここは〈赤字〉（決算の損失）の意味。決算の損失は〈赤〉で表すので、橙色は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51796, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝日が昇ると、空が橙色で変わった。", "corrected_sentence": "朝日が昇ると、空が橙色に変わった。", "error_description": "誤りは「で」。変化の結果を表す「に」が正しい形。「で」は場所や手段を表すので、変わる先の色には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51796, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋の夕暮れ、窓の外が橙色く輝いていた。", "corrected_sentence": "秋の夕暮れ、窓の外が橙色に輝いていた。", "error_description": "誤りは「く」。「橙色」は名詞なので、様子を表すには「に」が必要。「く」は形容詞の活用なので、名詞には付けられない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
