INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51797, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "赤い色のことです。", "primary_collocate": null, "pronunciation": "あかいろ", "ipa": "akaiɾo", "syllable_count": 4, "sentences": [{"text": "消防車は目立つように、全体が明るい赤色に塗られている。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "消防車[しょうぼうしゃ]は目立[めだ]つように、全体[ぜんたい]が明[あか]るい赤色[あかいろ]に塗[ぬ]られている。", "sentence_source": "generated"}, {"text": "郵便ポストは日本では赤色で、遠くからでもすぐ見つかる。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "郵便[ゆうびん]ポストは日本[にほん]では赤色[あかいろ]で、遠[とお]くからでもすぐ見[み]つかる。", "sentence_source": "generated"}, {"text": "この口紅は赤色が濃すぎて、普段の服には合わない。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "この口紅[くちべに]は赤色[あかいろ]が濃[こ]すぎて、普段[ふだん]の服[ふく]には合[あ]わない。", "sentence_source": "generated"}, {"text": "絵の具の赤色と黄色を混ぜると、オレンジ色ができる。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "絵[え]の具[ぐ]の赤色[あかいろ]と黄色[きいろ]を混[ま]ぜると、オレンジ色[いろ]ができる。", "sentence_source": "generated"}, {"text": "運動会では、赤色のチームが最後に逆転して勝った。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]では、赤色[あかいろ]のチームが最後[さいご]に逆転[ぎゃくてん]して勝[か]った。", "sentence_source": "generated"}, {"text": "カーテンを赤色から白に替えたら、部屋が明るくなった。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "カーテンを赤色[あかいろ]から白[しろ]に替[か]えたら、部屋[へや]が明[あか]るくなった。", "sentence_source": "generated"}, {"text": "彼は赤色のセーターを着ていたので、人混みでもすぐ分かった。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "彼[かれ]は赤色[あかいろ]のセーターを着[き]ていたので、人混[ひとご]みでもすぐ分[わ]かった。", "sentence_source": "generated"}, {"text": "国旗の真ん中にある赤色は、昇る太陽を表している。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "国旗[こっき]の真[ま]ん中[なか]にある赤色[あかいろ]は、昇[のぼ]る太陽[たいよう]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "冬の庭で、赤色の椿の花が雪の中に咲いていた。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "冬[ふゆ]の庭[にわ]で、赤色[あかいろ]の椿[つばき]の花[はな]が雪[ゆき]の中[なか]に咲[さ]いていた。", "sentence_source": "generated"}, {"text": "赤色のリンゴは甘そうに見えたので、迷わず買った。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "赤色[あかいろ]のリンゴは甘[あま]そうに見[み]えたので、迷[まよ]わず買[か]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "赤色", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "赤い色そのものを指す一般的な色名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75dc4a76-6e0c-4270-8be6-dbde762e7e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51797, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赤色", "is_correct": true, "explanation": "「明るい」に続く色名の基本形。消防車の塗りの色を表す。"}, {"text": "赤色の", "is_correct": false, "explanation": "連体形の「の」は後に名詞が続く形。「明るい赤色のに塗られている」では続かない。"}, {"text": "赤色を", "is_correct": false, "explanation": "「を」は目的語を示す。「明るい赤色をに塗られている」では文が成り立たない。"}, {"text": "赤色で", "is_correct": false, "explanation": "「で」は手段や場所を表す。「明るい赤色でに塗られている」では「に塗られている」が続かない。"}], "explanations": {"赤色": "「明るい」に続く色名の基本形。消防車の塗りの色を表す。", "赤色の": "連体形の「の」は後に名詞が続く形。「明るい赤色のに塗られている」では続かない。", "赤色を": "「を」は目的語を示す。「明るい赤色をに塗られている」では文が成り立たない。", "赤色で": "「で」は手段や場所を表す。「明るい赤色でに塗られている」では「に塗られている」が続かない。"}, "sentence_index": 0, "correct_answer": "赤色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は数学で赤色の点を取り、補習を受けた。", "explanation": "ここは〈赤点〉（不合格の成績）の意味。赤色は色の名前なので、成績の不合格は表せない。"}, {"text": "彼は公開の場で、赤色の恥をかいてしまった。", "explanation": "ここは〈赤っ恥〉（大恥）の意味。赤色は色の名前なので、恥の度合いは表せない。"}, {"text": "彼は昔の仲間を、赤色の他人のように無視した。", "explanation": "ここは〈赤の他人〉（まったくの他人）の意味。赤色は色の名前なので、関係の遠さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51797, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赤色", "is_correct": true, "explanation": "「のセーター」を修飾する名詞の基本形。セーターの色を表す。"}, {"text": "赤色に", "is_correct": false, "explanation": "「に」の後に「のセーター」は続かない。「赤色にのセーター」は不自然。"}, {"text": "赤色は", "is_correct": false, "explanation": "「は」は主題を示す。「赤色はのセーター」では名詞を修飾できない。"}, {"text": "赤色が", "is_correct": false, "explanation": "「が」は主語を示す。「赤色がのセーター」では名詞を修飾できない。"}], "explanations": {"赤色": "「のセーター」を修飾する名詞の基本形。セーターの色を表す。", "赤色に": "「に」の後に「のセーター」は続かない。「赤色にのセーター」は不自然。", "赤色は": "「は」は主題を示す。「赤色はのセーター」では名詞を修飾できない。", "赤色が": "「が」は主語を示す。「赤色がのセーター」では名詞を修飾できない。"}, "sentence_index": 6, "correct_answer": "赤色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は赤色の嘘を堂々とつき、誰も疑わなかった。", "explanation": "ここは〈真っ赤な嘘〉（明白な嘘）の慣用句の意味。赤色では嘘の明白さは表せない。"}, {"text": "子どもの頃は赤色の貧乏に耐えて暮らした。", "explanation": "ここは〈赤貧〉（ひどく貧しいこと）の意味。赤色は色なので、貧しさの程度は表せない。"}, {"text": "今期の損益は赤色で、会社は大きく落ち込んだ。", "explanation": "ここは〈赤字〉（損失）の意味。損失の表現は〈赤〉で、赤色の色名は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51797, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "踏切の警報灯は、赤色な点滅する。", "corrected_sentence": "踏切の警報灯は、赤色に点滅する。", "error_description": "誤りは「な」。「赤色」は名詞なので、様子を表すには「に」が正しい形。「な」は形容動詞の連体形で、名詞の後には付かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51797, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜の街灯は、ほんのり赤色く光っていた。", "corrected_sentence": "夜の街灯は、ほんのり赤色に光っていた。", "error_description": "誤りは「く」。「赤色」は名詞なので、様子を表すには「に」が必要。「く」は形容詞の活用で、名詞には付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
