INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51798, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "赤色は、血や太陽のような、あざやかで強い色を表す名詞です。", "primary_collocate": null, "pronunciation": "あかいろ", "ipa": "akaiɾo", "syllable_count": 4, "sentences": [{"text": "現実の太陽は橙色だが、私が記憶の中で求める太陽は、情熱的で切ない赤色でなければならない。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "現実[げんじつ]の太陽[たいよう]は橙色[だいだいいろ]だが、私[わたし]が記憶[きおく]の中[なか]で求[もと]める太陽[たいよう]は、情熱的[じょうねつてき]で切[せつ]ない赤色[あかいろ]でなければならない。", "sentence_source": "mined"}, {"text": "信号が赤色に変わったので、車は静かに止まった。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "信号[しんごう]が赤色[あかいろ]に変[か]わったので、車[くるま]は静[しず]かに止[と]まった。", "sentence_source": "generated"}, {"text": "彼女は赤色のスカーフを首に巻いて、駅で待っていた。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は赤色[あかいろ]のスカーフを首[くび]に巻[ま]いて、駅[えき]で待[ま]っていた。", "sentence_source": "generated"}, {"text": "夕焼けの空が赤色に染まり、町全体が燃えているようだった。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "夕焼[ゆうや]けの空[そら]が赤色[あかいろ]に染[そ]まり、町全体[まちぜんたい]が燃[も]えているようだった。", "sentence_source": "generated"}, {"text": "この絵では、背景の青と中心の赤色の対比が目を引く。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "この絵[え]では、背景[はいけい]の青[あお]と中心[ちゅうしん]の赤色[あかいろ]の対比[たいひ]が目[め]を引[ひ]く。", "sentence_source": "generated"}, {"text": "赤色のペンで間違いを直すと、先生に見やすいと言われた。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "赤色[あかいろ]のペンで間違[まちが]いを直[なお]すと、先生[せんせい]に見[み]やすいと言[い]われた。", "sentence_source": "generated"}, {"text": "秋になると、山の木の葉が黄色や赤色に変わる。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "秋[あき]になると、山[やま]の木[き]の葉[は]が黄色[きいろ]や赤色[あかいろ]に変[か]わる。", "sentence_source": "generated"}, {"text": "赤色の旗を振る係の人が、ゴールの場所を教えてくれた。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "赤色[あかいろ]の旗[はた]を振[ふ]る係[かかり]の人[ひと]が、ゴールの場所[ばしょ]を教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "私は赤色が好きなので、かばんも靴も同じ色にそろえた。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "私[わたし]は赤色[あかいろ]が好[す]きなので、かばんも靴[くつ]も同[おな]じ色[いろ]にそろえた。", "sentence_source": "generated"}, {"text": "トマトが十分に熟すと、皮は濃い赤色になる。", "target_word": "赤色", "complexity_tier": "T3", "furigana": "トマトが十分[じゅうぶん]に熟[じゅく]すと、皮[かわ]は濃[こ]い赤色[あかいろ]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "赤色", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "血や太陽を思わせる、あざやかで強い赤の色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75dc4a76-6e0c-4270-8be6-dbde762e7e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51798, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赤色", "is_correct": true, "explanation": "「情熱的で切ない〜でなければならない」に入る名詞の基本形。太陽の記憶の色を表す。"}, {"text": "赤色の", "is_correct": false, "explanation": "「の」は後ろに名詞が続く形。「切ない赤色のでなければならない」では文が成り立たない。"}, {"text": "赤色に", "is_correct": false, "explanation": "「に」は動詞や形容詞に続く形。「切ない赤色にでなければならない」では続かない。"}, {"text": "赤色を", "is_correct": false, "explanation": "「を」は目的語を示す。「切ない赤色をでなければならない」では文が成り立たない。"}], "explanations": {"赤色": "「情熱的で切ない〜でなければならない」に入る名詞の基本形。太陽の記憶の色を表す。", "赤色の": "「の」は後ろに名詞が続く形。「切ない赤色のでなければならない」では文が成り立たない。", "赤色に": "「に」は動詞や形容詞に続く形。「切ない赤色にでなければならない」では続かない。", "赤色を": "「を」は目的語を示す。「切ない赤色をでなければならない」では文が成り立たない。"}, "sentence_index": 0, "correct_answer": "赤色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今期の決算は赤色で、会社は大きな損失を出した。", "explanation": "ここは〈赤字〉（損失）の意味。赤色は色の名前なので、決算の損失を表す言い方にはならない。"}, {"text": "彼は赤色の嘘をついて、周りを驚かせた。", "explanation": "ここは〈真っ赤な嘘〉（明白な嘘）の慣用句の意味。赤色は嘘の強さを表せないので、この言い方はしない。"}, {"text": "彼は自分の失敗を、赤色の告白として淡々と語った。", "explanation": "ここは〈赤裸々〉（ありのままで隠さないこと）の意味。赤色は色の名前なので、率直さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51798, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赤色", "is_correct": true, "explanation": "「黄色や〜に変わる」に入る色名の基本形。葉の色の変化先を表す。"}, {"text": "赤色で", "is_correct": false, "explanation": "「で」の後に「に変わる」は続かない。手段や場所を表すので合わない。"}, {"text": "赤色が", "is_correct": false, "explanation": "「が」は主語を示す。「黄色や赤色がに変わる」では文が成り立たない。"}, {"text": "赤色は", "is_correct": false, "explanation": "「は」は主題を示す。「黄色や赤色はに変わる」では続かない。"}], "explanations": {"赤色": "「黄色や〜に変わる」に入る色名の基本形。葉の色の変化先を表す。", "赤色で": "「で」の後に「に変わる」は続かない。手段や場所を表すので合わない。", "赤色が": "「が」は主語を示す。「黄色や赤色がに変わる」では文が成り立たない。", "赤色は": "「は」は主題を示す。「黄色や赤色はに変わる」では続かない。"}, "sentence_index": 6, "correct_answer": "赤色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あの店員は、私にとって赤色の他人だ。", "explanation": "ここは〈赤の他人〉（まったくの他人）の意味。赤色は色の名前で、人間関係の強調には使えない。"}, {"text": "彼の家は赤色の貧乏で、食べるものにも困っていた。", "explanation": "ここは〈赤貧〉（ひどく貧しいこと）の意味。赤色は色なので、貧しさの程度は表せない。"}, {"text": "彼は皆の前で、赤色の恥をかいてしまった。", "explanation": "ここは〈赤っ恥〉（大恥）の意味。赤色は色の名前なので、恥の度合いは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51798, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "信号機の赤色を、雨の中で鮮やかに光った。", "corrected_sentence": "信号機の赤色が、雨の中で鮮やかに光った。", "error_description": "誤りは「を」。主語の「が」が正しい形。「を」は他動詞の目的語を示すので、自動詞の「光る」には使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51798, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕焼けの山が、濃い赤色く染まっていた。", "corrected_sentence": "夕焼けの山が、濃い赤色に染まっていた。", "error_description": "誤りは「く」。「赤色」は名詞なので、染まる様子を表すには「に」が必要。「く」は形容詞の活用で、名詞には付かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51803, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜に見える」の「に」で、見え方の内容を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語。「見える」は目的語を取らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、「見えた」の内容にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「見えた」の内容にはならない。"}], "correct_answer": "に", "explanations": {"に": "「〜に見える」の「に」で、見え方の内容を表す。", "を": "「を」は目的語。「見える」は目的語を取らない。", "で": "「で」は手段や場所を示し、「見えた」の内容にはならない。", "へ": "「へ」は方向を示し、「見えた」の内容にはならない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51803, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「つくる」の目的語を示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語で、「つくって」の目的語にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示し、目的語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示し、ここでは合わない。"}], "correct_answer": "を", "explanations": {"を": "「つくる」の目的語を示す。", "が": "「が」は主語で、「つくって」の目的語にはならない。", "と": "「と」は相手や並列を示し、目的語にはならない。", "より": "「より」は比較を示し、ここでは合わない。"}, "error_tags": {"が": "主語", "と": "相手・並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51803, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "まるい形のことです。", "primary_collocate": null, "pronunciation": "えん", "ipa": "eɴ", "syllable_count": 2, "sentences": [{"text": "ケーキの上にクリームで円を描くと、見た目がかわいくなる。", "target_word": "円", "complexity_tier": "T3", "furigana": "ケーキの上[うえ]にクリームで円[えん]を描[えが]くと、見[み]た目[め]がかわいくなる。", "sentence_source": "generated"}, {"text": "月が雲の間から、ほとんど完全な円に見えた。", "target_word": "円", "complexity_tier": "T3", "furigana": "月[つき]が雲[くも]の間[あいだ]から、ほとんど完全[かんぜん]な円[えん]に見[み]えた。", "sentence_source": "generated"}, {"text": "木の切り株を見ると、年輪が何重もの円になっている。", "target_word": "円", "complexity_tier": "T3", "furigana": "木[き]の切[き]り株[かぶ]を見[み]ると、年輪[ねんりん]が何重[なんじゅう]もの円[えん]になっている。", "sentence_source": "generated"}, {"text": "地面に棒で円を描いて、その中で遊ぶことにした。", "target_word": "円", "complexity_tier": "T3", "furigana": "地面[じめん]に棒[ぼう]で円[えん]を描[えが]いて、その中[なか]で遊[あそ]ぶことにした。", "sentence_source": "generated"}, {"text": "雨粒が落ちるたびに、水たまりに円が次々と生まれた。", "target_word": "円", "complexity_tier": "T3", "furigana": "雨粒[あまつぶ]が落[お]ちるたびに、水[みず]たまりに円[えん]が次々[つぎつぎ]と生[う]まれた。", "sentence_source": "generated"}, {"text": "犬は私のまわりを円を描くように走り回った。", "target_word": "円", "complexity_tier": "T3", "furigana": "犬[いぬ]は私[わたし]のまわりを円[えん]を描[えが]くように走[はし]り回[まわ]った。", "sentence_source": "generated"}, {"text": "この模様は、大小の円が重なってできている。", "target_word": "円", "complexity_tier": "T3", "furigana": "この模様[もよう]は、大小[だいしょう]の円[えん]が重[かさ]なってできている。", "sentence_source": "generated"}, {"text": "みんなで大きな円をつくって、ダンスを始めた。", "target_word": "円", "complexity_tier": "T3", "furigana": "みんなで大[おお]きな円[えん]をつくって、ダンスを始[はじ]めた。", "sentence_source": "generated"}, {"text": "テーブルの上に、コップの水で小さな円ができた。", "target_word": "円", "complexity_tier": "T3", "furigana": "テーブルの上[うえ]に、コップの水[みず]で小[ちい]さな円[えん]ができた。", "sentence_source": "generated"}, {"text": "紙に印をつけてはさみで切ると、きれいな円に仕上がる。", "target_word": "円", "complexity_tier": "T3", "furigana": "紙[かみ]に印[しるし]をつけてはさみで切[き]ると、きれいな円[えん]に仕上[しあ]がる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "円", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ぐるりと丸くつながった形や図形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: contains vocabulary far above tier T1: 雨粒 (Zipf 2.42)']::text[], '75dc4a76-6e0c-4270-8be6-dbde762e7e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51803, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "円", "is_correct": true, "explanation": "クリームで描く丸い図形として「円」が合う。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は「書く」もので、クリームで「描く」とは言わない。"}, {"text": "歌", "is_correct": false, "explanation": "歌はクリームで描くものではなく、この文に合わない。"}, {"text": "文章", "is_correct": false, "explanation": "文章は「書く」もので、「描く」とは続かない。"}], "explanations": {"円": "クリームで描く丸い図形として「円」が合う。", "手紙": "手紙は「書く」もので、クリームで「描く」とは言わない。", "歌": "歌はクリームで描くものではなく、この文に合わない。", "文章": "文章は「書く」もので、「描く」とは続かない。"}, "sentence_index": 0, "correct_answer": "円"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "車の円を握って、ゆっくり走らせた。", "explanation": "ここは〈ハンドル〉の意味（運転の操作部）。運転で握る部品は〈ハンドル〉と言い、〈円〉は形の名前で部品名にはならない。"}, {"text": "指輪の円に、小さな傷がついた。", "explanation": "ここは〈輪〉の意味。指輪のような中が空いた輪は〈輪〉と言い、〈円〉は使わない。"}, {"text": "強く打つと、野球の円が外野まで飛んだ。", "explanation": "ここは〈球〉の意味。ボールのような立体は〈球〉で、平面の図形を指す〈円〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51803, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "円", "is_correct": true, "explanation": "大小の丸い図形が重なる模様として「円」が合う。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は重なって模様を作るものではなく、文の内容に合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子が重なってできる模様という意味にはならない。"}, {"text": "手袋", "is_correct": false, "explanation": "手袋が重なって模様になるという文脈には合わない。"}], "explanations": {"円": "大小の丸い図形が重なる模様として「円」が合う。", "鍵": "鍵は重なって模様を作るものではなく、文の内容に合わない。", "椅子": "椅子が重なってできる模様という意味にはならない。", "手袋": "手袋が重なって模様になるという文脈には合わない。"}, "sentence_index": 6, "correct_answer": "円"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コートの円を留めて、寒い外へ出た。", "explanation": "ここは〈ボタン〉の意味。服を留める部品は〈ボタン〉と言い、〈円〉は形の名前で部品名にはならない。"}, {"text": "レコードの円に針を落とした。", "explanation": "ここは〈盤〉（円盤状の物）の意味。〈円〉は形を表し、物そのものを指す言い方にはならない。"}, {"text": "ラジオの円を回して、音量を上げた。", "explanation": "ここは〈つまみ〉の意味（回して操作する部品）。〈円〉は形の名前で部品名にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51803, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "コンパスで、きれいな円が描いた。", "corrected_sentence": "コンパスで、きれいな円を描いた。", "error_description": "「描く」の目的語は「を」で示す。「円が」は主語を示すため誤り（正：円を描いた）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51803, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ノートに大きな円に描き、中に名前を書いた。", "corrected_sentence": "ノートに大きな円を描き、中に名前を書いた。", "error_description": "「描く」は「円を」と目的語を取る。「円に描き」は誤りで、正しくは「円を描き」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51804, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「描く」の目的語を示す。ここで正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すが、「描く」の目的語にはならない。"}, {"text": "が", "is_correct": false, "explanation": "「円が」は主語になり、「描いた」の目的語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「描く」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「描く」の目的語を示す。ここで正しい。", "に": "「に」は場所や相手を示すが、「描く」の目的語にはならない。", "が": "「円が」は主語になり、「描いた」の目的語にはならない。", "へ": "「へ」は方向を示し、「描く」の目的語にはならない。"}, "error_tags": {"に": "場所・相手", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51804, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜になって」の「に」で、変化の結果を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語で、「なって」には続かない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示し、「なって」の相手にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を続けるだけで、「なって」とは続かない。"}], "correct_answer": "に", "explanations": {"に": "「〜になって」の「に」で、変化の結果を表す。", "を": "「を」は目的語で、「なって」には続かない。", "で": "「で」は手段や場所を示し、「なって」の相手にはならない。", "の": "「の」は名詞を続けるだけで、「なって」とは続かない。"}, "error_tags": {"を": "目的語", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51804, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "円形。丸い形。", "primary_collocate": null, "pronunciation": "えん", "ipa": "eɴ", "syllable_count": 2, "sentences": [{"text": "力強く円を描くことで、言葉にできない思春期の焦燥感が、少しずつ紙の上へ溶け出していくようだった。", "target_word": "円", "complexity_tier": "T3", "furigana": "力強[ちからづよ]く円[えん]を描[えが]くことで、言葉[ことば]にできない思春期[ししゅんき]の焦燥感[しょうそうかん]が、少[すこ]しずつ紙[かみ]の上[うえ]へ溶[と]け出[だ]していくようだった。", "sentence_source": "mined"}, {"text": "先生は黒板にチョークで大きな円を描いた。", "target_word": "円", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]にチョークで大[おお]きな円[えん]を描[えが]いた。", "sentence_source": "generated"}, {"text": "子どもたちは円になって座り、先生の話を聞いた。", "target_word": "円", "complexity_tier": "T3", "furigana": "子[こ]どもたちは円[えん]になって座[すわ]り、先生[せんせい]の話[はなし]を聞[き]いた。", "sentence_source": "generated"}, {"text": "コンパスを使えば、きれいな円を簡単に描ける。", "target_word": "円", "complexity_tier": "T3", "furigana": "コンパスを使[つか]えば、きれいな円[えん]を簡単[かんたん]に描[えが]ける。", "sentence_source": "generated"}, {"text": "池に小石を投げると、水面に小さな円が広がった。", "target_word": "円", "complexity_tier": "T3", "furigana": "池[いけ]に小石[こいし]を投[な]げると、水面[すいめん]に小[ちい]さな円[えん]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "この図で、円の中心から縁までの長さはどこも同じだ。", "target_word": "円", "complexity_tier": "T3", "furigana": "この図[ず]で、円[えん]の中心[ちゅうしん]から縁[ふち]までの長[なが]さはどこも同じだ。", "sentence_source": "generated"}, {"text": "友達と手をつないで円を作り、まわりながら歌った。", "target_word": "円", "complexity_tier": "T3", "furigana": "友達[ともだち]と手[て]をつないで円[えん]を作[つく]り、まわりながら歌[うた]った。", "sentence_source": "generated"}, {"text": "机の上のコップの跡が、白い円になって残っていた。", "target_word": "円", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]のコップの跡[あと]が、白[しろ]い円[えん]になって残[のこ]っていた。", "sentence_source": "generated"}, {"text": "地図に赤いペンで円を書き、集合場所を示した。", "target_word": "円", "complexity_tier": "T3", "furigana": "地図[ちず]に赤[あか]いペンで円[えん]を書[か]き、集合場所[しゅうごうばしょ]を示[しめ]した。", "sentence_source": "generated"}, {"text": "鳥は高い空で大きな円を描くように飛んでいた。", "target_word": "円", "complexity_tier": "T3", "furigana": "鳥[とり]は高[たか]い空[そら]で大[おお]きな円[えん]を描[えが]くように飛[と]んでいた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "円", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "中心から等しい距離にある、丸い図形や形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 力強く (Zipf 3.37), 思春 (Zipf 3.69), 焦燥 (Zipf 2.87)']::text[], '75dc4a76-6e0c-4270-8be6-dbde762e7e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51804, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "円", "is_correct": true, "explanation": "「描く」の対象として、丸い図形を表す「円」が文脈に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "手紙は「書く」ものなので、「描く」の対象にはならない。"}, {"text": "文章", "is_correct": false, "explanation": "文章も「書く」ものなので、「描く」とは続かない。"}, {"text": "歌", "is_correct": false, "explanation": "歌は「歌う」「作る」もので、「描く」の対象にならない。"}], "explanations": {"円": "「描く」の対象として、丸い図形を表す「円」が文脈に合う。", "手紙": "手紙は「書く」ものなので、「描く」の対象にはならない。", "文章": "文章も「書く」ものなので、「描く」とは続かない。", "歌": "歌は「歌う」「作る」もので、「描く」の対象にならない。"}, "sentence_index": 0, "correct_answer": "円"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "シャツの円を留めて、外出の準備を整えた。", "explanation": "ここは〈ボタン〉の意味。服を留める小さな部品は〈ボタン〉と言い、〈円〉は形の名前で部品名にはならない。"}, {"text": "ゴムの円をほどいて、髪をまとめ直した。", "explanation": "ここは〈輪〉の意味。中が空いたリング状のものは〈輪〉と言うので、〈円〉は使わない。"}, {"text": "ボールを強く投げると、円が後ろの壁に当たった。", "explanation": "ここは〈球〉の意味。ボールのような立体は〈球〉で、平面の図形を指す〈円〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51804, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "円", "is_correct": true, "explanation": "手をつないで作る丸い輪の形として「円」が合う。"}, {"text": "料理", "is_correct": false, "explanation": "料理は手をつないで作るものではなく、この場面に合わない。"}, {"text": "写真", "is_correct": false, "explanation": "写真は「撮る」もので、手をつないで作る形に合わない。"}, {"text": "地図", "is_correct": false, "explanation": "地図は手をつないで作れるものではなく、場面に合わない。"}], "explanations": {"円": "手をつないで作る丸い輪の形として「円」が合う。", "料理": "料理は手をつないで作るものではなく、この場面に合わない。", "写真": "写真は「撮る」もので、手をつないで作る形に合わない。", "地図": "地図は手をつないで作れるものではなく、場面に合わない。"}, "sentence_index": 6, "correct_answer": "円"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "陸上部の彼は、円を遠くへ投げる練習を毎日続けた。", "explanation": "ここは〈円盤〉の意味（円盤投げの道具）。投げる平たい物は〈円盤〉と言い、〈円〉は形の名前で物の名前にはならない。"}, {"text": "ボクシングの選手が、円に上がって試合を始めた。", "explanation": "ここは〈リング〉の意味。四角い試合場を指す〈リング〉を、図形の〈円〉で言い換えると合わない。"}, {"text": "テレビの円を回して、チャンネルを変えた。", "explanation": "ここは〈つまみ〉の意味（回して操作する部品）。〈円〉は形の名前で部品名にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51804, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の水たまりに、小さな円が広げた。", "corrected_sentence": "雨の水たまりに、小さな円が広がった。", "error_description": "「円が」が主語のため、他動詞「広げる」は使えない。主語の「円」には自動詞「広がる」を用いる（正：広がった）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51804, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "黒板に大きな円に描いて、班の場所を決めた。", "corrected_sentence": "黒板に大きな円を描いて、班の場所を決めた。", "error_description": "「描く」の目的語は「を」で示す。「円に」は誤りで、正しくは「円を描いて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51807, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「から」は理由・きっかけを示し、「焦燥から」で文の原因になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語で、「焦燥を」は原因を示せない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語で、「焦燥が」は原因の表し方として合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、原因にはならない。"}], "correct_answer": "から", "explanations": {"から": "「から」は理由・きっかけを示し、「焦燥から」で文の原因になる。", "を": "「を」は目的語で、「焦燥を」は原因を示せない。", "が": "「が」は主語で、「焦燥が」は原因の表し方として合わない。", "へ": "「へ」は方向を示し、原因にはならない。"}, "error_tags": {"を": "目的語", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51807, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「耐える」の対象を示す「に」。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示し、耐える対象にはならない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示し、ここでは合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するだけで、耐える対象を示さない。"}], "correct_answer": "に", "explanations": {"に": "「耐える」の対象を示す「に」。", "と": "「と」は相手や並列を示し、耐える対象にはならない。", "より": "「より」は比較を示し、ここでは合わない。", "の": "「の」は名詞を修飾するだけで、耐える対象を示さない。"}, "error_tags": {"と": "相手・並列", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51807, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いらいらして、おちつかないこと。", "primary_collocate": null, "pronunciation": "しょうそう", "ipa": "ɕoːsoː", "syllable_count": 4, "sentences": [{"text": "約束の時間を過ぎても連絡がなく、母は焦燥を隠せなかった。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "約束[やくそく]の時間[じかん]を過[す]ぎても連絡[れんらく]がなく、母[はは]は焦燥[しょうそう]を隠[かく]せなかった。", "sentence_source": "generated"}, {"text": "結果が出ない焦燥から、彼はつい弟にきつく当たってしまった。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "結果[けっか]が出[で]ない焦燥[しょうそう]から、彼[かれ]はつい弟[おとうと]にきつく当[あ]たってしまった。", "sentence_source": "generated"}, {"text": "スタートの合図を待つ間、選手たちは焦燥と緊張に包まれていた。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "スタートの合図[あいず]を待[ま]つ間[あいだ]、選手[せんしゅ]たちは焦燥[しょうそう]と緊張[きんちょう]に包[つつ]まれていた。", "sentence_source": "generated"}, {"text": "彼女は焦燥に駆られて、何度も時計を見た。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は焦燥[しょうそう]に駆[か]られて、何度[なんど]も時計[とけい]を見[み]た。", "sentence_source": "generated"}, {"text": "電車が止まったまま動かず、乗客の間に焦燥が広がった。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が止[と]まったまま動[うご]かず、乗客[じょうきゃく]の間[あいだ]に焦燥[しょうそう]が広[ひろ]がった。", "sentence_source": "generated"}, {"text": "焦燥を感じたときは、まず水を飲んで落ち着くようにしている。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "焦燥[しょうそう]を感[かん]じたときは、まず水[みず]を飲[の]んで落[お]ち着[つ]くようにしている。", "sentence_source": "generated"}, {"text": "夢が遠く思えるたび、私は胸の中で焦燥が大きくなるのを感じた。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "夢[ゆめ]が遠[とお]く思[おも]えるたび、私[わたし]は胸[むね]の中[なか]で焦燥[しょうそう]が大[おお]きくなるのを感[かん]じた。", "sentence_source": "generated"}, {"text": "長い待ち時間の焦燥に耐えきれず、彼は席を立った。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "長[なが]い待[ま]ち時間[じかん]の焦燥[しょうそう]に耐[た]えきれず、彼[かれ]は席[せき]を立[た]った。", "sentence_source": "generated"}, {"text": "部長の顔には、取引先を待つ焦燥がはっきり表れていた。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "部長[ぶちょう]の顔[かお]には、取引先[とりひきさき]を待[ま]つ焦燥[しょうそう]がはっきり表[あらわ]れていた。", "sentence_source": "generated"}, {"text": "焦燥の日々が続いたが、友人の言葉でやっと心が軽くなった。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "焦燥[しょうそう]の日々[ひび]が続[つづ]いたが、友人[ゆうじん]の言葉[ことば]でやっと心[こころ]が軽[かる]くなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "焦燥", "label": "基本形"}], "register": "formal", "sense_fingerprint": "待ち時間や遅れなどで、いらいらして落ち着けない状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75dc4a76-6e0c-4270-8be6-dbde762e7e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51807, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焦燥", "is_correct": true, "explanation": "「焦燥を隠す」で、落ち着かない気持ちを隠せない意味になる。"}, {"text": "天気", "is_correct": false, "explanation": "天気は隠すものではなく、この文に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "季節は隠せるものではなく、文脈に合わない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "夕焼けは隠す対象にならず、文に合わない。"}], "explanations": {"焦燥": "「焦燥を隠す」で、落ち着かない気持ちを隠せない意味になる。", "天気": "天気は隠すものではなく、この文に合わない。", "季節": "季節は隠せるものではなく、文脈に合わない。", "夕焼け": "夕焼けは隠す対象にならず、文に合わない。"}, "sentence_index": 0, "correct_answer": "焦燥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "双眼鏡の焦燥を合わせて、鳥を見つけた。", "explanation": "ここは〈焦点〉の意味（ピント）。レンズの位置を合わせる対象は〈焦点〉で、〈焦燥〉は気持ちの言葉なので合わない。"}, {"text": "合格の通知を見て、彼は焦燥で胸をなで下ろした。", "explanation": "ここは〈安堵〉の意味。ほっとして胸をなで下ろすので〈安堵〉を使う。〈焦燥〉はいらだつ気持ちで、この文脈では逆の意味になる。"}, {"text": "鍋の底の焦燥がこびりついて、洗うのが大変だった。", "explanation": "ここは〈焦げ〉の意味。鍋の焦げ付きを指し、〈焦燥〉は気持ちの言葉なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51807, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焦燥", "is_correct": true, "explanation": "胸の中で大きくなる、いらだつ気持ちとして「焦燥」が合う。"}, {"text": "鍵", "is_correct": false, "explanation": "鍵は胸の中で大きくなる気持ちを表さない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は胸の中で大きくなるものではない。"}, {"text": "切手", "is_correct": false, "explanation": "切手は気持ちではなく、大きくなる対象にならない。"}], "explanations": {"焦燥": "胸の中で大きくなる、いらだつ気持ちとして「焦燥」が合う。", "鍵": "鍵は胸の中で大きくなる気持ちを表さない。", "椅子": "椅子は胸の中で大きくなるものではない。", "切手": "切手は気持ちではなく、大きくなる対象にならない。"}, "sentence_index": 6, "correct_answer": "焦燥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の休暇を、焦燥を満喫しながら過ごした。", "explanation": "ここは〈満喫〉（楽しみを十分に味わう）の意味。焦燥はいらだつ気持ちで、味わって楽しむ対象にはならない。"}, {"text": "空襲のあと、町は一面の焦燥になった。", "explanation": "ここは〈焦土〉の意味（焼け野原）。〈焦燥〉は気持ちの言葉で、場所の状態には使わない。"}, {"text": "食べすぎて、お腹が焦燥になった。", "explanation": "ここは〈満腹〉の意味。〈焦燥〉は気持ちの言葉で、おなかがいっぱいの状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51807, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "バスが来ず、乗客は焦燥を襲われていた。", "corrected_sentence": "バスが来ず、乗客は焦燥に襲われていた。", "error_description": "「襲われる」は「〜に襲われる」と「に」を取る。「焦燥を」は誤りで、正しくは「焦燥に襲われて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51807, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "改札の前で、待つ人々の焦燥を高まっていった。", "corrected_sentence": "改札の前で、待つ人々の焦燥が高まっていった。", "error_description": "「高まる」は主語が「焦燥が」の自動詞。「焦燥を」は誤りで、正しくは「焦燥が高まっていった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
