INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51808, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「描かれている」の主語を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示し、「描かれている」とは続かない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示し、ここでは合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、受け身「描かれている」の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "「描かれている」の主語を示す。", "へ": "「へ」は方向を示し、「描かれている」とは続かない。", "より": "「より」は比較を示し、ここでは合わない。", "を": "「を」は目的語を示すが、受け身「描かれている」の主語にはならない。"}, "error_tags": {"へ": "方向", "より": "比較", "を": "目的語（受け身の主語にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51808, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "気持ちが落ち着かず、いらいらすること。", "primary_collocate": null, "pronunciation": "しょうそう", "ipa": "ɕoːsoː", "syllable_count": 4, "sentences": [{"text": "夜の電話を待つ間、彼の胸は焦燥に締めつけられていた。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "夜[よる]の電話[でんわ]を待[ま]つ間[あいだ]、彼[かれ]の胸[むね]は焦燥[しょうそう]に締[し]めつけられていた。", "sentence_source": "generated"}, {"text": "試験の日が近づくにつれ、彼の顔には焦燥の色が濃くなった。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "試験[しけん]の日[ひ]が近[ちか]づくにつれ、彼[かれ]の顔[かお]には焦燥[しょうそう]の色[いろ]が濃[こ]くなった。", "sentence_source": "generated"}, {"text": "何も進まない毎日に、彼女は焦燥を覚えた。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "何[なに]も進[すす]まない毎日[まいにち]に、彼女[かのじょ]は焦燥[しょうそう]を覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "同期が次々と昇進するのを見て、焦燥に駆られた。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "同期[どうき]が次々[つぎつぎ]と昇進[しょうしん]するのを見[み]て、焦燥[しょうそう]に駆[か]られた。", "sentence_source": "generated"}, {"text": "返事が来ないまま三日が過ぎ、焦燥は強まるばかりだった。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "返事[へんじ]が来[こ]ないまま三日[みっか]が過[す]ぎ、焦燥[しょうそう]は強[つよ]まるばかりだった。", "sentence_source": "generated"}, {"text": "焦燥のあまり、彼は夜中に何度も部屋の中を歩き回った。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "焦燥[しょうそう]のあまり、彼[かれ]は夜中[よなか]に何度[なんど]も部屋[へや]の中[なか]を歩[ある]き回[まわ]った。", "sentence_source": "generated"}, {"text": "焦燥を抑えようと、深呼吸をして窓の外を眺めた。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "焦燥[しょうそう]を抑[おさ]えようと、深呼吸[しんこきゅう]をして窓[まど]の外[そと]を眺[なが]めた。", "sentence_source": "generated"}, {"text": "彼の小説には、若者の孤独と焦燥が静かに描かれている。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "彼[かれ]の小説[しょうせつ]には、若者[わかもの]の孤独[こどく]と焦燥[しょうそう]が静[しず]かに描[えが]かれている。", "sentence_source": "generated"}, {"text": "締め切りが迫り、焦燥と疲れで手が止まってしまった。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "締[し]め切[き]りが迫[せま]り、焦燥[しょうそう]と疲[つか]れで手[て]が止[と]まってしまった。", "sentence_source": "generated"}, {"text": "焦燥に満ちた声で、彼は何度も同じ質問を繰り返した。", "target_word": "焦燥", "complexity_tier": "T3", "furigana": "焦燥[しょうそう]に満[み]ちた声[こえ]で、彼[かれ]は何度[なんど]も同[おな]じ質問[しつもん]を繰[く]り返[かえ]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "焦燥", "label": "基本形"}], "register": "formal", "sense_fingerprint": "思うようにならず、心が落ち着かずいらいらする気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75dc4a76-6e0c-4270-8be6-dbde762e7e6a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51808, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焦燥", "is_correct": true, "explanation": "胸を締めつける、いらだつ落ち着かない気持ちとして「焦燥」が合う。"}, {"text": "玉子", "is_correct": false, "explanation": "「玉子感」という言い方はなく、感情を表す語として合わない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は感情を表す語ではなく、「感」とも続かない。"}, {"text": "石", "is_correct": false, "explanation": "石は感情ではなく、「〜感」の形にならない。"}], "explanations": {"焦燥": "胸を締めつける、いらだつ落ち着かない気持ちとして「焦燥」が合う。", "玉子": "「玉子感」という言い方はなく、感情を表す語として合わない。", "天井": "天井は感情を表す語ではなく、「感」とも続かない。", "石": "石は感情ではなく、「〜感」の形にならない。"}, "sentence_index": 0, "correct_answer": "焦燥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カメラの焦燥を合わせて、花の写真を撮った。", "explanation": "ここは〈焦点〉の意味（ピント）。ピントを合わせる対象は〈焦点〉で、〈焦燥〉は気持ちを表す語なので合わない。"}, {"text": "空襲で街は焼かれ、一面が焦燥と化した。", "explanation": "ここは〈焦土〉の意味（焼け野原）。〈焦燥〉は気持ちの言葉で、焼けた土地の状態には使わない。"}, {"text": "鍋の底に焦燥がこびりついて、取れなくなった。", "explanation": "ここは〈焦げ〉の意味。鍋の焦げ付きは〈焦げ〉と言い、〈焦燥〉は気持ちを表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51808, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焦燥", "is_correct": true, "explanation": "「焦燥を抑える」で、いらだつ気持ちを抑える意味になる。"}, {"text": "窓", "is_correct": false, "explanation": "窓は抑える対象にならず、文の意味に合わない。"}, {"text": "椅子", "is_correct": false, "explanation": "椅子は抑えるものではなく、この文脈に合わない。"}, {"text": "地図", "is_correct": false, "explanation": "地図は気持ちを抑える対象にならない。"}], "explanations": {"焦燥": "「焦燥を抑える」で、いらだつ気持ちを抑える意味になる。", "窓": "窓は抑える対象にならず、文の意味に合わない。", "椅子": "椅子は抑えるものではなく、この文脈に合わない。", "地図": "地図は気持ちを抑える対象にならない。"}, "sentence_index": 6, "correct_answer": "焦燥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末はゲームに焦燥して、時間を忘れた。", "explanation": "ここは〈熱中〉の意味。〈焦燥〉はいらだつ気持ちで、夢中になる意味では使わない。"}, {"text": "焦燥しのぎに、パズルを解き始めた。", "explanation": "ここは〈退屈〉の意味（退屈しのぎ）。〈焦燥〉では「〜しのぎ」という言い方は成り立たない。"}, {"text": "仕上がりに焦燥して、彼は笑った。", "explanation": "ここは〈満足〉の意味。〈焦燥〉はいらだつ気持ちで、満足して笑う場面とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51808, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "試験の前日、彼女は焦燥を駆られて眠れなかった。", "corrected_sentence": "試験の前日、彼女は焦燥に駆られて眠れなかった。", "error_description": "「駆られる」は「〜に駆られる」と「に」を取る。「焦燥を」は誤りで、正しくは「焦燥に駆られて」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51808, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "返事を待つ間、焦燥を募っていった。", "corrected_sentence": "返事を待つ間、焦燥が募っていった。", "error_description": "「募る」は主語が「焦燥が」の自動詞。「焦燥を募る」は誤りで、正しくは「焦燥が募っていった」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a96c548-5d58-4f61-b552-1c772ba8db2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51809, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「チョコレートが溶け出してしまった」の「が」。溶け出すは自動詞で、動いて溶けるものを主語で示す。"}, {"text": "を", "is_correct": false, "explanation": "「チョコレートを溶け出してしまった」は目的語の「を」になるが、溶け出すは自動詞なので不可。"}, {"text": "と", "is_correct": false, "explanation": "「チョコレートと溶け出してしまった」は並列の「と」で、溶けるものの主語を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「チョコレートより溶け出してしまった」は比較の「より」で、主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "「チョコレートが溶け出してしまった」の「が」。溶け出すは自動詞で、動いて溶けるものを主語で示す。", "を": "「チョコレートを溶け出してしまった」は目的語の「を」になるが、溶け出すは自動詞なので不可。", "と": "「チョコレートと溶け出してしまった」は並列の「と」で、溶けるものの主語を示せない。", "より": "「チョコレートより溶け出してしまった」は比較の「より」で、主語を示せない。"}, "error_tags": {"を": "他動詞の目的語", "と": "並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
