INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51809, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かがとけ始めること。", "primary_collocate": null, "pronunciation": "とけだす", "ipa": "tokedasɯ", "syllable_count": 4, "sentences": [{"text": "春になり、山の雪が溶け出して、川の水が増えた。", "target_word": "溶け出して", "complexity_tier": "T3", "furigana": "春(はる)になり、山(やま)の雪(ゆき)が溶(と)け出(だ)して、川(かわ)の水(みず)が増(ふ)えた。", "sentence_source": "generated"}, {"text": "暑い日に外に置いたら、チョコレートが溶け出してしまった。", "target_word": "溶け出して", "complexity_tier": "T3", "furigana": "暑(あつ)い日(ひ)に外(そと)に置(お)いたら、チョコレートが溶(と)け出(だ)してしまった。", "sentence_source": "generated"}, {"text": "フライパンにバターを入れると、すぐに溶け出した。", "target_word": "溶け出した", "complexity_tier": "T3", "furigana": "フライパンにバターを入(い)れると、すぐに溶(と)け出(だ)した。", "sentence_source": "generated"}, {"text": "食べるのが遅くて、アイスが溶け出し、手にたれてきた。", "target_word": "溶け出し", "complexity_tier": "T3", "furigana": "食(た)べるのが遅(おそ)くて、アイスが溶(と)け出(だ)し、手(て)にたれてきた。", "sentence_source": "generated"}, {"text": "日が当たると、屋根の霜が溶け出して、水がぽたぽた落ちた。", "target_word": "溶け出して", "complexity_tier": "T3", "furigana": "日(ひ)が当(あ)たると、屋根(やね)の霜(しも)が溶(と)け出(だ)して、水(みず)がぽたぽた落(お)ちた。", "sentence_source": "generated"}, {"text": "ストーブの近くに置いたろうそくが、熱で溶け出していた。", "target_word": "溶け出して", "complexity_tier": "T3", "furigana": "ストーブの近(ちか)くに置(お)いたろうそくが、熱(ねつ)で溶(と)け出(だ)していた。", "sentence_source": "generated"}, {"text": "コップの氷が溶け出して、ジュースが薄くなった。", "target_word": "溶け出して", "complexity_tier": "T3", "furigana": "コップの氷(こおり)が溶(と)け出(だ)して、ジュースが薄(うす)くなった。", "sentence_source": "generated"}, {"text": "地球が暖かくなり、北極の氷が溶け出していると言われている。", "target_word": "溶け出して", "complexity_tier": "T3", "furigana": "地球(ちきゅう)が暖(あたた)かくなり、北極(ほっきょく)の氷(こおり)が溶(と)け出(だ)していると言(い)われている。", "sentence_source": "generated"}, {"text": "鍋の中で、砂糖が少しずつ溶け出し、あまい香りがしてきた。", "target_word": "溶け出し", "complexity_tier": "T3", "furigana": "鍋(なべ)の中(なか)で、砂糖(さとう)が少(すこ)しずつ溶(と)け出(だ)し、あまい香(かお)りがしてきた。", "sentence_source": "generated"}, {"text": "火にかけたチーズが溶け出したら、パンにのせてください。", "target_word": "溶け出した", "complexity_tier": "T3", "furigana": "火(ひ)にかけたチーズが溶(と)け出(だ)したら、パンにのせてください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "溶け出す", "label": "辞書形"}, {"form": "溶け出し", "label": "連用形"}, {"form": "溶け出して", "label": "て形"}, {"form": "溶け出した", "label": "た形"}, {"form": "溶け出さない", "label": "ない形"}], "register": "standard", "sense_fingerprint": "氷や雪などが熱でとけ始める", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T3: contains vocabulary far above tier T3: ぽたぽた (Zipf 1.98)']::text[], 'b4be6f74-22e6-41bf-9393-a52cbcefdc01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51809, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "溶け出して", "is_correct": true, "explanation": "て形。「雪が溶けて、川の水が増えた」と続く。"}, {"text": "溶け出さない", "is_correct": false, "explanation": "ない形は読点でつなげられず、「〜ず」の形が必要になる。"}, {"text": "溶かし", "is_correct": false, "explanation": "他動詞「溶かす」の連用形。雪が何かを溶かす意味になり、主語と合わない。"}, {"text": "凍らせて", "is_correct": false, "explanation": "「凍らせる」は他動詞。雪が何かを凍らせる文になり、意味が合わない。"}], "explanations": {"溶け出して": "て形。「雪が溶けて、川の水が増えた」と続く。", "溶け出さない": "ない形は読点でつなげられず、「〜ず」の形が必要になる。", "溶かし": "他動詞「溶かす」の連用形。雪が何かを溶かす意味になり、主語と合わない。", "凍らせて": "「凍らせる」は他動詞。雪が何かを凍らせる文になり、意味が合わない。"}, "sentence_index": 0, "correct_answer": "溶け出して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鍋のお湯が溶け出し始めて、底がむき出しになった。", "explanation": "ここは〈蒸発する〉の意味。水が少しずつ気体になって減るのは蒸発で、溶け出すは固体がとける意味なので合わない。"}, {"text": "冷蔵庫に入れ忘れた牛乳が、溶け出してきた。", "explanation": "ここは〈腐る〉の意味。食品が傷んで悪くなるのは腐るで、溶け出すは物が溶けて外へ出る意味なので合わない。"}, {"text": "オーブンに入れたパンの端が、溶け出してきた。", "explanation": "ここは〈焦げる〉の意味。熱で黒くなるのは焦げるで、溶け出すは溶けて外へ出る意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51809, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "溶け出して", "is_correct": true, "explanation": "て形。「氷が溶けて、ジュースが薄くなった」と続く。"}, {"text": "砕いて", "is_correct": false, "explanation": "他動詞「砕く」のて形。氷を砕く動作になり、氷が主語では合わない。"}, {"text": "冷やして", "is_correct": false, "explanation": "他動詞「冷やす」のて形。目的語がなく、氷が何かを冷やす文になって合わない。"}, {"text": "固めて", "is_correct": false, "explanation": "他動詞「固める」のて形。氷が何かを固めるという意味になり、文が合わない。"}], "explanations": {"溶け出して": "て形。「氷が溶けて、ジュースが薄くなった」と続く。", "砕いて": "他動詞「砕く」のて形。氷を砕く動作になり、氷が主語では合わない。", "冷やして": "他動詞「冷やす」のて形。目的語がなく、氷が何かを冷やす文になって合わない。", "固めて": "他動詞「固める」のて形。氷が何かを固めるという意味になり、文が合わない。"}, "sentence_index": 6, "correct_answer": "溶け出して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洗濯物がすっかり溶け出して、取り込めた。", "explanation": "ここは〈乾く〉の意味。水分が抜けて乾くのは乾くで、溶け出すは溶けて外へ出る意味なので合わない。"}, {"text": "鍋の湯がぐらぐら溶け出した。", "explanation": "ここは〈沸騰する〉の意味。湯が激しく泡立って沸くのは沸騰するで、溶け出すでは意味が合わない。"}, {"text": "たき火の炎が溶け出して、夜空を照らした。", "explanation": "ここは〈燃え上がる〉の意味。炎が勢いよく立ち上がるのは燃え上がるで、溶け出すは物質が溶けて出る意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51809, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暑い車内で、板チョコを溶け出してしまった。", "corrected_sentence": "暑い車内で、板チョコが溶け出してしまった。", "error_description": "「溶け出す」は自動詞なので、動いて溶けるものには「が」を使う。「を」では誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "溶け出して", "is_correct": true, "explanation": "て形＋しまった（溶け出してしまった）で、溶けてしまった結果を表す。"}, {"text": "溶け出す", "is_correct": false, "explanation": "辞書形に「しまった」は続かず、文が成り立たない。"}, {"text": "溶け出した", "is_correct": false, "explanation": "た形に「しまった」は続かず、不自然になる。"}, {"text": "溶け出さない", "is_correct": false, "explanation": "ない形に「しまった」は続かず、ここでは合わない。"}], "correct_form": "溶け出して", "base_form": "溶け出す", "form_label": "て形", "sentence_index": 1, "explanations": {"溶け出して": "て形＋しまった（溶け出してしまった）で、溶けてしまった結果を表す。", "溶け出す": "辞書形に「しまった」は続かず、文が成り立たない。", "溶け出した": "た形に「しまった」は続かず、不自然になる。", "溶け出さない": "ない形に「しまった」は続かず、ここでは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51809, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋根の雪が春の日差しで溶け出すていく。", "corrected_sentence": "屋根の雪が春の日差しで溶け出していく。", "error_description": "「溶け出す」を「〜ていく」につなぐには連用形＋て形の「溶け出して」が必要。辞書形に「て」を続けるのは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "溶け出して", "is_correct": true, "explanation": "て形＋いる（溶け出している）で、今まさに溶け出している様子を表す。"}, {"text": "溶け出し", "is_correct": false, "explanation": "連用形は「いる」に直接続かず、不自然になる。"}, {"text": "溶け出そう", "is_correct": false, "explanation": "意志形は「いる」に続かず、文が成り立たない。"}, {"text": "溶け出せる", "is_correct": false, "explanation": "可能形は「いる」と続けると意味が合わず、不自然になる。"}], "correct_form": "溶け出して", "base_form": "溶け出す", "form_label": "て形", "sentence_index": 7, "explanations": {"溶け出して": "て形＋いる（溶け出している）で、今まさに溶け出している様子を表す。", "溶け出し": "連用形は「いる」に直接続かず、不自然になる。", "溶け出そう": "意志形は「いる」に続かず、文が成り立たない。", "溶け出せる": "可能形は「いる」と続けると意味が合わず、不自然になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51810, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す。金属が溶け出す、の主語にあたる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語に使うが、溶け出すは自動詞なので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は行き先を表すので、溶ける物の主語を示す位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を表すので、溶ける物の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す。金属が溶け出す、の主語にあたる。", "を": "「を」は他動詞の目的語に使うが、溶け出すは自動詞なので合わない。", "に": "「に」は行き先を表すので、溶ける物の主語を示す位置には合わない。", "で": "「で」は手段や場所を表すので、溶ける物の主語を示せない。"}, "error_tags": {"を": "他動詞の目的語", "に": "行き先", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51810, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す。寂しさが溶け出している、の主語にあたる。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐ連体修飾なので、動詞の主語の位置には入らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を表すので、ここでは主語を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、溶けて出る主語の位置には合わない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す。寂しさが溶け出している、の主語にあたる。", "の": "「の」は名詞どうしをつなぐ連体修飾なので、動詞の主語の位置には入らない。", "と": "「と」は並列や引用を表すので、ここでは主語を示せない。", "へ": "「へ」は方向を表すので、溶けて出る主語の位置には合わない。"}, "error_tags": {"の": "連体修飾", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51810, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物が溶けて、外へ出てくること。また、感情などがにじみ出るように現れ始めること。", "primary_collocate": null, "pronunciation": "とけだす", "ipa": "tokedasɯ", "syllable_count": 4, "sentences": [{"text": "力強く円を描くことで、言葉にできない思春期の焦燥感が、少しずつ紙の上へ溶け出していくようだった。", "target_word": "溶け出し", "complexity_tier": "T3", "furigana": "力強(ちからづよ)く円(えん)を描(えが)くことで、言葉(ことば)にできない思春期(ししゅんき)の焦燥感(しょうそうかん)が、少(すこ)しずつ紙(かみ)の上(うえ)へ溶(と)け出(だ)していくようだった。", "sentence_source": "mined"}, {"text": "古い鍋から金属が溶け出して、スープの味が変わった。", "target_word": "溶け出して", "complexity_tier": "T3", "furigana": "古(ふる)い鍋(なべ)から金属(きんぞく)が溶(と)け出(だ)して、スープの味(あじ)が変(か)わった。", "sentence_source": "generated"}, {"text": "茶葉を入れてしばらくすると、お湯に色が溶け出してきた。", "target_word": "溶け出して", "complexity_tier": "T3", "furigana": "茶葉(ちゃば)を入(い)れてしばらくすると、お湯(ゆ)に色(いろ)が溶(と)け出(だ)してきた。", "sentence_source": "generated"}, {"text": "彼の歌声には、故郷への思いが溶け出していた。", "target_word": "溶け出して", "complexity_tier": "T3", "furigana": "彼(かれ)の歌声(うたごえ)には、故郷(こきょう)への思(おも)いが溶(と)け出(だ)していた。", "sentence_source": "generated"}, {"text": "野菜を煮ると、栄養がスープに溶け出す。", "target_word": "溶け出す", "complexity_tier": "T3", "furigana": "野菜(やさい)を煮(に)ると、栄養(えいよう)がスープに溶(と)け出(だ)す。", "sentence_source": "generated"}, {"text": "長く煮込むと、骨からうま味が溶け出す。", "target_word": "溶け出す", "complexity_tier": "T3", "furigana": "長(なが)く煮込(にこ)むと、骨(ほね)からうま味(み)が溶(と)け出(だ)す。", "sentence_source": "generated"}, {"text": "古い容器から有害な物質が溶け出すおそれがあるので、使わないでください。", "target_word": "溶け出す", "complexity_tier": "T3", "furigana": "古(ふる)い容器(ようき)から有害(ゆうがい)な物質(ぶっしつ)が溶(と)け出(だ)すおそれがあるので、使(つか)わないでください。", "sentence_source": "generated"}, {"text": "手紙の文字には、書いた人の寂しさが溶け出しているように感じた。", "target_word": "溶け出して", "complexity_tier": "T3", "furigana": "手紙(てがみ)の文字(もじ)には、書(か)いた人(ひと)の寂(さび)しさが溶(と)け出(だ)しているように感(かん)じた。", "sentence_source": "generated"}, {"text": "入浴剤が溶け出し、香りが部屋じゅうに広がった。", "target_word": "溶け出し", "complexity_tier": "T3", "furigana": "入浴剤(にゅうよくざい)が溶(と)け出(だ)し、香(かお)りが部屋(へや)じゅうに広(ひろ)がった。", "sentence_source": "generated"}, {"text": "彼女の絵には、静かな夜の空気が溶け出している。", "target_word": "溶け出して", "complexity_tier": "T3", "furigana": "彼女(かのじょ)の絵(え)には、静(しず)かな夜(よる)の空気(くうき)が溶(と)け出(だ)している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "溶け出す", "label": "辞書形"}, {"form": "溶け出し", "label": "連用形"}, {"form": "溶け出して", "label": "て形"}, {"form": "溶け出した", "label": "た形"}, {"form": "溶け出さない", "label": "ない形"}], "register": "standard", "sense_fingerprint": "成分や感情が溶けて外へにじみ出る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4be6f74-22e6-41bf-9393-a52cbcefdc01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51810, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "溶け出し", "is_correct": true, "explanation": "連用形。「〜ていく」に続けて「少しずつ広がっていく」の意味になる。"}, {"text": "溶け出す", "is_correct": false, "explanation": "辞書形は「〜ていく」の前に続かないので、この位置では使えない。"}, {"text": "溶け出した", "is_correct": false, "explanation": "た形は「〜ていく」に続かず、文が途中で成り立たない。"}, {"text": "溶け出さない", "is_correct": false, "explanation": "ない形は「〜ていく」に直接続かないので合わない。"}], "explanations": {"溶け出し": "連用形。「〜ていく」に続けて「少しずつ広がっていく」の意味になる。", "溶け出す": "辞書形は「〜ていく」の前に続かないので、この位置では使えない。", "溶け出した": "た形は「〜ていく」に続かず、文が途中で成り立たない。", "溶け出さない": "ない形は「〜ていく」に直接続かないので合わない。"}, "sentence_index": 0, "correct_answer": "溶け出し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は新しいクラスにすぐ溶け出し、もう転校生には見えない。", "explanation": "ここは〈溶け込む〉の意味。溶け出すは中にあるものが外へ出てくる意味なので、人がその場になじむ意味では使わない。"}, {"text": "二つの絵の具が溶け出して、きれいな緑になった。", "explanation": "ここは〈溶け合う〉の意味。二つのものが混ざって一つになる場合は溶け合うを使い、溶け出すでは外へ出てくる意味になる。"}, {"text": "汗が額から溶け出して、タオルがぬれた。", "explanation": "ここは〈滴る〉の意味。汗や水がしたたり落ちるのは滴るで、溶け出すは物質が溶けて外へ出る意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51810, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "溶け出す", "is_correct": true, "explanation": "辞書形。「おそれ」に直接続き、「溶け出すおそれがある」を作る。"}, {"text": "溶け出し", "is_correct": false, "explanation": "連用形は「おそれ」に直接続かず、文が成り立たない。"}, {"text": "溶け出して", "is_correct": false, "explanation": "て形は「おそれ」に続かず、ここでは使えない。"}, {"text": "溶かし", "is_correct": false, "explanation": "「溶かす」は他動詞の連用形で、目的語がないので「物質が溶かしおそれ」となり合わない。"}], "explanations": {"溶け出す": "辞書形。「おそれ」に直接続き、「溶け出すおそれがある」を作る。", "溶け出し": "連用形は「おそれ」に直接続かず、文が成り立たない。", "溶け出して": "て形は「おそれ」に続かず、ここでは使えない。", "溶かし": "「溶かす」は他動詞の連用形で、目的語がないので「物質が溶かしおそれ」となり合わない。"}, "sentence_index": 6, "correct_answer": "溶け出す"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "コーヒーの水分が溶け出して、鍋の中が空になった。", "explanation": "ここは〈蒸発する〉の意味。水分が気体になって消えるのは蒸発で、溶け出すでは意味が合わない。"}, {"text": "泥が底に溶け出して、水が澄んできた。", "explanation": "ここは〈沈殿する〉の意味。細かい粒が底に沈むのは沈殿で、溶け出すでは合わない。"}, {"text": "窓ガラスに水蒸気が溶け出して、くもった。", "explanation": "ここは〈凝結する〉の意味。気体が冷えて水になるのは凝結で、溶け出すは物質が溶けて出る意味なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51810, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "パスタを熱湯で長くゆでると、でんぷんがお湯を溶け出す。", "corrected_sentence": "パスタを熱湯で長くゆでると、でんぷんがお湯に溶け出す。", "error_description": "「溶け出す」は自動詞で、場所は「に」で表す。「を」は他動詞の目的語に使うので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "溶け出して", "is_correct": true, "explanation": "て形。「溶け出して、スープの味が変わった」と文をつなぐ。"}, {"text": "溶け出す", "is_correct": false, "explanation": "辞書形は文を止めてしまうので、後ろの「、スープの味が変わった」とつながらない。"}, {"text": "溶け出した", "is_correct": false, "explanation": "た形は文を終えてしまうので、ここでは後ろへ続かない。"}, {"text": "溶け出さない", "is_correct": false, "explanation": "ない形は「〜ず」や「〜なくて」に直さないと続かないので合わない。"}], "correct_form": "溶け出して", "base_form": "溶け出す", "form_label": "て形", "sentence_index": 1, "explanations": {"溶け出して": "て形。「溶け出して、スープの味が変わった」と文をつなぐ。", "溶け出す": "辞書形は文を止めてしまうので、後ろの「、スープの味が変わった」とつながらない。", "溶け出した": "た形は文を終えてしまうので、ここでは後ろへ続かない。", "溶け出さない": "ない形は「〜ず」や「〜なくて」に直さないと続かないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51810, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋根の氷がゆっくり溶け出た、水がしたたり落ちた。", "corrected_sentence": "屋根の氷がゆっくり溶け出して、水がしたたり落ちた。", "error_description": "「溶け出す」のて形は「溶け出して」。「溶け出た」は「出る」と混同した誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "溶け出して", "is_correct": true, "explanation": "て形＋いる（溶け出している）で、寂しさが外へにじみ出ている様子を表す。"}, {"text": "溶け出し", "is_correct": false, "explanation": "連用形は「いる」に直接続かず、不自然になる。"}, {"text": "溶け出そう", "is_correct": false, "explanation": "意志形は「いる」に続かず、文が成り立たない。"}, {"text": "溶け出せる", "is_correct": false, "explanation": "可能形は「いる」と続けると不自然で、ここでは意味が合わない。"}], "correct_form": "溶け出して", "base_form": "溶け出す", "form_label": "て形", "sentence_index": 7, "explanations": {"溶け出して": "て形＋いる（溶け出している）で、寂しさが外へにじみ出ている様子を表す。", "溶け出し": "連用形は「いる」に直接続かず、不自然になる。", "溶け出そう": "意志形は「いる」に続かず、文が成り立たない。", "溶け出せる": "可能形は「いる」と続けると不自然で、ここでは意味が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e69683-7b61-4b7f-b730-c66856906d1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
