INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51813, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「重ね塗りをした」の「を」。する の目的語で、文と合う。"}, {"text": "が", "is_correct": false, "explanation": "「重ね塗りがしたせいで」は主語になり、する と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「重ね塗りへしたせいで」は方向の形で、する の目的語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「重ね塗りよりしたせいで」は比較の形で、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「重ね塗りをした」の「を」。する の目的語で、文と合う。", "が": "「重ね塗りがしたせいで」は主語になり、する と合わない。", "へ": "「重ね塗りへしたせいで」は方向の形で、する の目的語にならない。", "より": "「重ね塗りよりしたせいで」は比較の形で、意味が通らない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51813, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "もう一度、上から絵の具をぬること。", "primary_collocate": null, "pronunciation": "かさねぬり", "ipa": "kasanenɯɾi", "syllable_count": 5, "sentences": [{"text": "色がうすかったので、もう一度、重ね塗りをした。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "いろがうすかったので、もういちど、かさねぬりをした。", "sentence_source": "generated"}, {"text": "乾く前に重ね塗りすると、下の絵の具がはがれてしまう。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "かわくまえにかさねぬりすると、したのえのぐがはがれてしまう。", "sentence_source": "generated"}, {"text": "父は古い扉の傷が目立たないように、ペンキを重ね塗りした。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "ちちはふるいとびらのきずがめだたないように、ペンキをかさねぬりした。", "sentence_source": "generated"}, {"text": "重ね塗りの前に、まず表面のほこりをきれいに拭き取る。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "かさねぬりのまえに、まずひょうめんのほこりをきれいにふきとる。", "sentence_source": "generated"}, {"text": "妹は、下の黄色が見えなくなるまで、青を重ね塗りした。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "いもうとは、したのきいろがみえなくなるまで、あおをかさねぬりした。", "sentence_source": "generated"}, {"text": "一度塗っただけでは足りず、壁は二回の重ね塗りが必要だった。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "いちどぬっただけではたりず、かべはにかいのかさねぬりがひつようだった。", "sentence_source": "generated"}, {"text": "失敗した所は、乾いてから上に重ね塗りすれば、直せる。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "しっぱいしたところは、かわいてからうえにかさねぬりすれば、なおせる。", "sentence_source": "generated"}, {"text": "重ね塗りをしたせいで、絵の具が厚くなりすぎた。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "かさねぬりをしたせいで、えのぐがあつくなりすぎた。", "sentence_source": "generated"}, {"text": "白い絵の具の重ね塗りで、まちがった線を消した。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "しろいえのぐのかさねぬりで、まちがったせんをけした。", "sentence_source": "generated"}, {"text": "先生は「重ね塗りは、下が乾いてからですよ」と言った。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "せんせいは「かさねぬりは、したがかわいてからですよ」といった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重ね塗りする", "label": "終止形"}, {"form": "重ね塗りした", "label": "過去形"}, {"form": "重ね塗りして", "label": "て形"}, {"form": "重ね塗りの", "label": "連体形（名詞＋の）"}], "register": "中立（普通体の書き言葉）", "sense_fingerprint": "すでに塗った面の上から、もう一度絵の具やペンキを塗ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197a392-5844-4a45-9c3f-f9f8a19150de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51813, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重ね塗り", "is_correct": true, "explanation": "「もう一度、重ね塗りをした」は上から塗り直したことを表し、文の内容と合う。"}, {"text": "色", "is_correct": false, "explanation": "「もう一度、色をした」は動詞と結びつかない。"}, {"text": "絵具", "is_correct": false, "explanation": "「絵具をした」は意味が通らない。"}, {"text": "筆", "is_correct": false, "explanation": "「筆をした」は意味が通らない。"}], "explanations": {"重ね塗り": "「もう一度、重ね塗りをした」は上から塗り直したことを表し、文の内容と合う。", "色": "「もう一度、色をした」は動詞と結びつかない。", "絵具": "「絵具をした」は意味が通らない。", "筆": "「筆をした」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "重ね塗り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "塗る前に、表面を重ね塗りして汚れを落とす。", "explanation": "ここは〈洗浄〉の意味。汚れを洗い落とす作業を指し、上から塗る重ね塗りでは汚れは落とせない。"}, {"text": "重ね塗りを水で薄めて使う。", "explanation": "ここは〈薄める〉の意味。薄めるのは絵の具などの材料で、塗る行為の重ね塗りは薄められない。"}, {"text": "夜のあいだに、雪が道に重ね塗りされた。", "explanation": "ここは〈積もる〉の意味。雪は塗らないので、絵の具を上から塗る重ね塗りとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51813, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重ね塗り", "is_correct": true, "explanation": "「上に重ね塗りすれば」は上から塗って直す方法を表し、文と合う。"}, {"text": "切り抜き", "is_correct": false, "explanation": "「上に切り抜きすれば」は意味が通らない。"}, {"text": "乾燥", "is_correct": false, "explanation": "「上に乾燥すれば」は不自然で、直す方法にならない。"}, {"text": "掃除", "is_correct": false, "explanation": "「上に掃除すれば」は直す方法として合わない。"}], "explanations": {"重ね塗り": "「上に重ね塗りすれば」は上から塗って直す方法を表し、文と合う。", "切り抜き": "「上に切り抜きすれば」は意味が通らない。", "乾燥": "「上に乾燥すれば」は不自然で、直す方法にならない。", "掃除": "「上に掃除すれば」は直す方法として合わない。"}, "sentence_index": 6, "correct_answer": "重ね塗り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "農薬を畑に重ね塗りした。", "explanation": "ここは〈散布〉の意味。液体をまき広げる作業を指すので、絵の具を上から塗る重ね塗りとは違う。"}, {"text": "レポートを重ね塗りして、提出した。", "explanation": "ここは〈書き直し〉の意味。文章を直す作業を指すので、絵の具の上塗りの重ね塗りは使わない。"}, {"text": "同じ練習を重ね塗りして、腕を上げた。", "explanation": "ここは〈繰り返し〉の意味。練習を重ねる行為を指すので、絵の具を塗る重ね塗りとは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51813, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "壁が乾いたら、上から重ね塗りがした。", "corrected_sentence": "壁が乾いたら、上から重ね塗りをした。", "error_description": "誤: 重ね塗りが / 正: 重ね塗りを。「する」の目的語は「を」で示す。「が」では不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51813, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "色むらは、重ね塗りを消せる。", "corrected_sentence": "色むらは、重ね塗りで消せる。", "error_description": "誤: 重ね塗りを / 正: 重ね塗りで。色むらを消す手段は「で」で示す。「を」では重ね塗りそのものを消す意味になり不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51814, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「重ね塗りをする」の「を」。する の目的語で、文と合う。"}, {"text": "が", "is_correct": false, "explanation": "「重ね塗りがすると」は主語になり、する の目的語にならない。"}, {"text": "の", "is_correct": false, "explanation": "「重ね塗りのすると」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "「重ね塗りよりすると」は比較の形にならず、不自然。"}], "correct_answer": "を", "explanations": {"を": "「重ね塗りをする」の「を」。する の目的語で、文と合う。", "が": "「重ね塗りがすると」は主語になり、する の目的語にならない。", "の": "「重ね塗りのすると」は意味が通らない。", "より": "「重ね塗りよりすると」は比較の形にならず、不自然。"}, "error_tags": {"が": "主語", "の": "所属・修飾", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51814, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51814, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "すでに塗った上に、さらに塗り重ねること。特に、絵画やマニキュアなどで、色を何度も塗って深みや濃さを出す技法。", "primary_collocate": null, "pronunciation": "かさねぬり", "ipa": "kasanenɯɾi", "syllable_count": 5, "sentences": [{"text": "指先で色を擦り混ぜ、重ね塗りをする技法によって、私は心の中の風景を絵として表現している。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "ゆびさきでいろをこすりまぜ、かさねぬりをするぎほうによって、わたしはこころのなかのふうけいをえとしてひょうげんしている。", "sentence_source": "mined"}, {"text": "重ね塗りをすると、一度では出せない深い色になる。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "かさねぬりをすると、いちどではだせないふかいいろになる。", "sentence_source": "generated"}, {"text": "彼女は爪に赤いマニキュアを重ね塗りして、濃い色に仕上げた。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "かのじょはつめにあかいマニキュアをかさねぬりして、こいいろにしあげた。", "sentence_source": "generated"}, {"text": "水彩画では、乾いてから重ね塗りをすると、色がにごりにくい。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "すいさいがでは、かわいてからかさねぬりをすると、いろがにごりにくい。", "sentence_source": "generated"}, {"text": "空の青は、薄い色の重ね塗りで少しずつ深くしていった。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "そらのあおは、うすいいろのかさねぬりで、すこしずつふかくしていった。", "sentence_source": "generated"}, {"text": "先生は「重ね塗りの回数が多いほど、絵に奥行きが出る」と教えてくれた。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "せんせいは「かさねぬりのかいすうがおおいほど、えにおくゆきがでる」とおしえてくれた。", "sentence_source": "generated"}, {"text": "油絵の重ね塗りは、下の色が乾くまで待つのがコツだ。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "あぶらえのかさねぬりは、したのいろがかわくまでまつのがコツだ。", "sentence_source": "generated"}, {"text": "壁の傷を隠すため、白いペンキで重ね塗りをした。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "かべのきずをかくすため、しろいペンキでかさねぬりをした。", "sentence_source": "generated"}, {"text": "彼の絵は、重ね塗りを何度もくり返したので、表面が少し厚くなっている。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "かれのえは、かさねぬりをなんどもくりかえしたので、ひょうめんがすこしあつくなっている。", "sentence_source": "generated"}, {"text": "重ね塗りの技法を使えば、夕焼けの赤にやわらかな深みを出せる。", "target_word": "重ね塗り", "complexity_tier": "T3", "furigana": "かさねぬりのぎほうをつかえば、ゆうやけのあかにやわらかなふかみをだせる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "重ね塗りする", "label": "終止形"}, {"form": "重ね塗りした", "label": "過去形"}, {"form": "重ね塗りして", "label": "て形"}, {"form": "重ね塗りの", "label": "連体形（名詞＋の）"}], "register": "中立（普通体の書き言葉）", "sense_fingerprint": "色を何度も塗り重ねて深みや濃さを出す絵画・マニキュアなどの技法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1197a392-5844-4a45-9c3f-f9f8a19150de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51814, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重ね塗り", "is_correct": true, "explanation": "「重ね塗りをする技法」は色を重ねて深みを出す技法で、文の内容と合う。"}, {"text": "留守番", "is_correct": false, "explanation": "「留守番をする技法」は意味が通らない。"}, {"text": "遠足", "is_correct": false, "explanation": "「遠足をする技法」は意味が通らない。"}, {"text": "迷子", "is_correct": false, "explanation": "「迷子をする技法」は意味が通らない。"}], "explanations": {"重ね塗り": "「重ね塗りをする技法」は色を重ねて深みを出す技法で、文の内容と合う。", "留守番": "「留守番をする技法」は意味が通らない。", "遠足": "「遠足をする技法」は意味が通らない。", "迷子": "「迷子をする技法」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "重ね塗り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒いので、重ね塗りをして外に出た。", "explanation": "ここは〈重ね着〉の意味。衣服を重ねて着る行為を指すので、絵の具を塗る重ね塗りとは合わない。"}, {"text": "資料を何枚も重ね塗りして、机の上に置いた。", "explanation": "ここは〈積み重ねる〉の意味。資料は塗らないので、絵の具を重ねる重ね塗りでは言い換えられない。"}, {"text": "子どもは重ね塗りの本で、一日中遊んでいた。", "explanation": "ここは〈色塗り〉の意味。一度ぬって色を付ける遊びを指し、重ねて深みを出す重ね塗りとは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51814, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重ね塗り", "is_correct": true, "explanation": "「油絵の重ね塗り」は絵の具を重ねる技法で、下の色を乾かす話と合う。"}, {"text": "洗濯", "is_correct": false, "explanation": "「油絵の洗濯」は意味が通らない。"}, {"text": "昼寝", "is_correct": false, "explanation": "「油絵の昼寝」は意味が通らない。"}, {"text": "散歩", "is_correct": false, "explanation": "「油絵の散歩」は意味が通らない。"}], "explanations": {"重ね塗り": "「油絵の重ね塗り」は絵の具を重ねる技法で、下の色を乾かす話と合う。", "洗濯": "「油絵の洗濯」は意味が通らない。", "昼寝": "「油絵の昼寝」は意味が通らない。", "散歩": "「油絵の散歩」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "重ね塗り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ギターの音を一本ずつ重ね塗りして、厚みを出した。", "explanation": "ここは〈重ね録り〉の意味。音を録音する作業を指し、絵の具を塗る重ね塗りは使わない。"}, {"text": "荷物を何重にも重ね塗りして、無事に届けた。", "explanation": "ここは〈包装〉の意味。包んで保護する作業を指すので、絵の具を塗る重ね塗りとは合わない。"}, {"text": "子どもは重ね塗りを高く積んで、遊んでいた。", "explanation": "ここは〈積み木〉の意味。積み上げて遊ぶ道具を指すので、塗る行為の重ね塗りは積めない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51814, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "重ね塗りに色に深みを出す。", "corrected_sentence": "重ね塗りで色に深みを出す。", "error_description": "誤: 重ね塗りに / 正: 重ね塗りで。方法や手段を表す「で」が必要。「に」では重ね塗りが方法にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51814, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "色を深くしたいなら、重ね塗りがするとよい。", "corrected_sentence": "色を深くしたいなら、重ね塗りをするとよい。", "error_description": "誤: 重ね塗りが / 正: 重ね塗りを。「する」の目的語は「を」で示す。「が」では重ね塗りが主語になり不自然。", "correct_sentence_indices": [6, 8, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd814f00b-58d1-452d-be24-ac9e1980691a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51815, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を表す「を」。「二種類の粉を擦り混ぜた」と擦り混ぜる対象を示し、文の意味に合う。"}, {"text": "に", "is_correct": false, "explanation": "場所や相手を表す「に」。「粉に擦り混ぜた」では対象を示せず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す「から」。「粉から擦り混ぜた」では出どころの意味になり、対象を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」。「粉へ擦り混ぜた」では向かう先の意味になり、対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "対象を表す「を」。「二種類の粉を擦り混ぜた」と擦り混ぜる対象を示し、文の意味に合う。", "に": "場所や相手を表す「に」。「粉に擦り混ぜた」では対象を示せず、文が成り立たない。", "から": "起点を表す「から」。「粉から擦り混ぜた」では出どころの意味になり、対象を表せない。", "へ": "方向を表す「へ」。「粉へ擦り混ぜた」では向かう先の意味になり、対象を示せない。"}, "error_tags": {"に": "場所・相手", "から": "起点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51815, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "手段・道具を表す「で」。「すり鉢で擦り混ぜるほど」と道具を示し、文の意味に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す「が」。「すり鉢が擦り混ぜる」では道具が動作主になり、文の意味に合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「すり鉢の擦り混ぜるほど」では名詞同士の関係にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」。「すり鉢より擦り混ぜるほど」では手段を示せず、不自然な文になる。"}], "correct_answer": "で", "explanations": {"で": "手段・道具を表す「で」。「すり鉢で擦り混ぜるほど」と道具を示し、文の意味に合う。", "が": "主語を表す「が」。「すり鉢が擦り混ぜる」では道具が動作主になり、文の意味に合わない。", "の": "連体修飾の「の」。「すり鉢の擦り混ぜるほど」では名詞同士の関係にならず、文が成り立たない。", "より": "比較を表す「より」。「すり鉢より擦り混ぜるほど」では手段を示せず、不自然な文になる。"}, "error_tags": {"が": "主語", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51815, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "指や道具で、ものをこすってまぜること。", "primary_collocate": null, "pronunciation": "すりまぜる", "ipa": "sɯɾimaze̞ɾɯ", "syllable_count": 5, "sentences": [{"text": "すり鉢でごまと味噌を擦り混ぜて、和えごろもを作った。", "target_word": "擦り混ぜて", "complexity_tier": "T3", "furigana": "すり鉢[ばち]でごまと味噌[みそ]を擦[す]り混[ま]ぜて、和[あ]えごろもを作[つく]った。", "sentence_source": "generated"}, {"text": "薬剤師は乳鉢で二種類の粉を擦り混ぜた。", "target_word": "擦り混ぜた", "complexity_tier": "T3", "furigana": "薬剤師[やくざいし]は乳鉢[にゅうばち]で二種類[にしゅるい]の粉[こな]を擦[す]り混[ま]ぜた。", "sentence_source": "generated"}, {"text": "粘土に水を少しずつ加えながら、手のひらで擦り混ぜる。", "target_word": "擦り混ぜる", "complexity_tier": "T3", "furigana": "粘土[ねんど]に水[みず]を少[すこ]しずつ加[くわ]えながら、手[て]のひらで擦[す]り混[ま]ぜる。", "sentence_source": "generated"}, {"text": "豆腐を木べらで擦り混ぜると、なめらかな白和えの衣になる。", "target_word": "擦り混ぜる", "complexity_tier": "T3", "furigana": "豆腐[とうふ]を木[き]べらで擦[す]り混[ま]ぜると、なめらかな白和[しろあ]えの衣[ころも]になる。", "sentence_source": "generated"}, {"text": "母は小麦粉とバターを指先で擦り混ぜて、さらさらの生地を作った。", "target_word": "擦り混ぜて", "complexity_tier": "T3", "furigana": "母[はは]は小麦粉[こむぎこ]とバターを指先[ゆびさき]で擦[す]り混[ま]ぜて、さらさらの生地[きじ]を作[つく]った。", "sentence_source": "generated"}, {"text": "塗料が固まらないように、へらでよく擦り混ぜてから使う。", "target_word": "擦り混ぜて", "complexity_tier": "T3", "furigana": "塗料[とりょう]が固[かた]まらないように、へらでよく擦[す]り混[ま]ぜてから使[つか]う。", "sentence_source": "generated"}, {"text": "二種類のクリームを指先で擦り混ぜてから、顔に塗った。", "target_word": "擦り混ぜて", "complexity_tier": "T3", "furigana": "二[に]種[しゅ]類[るい]のクリームを指先[ゆびさき]で擦[す]り混[ま]ぜてから、顔[かお]に塗[ぬ]った。", "sentence_source": "generated"}, {"text": "ごまは、すり鉢で擦り混ぜるほど香りが立つ。", "target_word": "擦り混ぜる", "complexity_tier": "T3", "furigana": "ごまは、すり鉢[ばち]で擦[す]り混[ま]ぜるほど香[か]りが立[た]つ。", "sentence_source": "generated"}, {"text": "白い粉と黄色い粉を指で擦り混ぜると、淡い色の粉になった。", "target_word": "擦り混ぜる", "complexity_tier": "T3", "furigana": "白[しろ]い粉[こな]と黄色[きいろ]い粉[こな]を指[ゆび]で擦[す]り混[ま]ぜると、淡[あわ]い色[いろ]の粉[こな]になった。", "sentence_source": "generated"}, {"text": "山椒の実と塩を擦り混ぜて、焼き魚にふりかけた。", "target_word": "擦り混ぜて", "complexity_tier": "T3", "furigana": "山椒[さんしょう]の実[み]と塩[しお]を擦[す]り混[ま]ぜて、焼[や]き魚[ざかな]にふりかけた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "擦り混ぜる", "label": "終止形"}, {"form": "擦り混ぜ", "label": "連用形"}, {"form": "擦り混ぜて", "label": "て形"}, {"form": "擦り混ぜた", "label": "過去形"}, {"form": "擦り混ぜない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "料理・調合・作業で、指や道具を使ってものをこすりながら混ぜ合わせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T4: contains vocabulary far above tier T4: 乳鉢 (Zipf 1.49)']::text[], '13f97567-fed9-4616-b891-4a3279b2183f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51815, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "擦り混ぜて", "is_correct": true, "explanation": "て形。「すり鉢で擦り混ぜて、和えごろもを作った」と動作を続ける形で、ここに入る。"}, {"text": "擦り混ぜる", "is_correct": false, "explanation": "終止形。文の途中に置くと言い切りになり、「和えごろもを作った」と続かない。"}, {"text": "擦り混ぜない", "is_correct": false, "explanation": "否定形。否定になると和えごろもを作る動作と合わず、文が成り立たない。"}, {"text": "擦り混ぜよう", "is_correct": false, "explanation": "意志形。「擦り混ぜよう、」は意志を表して文中に入らず、過去の結果と合わない。"}], "explanations": {"擦り混ぜて": "て形。「すり鉢で擦り混ぜて、和えごろもを作った」と動作を続ける形で、ここに入る。", "擦り混ぜる": "終止形。文の途中に置くと言い切りになり、「和えごろもを作った」と続かない。", "擦り混ぜない": "否定形。否定になると和えごろもを作る動作と合わず、文が成り立たない。", "擦り混ぜよう": "意志形。「擦り混ぜよう、」は意志を表して文中に入らず、過去の結果と合わない。"}, "sentence_index": 0, "correct_answer": "擦り混ぜて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ねぎを包丁で細かく擦り混ぜた。", "explanation": "ここは〈刻む〉の意味。擦り混ぜるは材料をこすり合わせて混ぜる動作で、包丁で切り分ける意味では使わない。"}, {"text": "洗った洗濯物を窓辺で擦り混ぜて乾かした。", "explanation": "ここは〈乾燥〉の意味。擦り混ぜるは材料を混ぜる動作で、水分を飛ばす意味では使わない。"}, {"text": "凍えた手を擦り混ぜて温めた。", "explanation": "ここは〈摩擦して温める〉の意味。擦り混ぜるは材料同士を混ぜ合わせる動作で、手をこすって温める意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51815, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擦り混ぜて", "is_correct": true, "explanation": "て形。「指先で擦り混ぜてから、顔に塗った」と「てから」で続ける形で、ここに入る。"}, {"text": "擦り混ぜさせ", "is_correct": false, "explanation": "使役の連用形。誰かに擦らせる意味になり、「てから」の形にもならない。"}, {"text": "擦り混ぜられ", "is_correct": false, "explanation": "受身の連用形。クリームが擦られる側になり、「てから」の形にもならない。"}, {"text": "擦り混ぜたら", "is_correct": false, "explanation": "仮定形。「たら」では「てから」の形にならず、「擦り混ぜたらから」と接続しない。"}], "explanations": {"擦り混ぜて": "て形。「指先で擦り混ぜてから、顔に塗った」と「てから」で続ける形で、ここに入る。", "擦り混ぜさせ": "使役の連用形。誰かに擦らせる意味になり、「てから」の形にもならない。", "擦り混ぜられ": "受身の連用形。クリームが擦られる側になり、「てから」の形にもならない。", "擦り混ぜたら": "仮定形。「たら」では「てから」の形にならず、「擦り混ぜたらから」と接続しない。"}, "sentence_index": 6, "correct_answer": "擦り混ぜて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "スープを鍋の中で擦り混ぜて、ぐつぐつ煮立てた。", "explanation": "ここは〈かき混ぜる〉の意味。擦り混ぜるは異なる材料をこすり合わせて混ぜる動作で、液体をおたまなどでかき回す意味では使わない。"}, {"text": "バターを湯せんで擦り混ぜて溶かした。", "explanation": "ここは〈融解〉の意味。擦り混ぜるは材料同士をこすり合わせて混ぜることで、熱を加えて固体をとろけさせる意味では使わない。"}, {"text": "銀のスプーンを布で擦り混ぜて磨いた。", "explanation": "ここは〈研磨〉の意味。擦り混ぜるは異なる材料を混ぜ合わせる動作で、表面をこすって光らせる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51815, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "すり鉢で砂糖ときな粉を擦り混ぜるば、きな粉まぶしが作れる。", "corrected_sentence": "すり鉢で砂糖ときな粉を擦り混ぜれば、きな粉まぶしが作れる。", "error_description": "正しくは「擦り混ぜれば」。擦り混ぜるは下一段動詞なので仮定形は「れば」になる。「擦り混ぜるば」は活用の誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "擦り混ぜた", "is_correct": true, "explanation": "過去形。「薬剤師は〜粉を擦り混ぜた」と完了した動作を言い切る形で、ここに入る。"}, {"text": "擦り混ぜ", "is_correct": false, "explanation": "連用形。単独では文を言い切れず、文末に置くと不完全になる。"}, {"text": "擦り混ぜて", "is_correct": false, "explanation": "て形。文末に置いても言い切れず、動作の完了を表せない。"}, {"text": "擦り混ぜれば", "is_correct": false, "explanation": "仮定形。「〜れば」で結ぶ文が完結せず、文末の過去形として成立しない。"}], "correct_form": "擦り混ぜた", "base_form": "擦り混ぜる", "form_label": "過去形", "sentence_index": 1, "explanations": {"擦り混ぜた": "過去形。「薬剤師は〜粉を擦り混ぜた」と完了した動作を言い切る形で、ここに入る。", "擦り混ぜ": "連用形。単独では文を言い切れず、文末に置くと不完全になる。", "擦り混ぜて": "て形。文末に置いても言い切れず、動作の完了を表せない。", "擦り混ぜれば": "仮定形。「〜れば」で結ぶ文が完結せず、文末の過去形として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51815, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "煎った白ごまは、すり鉢で擦り混ぜ香りが立つ。", "corrected_sentence": "煎った白ごまは、すり鉢で擦り混ぜると香りが立つ。", "error_description": "正しくは「擦り混ぜると」。条件を表す「と」が抜けると「擦り混ぜ香りが立つ」となり、文として接続しない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "擦り混ぜる", "is_correct": true, "explanation": "終止形。「擦り混ぜるほど香りが立つ」と程度を表す文に続く形で、ここに入る。"}, {"text": "擦り混ぜられ", "is_correct": false, "explanation": "受身の連用形。ごまが擦られる側になり、「ほど」に続く形として不自然。"}, {"text": "擦り混ぜさせ", "is_correct": false, "explanation": "使役の連用形。誰かに擦らせる意味になり、文の主語と合わない。"}, {"text": "擦り混ぜそう", "is_correct": false, "explanation": "様態の形。「擦り混ぜそうほど」は「ほど」に続かず、程度の文として成立しない。"}], "correct_form": "擦り混ぜる", "base_form": "擦り混ぜる", "form_label": "終止形", "sentence_index": 7, "explanations": {"擦り混ぜる": "終止形。「擦り混ぜるほど香りが立つ」と程度を表す文に続く形で、ここに入る。", "擦り混ぜられ": "受身の連用形。ごまが擦られる側になり、「ほど」に続く形として不自然。", "擦り混ぜさせ": "使役の連用形。誰かに擦らせる意味になり、文の主語と合わない。", "擦り混ぜそう": "様態の形。「擦り混ぜそうほど」は「ほど」に続かず、程度の文として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51816, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51816, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "対象を表す「を」。「色を擦り混ぜて」と擦り混ぜる対象を示し、文の意味に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す「が」。「色が擦り混ぜて」では色が自ら動くことになり、文の意味に合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「色の擦り混ぜて」では名詞同士の関係にならず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較・起点を表す「より」。「色より擦り混ぜて」では擦り混ぜる対象を示せず不自然。"}], "correct_answer": "を", "explanations": {"を": "対象を表す「を」。「色を擦り混ぜて」と擦り混ぜる対象を示し、文の意味に合う。", "が": "主語を表す「が」。「色が擦り混ぜて」では色が自ら動くことになり、文の意味に合わない。", "の": "連体修飾の「の」。「色の擦り混ぜて」では名詞同士の関係にならず、文が成り立たない。", "より": "比較・起点を表す「より」。「色より擦り混ぜて」では擦り混ぜる対象を示せず不自然。"}, "error_tags": {"が": "主語", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51816, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "異なる色や材料を指などでこすり合わせて混ぜること。特に絵を描くときの技法の一つ。", "primary_collocate": null, "pronunciation": "すりまぜる", "ipa": "sɯɾimaze̞ɾɯ", "syllable_count": 5, "sentences": [{"text": "指先で色を擦り混ぜ、重ね塗りをする技法によって、私は心の中の風景を絵として表現している。", "target_word": "擦り混ぜ", "complexity_tier": "T4", "furigana": "指先[ゆびさき]で色[いろ]を擦[す]り混[ま]ぜ、重[かさ]ね塗[ぬ]りをする技法[ぎほう]によって、私[わたし]は心[こころ]の中[なか]の風景[ふうけい]を絵[え]として表現[ひょうげん]している。", "sentence_source": "mined"}, {"text": "パステルで描いた空の青と白を、指で擦り混ぜて柔らかい雲にした。", "target_word": "擦り混ぜて", "complexity_tier": "T3", "furigana": "パステルで描[えが]いた空[そら]の青[あお]と白[しろ]を、指[ゆび]で擦[す]り混[ま]ぜて柔[やわ]らかい雲[くも]にした。", "sentence_source": "generated"}, {"text": "油絵では、絵の具を筆ではなく指で擦り混ぜると、独特のぼかしが生まれる。", "target_word": "擦り混ぜる", "complexity_tier": "T3", "furigana": "油絵[あぶらえ]では、絵[え]の具[ぐ]を筆[ふで]ではなく指[ゆび]で擦[す]り混[ま]ぜると、独特[どくとく]のぼかしが生[う]まれる。", "sentence_source": "generated"}, {"text": "先生は「境目をなくしたいなら、二色を軽く擦り混ぜなさい」と言った。", "target_word": "擦り混ぜ", "complexity_tier": "T3", "furigana": "先生[せんせい]は「境目[さかいめ]をなくしたいなら、二色[にしょく]を軽[かる]く擦[す]り混[ま]ぜなさい」と言[い]った。", "sentence_source": "generated"}, {"text": "赤と黄色を紙の上で擦り混ぜたら、夕焼けのようなオレンジ色になった。", "target_word": "擦り混ぜた", "complexity_tier": "T3", "furigana": "赤[あか]と黄色[きいろ]を紙[かみ]の上[うえ]で擦[す]り混[ま]ぜたら、夕焼[ゆうや]けのようなオレンジ色[いろ]になった。", "sentence_source": "generated"}, {"text": "木炭の線を擦り混ぜないでおくと、力強い輪郭が残る。", "target_word": "擦り混ぜない", "complexity_tier": "T3", "furigana": "木炭[もくたん]の線[せん]を擦[す]り混[ま]ぜないでおくと、力強[ちからづよ]い輪郭[りんかく]が残[のこ]る。", "sentence_source": "generated"}, {"text": "彼女はチョークの粉を指で擦り混ぜ、淡い影をつけた。", "target_word": "擦り混ぜ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はチョークの粉[こな]を指[ゆび]で擦[す]り混[ま]ぜ、淡[あわ]い影[かげ]をつけた。", "sentence_source": "generated"}, {"text": "子どもたちはクレヨンの色を擦り混ぜて、新しい色を作った。", "target_word": "擦り混ぜて", "complexity_tier": "T3", "furigana": "子[こ]どもたちはクレヨンの色[いろ]を擦[す]り混[ま]ぜて、新[あたら]しい色[いろ]を作[つく]った。", "sentence_source": "generated"}, {"text": "色鉛筆の色を擦り混ぜれば、きれいなグラデーションが簡単に作れる。", "target_word": "擦り混ぜれば", "complexity_tier": "T3", "furigana": "色鉛筆[いろえんぴつ]の色[いろ]を擦[す]り混[ま]ぜれば、きれいなグラデーションが簡単[かんたん]に作[つく]れる。", "sentence_source": "generated"}, {"text": "絵の具が乾く前に擦り混ぜておかないと、色の境目が残ってしまう。", "target_word": "擦り混ぜて", "complexity_tier": "T3", "furigana": "絵[え]の具[ぐ]が乾[かわ]く前[まえ]に擦[す]り混[ま]ぜておかないと、色[いろ]の境目[さかいめ]が残[のこ]ってしまう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "擦り混ぜる", "label": "終止形"}, {"form": "擦り混ぜ", "label": "連用形"}, {"form": "擦り混ぜて", "label": "て形"}, {"form": "擦り混ぜた", "label": "過去形"}, {"form": "擦り混ぜない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "絵画で、指などで色をこすり合わせて混ぜ、境目をぼかす技法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13f97567-fed9-4616-b891-4a3279b2183f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51816, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "擦り混ぜ", "is_correct": true, "explanation": "連用形。「色を擦り混ぜ、重ね塗りをする」と後ろに続けられる形で、ここに入る。"}, {"text": "擦り混ぜる", "is_correct": false, "explanation": "終止形。「、」の前に置くと文が言い切りになり、「重ね塗りをする」と続かない。"}, {"text": "擦り混ぜない", "is_correct": false, "explanation": "否定形。「擦り混ぜないで」なら続くが、「擦り混ぜない、」では文が不自然に止まる。"}, {"text": "擦り混ぜよう", "is_correct": false, "explanation": "意志形。「擦り混ぜよう、」は意志を表す形で、「技法によって」の前には入らない。"}], "explanations": {"擦り混ぜ": "連用形。「色を擦り混ぜ、重ね塗りをする」と後ろに続けられる形で、ここに入る。", "擦り混ぜる": "終止形。「、」の前に置くと文が言い切りになり、「重ね塗りをする」と続かない。", "擦り混ぜない": "否定形。「擦り混ぜないで」なら続くが、「擦り混ぜない、」では文が不自然に止まる。", "擦り混ぜよう": "意志形。「擦り混ぜよう、」は意志を表す形で、「技法によって」の前には入らない。"}, "sentence_index": 0, "correct_answer": "擦り混ぜ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "色水は筆でよく擦り混ぜて、濃さを揃えた。", "explanation": "ここは〈かき混ぜる〉の意味。擦り混ぜるは指などで色をこすり合わせる技法で、液体を筆で混ぜる場面には使わない。"}, {"text": "猫の背中を優しく擦り混ぜると、猫は喉を鳴らした。", "explanation": "ここは〈撫でる〉の意味。擦り混ぜるは異なる色や材料を混ぜ合わせる行為で、一つのものを撫でる場面には使わない。"}, {"text": "キャンバスの絵の具の汚れを指で擦り混ぜて消した。", "explanation": "ここは〈擦り落とす〉の意味。擦り混ぜるは色同士を混ぜる技法で、汚れを取り除く意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51816, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "擦り混ぜ", "is_correct": true, "explanation": "連用形。「指で擦り混ぜ、淡い影をつけた」と続ける形で、ここに入る。"}, {"text": "擦り混ぜれば", "is_correct": false, "explanation": "仮定形。「〜れば」の仮定が文末の過去と噛み合わず、連用形の位置に入らない。"}, {"text": "擦り混ぜられ", "is_correct": false, "explanation": "受身の連用形。主語の「彼女」が擦られる側になり、擦る行為者として合わない。"}, {"text": "擦り混ぜなかった", "is_correct": false, "explanation": "否定の過去形。「擦り混ぜなかった、」と続けると文が成り立たず、淡い影をつけた結果とも合わない。"}], "explanations": {"擦り混ぜ": "連用形。「指で擦り混ぜ、淡い影をつけた」と続ける形で、ここに入る。", "擦り混ぜれば": "仮定形。「〜れば」の仮定が文末の過去と噛み合わず、連用形の位置に入らない。", "擦り混ぜられ": "受身の連用形。主語の「彼女」が擦られる側になり、擦る行為者として合わない。", "擦り混ぜなかった": "否定の過去形。「擦り混ぜなかった、」と続けると文が成り立たず、淡い影をつけた結果とも合わない。"}, "sentence_index": 6, "correct_answer": "擦り混ぜ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鉛筆を小刀で擦り混ぜると、芯が現れる。", "explanation": "ここは〈削る〉の意味。擦り混ぜるは色同士をこすり合わせる技法で、物を削り取る意味では使わない。"}, {"text": "床を雑巾で擦り混ぜて、きれいに拭いた。", "explanation": "ここは〈拭く〉の意味。擦り混ぜるは色や材料を混ぜ合わせる動作で、床を拭き取る意味では使わない。"}, {"text": "ガラスを布で擦り混ぜると、きれいに光る。", "explanation": "ここは〈磨く〉の意味。擦り混ぜるは色を混ぜ合わせる行為で、表面を磨いて光らせる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51816, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "絵の具を指に擦り混ぜると、やわらかいぼかしが生まれる。", "corrected_sentence": "絵の具を指で擦り混ぜると、やわらかいぼかしが生まれる。", "error_description": "正しくは「指で」。擦り混ぜる手段を表す「で」が必要で、「指に」では道具を使う動作として意味が通らない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "擦り混ぜて", "is_correct": true, "explanation": "て形。「指で擦り混ぜて、柔らかい雲にした」と動作を続ける形で、ここに入る。"}, {"text": "擦り混ぜる", "is_correct": false, "explanation": "終止形。文の途中に置くと言い切りになり、「柔らかい雲にした」とつながらない。"}, {"text": "擦り混ぜ", "is_correct": false, "explanation": "連用形。「て」がないと「柔らかい雲にした」に接続せず、文として不完全になる。"}, {"text": "擦り混ぜない", "is_correct": false, "explanation": "否定形。否定になると雲を作った動作と意味が逆になり、文が成り立たない。"}], "correct_form": "擦り混ぜて", "base_form": "擦り混ぜる", "form_label": "て形", "sentence_index": 1, "explanations": {"擦り混ぜて": "て形。「指で擦り混ぜて、柔らかい雲にした」と動作を続ける形で、ここに入る。", "擦り混ぜる": "終止形。文の途中に置くと言い切りになり、「柔らかい雲にした」とつながらない。", "擦り混ぜ": "連用形。「て」がないと「柔らかい雲にした」に接続せず、文として不完全になる。", "擦り混ぜない": "否定形。否定になると雲を作った動作と意味が逆になり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51816, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は指で色を擦り混ぜる、柔らかい影をつけた。", "corrected_sentence": "彼は指で色を擦り混ぜ、柔らかい影をつけた。", "error_description": "正しくは連用形「擦り混ぜ」。終止形の「擦り混ぜる」は「、」の前で言い切りになり、「柔らかい影をつけた」と続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "擦り混ぜて", "is_correct": true, "explanation": "て形。「色を擦り混ぜて、新しい色を作った」と動作を続ける形で、ここに入る。"}, {"text": "擦り混ぜたい", "is_correct": false, "explanation": "希望の形。「擦り混ぜたい、新しい色を作った」では希望と結果がつながらない。"}, {"text": "擦り混ぜられ", "is_correct": false, "explanation": "受身の連用形。子どもたちが擦られる側になり、行為の主体と合わない。"}, {"text": "擦り混ぜなかった", "is_correct": false, "explanation": "否定の過去形。「擦り混ぜなかった、」と続けると文が成り立たず、新しい色を作った動作と合わない。"}], "correct_form": "擦り混ぜて", "base_form": "擦り混ぜる", "form_label": "て形", "sentence_index": 7, "explanations": {"擦り混ぜて": "て形。「色を擦り混ぜて、新しい色を作った」と動作を続ける形で、ここに入る。", "擦り混ぜたい": "希望の形。「擦り混ぜたい、新しい色を作った」では希望と結果がつながらない。", "擦り混ぜられ": "受身の連用形。子どもたちが擦られる側になり、行為の主体と合わない。", "擦り混ぜなかった": "否定の過去形。「擦り混ぜなかった、」と続けると文が成り立たず、新しい色を作った動作と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
