INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51817, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51817, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "ざらざらした感じがあること。", "primary_collocate": null, "pronunciation": "ざらつく", "ipa": "zaɾatsɯkɯ", "syllable_count": 4, "sentences": [{"text": "砂浜を歩いたあと、足の裏がざらつく。", "target_word": "ざらつく", "complexity_tier": "T3", "furigana": "砂浜[すなはま]を歩[ある]いたあと、足[あし]の裏[うら]がざらつく。", "sentence_source": "generated"}, {"text": "風邪で舌がざらつき、味がよく分からなかった。", "target_word": "ざらつき", "complexity_tier": "T3", "furigana": "風邪[かぜ]で舌[した]がざらつき、味[あじ]がよく分[わ]からなかった。", "sentence_source": "generated"}, {"text": "洗ったタオルが乾いてざらつくのは、柔軟剤を使わなかったからだ。", "target_word": "ざらつく", "complexity_tier": "T3", "furigana": "洗[あら]ったタオルが乾[かわ]いてざらつくのは、柔軟剤[じゅうなんざい]を使[つか]わなかったからだ。", "sentence_source": "generated"}, {"text": "目にごみが入ったのか、まぶたの裏がざらついた感じがする。", "target_word": "ざらついた", "complexity_tier": "T3", "furigana": "目[め]にごみが入[はい]ったのか、まぶたの裏[うら]がざらついた感[かん]じがする。", "sentence_source": "generated"}, {"text": "寒い日は頬がざらつくので、化粧水をたっぷり使う。", "target_word": "ざらつく", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]は頬[ほお]がざらつくので、化粧水[けしょうすい]をたっぷり使[つか]う。", "sentence_source": "generated"}, {"text": "机の上を手でなでると、細かい粉で少しざらついていた。", "target_word": "ざらついて", "complexity_tier": "T3", "furigana": "机[つくえ]の上[うえ]を手[て]でなでると、細[こま]かい粉[こな]で少[すこ]しざらついていた。", "sentence_source": "generated"}, {"text": "焼きすぎたパンの皮は、口に当たるとざらつく。", "target_word": "ざらつく", "complexity_tier": "T3", "furigana": "焼[や]きすぎたパンの皮[かわ]は、口[くち]に当[あ]たるとざらつく。", "sentence_source": "generated"}, {"text": "ざらつかない生地を選ぶために、店で一枚ずつ触って確かめた。", "target_word": "ざらつかない", "complexity_tier": "T3", "furigana": "ざらつかない生地[きじ]を選[えら]ぶために、店[みせ]で一枚[いちまい]ずつ触[さわ]って確[たし]かめた。", "sentence_source": "generated"}, {"text": "長く使った砥石の面は、指で触るとざらついている。", "target_word": "ざらついて", "complexity_tier": "T3", "furigana": "長[なが]く使[つか]った砥石[といし]の面[めん]は、指[ゆび]で触[さわ]るとざらついている。", "sentence_source": "generated"}, {"text": "海から戻った髪は、塩でざらつきやすい。", "target_word": "ざらつき", "complexity_tier": "T3", "furigana": "海[うみ]から戻[もど]った髪[かみ]は、塩[しお]でざらつきやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ざらつく", "label": "終止形"}, {"form": "ざらつき", "label": "連用形"}, {"form": "ざらついて", "label": "て形"}, {"form": "ざらついた", "label": "過去形"}, {"form": "ざらつかない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "肌・舌・布などに、ざらざらした感触がある", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13f97567-fed9-4616-b891-4a3279b2183f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51817, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ざらつく", "is_correct": true, "explanation": "終止形。「足の裏がざらつく」と言い切る形で、砂浜を歩いた後の感覚を述べる文に合う。"}, {"text": "ざらつき", "is_correct": false, "explanation": "連用形。単独では文を言い切れず、「足の裏がざらつき。」は不完全になる。"}, {"text": "ざらついて", "is_correct": false, "explanation": "て形。文末に置くと言い切れず、続きの文がないと成立しない。"}, {"text": "ざらつかせ", "is_correct": false, "explanation": "使役の連用形。足の裏に何かをさせる意味になり、主語と合わない。"}], "explanations": {"ざらつく": "終止形。「足の裏がざらつく」と言い切る形で、砂浜を歩いた後の感覚を述べる文に合う。", "ざらつき": "連用形。単独では文を言い切れず、「足の裏がざらつき。」は不完全になる。", "ざらついて": "て形。文末に置くと言い切れず、続きの文がないと成立しない。", "ざらつかせ": "使役の連用形。足の裏に何かをさせる意味になり、主語と合わない。"}, "sentence_index": 0, "correct_answer": "ざらつく"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "寒い夜は、湯たんぽで足がざらつくほど心地よい。", "explanation": "ここは〈ぬくぬく〉の意味。ざらつくは不快な凹凸の感触で、心地よい温かさを表す場面には使わない。"}, {"text": "ぶつけた肘が、ざらつくほど滑らかになった。", "explanation": "ここは〈すべすべ〉の意味。ざらつくは凹凸のある粗い感触で、すべすべとした滑らかさを表す場面には使わない。"}, {"text": "納豆をかき混ぜると、指がざらつく。", "explanation": "ここは〈ねばねば〉の意味。ざらつくは細かい凹凸の感触で、粘りつく感じには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51817, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ざらつく", "is_correct": true, "explanation": "終止形。「口に当たるとざらつく」と条件の「と」に続く形で、ここに入る。"}, {"text": "ざらつけば", "is_correct": false, "explanation": "仮定形。「当たるとざらつけば」と二重の条件になり、文の意味が通らない。"}, {"text": "ざらつこう", "is_correct": false, "explanation": "意志形。皮が意志を持つ意味になり、事実を述べる文に合わない。"}, {"text": "ざらつかせる", "is_correct": false, "explanation": "使役の終止形。目的語がなく、「当たるとざらつかせる」では成立しない。"}], "explanations": {"ざらつく": "終止形。「口に当たるとざらつく」と条件の「と」に続く形で、ここに入る。", "ざらつけば": "仮定形。「当たるとざらつけば」と二重の条件になり、文の意味が通らない。", "ざらつこう": "意志形。皮が意志を持つ意味になり、事実を述べる文に合わない。", "ざらつかせる": "使役の終止形。目的語がなく、「当たるとざらつかせる」では成立しない。"}, "sentence_index": 6, "correct_answer": "ざらつく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い朝は、指先がざらついて感覚が消える。", "explanation": "ここは〈麻痺〉の意味。ざらつくは表面の凹凸による感触で、感覚が失われる状態には使わない。"}, {"text": "辛いスープを飲むと、舌がざらつくどころか、なめらかになる。", "explanation": "ここは〈つるつる〉の意味。ざらつくは細かい凹凸の不快な感触で、滑らかに変わる状態には使わない。"}, {"text": "ゆでた卵の殻をむくと、白身がざらつくどころか、弾むように揺れる。", "explanation": "ここは〈弾力〉の意味。ざらつくは細かい凹凸の感触で、弾力による揺れを表す場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51817, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海水を浴びたあと、肩の肌をざらつく。", "corrected_sentence": "海水を浴びたあと、肩の肌がざらつく。", "error_description": "正しくは「肌が」。ざらつくは主語の「肌」に「が」を付ける自動詞。「を」では他動詞のように見え、文として成立しない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ざらつき", "is_correct": true, "explanation": "連用形。「舌がざらつき、味がよく分からなかった」と後ろに続ける形で、ここに入る。"}, {"text": "ざらつく", "is_correct": false, "explanation": "終止形。「舌がざらつく、味が」と「、」の前で言い切ると、後ろの文とつながらない。"}, {"text": "ざらつかない", "is_correct": false, "explanation": "否定形。舌がざらつかなかったという意味になり、味が分からなかった理由と合わない。"}, {"text": "ざらつかせ", "is_correct": false, "explanation": "使役の連用形。舌に何かをさせる意味になり、主語「舌」と合わない。"}], "correct_form": "ざらつき", "base_form": "ざらつく", "form_label": "連用形", "sentence_index": 1, "explanations": {"ざらつき": "連用形。「舌がざらつき、味がよく分からなかった」と後ろに続ける形で、ここに入る。", "ざらつく": "終止形。「舌がざらつく、味が」と「、」の前で言い切ると、後ろの文とつながらない。", "ざらつかない": "否定形。舌がざらつかなかったという意味になり、味が分からなかった理由と合わない。", "ざらつかせ": "使役の連用形。舌に何かをさせる意味になり、主語「舌」と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51817, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒風に吹かれたあと、頬がざらつくた。", "corrected_sentence": "寒風に吹かれたあと、頬がざらつく。", "error_description": "正しくは「ざらつく」。「ざらつくた」は存在しない形で、過去形は「ざらついた」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ざらつかない", "is_correct": true, "explanation": "否定形。「ざらつかない生地」と名詞を修飾する形で、ここに入る。"}, {"text": "ざらつけば", "is_correct": false, "explanation": "仮定形。「ざらつけば生地」と名詞を修飾できず、文の構造が成り立たない。"}, {"text": "ざらつこう", "is_correct": false, "explanation": "意志形。「ざらつこう生地」では名詞を修飾できず、不自然な文になる。"}, {"text": "ざらつかせる", "is_correct": false, "explanation": "使役の終止形。生地に何かをさせる意味になり、「ざらつかせる生地」は文意が合わない。"}], "correct_form": "ざらつかない", "base_form": "ざらつく", "form_label": "否定形", "sentence_index": 7, "explanations": {"ざらつかない": "否定形。「ざらつかない生地」と名詞を修飾する形で、ここに入る。", "ざらつけば": "仮定形。「ざらつけば生地」と名詞を修飾できず、文の構造が成り立たない。", "ざらつこう": "意志形。「ざらつこう生地」では名詞を修飾できず、不自然な文になる。", "ざらつかせる": "使役の終止形。生地に何かをさせる意味になり、「ざらつかせる生地」は文意が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
