INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51818, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51818, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "property", "definition": "表面が滑らかでなく、細かい凹凸があって触ると不快な感じがすること。また、そのような質感。", "primary_collocate": null, "pronunciation": "ざらつく", "ipa": "zaɾatsɯkɯ", "syllable_count": 4, "sentences": [{"text": "クレヨンのざらついた質感と鮮やかな色彩が交わる瞬間、言葉にできない感情が視覚化されていく。", "target_word": "ざらついた", "complexity_tier": "T4", "furigana": "クレヨンのざらついた質感[しつかん]と鮮[あざ]やかな色彩[しきさい]が交[まじ]わる瞬間[しゅんかん]、言葉[ことば]にできない感情[かんじょう]が視覚化[しかくか]されていく。", "sentence_source": "mined"}, {"text": "冬は空気が乾燥して、手の甲がざらつく。", "target_word": "ざらつく", "complexity_tier": "T3", "furigana": "冬[ふゆ]は空気[くうき]が乾燥[かんそう]して、手[て]の甲[こう]がざらつく。", "sentence_source": "generated"}, {"text": "古い机の表面がざらついていて、指にささくれが刺さった。", "target_word": "ざらついて", "complexity_tier": "T3", "furigana": "古[ふる]い机[つくえ]の表面[ひょうめん]がざらついていて、指[ゆび]にささくれが刺[さ]さった。", "sentence_source": "generated"}, {"text": "砂が入ったのか、口の中がざらついて気持ちが悪い。", "target_word": "ざらついて", "complexity_tier": "T3", "furigana": "砂[すな]が入[はい]ったのか、口[くち]の中[なか]がざらついて気持[きも]ちが悪[わる]い。", "sentence_source": "generated"}, {"text": "紙やすりをかけたら、ざらついた壁がつるつるになった。", "target_word": "ざらついた", "complexity_tier": "T3", "furigana": "紙[かみ]やすりをかけたら、ざらついた壁[かべ]がつるつるになった。", "sentence_source": "generated"}, {"text": "洗剤で洗いすぎると、肌がざらついてしまう。", "target_word": "ざらついて", "complexity_tier": "T3", "furigana": "洗剤[せんざい]で洗[あら]いすぎると、肌[はだ]がざらついてしまう。", "sentence_source": "generated"}, {"text": "床がざらつくのは、窓から入った砂ぼこりが積もっているからだ。", "target_word": "ざらつく", "complexity_tier": "T3", "furigana": "床[ゆか]がざらつくのは、窓[まど]から入[はい]った砂[すな]ぼこりが積[つ]もっているからだ。", "sentence_source": "generated"}, {"text": "日焼けした唇がざらつかないよう、毎晩クリームを塗っている。", "target_word": "ざらつかない", "complexity_tier": "T3", "furigana": "日焼[ひや]けした唇[くちびる]がざらつかないよう、毎晩[まいばん]クリームを塗[ぬ]っている。", "sentence_source": "generated"}, {"text": "雨にぬれた木の板は、乾くと表面がざらつきやすい。", "target_word": "ざらつき", "complexity_tier": "T3", "furigana": "雨[あめ]にぬれた木[き]の板[いた]は、乾[かわ]くと表面[ひょうめん]がざらつきやすい。", "sentence_source": "generated"}, {"text": "この紙はざらついているので、鉛筆の線がよくのる。", "target_word": "ざらついて", "complexity_tier": "T3", "furigana": "この紙[かみ]はざらついているので、鉛筆[えんぴつ]の線[せん]がよくのる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ざらつく", "label": "終止形"}, {"form": "ざらつき", "label": "連用形"}, {"form": "ざらついて", "label": "て形"}, {"form": "ざらついた", "label": "過去形"}, {"form": "ざらつかない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "表面に細かい凹凸があり、触れると滑らかでなく不快に感じる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13f97567-fed9-4616-b891-4a3279b2183f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51818, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ざらついた", "is_correct": true, "explanation": "過去形の連体形「ざらついた」。「質感」を修飾し、ここに入る。"}, {"text": "ざらつけ", "is_correct": false, "explanation": "命令形。「ざらつけ質感」と名詞を修飾できず、文が成り立たない。"}, {"text": "ざらつき", "is_correct": false, "explanation": "連用形の名詞的用法。「ざらつきた」では過去の連体形が作れず、文が成り立たない。"}, {"text": "ざらつこう", "is_correct": false, "explanation": "意志形。「ざらつこう質感」と名詞を修飾できず、文が成り立たない。"}], "explanations": {"ざらついた": "過去形の連体形「ざらついた」。「質感」を修飾し、ここに入る。", "ざらつけ": "命令形。「ざらつけ質感」と名詞を修飾できず、文が成り立たない。", "ざらつき": "連用形の名詞的用法。「ざらつきた」では過去の連体形が作れず、文が成り立たない。", "ざらつこう": "意志形。「ざらつこう質感」と名詞を修飾できず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "ざらついた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜂蜜をこぼした机が、触るとざらついて手が離れない。", "explanation": "ここは〈べたつく〉の意味。ざらつくは細かい凹凸の感触で、粘って離れない感じには使わない。"}, {"text": "釣り上げた魚は、体がざらついて指が滑り、掴めない。", "explanation": "ここは〈ぬめり〉の意味。ざらつくは細かい凹凸の感触で、粘液による滑りを表す場面には使わない。"}, {"text": "洗濯したシーツは、ざらついて赤く染まった。", "explanation": "ここは〈染色〉の意味。ざらつくは表面の凹凸による感触で、色が変わる状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51818, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ざらつく", "is_correct": true, "explanation": "終止形。「床がざらつくのは〜からだ」と主語に続く形で、ここに入る。"}, {"text": "ざらつけば", "is_correct": false, "explanation": "仮定形。「ざらつけばのは」と続かず、主語を述べる文の形にならない。"}, {"text": "ざらつこう", "is_correct": false, "explanation": "意志形。床が意志を持つ意味になり、事実を説明する文と合わない。"}, {"text": "ざらつかせる", "is_correct": false, "explanation": "使役の終止形。目的語のない文では成立せず、「床がざらつかせる」は不自然。"}], "explanations": {"ざらつく": "終止形。「床がざらつくのは〜からだ」と主語に続く形で、ここに入る。", "ざらつけば": "仮定形。「ざらつけばのは」と続かず、主語を述べる文の形にならない。", "ざらつこう": "意志形。床が意志を持つ意味になり、事実を説明する文と合わない。", "ざらつかせる": "使役の終止形。目的語のない文では成立せず、「床がざらつかせる」は不自然。"}, "sentence_index": 6, "correct_answer": "ざらつく"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "保湿クリームを塗ると、肌がざらついて落ち着く。", "explanation": "ここは〈しっとり〉の意味。ざらつくは凹凸のある不快な感触で、潤って落ち着く状態には使わない。"}, {"text": "磨いた床がざらついて光っている。", "explanation": "ここは〈ぴかぴか〉の意味。ざらつくは表面が滑らかでない感触で、光沢を表す場面には使わない。"}, {"text": "ガラスのコップは、ざらついて指がよく滑る。", "explanation": "ここは〈つるつる〉の意味。ざらつくは細かい凹凸の不快な感触で、滑らかで指が滑る状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51818, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨に濡れた床の表面をざらつき、靴下が引っかかる。", "corrected_sentence": "雨に濡れた床の表面がざらつき、靴下が引っかかる。", "error_description": "正しくは「表面が」。ざらつくは自動詞で、主語の「表面」に「が」を付ける。「を」では他動詞のように見え、文として成立しない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ざらつく", "is_correct": true, "explanation": "終止形。「手の甲がざらつく」と言い切る形で、冬の乾燥の事実を述べる文に合う。"}, {"text": "ざらつき", "is_correct": false, "explanation": "連用形。単独では文を言い切れず、「手の甲がざらつき。」は不完全になる。"}, {"text": "ざらついて", "is_correct": false, "explanation": "て形。文末に置くと言い切れず、続きの文がないと成立しない。"}, {"text": "ざらつかせ", "is_correct": false, "explanation": "使役の連用形。「手の甲をざらつかせる」の意味になり、主語「手の甲」と合わない。"}], "correct_form": "ざらつく", "base_form": "ざらつく", "form_label": "終止形", "sentence_index": 1, "explanations": {"ざらつく": "終止形。「手の甲がざらつく」と言い切る形で、冬の乾燥の事実を述べる文に合う。", "ざらつき": "連用形。単独では文を言い切れず、「手の甲がざらつき。」は不完全になる。", "ざらついて": "て形。文末に置くと言い切れず、続きの文がないと成立しない。", "ざらつかせ": "使役の連用形。「手の甲をざらつかせる」の意味になり、主語「手の甲」と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51818, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古いノートの紙は、指でなでるとざらつかく。", "corrected_sentence": "古いノートの紙は、指でなでるとざらつく。", "error_description": "正しくは「ざらつく」。「ざらつかく」は存在しない活用で、否定形「ざらつかない」と混同した誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ざらつかない", "is_correct": true, "explanation": "否定形。「ざらつかないよう」と目的を表す形で続き、ここに入る。"}, {"text": "ざらつけば", "is_correct": false, "explanation": "仮定形。「ざらつけばよう」では目的の形にならず、文が成り立たない。"}, {"text": "ざらつこう", "is_correct": false, "explanation": "意志形。「ざらつこうよう」では成立せず、目的を表す文に入らない。"}, {"text": "ざらつかせる", "is_correct": false, "explanation": "使役の終止形。唇に何かをさせる意味になり、「ざらつかせるよう」は不自然。"}], "correct_form": "ざらつかない", "base_form": "ざらつく", "form_label": "否定形", "sentence_index": 7, "explanations": {"ざらつかない": "否定形。「ざらつかないよう」と目的を表す形で続き、ここに入る。", "ざらつけば": "仮定形。「ざらつけばよう」では目的の形にならず、文が成り立たない。", "ざらつこう": "意志形。「ざらつこうよう」では成立せず、目的を表す文に入らない。", "ざらつかせる": "使役の終止形。唇に何かをさせる意味になり、「ざらつかせるよう」は不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51819, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「明るくなる」は自動詞なので目的語を取らず、合わない。"}, {"text": "が", "is_correct": true, "explanation": "「色彩」が「明るくなる」の主語になるので「が」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は変化の相手や結果を示すが、主語の「色彩」には「が」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は移動の方向を示す助詞で、色の変化の主語には使えない。"}], "correct_answer": "が", "explanations": {"を": "「を」は目的語を示すが、「明るくなる」は自動詞なので目的語を取らず、合わない。", "が": "「色彩」が「明るくなる」の主語になるので「が」が正しい。", "に": "「に」は変化の相手や結果を示すが、主語の「色彩」には「が」が必要。", "へ": "「へ」は移動の方向を示す助詞で、色の変化の主語には使えない。"}, "error_tags": {"を": "目的語", "に": "変化の相手・結果", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51819, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す助詞で、ここでは主語を示せない。"}, {"text": "が", "is_correct": true, "explanation": "「色彩」に直接付き、「多すぎる」の主語になるので「が」が正しい。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比べる意味を表し、「多すぎる」の主語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、色の多さを表す主語にはならない。"}], "correct_answer": "が", "explanations": {"と": "「と」は並列や相手を示す助詞で、ここでは主語を示せない。", "が": "「色彩」に直接付き、「多すぎる」の主語になるので「が」が正しい。", "より": "「より」は比べる意味を表し、「多すぎる」の主語にはならない。", "から": "「から」は起点を示し、色の多さを表す主語にはならない。"}, "error_tags": {"と": "並列・相手", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51819, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いろ", "primary_collocate": null, "pronunciation": "しきさい", "ipa": "ɕikisai", "syllable_count": 4, "sentences": [{"text": "この絵は色彩が豊かで、見ていると元気が出ます。", "target_word": "色彩", "complexity_tier": "T3", "furigana": "この絵[え]は色彩[しきさい]が豊[ゆた]かで、見[み]ていると元気[げんき]が出[で]ます。", "sentence_source": "generated"}, {"text": "春になると、町の色彩が明るくなります。", "target_word": "色彩", "complexity_tier": "T3", "furigana": "春[はる]になると、町[まち]の色彩[しきさい]が明[あか]るくなります。", "sentence_source": "generated"}, {"text": "秋の山は赤や黄色の色彩が美しい。", "target_word": "色彩", "complexity_tier": "T3", "furigana": "秋[あき]の山[やま]は赤[あか]や黄色[きいろ]の色彩[しきさい]が美[うつく]しい。", "sentence_source": "generated"}, {"text": "彼女は色彩の感覚がするどく、服選びが上手だ。", "target_word": "色彩", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は色彩[しきさい]の感覚[かんかく]がするどく、服選[ふくえら]びが上手[じょうず]だ。", "sentence_source": "generated"}, {"text": "色彩が地味な部屋に、赤いカーテンをつけた。", "target_word": "色彩", "complexity_tier": "T3", "furigana": "色彩[しきさい]が地味[じみ]な部屋[へや]に、赤[あか]いカーテンをつけた。", "sentence_source": "generated"}, {"text": "画家はやわらかい色彩で海を描いた。", "target_word": "色彩", "complexity_tier": "T3", "furigana": "画家[がか]はやわらかい色彩[しきさい]で海[うみ]を描[えが]いた。", "sentence_source": "generated"}, {"text": "南の国の市場は色彩にあふれていた。", "target_word": "色彩", "complexity_tier": "T3", "furigana": "南[みなみ]の国[くに]の市場[いちば]は色彩[しきさい]にあふれていた。", "sentence_source": "generated"}, {"text": "色彩が多すぎて、このポスターは目が疲れる。", "target_word": "色彩", "complexity_tier": "T3", "furigana": "色彩[しきさい]が多[おお]すぎて、このポスターは目[め]が疲[つか]れる。", "sentence_source": "generated"}, {"text": "子どもの絵は自由な色彩で、見ていて楽しい。", "target_word": "色彩", "complexity_tier": "T3", "furigana": "子[こ]どもの絵[え]は自由[じゆう]な色彩[しきさい]で、見[み]ていて楽[たの]しい。", "sentence_source": "generated"}, {"text": "夕焼けの色彩は、毎日少しずつちがう。", "target_word": "色彩", "complexity_tier": "T3", "furigana": "夕焼[ゆうや]けの色彩[しきさい]は、毎日[まいにち]少[すこ]しずつちがう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "色彩", "label": "基本形"}, {"form": "色彩の", "label": "連体修飾（の）"}, {"form": "色彩が", "label": "主格"}, {"form": "色彩を", "label": "目的格"}], "register": "neutral", "sense_fingerprint": "ものや景色が持ついろ、いろの様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T3: contains vocabulary far above tier T3: するどく (Zipf 1.74)']::text[], 'eb6837b5-37ea-42d1-91e7-d13681740b4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51819, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "人や動物の重さを表す語で、絵の豊かさには合わない。"}, {"text": "電池", "is_correct": false, "explanation": "電気を蓄える装置で、絵の様子には結びつかない。"}, {"text": "色彩", "is_correct": true, "explanation": "絵の色のとり合わせや色合いを表し、「色彩が豊か」として文の意味に合う。"}, {"text": "気温", "is_correct": false, "explanation": "空気の温度を表す語で、絵の豊かさとは合わない。"}], "explanations": {"体重": "人や動物の重さを表す語で、絵の豊かさには合わない。", "電池": "電気を蓄える装置で、絵の様子には結びつかない。", "色彩": "絵の色のとり合わせや色合いを表し、「色彩が豊か」として文の意味に合う。", "気温": "空気の温度を表す語で、絵の豊かさとは合わない。"}, "sentence_index": 0, "correct_answer": "色彩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "あの俳優は色彩があって、女性に人気がある。", "explanation": "ここは〈色気〉の意味。色彩はものや景色のいろを指し、人の魅力には使わない。"}, {"text": "文化祭で色彩を配って、みんなで寄せ書きをした。", "explanation": "ここは〈色紙〉の意味。色彩は色の様子を指し、紙そのものを配るものではない。"}, {"text": "病気のあとで色彩がわるく、顔がずっと青白かった。", "explanation": "ここは〈顔色〉の意味。色彩は景色やものの色の取り合わせを指し、人の顔の血色には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51819, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "電卓", "is_correct": false, "explanation": "計算に使う機械で、市場の様子を表す語には合わない。"}, {"text": "鉄骨", "is_correct": false, "explanation": "建物の骨組みに使う鋼材で、あふれる様子とは結びつかない。"}, {"text": "深海", "is_correct": false, "explanation": "海の深い場所を指し、市場の様子には合わない。"}, {"text": "色彩", "is_correct": true, "explanation": "さまざまな色があふれている様子を表し、市場の様子に合う。"}], "explanations": {"電卓": "計算に使う機械で、市場の様子を表す語には合わない。", "鉄骨": "建物の骨組みに使う鋼材で、あふれる様子とは結びつかない。", "深海": "海の深い場所を指し、市場の様子には合わない。", "色彩": "さまざまな色があふれている様子を表し、市場の様子に合う。"}, "sentence_index": 6, "correct_answer": "色彩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は色彩で、緑と赤の区別がつかない。", "explanation": "ここは〈色盲〉の意味。色彩は色の様子を表し、人の目の状態を指す語ではない。"}, {"text": "子どもが色彩を三本使い切った。", "explanation": "ここは〈色鉛筆〉の意味。色彩は色の様子を指し、鉛筆のように本数で数えて使うものではない。"}, {"text": "この写真は色彩が高く、色がとても鮮やかだ。", "explanation": "ここは〈彩度〉の意味。彩度は色の鮮やかさの度合いで「高い」と言うが、色彩は「高い」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51819, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方になると、町の色彩を暗くなります。", "corrected_sentence": "夕方になると、町の色彩が暗くなります。", "error_description": "「暗くなる」の主語は「色彩」なので「が」が正しい。「を」は目的語の助詞で、自動詞「暗くなる」とは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51819, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕焼けの色彩は、毎日少しずつ変わられている。", "corrected_sentence": "夕焼けの色彩は、毎日少しずつ変わっている。", "error_description": "自動詞「変わる」には受身形「変わられ」がなく、文として成り立たない。正しくは「変わっている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
