INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51821, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二つのものが、いっしょになること。", "primary_collocate": null, "pronunciation": "まじわる", "ipa": "madʒiwaɾɯ", "syllable_count": 4, "sentences": [{"text": "二つの川が交わって、大きな流れになる。", "target_word": "交わって", "complexity_tier": "T3", "furigana": "二[ふた]つの川[かわ]が交[まじ]わって、大[おお]きな流[なが]れになる。", "sentence_source": "generated"}, {"text": "東西の文化が交わる港町で、新しい料理が生まれた。", "target_word": "交わる", "complexity_tier": "T3", "furigana": "東西[とうざい]の文化[ぶんか]が交[まじ]わる港町[みなとまち]で、新[あたら]しい料理[りょうり]が生[う]まれた。", "sentence_source": "generated"}, {"text": "冷たい空気と暖かい空気が交わる場所では、雲ができやすい。", "target_word": "交わる", "complexity_tier": "T3", "furigana": "冷[つめ]たい空気[くうき]と暖[あたた]かい空気[くうき]が交[まじ]わる場所[ばしょ]では、雲[くも]ができやすい。", "sentence_source": "generated"}, {"text": "山から来た水と海の水が交わる河口には、魚が多い。", "target_word": "交わる", "complexity_tier": "T3", "furigana": "山[やま]から来[き]た水[みず]と海[うみ]の水[みず]が交[まじ]わる河口[かこう]には、魚[さかな]が多[おお]い。", "sentence_source": "generated"}, {"text": "二つの流派が交わり、新しい画風が生まれた。", "target_word": "交わり", "complexity_tier": "T3", "furigana": "二[ふた]つの流派[りゅうは]が交[まじ]わり、新[あたら]しい画風[がふう]が生[う]まれた。", "sentence_source": "generated"}, {"text": "古い伝統と新しい技術が交わり、独特のデザインが生まれた。", "target_word": "交わり", "complexity_tier": "T3", "furigana": "古[ふる]い伝統[でんとう]と新[あたら]しい技術[ぎじゅつ]が交[まじ]わり、独特[どくとく]のデザインが生[う]まれた。", "sentence_source": "generated"}, {"text": "二人の笑い声が交わって、部屋じゅうに響いた。", "target_word": "交わって", "complexity_tier": "T3", "furigana": "二人[ふたり]の笑[わら]い声[ごえ]が交[まじ]わって、部屋[へや]じゅうに響[ひび]いた。", "sentence_source": "generated"}, {"text": "二つの小さなグループが交わり、一つのチームになった。", "target_word": "交わり", "complexity_tier": "T3", "furigana": "二[ふた]つの小[ちい]さなグループが交[まじ]わり、一[ひと]つのチームになった。", "sentence_source": "generated"}, {"text": "二つの意見が交わり、やがて一つの案にまとまった。", "target_word": "交わり", "complexity_tier": "T3", "furigana": "二[ふた]つの意見[いけん]が交[まじ]わり、やがて一[ひと]つの案[あん]にまとまった。", "sentence_source": "generated"}, {"text": "別々に歩いていた二人の道が交わり、夫婦として歩き始めた。", "target_word": "交わり", "complexity_tier": "T3", "furigana": "別々[べつべつ]に歩[ある]いていた二人[ふたり]の道[みち]が交[まじ]わり、夫婦[ふうふ]として歩[ある]き始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交わる", "label": "終止形"}, {"form": "交わり", "label": "連用形"}, {"form": "交わって", "label": "て形"}, {"form": "交わった", "label": "過去形"}, {"form": "交わらない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "二つの流れ・文化・意見などが合流して一つになる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13f97567-fed9-4616-b891-4a3279b2183f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51821, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交わって", "is_correct": true, "explanation": "て形で、「、大きな流れになる」と続けて文が成り立つ。"}, {"text": "交わろう", "is_correct": false, "explanation": "意向形で、後ろの「大きな流れになる」とつながらない。"}, {"text": "交われ", "is_correct": false, "explanation": "命令形で、文の流れに合わない。"}, {"text": "交わるな", "is_correct": false, "explanation": "禁止形。「交わるな、〜」と命じる文になり、事実を述べる文に合わない。"}], "explanations": {"交わって": "て形で、「、大きな流れになる」と続けて文が成り立つ。", "交わろう": "意向形で、後ろの「大きな流れになる」とつながらない。", "交われ": "命令形で、文の流れに合わない。", "交わるな": "禁止形。「交わるな、〜」と命じる文になり、事実を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "交わって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は若いころ、怪しい仲間に交わっていたらしい。", "explanation": "ここは〈交際する〉の意味。〈交わる〉は二つのものがいっしょになる意味なので、人と付き合う場面には使わない。"}, {"text": "二つの作品が交わって、どちらが優れているか比べられた。", "explanation": "ここは〈比べる〉の場面。〈交わる〉は二つのものがいっしょになる意味なので、優劣を比べる様子は表さない。"}, {"text": "二つの勢力が交わって、激しい戦いになった。", "explanation": "ここは〈衝突する〉の場面。〈交わる〉は二つのものがいっしょになる意味で、対立してぶつかる様子は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51821, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交わって", "is_correct": true, "explanation": "て形で、「、部屋じゅうに響いた」と続けて文が成り立つ。"}, {"text": "交わる", "is_correct": false, "explanation": "辞書形で、「、」の後に続けると文として成り立たない。"}, {"text": "交わるな", "is_correct": false, "explanation": "禁止の形で、文の流れに合わない。"}, {"text": "交わらせ", "is_correct": false, "explanation": "使役の連用形で、「笑い声が交わらせ」は文として成り立たない。"}], "explanations": {"交わって": "て形で、「、部屋じゅうに響いた」と続けて文が成り立つ。", "交わる": "辞書形で、「、」の後に続けると文として成り立たない。", "交わるな": "禁止の形で、文の流れに合わない。", "交わらせ": "使役の連用形で、「笑い声が交わらせ」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "交わって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一本の川が途中で二つに交わって、海へ流れていく。", "explanation": "ここは〈二つに分かれる〉の場面。〈交わる〉は二つのものが一つになる意味で、分かれる様子は表さない。"}, {"text": "床いっぱいに、ビーズが交わっている。", "explanation": "ここは〈散らばる〉の場面。〈交わる〉は一つになる意味で、散らばって広がる様子は表さない。"}, {"text": "二つの組織が激しく交わっていた。", "explanation": "ここは〈対立する〉の場面。〈交わる〉は一つになる意味で、対立し合う関係は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51821, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "温かい湯と冷たい水が交われて、ちょうどいい温度になった。", "corrected_sentence": "温かい湯と冷たい水が交わって、ちょうどいい温度になった。", "error_description": "「交わる」のて形は「交わって」。「交われて」は活用の誤りで、正しくは「交わって」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "交わる", "is_correct": true, "explanation": "連体形。直後の「港町」を修飾している。"}, {"text": "交わって", "is_correct": false, "explanation": "て形で、名詞「港町」を修飾できない。"}, {"text": "交わり", "is_correct": false, "explanation": "連用形で、直後の「港町」を修飾する形にならない。"}, {"text": "交われ", "is_correct": false, "explanation": "命令形。名詞「港町」を修飾できず、文が成り立たない。"}], "correct_form": "交わる", "base_form": "交わる", "form_label": "連体形", "sentence_index": 1, "explanations": {"交わる": "連体形。直後の「港町」を修飾している。", "交わって": "て形で、名詞「港町」を修飾できない。", "交わり": "連用形で、直後の「港町」を修飾する形にならない。", "交われ": "命令形。名詞「港町」を修飾できず、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51821, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二つの流れを湖の入り口で交わって一つになった。", "corrected_sentence": "二つの流れが湖の入り口で交わって一つになった。", "error_description": "「交わる」の主語は「が」で示す。「を」は誤りで、正しくは「流れが」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "交わり", "is_correct": true, "explanation": "連用形。「、一つのチームになった」と中止形で続けて文が成り立つ。"}, {"text": "交わる", "is_correct": false, "explanation": "終止形で、「、」に続けると文が成り立たない。"}, {"text": "交われ", "is_correct": false, "explanation": "命令形。「交われ、一つのチームになった」と命じる文になり、事実を述べる文に合わない。"}, {"text": "交わらない", "is_correct": false, "explanation": "否定形で、「、一つのチームになった」と続けると文が成り立たない。"}], "correct_form": "交わり", "base_form": "交わる", "form_label": "連用形", "sentence_index": 7, "explanations": {"交わり": "連用形。「、一つのチームになった」と中止形で続けて文が成り立つ。", "交わる": "終止形で、「、」に続けると文が成り立たない。", "交われ": "命令形。「交われ、一つのチームになった」と命じる文になり、事実を述べる文に合わない。", "交わらない": "否定形で、「、一つのチームになった」と続けると文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
