INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51822, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "二つ以上のものが、一点で出会ったり、重なったりすること。", "primary_collocate": null, "pronunciation": "まじわる", "ipa": "madʒiwaɾɯ", "syllable_count": 4, "sentences": [{"text": "二本の線が交わる瞬間、光が一点に集まった。", "target_word": "交わる", "complexity_tier": "T3", "furigana": "二本[にほん]の線[せん]が交[まじ]わる瞬間[しゅんかん]、光[ひかり]が一点[いってん]に集[あつ]まった。", "sentence_source": "generated"}, {"text": "二本の道が交わる交差点で、事故が起きた。", "target_word": "交わる", "complexity_tier": "T3", "furigana": "二本[にほん]の道[みち]が交[まじ]わる交差点[こうさてん]で、事故[じこ]が起[お]きた。", "sentence_source": "generated"}, {"text": "直線ABと直線CDは、点Pで交わっている。", "target_word": "交わって", "complexity_tier": "T3", "furigana": "直線[ちょくせん]ABと直線[ちょくせん]CDは、点[てん]Pで交[まじ]わっている。", "sentence_source": "generated"}, {"text": "二人の視線が交わった瞬間、彼は思わず目をそらした。", "target_word": "交わった", "complexity_tier": "T3", "furigana": "二人[ふたり]の視線[しせん]が交[まじ]わった瞬間[しゅんかん]、彼[かれ]は思[おも]わず目[め]をそらした。", "sentence_source": "generated"}, {"text": "平行な線は、どこまで延ばしても交わらない。", "target_word": "交わらない", "complexity_tier": "T3", "furigana": "平行[へいこう]な線[せん]は、どこまで延[の]ばしても交[まじ]わらない。", "sentence_source": "generated"}, {"text": "川と線路が交わる場所に、古い橋がある。", "target_word": "交わる", "complexity_tier": "T3", "furigana": "川[かわ]と線路[せんろ]が交[まじ]わる場所[ばしょ]に、古[ふる]い橋[はし]がある。", "sentence_source": "generated"}, {"text": "二つの円が交わると、花びらのような形ができる。", "target_word": "交わる", "complexity_tier": "T3", "furigana": "二[ふた]つの円[えん]が交[まじ]わると、花[はな]びらのような形[かたち]ができる。", "sentence_source": "generated"}, {"text": "光の筋が交わる中心で、舞台の主役が立っている。", "target_word": "交わる", "complexity_tier": "T3", "furigana": "光[ひかり]の筋[すじ]が交[まじ]わる中心[ちゅうしん]で、舞台[ぶたい]の主役[しゅやく]が立[た]っている。", "sentence_source": "generated"}, {"text": "二人の人生が交わったのは、大学の入学式の日だった。", "target_word": "交わった", "complexity_tier": "T3", "furigana": "二人[ふたり]の人生[じんせい]が交[まじ]わったのは、大学[だいがく]の入学式[にゅうがくしき]の日[ひ]だった。", "sentence_source": "generated"}, {"text": "二つの波が交わる所では、水面が高く盛り上がる。", "target_word": "交わる", "complexity_tier": "T3", "furigana": "二[ふた]つの波[なみ]が交[まじ]わる所[ところ]では、水面[すいめん]が高[たか]く盛[も]り上[あ]がる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "交わる", "label": "終止形"}, {"form": "交わり", "label": "連用形"}, {"form": "交わって", "label": "て形"}, {"form": "交わった", "label": "過去形"}, {"form": "交わらない", "label": "否定形"}], "register": "中立", "sense_fingerprint": "道・線・視線などが一点で出会ったり重なったりする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13f97567-fed9-4616-b891-4a3279b2183f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51822, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交わる", "is_correct": true, "explanation": "辞書形（連体形）。直後の「瞬間」を修飾している。"}, {"text": "交わって", "is_correct": false, "explanation": "て形は文を続ける形で、「瞬間」を直接修飾できない。"}, {"text": "交わり", "is_correct": false, "explanation": "名詞形。「の」がないと「瞬間」に続かない。"}, {"text": "交わろう", "is_correct": false, "explanation": "意向形。「瞬間」を修飾する形ではない。"}], "explanations": {"交わる": "辞書形（連体形）。直後の「瞬間」を修飾している。", "交わって": "て形は文を続ける形で、「瞬間」を直接修飾できない。", "交わり": "名詞形。「の」がないと「瞬間」に続かない。", "交わろう": "意向形。「瞬間」を修飾する形ではない。"}, "sentence_index": 0, "correct_answer": "交わる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は事件に交わっていたので、警察に呼ばれた。", "explanation": "ここは〈関わる〉の場面。〈交わる〉は二つ以上のものが一点で出会う・重なる意味なので、人が事件に関係する場面には使わない。"}, {"text": "砂糖と水が交わって、甘いシロップになった。", "explanation": "ここは〈混ざる・溶け合う〉の場面。〈交わる〉は線や道が一点で出会う意味なので、液体を混ぜる場面には使わない。"}, {"text": "二人の言い分が交わり、話がまとまった。", "explanation": "ここは〈合わさって一つになる〉の意味。〈交わる〉は線や道が一点で出会う意味なので、言い分の合流には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51822, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交わる", "is_correct": true, "explanation": "辞書形に「と」をつけて「〜すると」の条件を表し、文が成り立つ。"}, {"text": "交われ", "is_correct": false, "explanation": "命令形で、「と」に続けても条件の文にならず、この位置には入らない。"}, {"text": "交わらず", "is_correct": false, "explanation": "打ち消しの連用形で、「と」に続けると文が成り立たない。"}, {"text": "交わりたく", "is_correct": false, "explanation": "希望の連用形で、「と」に続けると文が成り立たない。"}], "explanations": {"交わる": "辞書形に「と」をつけて「〜すると」の条件を表し、文が成り立つ。", "交われ": "命令形で、「と」に続けても条件の文にならず、この位置には入らない。", "交わらず": "打ち消しの連用形で、「と」に続けると文が成り立たない。", "交わりたく": "希望の連用形で、「と」に続けると文が成り立たない。"}, "sentence_index": 6, "correct_answer": "交わる"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祭りの日、大勢の人が広場で交わった。", "explanation": "ここは〈人が集まる〉の場面。〈交わる〉は線や道などが一点で出会うことなので、人が大勢集まる意味では使わない。"}, {"text": "二台の車が交わって、大きくへこんだ。", "explanation": "ここは〈ぶつかる〉の場面。〈交わる〉は出会う・重なる意味で、激しく衝突して凹む様子は表さない。"}, {"text": "大切な指輪が交わって、どこかへ消えてしまった。", "explanation": "ここは〈なくなる〉の場面。〈交わる〉は一点で出会う・重なる意味なので、物がなくなる様子は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8075277d-6172-4a3a-bc54-41179d414a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
