INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51823, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「愛するとは」で、言葉の意味を取り上げる形になる。"}, {"text": "を", "is_correct": false, "explanation": "「愛するをは」とは言えない。"}, {"text": "が", "is_correct": false, "explanation": "「愛するがは」とは言えない。"}, {"text": "へ", "is_correct": false, "explanation": "「愛するへは」とは言えない。"}], "correct_answer": "と", "explanations": {"と": "「愛するとは」で、言葉の意味を取り上げる形になる。", "を": "「愛するをは」とは言えない。", "が": "「愛するがは」とは言えない。", "へ": "「愛するへは」とは言えない。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "憎む", "is_correct": true, "explanation": "強く嫌って恨むことで、「愛する」の反対の意味。"}, {"text": "敬う", "is_correct": false, "explanation": "尊敬することで、「愛する」の反対ではない。"}, {"text": "守る", "is_correct": false, "explanation": "害から守ることで、「愛する」の反対ではない。"}, {"text": "頼る", "is_correct": false, "explanation": "人を当てにすることで、「愛する」の反対ではない。"}], "correct_answer": "憎む", "explanations": {"憎む": "強く嫌って恨むことで、「愛する」の反対の意味。", "敬う": "尊敬することで、「愛する」の反対ではない。", "守る": "害から守ることで、「愛する」の反対ではない。", "頼る": "人を当てにすることで、「愛する」の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51823, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをとても好きで、大事に思うこと。", "primary_collocate": null, "pronunciation": "あいする", "ipa": "aiɕɯɾɯ", "syllable_count": 4, "sentences": [{"text": "祖母が愛しているのは、庭の白いバラです。", "target_word": "愛している", "complexity_tier": "T3", "furigana": "祖母[そぼ]が愛[あい]しているのは、庭[にわ]の白[しろ]いバラです。", "sentence_source": "generated"}, {"text": "愛する家族のために、毎日働いている。", "target_word": "愛する", "complexity_tier": "T3", "furigana": "愛[あい]する家族[かぞく]のために、毎日[まいにち]働[はたら]いている。", "sentence_source": "generated"}, {"text": "子どもは、親に愛されて育つ。", "target_word": "愛されて", "complexity_tier": "T4", "furigana": "子[こ]どもは、親[おや]に愛[あい]されて育[そだ]つ。", "sentence_source": "generated"}, {"text": "彼は、本を愛した人でした。", "target_word": "愛した", "complexity_tier": "T3", "furigana": "彼[かれ]は、本[ほん]を愛[あい]した人[ひと]でした。", "sentence_source": "generated"}, {"text": "ペットを愛する気持ちは、誰にも負けません。", "target_word": "愛する", "complexity_tier": "T3", "furigana": "ペットを愛[あい]する気持[きも]ちは、誰[だれ]にも負[ま]けません。", "sentence_source": "generated"}, {"text": "愛せるほど好きなものがあるのは、幸せだ。", "target_word": "愛せる", "complexity_tier": "T4", "furigana": "愛[あい]せるほど好[す]きなものがあるのは、幸[しあわ]せだ。", "sentence_source": "generated"}, {"text": "この町の人々は、自分たちの町を愛している。", "target_word": "愛している", "complexity_tier": "T3", "furigana": "この町[まち]の人々[ひとびと]は、自分[じぶん]たちの町[まち]を愛[あい]している。", "sentence_source": "generated"}, {"text": "愛するとは、相手を大切に思うことです。", "target_word": "愛する", "complexity_tier": "T3", "furigana": "愛[あい]するとは、相手[あいて]を大切[たいせつ]に思[おも]うことです。", "sentence_source": "generated"}, {"text": "昔から愛されてきた歌を、みんなで歌った。", "target_word": "愛されて", "complexity_tier": "T4", "furigana": "昔[むかし]から愛[あい]されてきた歌[うた]を、みんなで歌[うた]った。", "sentence_source": "generated"}, {"text": "自分の仕事を愛すれば、毎日が楽しくなる。", "target_word": "愛すれば", "complexity_tier": "T4", "furigana": "自分[じぶん]の仕事[しごと]を愛[あい]すれば、毎日[まいにち]が楽[たの]しくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "愛します", "label": "活用"}, {"form": "愛した", "label": "活用"}, {"form": "愛さない", "label": "活用"}, {"form": "愛される", "label": "活用"}, {"form": "愛し合う", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 何かを大好きで大事に思う", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d94e4e-9169-4547-91bc-074c7abed4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51823, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "愛する", "is_correct": true, "explanation": "聞いた音「あいする」と同じで、正解。"}, {"text": "排する", "is_correct": false, "explanation": "「はいする」で、1拍目の「あ」が「は」に変わっている。"}, {"text": "害する", "is_correct": false, "explanation": "「がいする」で、1拍目の「あ」が「が」に変わっている。"}, {"text": "対する", "is_correct": false, "explanation": "「たいする」で、1拍目の「あ」が「た」に変わっている。"}, {"text": "倍する", "is_correct": false, "explanation": "「ばいする」で、1拍目の「あ」が「ば」に変わっている。"}], "explanations": {"愛する": "聞いた音「あいする」と同じで、正解。", "排する": "「はいする」で、1拍目の「あ」が「は」に変わっている。", "害する": "「がいする」で、1拍目の「あ」が「が」に変わっている。", "対する": "「たいする」で、1拍目の「あ」が「た」に変わっている。", "倍する": "「ばいする」で、1拍目の「あ」が「ば」に変わっている。"}, "sentence_index": null, "correct_answer": "愛する"}, "level_3": {"options": [{"text": "愛している", "is_correct": true, "explanation": "「祖母が愛している」で、大事に思う意味に合う。"}, {"text": "着ている", "is_correct": false, "explanation": "形は合うが意味が合わない。庭のバラは着るものではない。"}, {"text": "飲んでいる", "is_correct": false, "explanation": "形は合うが意味が合わない。庭のバラは飲むものではない。"}, {"text": "読んでいる", "is_correct": false, "explanation": "形は合うが意味が合わない。庭のバラは読むものではない。"}], "explanations": {"愛している": "「祖母が愛している」で、大事に思う意味に合う。", "着ている": "形は合うが意味が合わない。庭のバラは着るものではない。", "飲んでいる": "形は合うが意味が合わない。庭のバラは飲むものではない。", "読んでいる": "形は合うが意味が合わない。庭のバラは読むものではない。"}, "sentence_index": 0, "correct_answer": "愛している"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんに、パンを愛して学校へ行った。", "explanation": "「愛する」は大事に思う意味で、「食べる」の意味では使えない。"}, {"text": "雨が降りそうなので、洗濯物を愛して部屋に入れた。", "explanation": "「愛する」に物を取り込む意味はなく、「取り込む」と混同した誤用。"}, {"text": "彼女に電話を愛したが、だれも出なかった。", "explanation": "「愛する」に電話をかける意味はなく、「かける」と混同した誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51823, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "愛する", "is_correct": true, "explanation": "聞いた音「あいする」と同じで、正解。"}, {"text": "解する", "is_correct": false, "explanation": "「かいする」で、1拍目の「あ」が「か」に変わっている。"}, {"text": "際する", "is_correct": false, "explanation": "「さいする」で、1拍目の「あ」が「さ」に変わっている。"}, {"text": "拝する", "is_correct": false, "explanation": "「はいする」で、1拍目の「あ」が「は」に変わっている。"}], "explanations": {"愛する": "聞いた音「あいする」と同じで、正解。", "解する": "「かいする」で、1拍目の「あ」が「か」に変わっている。", "際する": "「さいする」で、1拍目の「あ」が「さ」に変わっている。", "拝する": "「はいする」で、1拍目の「あ」が「は」に変わっている。"}, "sentence_index": null, "correct_answer": "愛する"}, "level_3": {"options": [{"text": "愛している", "is_correct": true, "explanation": "「自分たちの町を愛している」で、大事に思う意味に合う。"}, {"text": "食べている", "is_correct": false, "explanation": "形は合うが意味が合わない。町は食べるものではない。"}, {"text": "運んでいる", "is_correct": false, "explanation": "形は合うが意味が合わない。町は運ぶものではない。"}, {"text": "洗っている", "is_correct": false, "explanation": "形は合うが意味が合わない。町は洗うものではない。"}], "explanations": {"愛している": "「自分たちの町を愛している」で、大事に思う意味に合う。", "食べている": "形は合うが意味が合わない。町は食べるものではない。", "運んでいる": "形は合うが意味が合わない。町は運ぶものではない。", "洗っている": "形は合うが意味が合わない。町は洗うものではない。"}, "sentence_index": 6, "correct_answer": "愛している"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は、毎朝六時に、顔を愛してから朝ごはんを食べる。", "explanation": "「愛する」に洗う意味はなく、「洗う」と混同した誤用。"}, {"text": "駅で財布を愛したので、交番に届けた。", "explanation": "「愛する」に拾う意味はなく、「拾う」と混同した誤用。"}, {"text": "夏休みに、家族で海を愛しに行った。", "explanation": "「愛する」に見る意味はなく、「見る」と混同した誤用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings 