INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51823, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は、古い時計に愛している。", "corrected_sentence": "祖父は、古い時計を愛している。", "error_description": "「愛する」の対象を表す助詞は「に」ではなく「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "愛する", "is_correct": true, "explanation": "「愛する家族」で、名詞を修飾する形。"}, {"text": "愛して", "is_correct": false, "explanation": "「て形」なので、「家族」を直接修飾できない。"}, {"text": "愛せば", "is_correct": false, "explanation": "仮定の形なので、「家族」を修飾できない。"}, {"text": "愛そう", "is_correct": false, "explanation": "意志の形なので、「家族」を修飾できない。"}], "correct_form": "愛する", "base_form": "愛する", "form_label": "連体形", "sentence_index": 1, "explanations": {"愛する": "「愛する家族」で、名詞を修飾する形。", "愛して": "「て形」なので、「家族」を直接修飾できない。", "愛せば": "仮定の形なので、「家族」を修飾できない。", "愛そう": "意志の形なので、「家族」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51823, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この歌は、世界中の人に愛している。", "corrected_sentence": "この歌は、世界中の人に愛されている。", "error_description": "歌が主語なので、「愛している」ではなく受け身の「愛されている」にする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "愛する", "is_correct": true, "explanation": "「愛するとは」で、辞書形に「とは」がつく。"}, {"text": "愛さず", "is_correct": false, "explanation": "否定の連用形なので、「とは」につかない。"}, {"text": "愛し", "is_correct": false, "explanation": "連用形のままでは、「とは」につかない。"}, {"text": "愛せよ", "is_correct": false, "explanation": "命令の形なので、「とは」につかない。"}], "correct_form": "愛する", "base_form": "愛する", "form_label": "辞書形", "sentence_index": 7, "explanations": {"愛する": "「愛するとは」で、辞書形に「とは」がつく。", "愛さず": "否定の連用形なので、「とは」につかない。", "愛し": "連用形のままでは、「とは」につかない。", "愛せよ": "命令の形なので、「とは」につかない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51824, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「家族を愛する」で、愛する対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「家族に愛しています」とは言えず、対象を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「家族へ愛しています」は文にならない。"}, {"text": "と", "is_correct": false, "explanation": "「家族と愛しています」とは言えず、対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「家族を愛する」で、愛する対象を示す。", "に": "「家族に愛しています」とは言えず、対象を示せない。", "へ": "「へ」は方向を示すので、「家族へ愛しています」は文にならない。", "と": "「家族と愛しています」とは言えず、対象を示せない。"}, "error_tags": {"に": "target_vs_object", "へ": "direction", "と": "accompaniment"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "憎む", "is_correct": true, "explanation": "強く嫌って恨むことで、「愛する」の反対の意味。"}, {"text": "慕う", "is_correct": false, "explanation": "恋しく思って心を寄せることで、「愛する」に近い意味。"}, {"text": "敬う", "is_correct": false, "explanation": "尊敬することで、「愛する」の反対ではない。"}, {"text": "守る", "is_correct": false, "explanation": "害から守ることで、「愛する」の反対ではない。"}], "correct_answer": "憎む", "explanations": {"憎む": "強く嫌って恨むことで、「愛する」の反対の意味。", "慕う": "恋しく思って心を寄せることで、「愛する」に近い意味。", "敬う": "尊敬することで、「愛する」の反対ではない。", "守る": "害から守ることで、「愛する」の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51824, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「愛せるものがある」で、存在するものを示す。"}, {"text": "を", "is_correct": false, "explanation": "「ある」の前に「を」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "「ものにあると」では、存在するものを示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「ものへあると」は文にならない。"}], "correct_answer": "が", "explanations": {"が": "「愛せるものがある」で、存在するものを示す。", "を": "「ある」の前に「を」は使えない。", "に": "「ものにあると」では、存在するものを示せない。", "へ": "「へ」は方向を示すので、「ものへあると」は文にならない。"}, "error_tags": {"を": "object_marker", "に": "location", "へ": "direction"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "嫌う", "is_correct": true, "explanation": "好まず遠ざけることで、「愛する」の反対の意味。"}, {"text": "好む", "is_correct": false, "explanation": "気に入って選ぶことで、「愛する」に近い意味。"}, {"text": "願う", "is_correct": false, "explanation": "そうなってほしいと思うことで、「愛する」の反対ではない。"}, {"text": "信じる", "is_correct": false, "explanation": "本当だと思うことで、「愛する」の反対ではない。"}], "correct_answer": "嫌う", "explanations": {"嫌う": "好まず遠ざけることで、「愛する」の反対の意味。", "好む": "気に入って選ぶことで、「愛する」に近い意味。", "願う": "そうなってほしいと思うことで、「愛する」の反対ではない。", "信じる": "本当だと思うことで、「愛する」の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51824, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある対象に対して深い愛情や強い好意を持ち、大切に思う気持ちを表す動詞。", "primary_collocate": null, "pronunciation": "あいする", "ipa": "aiɕɯɾɯ", "syllable_count": 4, "sentences": [{"text": "地元の風景を愛するロックバンドが、新たなオリジナルTシャツを製作しました。", "target_word": "愛する", "complexity_tier": "T5", "furigana": "地元[じもと]の風景[ふうけい]を愛[あい]するロックバンドが、新[あら]たなオリジナルTシャツを製作[せいさく]しました。", "sentence_source": "mined"}, {"text": "私は家族を愛しています。", "target_word": "愛しています", "complexity_tier": "T3", "furigana": "私[わたし]は家族[かぞく]を愛[あい]しています。", "sentence_source": "generated"}, {"text": "彼の愛するふるさとは、海の近くにある。", "target_word": "愛する", "complexity_tier": "T3", "furigana": "彼[かれ]の愛[あい]するふるさとは、海[うみ]の近[ちか]くにある。", "sentence_source": "generated"}, {"text": "愛する人と、いっしょに暮らしたい。", "target_word": "愛する", "complexity_tier": "T3", "furigana": "愛[あい]する人[ひと]と、いっしょに暮[く]らしたい。", "sentence_source": "generated"}, {"text": "母は、子どもたちを深く愛している。", "target_word": "愛している", "complexity_tier": "T3", "furigana": "母[はは]は、子[こ]どもたちを深[ふか]く愛[あい]している。", "sentence_source": "generated"}, {"text": "誰からも愛される先生になりたい。", "target_word": "愛される", "complexity_tier": "T4", "furigana": "誰[だれ]からも愛[あい]される先生[せんせい]になりたい。", "sentence_source": "generated"}, {"text": "この犬は、みんなに愛されて育った。", "target_word": "愛されて", "complexity_tier": "T4", "furigana": "この犬[いぬ]は、みんなに愛[あい]されて育[そだ]った。", "sentence_source": "generated"}, {"text": "愛せるものがあると、人は強くなれる。", "target_word": "愛せる", "complexity_tier": "T4", "furigana": "愛[あい]せるものがあると、人[ひと]は強[つよ]くなれる。", "sentence_source": "generated"}, {"text": "彼は音楽を愛するあまり、仕事をやめてしまった。", "target_word": "愛する", "complexity_tier": "T4", "furigana": "彼[かれ]は音楽[おんがく]を愛[あい]するあまり、仕事[しごと]をやめてしまった。", "sentence_source": "generated"}, {"text": "愛することは、愛されることより難しいかもしれない。", "target_word": "愛する", "complexity_tier": "T4", "furigana": "愛[あい]することは、愛[あい]されることより難[むずか]しいかもしれない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "愛します", "label": "活用"}, {"form": "愛した", "label": "活用"}, {"form": "愛さない", "label": "活用"}, {"form": "愛される", "label": "活用"}, {"form": "愛し合う", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 深い愛情や強い好意を持つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d94e4e-9169-4547-91bc-074c7abed4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
