rompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51824, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "愛する", "is_correct": true, "explanation": "聞いた音「あいする」と同じで、正解。"}, {"text": "解する", "is_correct": false, "explanation": "「かいする」で、1拍目の「あ」が「か」に変わっている。"}, {"text": "倍する", "is_correct": false, "explanation": "「ばいする」で、1拍目の「あ」が「ば」に変わっている。"}, {"text": "排する", "is_correct": false, "explanation": "「はいする」で、1拍目の「あ」が「は」に変わっている。"}], "explanations": {"愛する": "聞いた音「あいする」と同じで、正解。", "解する": "「かいする」で、1拍目の「あ」が「か」に変わっている。", "倍する": "「ばいする」で、1拍目の「あ」が「ば」に変わっている。", "排する": "「はいする」で、1拍目の「あ」が「は」に変わっている。"}, "sentence_index": null, "correct_answer": "愛する"}, "level_3": {"options": [{"text": "愛されて", "is_correct": true, "explanation": "「みんなに愛されて育った」で、かわいがられた意味に合う。"}, {"text": "食べられて", "is_correct": false, "explanation": "形は合うが意味が合わない。犬が食べられて育つことにはならない。"}, {"text": "運ばれて", "is_correct": false, "explanation": "形は合うが意味が合わない。運ばれることは、育った様子に合わない。"}, {"text": "数えられて", "is_correct": false, "explanation": "形は合うが意味が合わない。数えられることは、育った様子に合わない。"}], "explanations": {"愛されて": "「みんなに愛されて育った」で、かわいがられた意味に合う。", "食べられて": "形は合うが意味が合わない。犬が食べられて育つことにはならない。", "運ばれて": "形は合うが意味が合わない。運ばれることは、育った様子に合わない。", "数えられて": "形は合うが意味が合わない。数えられることは、育った様子に合わない。"}, "sentence_index": 6, "correct_answer": "愛されて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友だちに借りた傘を、電車の中で愛してしまった。", "explanation": "「愛する」に物をなくす意味はなく、「忘れる」や「なくす」と混同した誤用。"}, {"text": "この部屋はせまいので、荷物を愛する場所がない。", "explanation": "「愛する」に物を置く意味はなく、「置く」と混同した誤用。"}, {"text": "兄は犬が苦手で、いつも犬を愛して道を変える。", "explanation": "「愛する」は避ける意味では使えず、苦手な犬への態度と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51824, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は、ふるさとに深く愛している。", "corrected_sentence": "彼は、ふるさとを深く愛している。", "error_description": "「愛する」の対象を表す助詞は「に」ではなく「を」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "愛しています", "is_correct": true, "explanation": "「家族を愛しています」で、今の気持ちを丁寧に言う形。"}, {"text": "愛すれば", "is_correct": false, "explanation": "仮定の形なので、文を言い切る位置には合わない。"}, {"text": "愛されて", "is_correct": false, "explanation": "受け身の「て形」なので、文の終わりには置けない。"}, {"text": "愛し", "is_correct": false, "explanation": "連用形のままでは、文を言い切れない。"}], "correct_form": "愛しています", "base_form": "愛する", "form_label": "ている形(丁寧)", "sentence_index": 1, "explanations": {"愛しています": "「家族を愛しています」で、今の気持ちを丁寧に言う形。", "愛すれば": "仮定の形なので、文を言い切る位置には合わない。", "愛されて": "受け身の「て形」なので、文の終わりには置けない。", "愛し": "連用形のままでは、文を言い切れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51824, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この先生は生徒たちを愛されている。", "corrected_sentence": "この先生は生徒たちに愛されている。", "error_description": "受け身の「愛されている」では、愛する側を「に」で示す。「を」は使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "愛せる", "is_correct": true, "explanation": "「愛せるもの」で、愛することができるという可能の形。"}, {"text": "愛せば", "is_correct": false, "explanation": "仮定の形なので、「もの」を修飾できない。"}, {"text": "愛して", "is_correct": false, "explanation": "「て形」なので、「もの」を直接修飾できない。"}, {"text": "愛そう", "is_correct": false, "explanation": "意志の形なので、「もの」を修飾できない。"}], "correct_form": "愛せる", "base_form": "愛する", "form_label": "可能形", "sentence_index": 7, "explanations": {"愛せる": "「愛せるもの」で、愛することができるという可能の形。", "愛せば": "仮定の形なので、「もの」を修飾できない。", "愛して": "「て形」なので、「もの」を直接修飾できない。", "愛そう": "意志の形なので、「もの」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51825, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「オリジナルを見る」で、見る対象を表す。"}, {"text": "の", "is_correct": false, "explanation": "「オリジナルの見て」は文法的に成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「見てください」の対象を「が」で表すことはできず、「オリジナルが見てください」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「オリジナルへ見て」は文法的に合わない。"}], "correct_answer": "を", "explanations": {"を": "「オリジナルを見る」で、見る対象を表す。", "の": "「オリジナルの見て」は文法的に成り立たない。", "が": "「見てください」の対象を「が」で表すことはできず、「オリジナルが見てください」は文法的に成り立たない。", "へ": "「オリジナルへ見て」は文法的に合わない。"}, "error_tags": {"の": "possessive", "が": "subject_marker", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51825, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「これは〜です」で主題を表す。"}, {"text": "を", "is_correct": false, "explanation": "「これをコピーではなく、オリジナルです」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「これへ」は方向の用法で、文法的に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「これとコピーではなく」は文として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「これは〜です」で主題を表す。", "を": "「これをコピーではなく、オリジナルです」は文として成り立たない。", "へ": "「これへ」は方向の用法で、文法的に合わない。", "と": "「これとコピーではなく」は文として成り立たない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "と": "quotation_or_with"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
