{"form": "オリジナルグッズ", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 自分で作ったまねでないもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c392ff-c6f7-45b1-9aa3-80ca467ce7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51825, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "オリジナル", "is_correct": true, "explanation": "自分で作った絵という意味が合う。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが意味が合わない。「値段の絵」は意味が通らない。"}, {"text": "時間", "is_correct": false, "explanation": "形は合うが意味が合わない。「時間の絵」は文脈に合わない。"}, {"text": "理由", "is_correct": false, "explanation": "形は合うが意味が合わない。「理由の絵」では意味が通らない。"}], "explanations": {"オリジナル": "自分で作った絵という意味が合う。", "値段": "形は合うが意味が合わない。「値段の絵」は意味が通らない。", "時間": "形は合うが意味が合わない。「時間の絵」は文脈に合わない。", "理由": "形は合うが意味が合わない。「理由の絵」では意味が通らない。"}, "sentence_index": 0, "correct_answer": "オリジナル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "これは本物そっくりにまねして作ったオリジナルの時計です。", "explanation": "まねして作ったものはオリジナルではなく、意味が矛盾する。"}, {"text": "私のオリジナルは三時に駅に着きました。", "explanation": "オリジナルは人を指す語ではないので、主語として誤り。"}, {"text": "オリジナルが痛くて、病院に行った。", "explanation": "オリジナルは体の部位ではなく、使い方が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51825, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "オリジナル", "is_correct": true, "explanation": "独自のデザインのカバンという意味が合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。「天気のカバン」は意味が通らない。"}, {"text": "時間", "is_correct": false, "explanation": "形は合うが意味が合わない。「時間のカバン」は文脈に合わない。"}, {"text": "病気", "is_correct": false, "explanation": "形は合うが意味が合わない。「病気のカバン」では意味が通らない。"}], "explanations": {"オリジナル": "独自のデザインのカバンという意味が合う。", "天気": "形は合うが意味が合わない。「天気のカバン」は意味が通らない。", "時間": "形は合うが意味が合わない。「時間のカバン」は文脈に合わない。", "病気": "形は合うが意味が合わない。「病気のカバン」では意味が通らない。"}, "sentence_index": 6, "correct_answer": "オリジナル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この絵は、有名な絵をそのまま写して作ったオリジナルだ。", "explanation": "そのまま写して作ったものはオリジナルではなく、意味が矛盾する。"}, {"text": "この水はオリジナルだから、とても冷たい。", "explanation": "オリジナルは温度を表さず、因果関係が成り立たない。"}, {"text": "オリジナルを走って学校に行った。", "explanation": "オリジナルは走る対象や手段にならず、使い方が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51825, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "これはオリジナルをケーキです。", "corrected_sentence": "これはオリジナルのケーキです。", "error_description": "名詞「ケーキ」を修飾するには「を」ではなく「の」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51825, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼のオリジナルに靴はとても丈夫だ。", "corrected_sentence": "彼のオリジナルの靴はとても丈夫だ。", "error_description": "「靴」を修飾するには「オリジナルに」ではなく「オリジナルの」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51826, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「彼のオリジナル」で所有・作者を表す。"}, {"text": "を", "is_correct": false, "explanation": "「彼をオリジナルです」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「彼へオリジナル」は方向の用法で、ここでは文法的に合わない。"}, {"text": "まで", "is_correct": false, "explanation": "「彼までオリジナルです」は意味も文法も合わない。"}], "correct_answer": "の", "explanations": {"の": "「彼のオリジナル」で所有・作者を表す。", "を": "「彼をオリジナルです」は文として成り立たない。", "へ": "「彼へオリジナル」は方向の用法で、ここでは文法的に合わない。", "まで": "「彼までオリジナルです」は意味も文法も合わない。"}, "error_tags": {"を": "object_marker", "へ": "direction", "まで": "limit"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "コピー", "is_correct": true, "explanation": "他をまねて作ったものを指し、オリジナルの反対。"}, {"text": "独創", "is_correct": false, "explanation": "独自に考え出すことで、オリジナルに近い意味。"}, {"text": "創作", "is_correct": false, "explanation": "新しく作ることで、反対ではなく近い意味。"}, {"text": "新品", "is_correct": false, "explanation": "使われていない品物のことで、反意関係にはない。"}], "correct_answer": "コピー", "explanations": {"コピー": "他をまねて作ったものを指し、オリジナルの反対。", "独創": "独自に考え出すことで、オリジナルに近い意味。", "創作": "新しく作ることで、反対ではなく近い意味。", "新品": "使われていない品物のことで、反意関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51826, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「〜にこだわる」の形で、こだわる対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「こだわる」の対象は「が」で表せず、「オリジナルがこだわる」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「オリジナルへこだわる」は文法的に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「オリジナルとこだわる」は文法的に成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「〜にこだわる」の形で、こだわる対象を表す。", "が": "「こだわる」の対象は「が」で表せず、「オリジナルがこだわる」は意味が通らない。", "へ": "「へ」は方向を表し、「オリジナルへこだわる」は文法的に合わない。", "と": "「オリジナルとこだわる」は文法的に成り立たない。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "と": "quotation_or_with"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "模倣", "is_correct": true, "explanation": "他をまねることで、オリジナルの反対。"}, {"text": "独自", "is_correct": false, "explanation": "その人だけのという意味で、オリジナルに近い。"}, {"text": "発明", "is_correct": false, "explanation": "新しく作り出すことで、反対ではない。"}, {"text": "個性", "is_correct": false, "explanation": "その人らしさのことで、反意語ではない。"}], "correct_answer": "模倣", "explanations": {"模倣": "他をまねることで、オリジナルの反対。", "独自": "その人だけのという意味で、オリジナルに近い。", "発明": "新しく作り出すことで、反対ではない。", "個性": "その人らしさのことで、反意語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51826, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "他を模倣せず、自分だけの新しい考えや作品であること。また、そのようなもの。", "primary_collocate": null, "pronunciation": "おりじなる", "ipa": "oɾiʑinaɾɯ", "syllable_count": 5, "sentences": [{"text": "地元の風景を愛するロックバンドが、新たなオリジナルTシャツを製作しました。", "target_word": "オリジナル", "complexity_tier": "T5", "furigana": "地元[じもと]の風景[ふうけい]を愛[あい]するロックバンドが、新[あら]たなオリジナルTシャツを製作[せいさく]しました。", "sentence_source": "mined"}, {"text": "この曲は彼のオリジナルです。", "target_word": "オリジナル", "complexity_tier": "T2", "furigana": "この曲[きょく]は彼[かれ]のオリジナルです。", "sentence_source": "generated"}, {"text": "オリジナルの作品を作りたいです。", "target_word": "オリジナル", "complexity_tier": "T2", "furigana": "オリジナルの作品[さくひん]を作[つく]りたいです。", "sentence_source": "generated"}, {"text": "この店はオリジナルのカレーが人気だ。", "target_word": "オリジナル", "complexity_tier": "T3", "furigana": "この店[みせ]はオリジナルのカレーが人気[にんき]だ。", "sentence_source": "generated"}, {"text": "彼の絵はとてもオリジナルな考えから生まれた。", "target_word": "オリジナル", "complexity_tier": "T3", "furigana": "彼[かれ]の絵[え]はとてもオリジナルな考[かんが]えから生[う]まれた。", "sentence_source": "generated"}, {"text": "オリジナルを超えるのは簡単ではない。", "target_word": "オリジナル", "complexity_tier": "T3", "furigana": "オリジナルを超[こ]えるのは簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "学生たちが自分でオリジナルのゲームを作って、友達に見せた。", "target_word": "オリジナル", "complexity_tier": "T4", "furigana": "学生[がくせい]たちが自分[じぶん]でオリジナルのゲームを作[つく]って、友達[ともだち]に見[み]せた。", "sentence_source": "generated"}, {"text": "オリジナルにこだわるデザイナーが多い。", "target_word": "オリジナル", "complexity_tier": "T3", "furigana": "オリジナルにこだわるデザイナーが多[おお]い。", "sentence_source": "generated"}, {"text": "この本は著者のオリジナルな研究をまとめたものだ。", "target_word": "オリジナル", "complexity_tier": "T4", "furigana": "この本[ほん]は著者[ちょしゃ]のオリジナルな研究[けんきゅう]をまとめたものだ。", "sentence_source": "generated"}, {"text": "まねではなく、オリジナルで勝負したい。", "target_word": "オリジナル", "complexity_tier": "T3", "furigana": "まねではなく、オリジナルで勝負[しょうぶ]したい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "オリジナリティ", "label": "派生"}, {"form": "オリジナル曲", "label": "派生"}, {"form": "オリジナルグッズ", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 模倣でない独自の作品や考え", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c392ff-c6f7-45b1-9aa3-80ca467ce7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51826, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "オリジナル", "is_correct": true, "explanation": "「新たなオリジナルTシャツ」で、独自のデザインのTシャツという意味が合う。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。「天気Tシャツ」は意味をなさない。"}, {"text": "宿題", "is_correct": false, "explanation": "形は合うが意味が合わない。「宿題Tシャツ」では意味が通らない。"}, {"text": "交通", "is_correct": false, "explanation": "形は合うが意味が合わない。「交通Tシャツ」では意味が通らない。"}], "explanations": {"オリジナル": "「新たなオリジナルTシャツ」で、独自のデザインのTシャツという意味が合う。", "天気": "形は合うが意味が合わない。「天気Tシャツ」は意味をなさない。", "宿題": "形は合うが意味が合わない。「宿題Tシャツ」では意味が通らない。", "交通": "形は合うが意味が合わない。「交通Tシャツ」では意味が通らない。"}, "sentence_index": 0, "correct_answer": "オリジナル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅からこの店までオリジナルで十分かかる。", "explanation": "オリジナルは距離や所要時間を表す語ではないので、使い方が誤り。"}, {"text": "他の店のカレーをそっくりまねして作ったから、オリジナルだと言える。", "explanation": "まねして作ったものは独自ではないので、オリジナルの意味と矛盾する。"}, {"text": "明日の天気はオリジナルなので、傘を持っていこう。", "explanation": "オリジナルは天気の状態を表す語ではなく、意味が通らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51826, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "オリジナル", "is_correct": true, "explanation": "自分で作った独自のゲームという意味が合う。"}, {"text": "中古", "is_correct": false, "explanation": "形は合うが意味が合わない。自分で作ったばかりのゲームは中古にならない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。自分で作るゲームの修飾として不自然。"}, {"text": "病気", "is_correct": false, "explanation": "形は合うが意味が合わない。「病気のゲーム」では意味が通らない。"}], "explanations": {"オリジナル": "自分で作った独自のゲームという意味が合う。", "中古": "形は合うが意味が合わない。自分で作ったばかりのゲームは中古にならない。", "天気": "形は合うが意味が合わない。自分で作るゲームの修飾として不自然。", "病気": "形は合うが意味が合わない。「病気のゲーム」では意味が通らない。"}, "sentence_index": 6, "correct_answer": "オリジナル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "有名な曲をそのまま写した曲なので、彼のオリジナルと言える。", "explanation": "そのまま写したものは独自の作品ではなく、オリジナルの意味と矛盾する。"}, {"text": "この水はオリジナルだから、とても冷たい。", "explanation": "オリジナルは温度の性質を表さず、因果関係が成り立たない。"}, {"text": "オリジナルを走って学校に行った。", "explanation": "オリジナルは走る対象や手段にならず、使い方が誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51826, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このカフェはオリジナルにコーヒーが有名だ。", "corrected_sentence": "このカフェはオリジナルのコーヒーが有名だ。", "error_description": "名詞「コーヒー」を修飾するには「オリジナルに」ではなく「オリジナルの」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51826, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女のオリジナルに服はとてもかわいい。", "corrected_sentence": "彼女のオリジナルの服はとてもかわいい。", "error_description": "「服」を修飾するには「オリジナルに」ではなく「オリジナルの」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51827, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「大学の図書館」の「の」。大学と図書館を修飾関係で結ぶ。"}, {"text": "から", "is_correct": false, "explanation": "「大学から図書館は」と起点の関係になり、場所を表せず文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「大学を図書館は」は目的語の関係が成り立たず、文が壊れる。"}, {"text": "へ", "is_correct": false, "explanation": "「大学へ図書館は夜十時まで開いている」は方向の意味になり、場所の関係として不自然。"}], "correct_answer": "の", "explanations": {"の": "「大学の図書館」の「の」。大学と図書館を修飾関係で結ぶ。", "から": "「大学から図書館は」と起点の関係になり、場所を表せず文が成り立たない。", "を": "「大学を図書館は」は目的語の関係が成り立たず、文が壊れる。", "へ": "「大学へ図書館は夜十時まで開いている」は方向の意味になり、場所の関係として不自然。"}, "error_tags": {"が": "主格（主語の重複）", "を": "目的語（格の誤用）", "へ": "方向（行き先）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51827, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「大学で心理学を学んだ」の「で」。学んだ場所を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は到達点や相手を示すため、「大学に心理学を学んだ」は学ぶ場所として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同や並列を示すため、「大学と心理学を学んだ」は場所の意味にならない。"}, {"text": "を", "is_correct": false, "explanation": "「大学を心理学を」と目的語が二つ重なり、場所を表せないので文が崩れる。"}], "correct_answer": "で", "explanations": {"で": "「大学で心理学を学んだ」の「で」。学んだ場所を示す。", "に": "「に」は到達点や相手を示すため、「大学に心理学を学んだ」は学ぶ場所として不自然。", "と": "「と」は共同や並列を示すため、「大学と心理学を学んだ」は場所の意味にならない。", "を": "「大学を心理学を」と目的語が二つ重なり、場所を表せないので文が崩れる。"}, "error_tags": {"に": "到達点・相手", "と": "共同・並列", "を": "目的語の重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51827, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "高校のあとで、専門的に学ぶ学校。", "primary_collocate": null, "pronunciation": "だいがく", "ipa": "daigakɯ", "syllable_count": 4, "sentences": [{"text": "兄は東京の大学で経済を勉強しています。", "target_word": "大学", "complexity_tier": "T3", "furigana": "兄[あに]は東京[とうきょう]の大学[だいがく]で経済[けいざい]を勉強[べんきょう]しています。", "sentence_source": "generated"}, {"text": "大学の図書館は夜十時まで開いている。", "target_word": "大学", "complexity_tier": "T3", "furigana": "大学[だいがく]の図書館[としょかん]は夜[よる]十時[じゅうじ]まで開[あ]いている。", "sentence_source": "generated"}, {"text": "高校を卒業したら、大学に行くつもりです。", "target_word": "大学", "complexity_tier": "T3", "furigana": "高校[こうこう]を卒業[そつぎょう]したら、大学[だいがく]に行[い]くつもりです。", "sentence_source": "generated"}, {"text": "私の大学は駅から歩いて五分の所にある。", "target_word": "大学", "complexity_tier": "T3", "furigana": "私[わたし]の大学[だいがく]は駅[えき]から歩[ある]いて五分[ごふん]の所[ところ]にある。", "sentence_source": "generated"}, {"text": "大学の授業は、自分で時間割を決められる。", "target_word": "大学", "complexity_tier": "T3", "furigana": "大学[だいがく]の授業[じゅぎょう]は、自分[じぶん]で時間割[じかんわり]を決[き]められる。", "sentence_source": "generated"}, {"text": "姉は大学を出て、小さな会社で働いている。", "target_word": "大学", "complexity_tier": "T3", "furigana": "姉[あね]は大学[だいがく]を出[で]て、小[ちい]さな会社[かいしゃ]で働[はたら]いている。", "sentence_source": "generated"}, {"text": "大学には世界中から留学生が来ています。", "target_word": "大学", "complexity_tier": "T3", "furigana": "大学[だいがく]には世界中[せかいじゅう]から留学生[りゅうがくせい]が来[き]ています。", "sentence_source": "generated"}, {"text": "大学で心理学を学んだので、人の気持ちに興味がある。", "target_word": "大学", "complexity_tier": "T3", "furigana": "大学[だいがく]で心理学[しんりがく]を学[まな]んだので、人[ひと]の気持[きも]ちに興味[きょうみ]がある。", "sentence_source": "generated"}, {"text": "この大学は研究が有名で、入るのがむずかしい。", "target_word": "大学", "complexity_tier": "T3", "furigana": "この大学[だいがく]は研究[けんきゅう]が有名[ゆうめい]で、入[はい]るのがむずかしい。", "sentence_source": "generated"}, {"text": "大学のサークルで、新しい友だちができた。", "target_word": "大学", "complexity_tier": "T3", "furigana": "大学[だいがく]のサークルで、新[あたら]しい友[とも]だちができた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大学", "label": "基本形"}, {"form": "大学の", "label": "連体修飾（の）"}, {"form": "大学で", "label": "場所格"}, {"form": "大学に", "label": "与格"}], "register": "neutral", "sense_fingerprint": "高校のあとで専門的に学ぶ学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb6837b5-37ea-42d1-91e7-d13681740b4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51827, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大学", "is_correct": true, "explanation": "「東京の大学で経済を勉強」に合う、専門的に学ぶ教育機関。"}, {"text": "病院", "is_correct": false, "explanation": "病院で経済を勉強する文脈は成立せず、文が不自然になる。"}, {"text": "工場", "is_correct": false, "explanation": "工場で経済を学ぶという文脈は成立せず、勉強の場所に合わない。"}, {"text": "薬局", "is_correct": false, "explanation": "薬局で経済を勉強する文脈は成立せず、勉強の場所に合わない。"}], "explanations": {"大学": "「東京の大学で経済を勉強」に合う、専門的に学ぶ教育機関。", "病院": "病院で経済を勉強する文脈は成立せず、文が不自然になる。", "工場": "工場で経済を学ぶという文脈は成立せず、勉強の場所に合わない。", "薬局": "薬局で経済を勉強する文脈は成立せず、勉強の場所に合わない。"}, "sentence_index": 0, "correct_answer": "大学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "授業の前に、大学が教室に集まった。", "explanation": "〈学生〉の意味。大学は学びの場所を指すので、人が集まるとは言えない。"}, {"text": "おやつに大学を一皿食べた。", "explanation": "〈大学芋〉（さつまいもの菓子）の意味。大学だけでは食べ物の名前にならない。"}, {"text": "祖父は毎朝、大学に乗って駅へ行った。", "explanation": "〈バス〉（乗り物）の意味。大学は場所なので、乗って移動する対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51827, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大学", "is_correct": true, "explanation": "留学生が来る教育機関を指し、「大学には」に自然に入る。"}, {"text": "動物園", "is_correct": false, "explanation": "動物園に留学生が来る文脈は不自然で、文の意味が通らない。"}, {"text": "温泉", "is_correct": false, "explanation": "温泉に留学生が来るという文脈は成立せず、意味が通らない。"}, {"text": "漁港", "is_correct": false, "explanation": "漁港に留学生が来るという文脈は不自然で、文として成り立たない。"}], "explanations": {"大学": "留学生が来る教育機関を指し、「大学には」に自然に入る。", "動物園": "動物園に留学生が来る文脈は不自然で、文の意味が通らない。", "温泉": "温泉に留学生が来るという文脈は成立せず、意味が通らない。", "漁港": "漁港に留学生が来るという文脈は不自然で、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "大学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末、大学に登って景色を見た。", "explanation": "〈山〉の意味。大学は山ではないので、登る対象にはならない。"}, {"text": "手術のため、大学に入院した。", "explanation": "〈病院〉の意味。大学は治療を受ける施設ではないので、入院先には使えない。"}, {"text": "大学を肩にかけて家を出た。", "explanation": "〈かばん〉の意味。大学は学ぶ場所なので、肩にかけて運ぶ物にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51827, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉は東京の大学を化学を勉強しています。", "corrected_sentence": "姉は東京の大学で化学を勉強しています。", "error_description": "勉強する場所を示すには「で」が必要。「大学を」は目的語を示すため、場所の意味にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51827, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は大学を入学して、就職した。", "corrected_sentence": "姉は大学を卒業して、就職した。", "error_description": "「大学を」と組めるのは卒業する方。「入学する」は「大学に入学する」の形で使い、「大学を」とは組まない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
