INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51829, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ロックは、ギターやドラムで演奏する、元気な音楽です。", "primary_collocate": null, "pronunciation": "ろっく", "ipa": "ɾokkɯ", "syllable_count": 3, "sentences": [{"text": "ロックは元気な音楽です。", "target_word": "ロック", "complexity_tier": "T2", "furigana": "ロックは元気[げんき]な音楽[おんがく]です。", "sentence_source": "generated"}, {"text": "私はロックが好きです。", "target_word": "ロック", "complexity_tier": "T2", "furigana": "私[わたし]はロックが好[す]きです。", "sentence_source": "generated"}, {"text": "ロックを聞きながら走ります。", "target_word": "ロック", "complexity_tier": "T2", "furigana": "ロックを聞[き]きながら走[はし]ります。", "sentence_source": "generated"}, {"text": "姉はギターでロックを弾く。", "target_word": "ロック", "complexity_tier": "T3", "furigana": "姉[あね]はギターでロックを弾[ひ]く。", "sentence_source": "generated"}, {"text": "このロックはとても速いです。", "target_word": "ロック", "complexity_tier": "T2", "furigana": "このロックはとても速[はや]いです。", "sentence_source": "generated"}, {"text": "ロックのコンサートに行きました。", "target_word": "ロック", "complexity_tier": "T2", "furigana": "ロックのコンサートに行[い]きました。", "sentence_source": "generated"}, {"text": "友達と、ギターがかっこいいロックについて話した。", "target_word": "ロック", "complexity_tier": "T3", "furigana": "友達[ともだち]と、ギターがかっこいいロックについて話[はな]した。", "sentence_source": "generated"}, {"text": "ロックのCDを買って、家で聞いた。", "target_word": "ロック", "complexity_tier": "T3", "furigana": "ロックのCDを買[か]って、家[いえ]で聞[き]いた。", "sentence_source": "generated"}, {"text": "学校でロックをやりたいと思っている。", "target_word": "ロック", "complexity_tier": "T3", "furigana": "学校[がっこう]でロックをやりたいと思[おも]っている。", "sentence_source": "generated"}, {"text": "ロックを知らない人は少ないだろう。", "target_word": "ロック", "complexity_tier": "T3", "furigana": "ロックを知[し]らない人[ひと]は少[すく]ないだろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ロックバンド", "label": "派生"}, {"form": "ロック音楽", "label": "派生"}, {"form": "ロックンロール", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ギターやドラムで奏でる元気な音楽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c392ff-c6f7-45b1-9aa3-80ca467ce7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
