INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51830, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ロックは、1950年代にアメリカで生まれたポピュラー音楽の一種で、強いリズムとエレキギターのサウンドが特徴です。", "primary_collocate": null, "pronunciation": "ろっく", "ipa": "ɾokkɯ", "syllable_count": 3, "sentences": [{"text": "地元の風景を愛するロックバンドが、新たなオリジナルTシャツを製作しました。", "target_word": "ロック", "complexity_tier": "T5", "furigana": "地元[じもと]の風景[ふうけい]を愛[あい]するロックバンドが、新[あら]たなオリジナルTシャツを製作[せいさく]しました。", "sentence_source": "mined"}, {"text": "私はロックを聞くのが好きです。", "target_word": "ロック", "complexity_tier": "T2", "furigana": "私[わたし]はロックを聞[き]くのが好[す]きです。", "sentence_source": "generated"}, {"text": "兄はロックが大好きで、毎日聞いている。", "target_word": "ロック", "complexity_tier": "T3", "furigana": "兄[あに]はロックが大好[だいす]きで、毎日[まいにち]聞[き]いている。", "sentence_source": "generated"}, {"text": "このバンドはロックを演奏します。", "target_word": "ロック", "complexity_tier": "T2", "furigana": "このバンドはロックを演奏[えんそう]します。", "sentence_source": "generated"}, {"text": "ロックの歴史について調べた。", "target_word": "ロック", "complexity_tier": "T3", "furigana": "ロックの歴史[れきし]について調[しら]べた。", "sentence_source": "generated"}, {"text": "彼の声はロックに合っている。", "target_word": "ロック", "complexity_tier": "T3", "furigana": "彼[かれ]の声[こえ]はロックに合[あ]っている。", "sentence_source": "generated"}, {"text": "昔のロックは今でも人気がある。", "target_word": "ロック", "complexity_tier": "T3", "furigana": "昔[むかし]のロックは今[いま]でも人気[にんき]がある。", "sentence_source": "generated"}, {"text": "ロックとジャズでは、リズムが違う。", "target_word": "ロック", "complexity_tier": "T3", "furigana": "ロックとジャズでは、リズムが違[ちが]う。", "sentence_source": "generated"}, {"text": "ギターを習って、ロックの曲を弾けるようになった。", "target_word": "ロック", "complexity_tier": "T4", "furigana": "ギターを習[なら]って、ロックの曲[きょく]を弾[ひ]けるようになった。", "sentence_source": "generated"}, {"text": "父が若いころ好きだったロックを、一緒に聞いた。", "target_word": "ロック", "complexity_tier": "T4", "furigana": "父[ちち]が若[わか]いころ好[す]きだったロックを、一緒[いっしょ]に聞[き]いた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ロックバンド", "label": "派生"}, {"form": "ロック音楽", "label": "派生"}, {"form": "ロックンロール", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 強いリズムのポピュラー音楽の一種", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c392ff-c6f7-45b1-9aa3-80ca467ce7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
