INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51830, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "ロック", "is_correct": true, "explanation": "見出し語。"}, {"text": "ノック", "is_correct": false, "explanation": "ロ→ノの一音違い。"}, {"text": "ロッジ", "is_correct": false, "explanation": "ク→ジの一音違い。"}, {"text": "ロット", "is_correct": false, "explanation": "ク→トの一音違い。"}, {"text": "ホック", "is_correct": false, "explanation": "ロ→ホの一音違い。"}], "explanations": {"ロック": "見出し語。", "ノック": "ロ→ノの一音違い。", "ロッジ": "ク→ジの一音違い。", "ロット": "ク→トの一音違い。", "ホック": "ロ→ホの一音違い。"}, "sentence_index": null, "correct_answer": "ロック"}, "level_3": {"options": [{"text": "ロック", "is_correct": true, "explanation": "昔の音楽が今も人気という意味が合う。"}, {"text": "宿題", "is_correct": false, "explanation": "形は合うが意味が合わない。「昔の宿題が人気」は不自然。"}, {"text": "病気", "is_correct": false, "explanation": "形は合うが意味が合わない。「病気が人気がある」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。「昔の天気が人気」は不自然。"}], "explanations": {"ロック": "昔の音楽が今も人気という意味が合う。", "宿題": "形は合うが意味が合わない。「昔の宿題が人気」は不自然。", "病気": "形は合うが意味が合わない。「病気が人気がある」は意味が通らない。", "天気": "形は合うが意味が合わない。「昔の天気が人気」は不自然。"}, "sentence_index": 6, "correct_answer": "ロック"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ロックが咲いたので、公園に見に行った。", "explanation": "ロックは音楽で、花のように咲くものではないので意味が合わない。"}, {"text": "昨日の夕食はロックで、とてもおいしかった。", "explanation": "ロックは料理ではなく音楽なので、意味が合わない。"}, {"text": "彼はロックを三匹飼っている。", "explanation": "ロックは動物ではなく、「匹」で数えられない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51830, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟はロックに大好きで、毎日歌っている。", "corrected_sentence": "弟はロックが大好きで、毎日歌っている。", "error_description": "「大好きだ」の対象は「に」ではなく「が」で表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
