INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51831, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "グループの一員のことです。", "primary_collocate": null, "pronunciation": "めんばー", "ipa": "meɴbaː", "syllable_count": 4, "sentences": [{"text": "私はこのクラブのメンバーです。", "target_word": "メンバー", "complexity_tier": "T2", "furigana": "私[わたし]はこのクラブのメンバーです。", "sentence_source": "generated"}, {"text": "メンバーは五人います。", "target_word": "メンバー", "complexity_tier": "T2", "furigana": "メンバーは五人[ごにん]います。", "sentence_source": "generated"}, {"text": "彼は新しいメンバーです。", "target_word": "メンバー", "complexity_tier": "T2", "furigana": "彼[かれ]は新[あたら]しいメンバーです。", "sentence_source": "generated"}, {"text": "メンバーみんなで写真を撮った。", "target_word": "メンバー", "complexity_tier": "T3", "furigana": "メンバーみんなで写真[しゃしん]を撮[と]った。", "sentence_source": "generated"}, {"text": "サッカーチームのメンバーを集めます。", "target_word": "メンバー", "complexity_tier": "T3", "furigana": "サッカーチームのメンバーを集[あつ]めます。", "sentence_source": "generated"}, {"text": "彼女はバンドのメンバーだ。", "target_word": "メンバー", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はバンドのメンバーだ。", "sentence_source": "generated"}, {"text": "メンバーが全員そろいました。", "target_word": "メンバー", "complexity_tier": "T2", "furigana": "メンバーが全員[ぜんいん]そろいました。", "sentence_source": "generated"}, {"text": "新しいメンバーに会いたいです。", "target_word": "メンバー", "complexity_tier": "T2", "furigana": "新[あたら]しいメンバーに会[あ]いたいです。", "sentence_source": "generated"}, {"text": "メンバーになるには、申し込みが必要だ。", "target_word": "メンバー", "complexity_tier": "T3", "furigana": "メンバーになるには、申[もう]し込[こ]みが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "兄は合唱団のメンバーとして歌っている。", "target_word": "メンバー", "complexity_tier": "T3", "furigana": "兄[あに]は合唱団[がっしょうだん]のメンバーとして歌[うた]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "新メンバー", "label": "派生"}, {"form": "元メンバー", "label": "派生"}, {"form": "メンバーシップ", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | グループに入っている一人の人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c392ff-c6f7-45b1-9aa3-80ca467ce7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51831, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "メンバー", "is_correct": true, "explanation": "見出し語そのものの音で、グループの一員という意味です。"}, {"text": "ナンバー", "is_correct": false, "explanation": "最初の「メ」が「ナ」に変わった別の語で、「番号」の意味です。"}, {"text": "メンター", "is_correct": false, "explanation": "「バ」が「タ」に変わった別の語で、「助言者」の意味です。"}, {"text": "ジャンバー", "is_correct": false, "explanation": "最初の「メ」が「ジャ」に変わった別の語で、「上着」の意味です。"}], "explanations": {"メンバー": "見出し語そのものの音で、グループの一員という意味です。", "ナンバー": "最初の「メ」が「ナ」に変わった別の語で、「番号」の意味です。", "メンター": "「バ」が「タ」に変わった別の語で、「助言者」の意味です。", "ジャンバー": "最初の「メ」が「ジャ」に変わった別の語で、「上着」の意味です。"}, "sentence_index": null, "correct_answer": "メンバー"}, "level_3": {"options": [{"text": "メンバー", "is_correct": true, "explanation": "クラブの一員という意味で、文に合います。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。私がクラブの天気ということはありません。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。人が季節であるという意味にはなりません。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが意味が合わない。人が果物であるという意味にはなりません。"}], "explanations": {"メンバー": "クラブの一員という意味で、文に合います。", "天気": "形は合うが意味が合わない。私がクラブの天気ということはありません。", "季節": "形は合うが意味が合わない。人が季節であるという意味にはなりません。", "果物": "形は合うが意味が合わない。人が果物であるという意味にはなりません。"}, "sentence_index": 0, "correct_answer": "メンバー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "メンバーを開けて、部屋に入った。", "explanation": "メンバーは人を表す語で、ドアのように開けるものではありません。"}, {"text": "母はメンバーを作るために、野菜を切った。", "explanation": "メンバーは料理の名前ではなく、野菜で作るものを表せません。"}, {"text": "来月のメンバーは三十日まである。", "explanation": "メンバーは月や日数を表す語ではなく、カレンダーの意味では使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51831, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "メンバー", "is_correct": true, "explanation": "グループの人が全員そろったという意味に合います。"}, {"text": "荷物", "is_correct": false, "explanation": "形は合うが意味が合わない。荷物に「全員」は使いません。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。季節が全員そろうとは言いません。"}, {"text": "机", "is_correct": false, "explanation": "形は合うが意味が合わない。机に「全員」は使えません。"}], "explanations": {"メンバー": "グループの人が全員そろったという意味に合います。", "荷物": "形は合うが意味が合わない。荷物に「全員」は使いません。", "季節": "形は合うが意味が合わない。季節が全員そろうとは言いません。", "机": "形は合うが意味が合わない。机に「全員」は使えません。"}, "sentence_index": 6, "correct_answer": "メンバー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空にメンバーがたくさん光っている。", "explanation": "メンバーは人を表す語で、星のように光るものの意味はありません。"}, {"text": "メンバーを履いて、公園まで走った。", "explanation": "メンバーは靴のような履き物ではなく、「履く」の目的語になりません。"}, {"text": "暑かったので、冷たいメンバーを一杯飲んだ。", "explanation": "メンバーは人を表す語で、飲み物の意味はありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51831, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は野球チームのメンバーをなった。", "corrected_sentence": "兄は野球チームのメンバーになった。", "error_description": "「なる」には「に」を使います。「メンバーを」は誤りで、「メンバーになった」が正しいです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51831, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は有名なバンドのメンバーを会いたいです。", "corrected_sentence": "私は有名なバンドのメンバーに会いたいです。", "error_description": "「会う」は「に」を取ります。「メンバーを会う」は誤りです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51832, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「メンバー」が「来ました」の主語になるので「が」です。"}, {"text": "を", "is_correct": false, "explanation": "「来る」は目的語を取らないので、メンバーに「を」は付きません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、主語を示せません。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、ここでは意味が通りません。"}], "correct_answer": "が", "explanations": {"が": "「メンバー」が「来ました」の主語になるので「が」です。", "を": "「来る」は目的語を取らないので、メンバーに「を」は付きません。", "へ": "「へ」は方向を表し、主語を示せません。", "より": "「より」は比較を表し、ここでは意味が通りません。"}, "error_tags": {"を": "object marker", "へ": "direction", "より": "comparison"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51832, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「委員会のメンバー」と、所属を表す「の」でつなぎます。"}, {"text": "が", "is_correct": false, "explanation": "「委員会が」にすると、彼女は…が選ばれたという文になり、成り立ちません。"}, {"text": "を", "is_correct": false, "explanation": "「委員会を」にすると、メンバーとの関係が成り立ちません。"}, {"text": "しか", "is_correct": false, "explanation": "「しか」は否定と一緒に使うので、肯定の「選ばれた」とは合いません。"}], "correct_answer": "の", "explanations": {"の": "「委員会のメンバー」と、所属を表す「の」でつなぎます。", "が": "「委員会が」にすると、彼女は…が選ばれたという文になり、成り立ちません。", "を": "「委員会を」にすると、メンバーとの関係が成り立ちません。", "しか": "「しか」は否定と一緒に使うので、肯定の「選ばれた」とは合いません。"}, "error_tags": {"が": "subject marker", "を": "object marker", "しか": "needs negative"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51832, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ある集団や組織を構成する一人ひとりの人のこと。", "primary_collocate": null, "pronunciation": "めんばー", "ipa": "meɴbaː", "syllable_count": 4, "sentences": [{"text": "デザインを担当したのは、美術大学に通うメンバーです。", "target_word": "メンバー", "complexity_tier": "T4", "furigana": "デザインを担当[たんとう]したのは、美術[びじゅつ]大学[だいがく]に通[かよ]うメンバーです。", "sentence_source": "mined"}, {"text": "新しいメンバーが会議に来ました。", "target_word": "メンバー", "complexity_tier": "T2", "furigana": "新[あたら]しいメンバーが会議[かいぎ]に来[き]ました。", "sentence_source": "generated"}, {"text": "彼は研究チームの中心メンバーだ。", "target_word": "メンバー", "complexity_tier": "T3", "furigana": "彼[かれ]は研究[けんきゅう]チームの中心[ちゅうしん]メンバーだ。", "sentence_source": "generated"}, {"text": "メンバー全員で意見を出し合った。", "target_word": "メンバー", "complexity_tier": "T3", "furigana": "メンバー全員[ぜんいん]で意見[いけん]を出[だ]し合[あ]った。", "sentence_source": "generated"}, {"text": "バンドのメンバーを一人ずつ紹介する。", "target_word": "メンバー", "complexity_tier": "T3", "furigana": "バンドのメンバーを一人[ひとり]ずつ紹介[しょうかい]する。", "sentence_source": "generated"}, {"text": "このクラブのメンバーになりたいです。", "target_word": "メンバー", "complexity_tier": "T3", "furigana": "このクラブのメンバーになりたいです。", "sentence_source": "generated"}, {"text": "メンバーが足りなくて、試合に出られない。", "target_word": "メンバー", "complexity_tier": "T3", "furigana": "メンバーが足[た]りなくて、試合[しあい]に出[で]られない。", "sentence_source": "generated"}, {"text": "彼女は委員会のメンバーとして選ばれた。", "target_word": "メンバー", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は委員会[いいんかい]のメンバーとして選[えら]ばれた。", "sentence_source": "generated"}, {"text": "メンバーの都合に合わせて、集まる日を決めよう。", "target_word": "メンバー", "complexity_tier": "T4", "furigana": "メンバーの都合[つごう]に合[あ]わせて、集[あつ]まる日[ひ]を決[き]めよう。", "sentence_source": "generated"}, {"text": "古いメンバーが辞めたため、新しい人を探している。", "target_word": "メンバー", "complexity_tier": "T4", "furigana": "古[ふる]いメンバーが辞[や]めたため、新[あたら]しい人[ひと]を探[さが]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "新メンバー", "label": "派生"}, {"form": "元メンバー", "label": "派生"}, {"form": "メンバーシップ", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 集団や組織を構成する一人の人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c392ff-c6f7-45b1-9aa3-80ca467ce7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51832, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "メンバー", "is_correct": true, "explanation": "見出し語そのものの音で、集団の一人という意味です。"}, {"text": "ナンバー", "is_correct": false, "explanation": "最初の「メ」が「ナ」に変わった別の語で、「番号」の意味です。"}, {"text": "メンター", "is_correct": false, "explanation": "「バ」が「タ」に変わった別の語で、「助言者」の意味です。"}, {"text": "ジャンバー", "is_correct": false, "explanation": "最初の「メ」が「ジャ」に変わった別の語で、「上着」の意味です。"}], "explanations": {"メンバー": "見出し語そのものの音で、集団の一人という意味です。", "ナンバー": "最初の「メ」が「ナ」に変わった別の語で、「番号」の意味です。", "メンター": "「バ」が「タ」に変わった別の語で、「助言者」の意味です。", "ジャンバー": "最初の「メ」が「ジャ」に変わった別の語で、「上着」の意味です。"}, "sentence_index": null, "correct_answer": "メンバー"}, "level_3": {"options": [{"text": "メンバー", "is_correct": true, "explanation": "大学に通う集団の一員という意味で、文脈に合います。"}, {"text": "校舎", "is_correct": false, "explanation": "形は合うが意味が合わない。建物が大学に通うことはありません。"}, {"text": "建物", "is_correct": false, "explanation": "形は合うが意味が合わない。建物は大学に通いません。"}, {"text": "道具", "is_correct": false, "explanation": "形は合うが意味が合わない。道具がデザインを担当して大学に通うことはありません。"}], "explanations": {"メンバー": "大学に通う集団の一員という意味で、文脈に合います。", "校舎": "形は合うが意味が合わない。建物が大学に通うことはありません。", "建物": "形は合うが意味が合わない。建物は大学に通いません。", "道具": "形は合うが意味が合わない。道具がデザインを担当して大学に通うことはありません。"}, "sentence_index": 0, "correct_answer": "メンバー"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、コーヒーにメンバーを入れて飲んでいる。", "explanation": "メンバーは人を表す語なので、飲み物に入れる材料としては使えません。"}, {"text": "駅の前にある大きなメンバーで買い物をした。", "explanation": "メンバーは集団の一員で、買い物をする店や場所の意味はありません。"}, {"text": "昨日は天気がよくて、空のメンバーがとてもきれいだった。", "explanation": "メンバーは人を指す語で、空の景色や様子を表す意味では使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51832, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "メンバー", "is_correct": true, "explanation": "人数が足りなくて試合に出られないという意味に合います。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気が足りないとは言いません。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。季節が足りなくて試合に出られないことはありません。"}, {"text": "笑顔", "is_correct": false, "explanation": "形は合うが意味が合わない。笑顔が足りないことは試合に出られない理由になりません。"}], "explanations": {"メンバー": "人数が足りなくて試合に出られないという意味に合います。", "天気": "形は合うが意味が合わない。天気が足りないとは言いません。", "季節": "形は合うが意味が合わない。季節が足りなくて試合に出られないことはありません。", "笑顔": "形は合うが意味が合わない。笑顔が足りないことは試合に出られない理由になりません。"}, "sentence_index": 6, "correct_answer": "メンバー"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は毎晩、メンバーを読んでから寝る。", "explanation": "メンバーは人を表す語で、読む本や読み物の意味はありません。"}, {"text": "この川のメンバーはとても冷たくて、きれいだ。", "explanation": "メンバーは水の意味ではなく、川の水を表せません。"}, {"text": "朝からメンバーが降っていて、出かけられない。", "explanation": "メンバーは雨や雪のような天気を表せず、「降る」の主語になりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51832, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "チームにはメンバーを五人います。", "corrected_sentence": "チームにはメンバーが五人います。", "error_description": "「いる」の主語は「が」で示します。「メンバーを」は誤りで、「メンバーが」が正しいです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51832, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私たちのメンバーのは全員で十人です。", "corrected_sentence": "私たちのメンバーは全員で十人です。", "error_description": "「メンバー」の後ろに余分な「の」があります。主題を示すには「は」だけで足ります。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51833, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "通う先を示すので「会社に通う」と「に」を使います。"}, {"text": "が", "is_correct": false, "explanation": "「会社が通っている」では会社が主語になり、意味が通りません。"}, {"text": "と", "is_correct": false, "explanation": "「会社と通っている」は行き先を示せず、不自然です。"}, {"text": "しか", "is_correct": false, "explanation": "「しか」は否定と一緒に使うので、肯定の「通っている」とは合いません。"}], "correct_answer": "に", "explanations": {"に": "通う先を示すので「会社に通う」と「に」を使います。", "が": "「会社が通っている」では会社が主語になり、意味が通りません。", "と": "「会社と通っている」は行き先を示せず、不自然です。", "しか": "「しか」は否定と一緒に使うので、肯定の「通っている」とは合いません。"}, "error_tags": {"が": "subject marker", "と": "accompaniment", "しか": "needs negative"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51833, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "通う先を示すので「高校に通う」と「に」を使います。"}, {"text": "が", "is_correct": false, "explanation": "「高校が通った」では高校が主語になり、意味が通りません。"}, {"text": "しか", "is_correct": false, "explanation": "「しか」は否定を伴う語で、肯定の「通った」とは合いません。"}, {"text": "ので", "is_correct": false, "explanation": "「ので」は名詞に直接付かず、「高校ので」は文法的に誤りです。"}], "correct_answer": "に", "explanations": {"に": "通う先を示すので「高校に通う」と「に」を使います。", "が": "「高校が通った」では高校が主語になり、意味が通りません。", "しか": "「しか」は否定を伴う語で、肯定の「通った」とは合いません。", "ので": "「ので」は名詞に直接付かず、「高校ので」は文法的に誤りです。"}, "error_tags": {"が": "subject marker", "しか": "needs negative", "ので": "conjunction"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51833, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "毎日、学校や会社に行くこと。", "primary_collocate": null, "pronunciation": "かよう", "ipa": "kajoː", "syllable_count": 3, "sentences": [{"text": "私は毎日学校に通います。", "target_word": "通います", "complexity_tier": "T2", "furigana": "私[わたし]は毎日[まいにち]学校[がっこう]に通[かよ]います。", "sentence_source": "generated"}, {"text": "父は電車で会社に通っている。", "target_word": "通っ", "complexity_tier": "T3", "furigana": "父[ちち]は電車[でんしゃ]で会社[かいしゃ]に通[かよ]っている。", "sentence_source": "generated"}, {"text": "姉は大学に通っています。", "target_word": "通っ", "complexity_tier": "T2", "furigana": "姉[あね]は大学[だいがく]に通[かよ]っています。", "sentence_source": "generated"}, {"text": "毎日通う学校は家から近い。", "target_word": "通う", "complexity_tier": "T3", "furigana": "毎日[まいにち]通[かよ]う学校[がっこう]は家[いえ]から近[ちか]い。", "sentence_source": "generated"}, {"text": "歩いて通える学校がいいです。", "target_word": "通える", "complexity_tier": "T2", "furigana": "歩[ある]いて通[かよ]える学校[がっこう]がいいです。", "sentence_source": "generated"}, {"text": "弟は小学校に通うようになった。", "target_word": "通う", "complexity_tier": "T3", "furigana": "弟[おとうと]は小学校[しょうがっこう]に通[かよ]うようになった。", "sentence_source": "generated"}, {"text": "雨の日も、会社に通わなければならない。", "target_word": "通わ", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]も、会社[かいしゃ]に通[かよ]わなければならない。", "sentence_source": "generated"}, {"text": "昔は自転車で高校に通った。", "target_word": "通った", "complexity_tier": "T3", "furigana": "昔[むかし]は自転車[じてんしゃ]で高校[こうこう]に通[かよ]った。", "sentence_source": "generated"}, {"text": "毎日バスに乗って、学校に通う。", "target_word": "通う", "complexity_tier": "T3", "furigana": "毎日[まいにち]バスに乗[の]って、学校[がっこう]に通[かよ]う。", "sentence_source": "generated"}, {"text": "兄は遠くの会社に通っているので、朝が早い。", "target_word": "通っ", "complexity_tier": "T3", "furigana": "兄[あに]は遠[とお]くの会社[かいしゃ]に通[かよ]っているので、朝[あさ]が早[はや]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "通います", "label": "活用"}, {"form": "通った", "label": "活用"}, {"form": "通って", "label": "活用"}, {"form": "通わない", "label": "活用"}, {"form": "通える", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 毎日学校や会社に出かける", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c392ff-c6f7-45b1-9aa3-80ca467ce7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51833, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通う", "is_correct": true, "explanation": "見出し語そのものの音「かよう」で、学校や会社に行く意味です。"}, {"text": "迷う", "is_correct": false, "explanation": "最初の「か」が「ま」に変わった別の語「まよう」です。"}, {"text": "多様", "is_correct": false, "explanation": "最初の「か」が「た」に変わった別の語「たよう」です。"}, {"text": "可能", "is_correct": false, "explanation": "「よ」が「の」に変わった別の語「かのう」です。"}], "explanations": {"通う": "見出し語そのものの音「かよう」で、学校や会社に行く意味です。", "迷う": "最初の「か」が「ま」に変わった別の語「まよう」です。", "多様": "最初の「か」が「た」に変わった別の語「たよう」です。", "可能": "「よ」が「の」に変わった別の語「かのう」です。"}, "sentence_index": null, "correct_answer": "通う"}, "level_3": {"options": [{"text": "通います", "is_correct": true, "explanation": "毎日学校に行くという意味に合う丁寧な形です。"}, {"text": "咲きます", "is_correct": false, "explanation": "形は合うが意味が合わない。人は学校に咲きません。"}, {"text": "光ります", "is_correct": false, "explanation": "形は合うが意味が合わない。私が学校に光るとは言いません。"}, {"text": "凍ります", "is_correct": false, "explanation": "形は合うが意味が合わない。私が学校に凍るとは言いません。"}], "explanations": {"通います": "毎日学校に行くという意味に合う丁寧な形です。", "咲きます": "形は合うが意味が合わない。人は学校に咲きません。", "光ります": "形は合うが意味が合わない。私が学校に光るとは言いません。", "凍ります": "形は合うが意味が合わない。私が学校に凍るとは言いません。"}, "sentence_index": 0, "correct_answer": "通います"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このトンネルを通う電車は一日に三本だけだ。", "explanation": "トンネルを通過する意味は「通る」で、「通う」は毎日行く意味です。"}, {"text": "来月、初めて旅行でパリに通います。", "explanation": "「通う」は繰り返し行く意味で、初めての旅行には使えません。"}, {"text": "試験に通うために、毎日勉強している。", "explanation": "試験に合格する意味は「通る」で、「通う」は学校や会社に行く意味です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51833, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "通う", "is_correct": true, "explanation": "見出し語そのものの音「かよう」で、学校や会社に行く意味です。"}, {"text": "過労", "is_correct": false, "explanation": "「よ」が「ろ」に変わった別の語「かろう」です。"}, {"text": "華道", "is_correct": false, "explanation": "「よ」が「ど」に変わった別の語「かどう」です。"}, {"text": "作用", "is_correct": false, "explanation": "最初の「か」が「さ」に変わった別の語「さよう」です。"}], "explanations": {"通う": "見出し語そのものの音「かよう」で、学校や会社に行く意味です。", "過労": "「よ」が「ろ」に変わった別の語「かろう」です。", "華道": "「よ」が「ど」に変わった別の語「かどう」です。", "作用": "最初の「か」が「さ」に変わった別の語「さよう」です。"}, "sentence_index": null, "correct_answer": "通う"}, "level_3": {"options": [{"text": "通わ", "is_correct": true, "explanation": "「通わなければならない」で、未然形「通わ」が入ります。"}, {"text": "咲か", "is_correct": false, "explanation": "形は合うが意味が合わない。人が会社に咲くことはありません。"}, {"text": "光ら", "is_correct": false, "explanation": "形は合うが意味が合わない。会社に光るという意味にはなりません。"}, {"text": "凍ら", "is_correct": false, "explanation": "形は合うが意味が合わない。会社に凍るという意味にはなりません。"}], "explanations": {"通わ": "「通わなければならない」で、未然形「通わ」が入ります。", "咲か": "形は合うが意味が合わない。人が会社に咲くことはありません。", "光ら": "形は合うが意味が合わない。会社に光るという意味にはなりません。", "凍ら": "形は合うが意味が合わない。会社に凍るという意味にはなりません。"}, "sentence_index": 6, "correct_answer": "通わ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水道の水が長い管を通う。", "explanation": "水が管を流れる意味は「通る」で、「通う」は人が行き来する意味です。"}, {"text": "私の意見が会議で通います。", "explanation": "意見が認められる意味は「通る」で、「通う」では表せません。"}, {"text": "この道は狭くて、大きな車は通いません。", "explanation": "道を車が通り抜ける意味は「通る」で、「通う」は定期的に行く意味です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51833, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹は毎朝、高校で通っています。", "corrected_sentence": "妹は毎朝、高校に通っています。", "error_description": "通う先は「に」で示します。「で」は誤りです。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "通っ", "is_correct": true, "explanation": "「通っている」で、て形の促音便「通っ」が入ります。"}, {"text": "通い", "is_correct": false, "explanation": "「通いている」は誤りで、て形では「通っ」になります。"}, {"text": "通わ", "is_correct": false, "explanation": "「通わている」は文法的に誤りです。"}, {"text": "通う", "is_correct": false, "explanation": "「通うている」は誤りで、「ている」の前は「通っ」です。"}], "correct_form": "通っ", "base_form": "通う", "form_label": "て形", "sentence_index": 1, "explanations": {"通っ": "「通っている」で、て形の促音便「通っ」が入ります。", "通い": "「通いている」は誤りで、て形では「通っ」になります。", "通わ": "「通わている」は文法的に誤りです。", "通う": "「通うている」は誤りで、「ている」の前は「通っ」です。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51833, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は自転車に学校に通っています。", "corrected_sentence": "弟は自転車で学校に通っています。", "error_description": "手段は「で」で示します。「自転車に」は誤りです。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "通った", "is_correct": true, "explanation": "「昔は〜通った」で、過去を表すた形が合います。"}, {"text": "通って", "is_correct": false, "explanation": "「昔は」の過去の事実を言い切るにはた形が必要です。「通って」は依頼などの意味になり、ここでは合いません。"}, {"text": "通い", "is_correct": false, "explanation": "「通い。」では文として言い切れず、不自然です。"}, {"text": "通わ", "is_correct": false, "explanation": "「通わ。」は未然形で、文を終えられません。"}], "correct_form": "通った", "base_form": "通う", "form_label": "た形", "sentence_index": 7, "explanations": {"通った": "「昔は〜通った」で、過去を表すた形が合います。", "通って": "「昔は」の過去の事実を言い切るにはた形が必要です。「通って」は依頼などの意味になり、ここでは合いません。", "通い": "「通い。」では文として言い切れず、不自然です。", "通わ": "「通わ。」は未然形で、文を終えられません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
