INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51834, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所に定期的に行き来すること。", "primary_collocate": null, "pronunciation": "かよう", "ipa": "kajoː", "syllable_count": 3, "sentences": [{"text": "デザインを担当したのは、美術大学に通うメンバーです。", "target_word": "通う", "complexity_tier": "T4", "furigana": "デザインを担当[たんとう]したのは、美術[びじゅつ]大学[だいがく]に通[かよ]うメンバーです。", "sentence_source": "mined"}, {"text": "毎週、ピアノ教室に通っています。", "target_word": "通っ", "complexity_tier": "T3", "furigana": "毎週[まいしゅう]、ピアノ教室[きょうしつ]に通[かよ]っています。", "sentence_source": "generated"}, {"text": "弟は近くの中学校に通う。", "target_word": "通う", "complexity_tier": "T3", "furigana": "弟[おとうと]は近[ちか]くの中学校[ちゅうがっこう]に通[かよ]う。", "sentence_source": "generated"}, {"text": "私は週に三回ジムに通います。", "target_word": "通います", "complexity_tier": "T2", "furigana": "私[わたし]は週[しゅう]に三回[さんかい]ジムに通[かよ]います。", "sentence_source": "generated"}, {"text": "病院に通ったおかげで、体が楽になった。", "target_word": "通った", "complexity_tier": "T3", "furigana": "病院[びょういん]に通[かよ]ったおかげで、体[からだ]が楽[らく]になった。", "sentence_source": "generated"}, {"text": "家から駅まで歩いて通えるので便利だ。", "target_word": "通える", "complexity_tier": "T3", "furigana": "家[いえ]から駅[えき]まで歩[ある]いて通[かよ]えるので便利[べんり]だ。", "sentence_source": "generated"}, {"text": "毎日バスで会社に通うのは大変だ。", "target_word": "通う", "complexity_tier": "T3", "furigana": "毎日[まいにち]バスで会社[かいしゃ]に通[かよ]うのは大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "兄は大学に通いながら、アルバイトをしている。", "target_word": "通い", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]に通[かよ]いながら、アルバイトをしている。", "sentence_source": "generated"}, {"text": "遠くの学校に通わせるのは心配だ。", "target_word": "通わせる", "complexity_tier": "T4", "furigana": "遠[とお]くの学校[がっこう]に通[かよ]わせるのは心配[しんぱい]だ。", "sentence_source": "generated"}, {"text": "この店に通う客は、みんな店長と友達だ。", "target_word": "通う", "complexity_tier": "T3", "furigana": "この店[みせ]に通[かよ]う客[きゃく]は、みんな店長[てんちょう]と友達[ともだち]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "通います", "label": "活用"}, {"form": "通った", "label": "活用"}, {"form": "通って", "label": "活用"}, {"form": "通わない", "label": "活用"}, {"form": "通える", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | ある場所に定期的に行き来する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c392ff-c6f7-45b1-9aa3-80ca467ce7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51834, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "通う", "is_correct": true, "explanation": "見出し語そのものの音「かよう」で、定期的に行き来する意味です。"}, {"text": "迷う", "is_correct": false, "explanation": "最初の「か」が「ま」に変わった別の語「まよう」です。"}, {"text": "多様", "is_correct": false, "explanation": "最初の「か」が「た」に変わった別の語「たよう」です。"}, {"text": "可能", "is_correct": false, "explanation": "「よ」が「の」に変わった別の語「かのう」です。"}], "explanations": {"通う": "見出し語そのものの音「かよう」で、定期的に行き来する意味です。", "迷う": "最初の「か」が「ま」に変わった別の語「まよう」です。", "多様": "最初の「か」が「た」に変わった別の語「たよう」です。", "可能": "「よ」が「の」に変わった別の語「かのう」です。"}, "sentence_index": null, "correct_answer": "通う"}, "level_3": {"options": [{"text": "通う", "is_correct": true, "explanation": "美術大学に定期的に行く人という意味に合います。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "形は合うが意味が合わない。大学に泳ぐとは言いません。"}, {"text": "咲く", "is_correct": false, "explanation": "形は合うが意味が合わない。人は大学に咲きません。"}, {"text": "光る", "is_correct": false, "explanation": "形は合うが意味が合わない。大学に光るメンバーとは言いません。"}], "explanations": {"通う": "美術大学に定期的に行く人という意味に合います。", "泳ぐ": "形は合うが意味が合わない。大学に泳ぐとは言いません。", "咲く": "形は合うが意味が合わない。人は大学に咲きません。", "光る": "形は合うが意味が合わない。大学に光るメンバーとは言いません。"}, "sentence_index": 0, "correct_answer": "通う"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この急行は小さい駅を通います。", "explanation": "「通う」は定期的に行き来する意味で、駅を通過する意味は「通る」です。"}, {"text": "新しい案が会議でやっと通います。", "explanation": "案が承認される意味は「通る」で、「通う」では表せません。"}, {"text": "この道は人が多くて、車が通うのは難しい。", "explanation": "車が通り抜ける意味は「通る」で、「通う」は定期的に行く意味です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51834, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "通う", "is_correct": true, "explanation": "見出し語そのものの音「かよう」で、定期的に行き来する意味です。"}, {"text": "過労", "is_correct": false, "explanation": "「よ」が「ろ」に変わった別の語「かろう」です。"}, {"text": "華道", "is_correct": false, "explanation": "「よ」が「ど」に変わった別の語「かどう」です。"}, {"text": "作用", "is_correct": false, "explanation": "最初の「か」が「さ」に変わった別の語「さよう」です。"}], "explanations": {"通う": "見出し語そのものの音「かよう」で、定期的に行き来する意味です。", "過労": "「よ」が「ろ」に変わった別の語「かろう」です。", "華道": "「よ」が「ど」に変わった別の語「かどう」です。", "作用": "最初の「か」が「さ」に変わった別の語「さよう」です。"}, "sentence_index": null, "correct_answer": "通う"}, "level_3": {"options": [{"text": "通う", "is_correct": true, "explanation": "毎日バスで会社に行き来する意味で、文に合います。"}, {"text": "凍る", "is_correct": false, "explanation": "形は合うが意味が合わない。会社に凍るとは言いません。"}, {"text": "溶ける", "is_correct": false, "explanation": "形は合うが意味が合わない。バスで会社に溶けることはありません。"}, {"text": "洗う", "is_correct": false, "explanation": "形は合うが意味が合わない。バスで会社に洗うとは言いません。"}], "explanations": {"通う": "毎日バスで会社に行き来する意味で、文に合います。", "凍る": "形は合うが意味が合わない。会社に凍るとは言いません。", "溶ける": "形は合うが意味が合わない。バスで会社に溶けることはありません。", "洗う": "形は合うが意味が合わない。バスで会社に洗うとは言いません。"}, "sentence_index": 6, "correct_answer": "通う"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "針の穴に糸を通う。", "explanation": "糸を穴に入れる意味は「通す」で、「通う」は人が定期的に行き来する意味です。"}, {"text": "一度だけ、旅行で京都に通う。", "explanation": "「通う」は繰り返し行き来する意味で、一度だけの旅行には使えません。"}, {"text": "ボールが小さな穴を通います。", "explanation": "穴を抜ける意味は「通る」で、「通う」は定期的に行く意味です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51834, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟は毎日、学校が通っています。", "corrected_sentence": "弟は毎日、学校に通っています。", "error_description": "「通う」の行き先は「に」で示します。「学校が」は誤りです。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "通っ", "is_correct": true, "explanation": "「通っています」で、て形の促音便「通っ」が入ります。"}, {"text": "通い", "is_correct": false, "explanation": "「通いています」は不自然です。て形では促音便になります。"}, {"text": "通わ", "is_correct": false, "explanation": "「通わています」は文法的に誤りです。"}, {"text": "通う", "is_correct": false, "explanation": "「通うています」は誤りで、「ています」の前はて形「通っ」です。"}], "correct_form": "通っ", "base_form": "通う", "form_label": "て形", "sentence_index": 1, "explanations": {"通っ": "「通っています」で、て形の促音便「通っ」が入ります。", "通い": "「通いています」は不自然です。て形では促音便になります。", "通わ": "「通わています」は文法的に誤りです。", "通う": "「通うています」は誤りで、「ています」の前はて形「通っ」です。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51834, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は週末、料理教室で通っています。", "corrected_sentence": "私は週末、料理教室に通っています。", "error_description": "通う場所は「に」で示します。「で」は誤りです。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "通い", "is_correct": true, "explanation": "「通いながら」で、連用形「通い」に「ながら」が付きます。"}, {"text": "通っ", "is_correct": false, "explanation": "「通っながら」は誤りです。「ながら」は連用形に付きます。"}, {"text": "通わ", "is_correct": false, "explanation": "「通わながら」は誤りです。未然形には「ながら」が付きません。"}, {"text": "通え", "is_correct": false, "explanation": "「通えながら」は不自然で、この意味にも合いません。"}], "correct_form": "通い", "base_form": "通う", "form_label": "連用形", "sentence_index": 7, "explanations": {"通い": "「通いながら」で、連用形「通い」に「ながら」が付きます。", "通っ": "「通っながら」は誤りです。「ながら」は連用形に付きます。", "通わ": "「通わながら」は誤りです。未然形には「ながら」が付きません。", "通え": "「通えながら」は不自然で、この意味にも合いません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
