INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51835, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "商店", "is_correct": true, "explanation": "聞こえた語そのもの。「しょうてん」で正解。"}, {"text": "終点", "is_correct": false, "explanation": "「しゅうてん」。しょ→しゅの一拍だけが違う。"}, {"text": "重点", "is_correct": false, "explanation": "「じゅうてん」。しょ→じゅの一拍だけが違う。"}, {"text": "少年", "is_correct": false, "explanation": "「しょうねん」。て→ねの一拍だけが違う。"}, {"text": "商戦", "is_correct": false, "explanation": "「しょうせん」。て→せの一拍だけが違う。"}], "explanations": {"商店": "聞こえた語そのもの。「しょうてん」で正解。", "終点": "「しゅうてん」。しょ→しゅの一拍だけが違う。", "重点": "「じゅうてん」。しょ→じゅの一拍だけが違う。", "少年": "「しょうねん」。て→ねの一拍だけが違う。", "商戦": "「しょうせん」。て→せの一拍だけが違う。"}, "sentence_index": null, "correct_answer": "商店"}, "level_3": {"options": [{"text": "商店", "is_correct": true, "explanation": "「ここは商店です」で、物を売る場所を示せる。"}, {"text": "天気", "is_correct": false, "explanation": "「ここは天気です」は、形は合うが意味が合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "「ここは宿題です」は、形は合うが意味が合わない。"}, {"text": "気分", "is_correct": false, "explanation": "「ここは気分です」は、形は合うが意味が合わない。"}], "explanations": {"商店": "「ここは商店です」で、物を売る場所を示せる。", "天気": "「ここは天気です」は、形は合うが意味が合わない。", "宿題": "「ここは宿題です」は、形は合うが意味が合わない。", "気分": "「ここは気分です」は、形は合うが意味が合わない。"}, "sentence_index": 0, "correct_answer": "商店"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、商店を飲んでから会社へ行きます。", "explanation": "商店は物を売る店で、飲み物ではないので「飲む」の目的語にならない。"}, {"text": "商店は三時に走って、家へ帰りました。", "explanation": "商店は店舗であり、人のように走って帰ることはない。"}, {"text": "昨日、商店が熱を出して、学校を休みました。", "explanation": "熱を出すのは人や動物で、店舗である商店には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.valid