INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51836, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "商品を販売する店舗のこと。", "primary_collocate": null, "pronunciation": "しょうてん", "ipa": "ɕoːteɴ", "syllable_count": 4, "sentences": [{"text": "彼が描いたのは、見慣れた商店街のグラフィックでした。", "target_word": "商店", "complexity_tier": "T4", "furigana": "彼[かれ]が描[えが]いたのは、見慣[みな]れた商店街[しょうてんがい]のグラフィックでした。", "sentence_source": "mined"}, {"text": "この商店は朝七時に開きます。", "target_word": "商店", "complexity_tier": "T2", "furigana": "この商店[しょうてん]は朝[あさ]七時[しちじ]に開[あ]きます。", "sentence_source": "generated"}, {"text": "駅の近くに小さな商店がある。", "target_word": "商店", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに小[ちい]さな商店[しょうてん]がある。", "sentence_source": "generated"}, {"text": "祖父は昔、商店を経営していた。", "target_word": "商店", "complexity_tier": "T3", "furigana": "祖父[そふ]は昔[むかし]、商店[しょうてん]を経営[けいえい]していた。", "sentence_source": "generated"}, {"text": "商店で野菜と果物を買った。", "target_word": "商店", "complexity_tier": "T3", "furigana": "商店[しょうてん]で野菜[やさい]と果物[くだもの]を買[か]った。", "sentence_source": "generated"}, {"text": "この町には古い商店が多い。", "target_word": "商店", "complexity_tier": "T3", "furigana": "この町[まち]には古[ふる]い商店[しょうてん]が多[おお]い。", "sentence_source": "generated"}, {"text": "地元の商店を応援するイベントが開かれた。", "target_word": "商店", "complexity_tier": "T4", "furigana": "地元[じもと]の商店[しょうてん]を応援[おうえん]するイベントが開[ひら]かれた。", "sentence_source": "generated"}, {"text": "大きな店ができて、商店の客が減ってしまった。", "target_word": "商店", "complexity_tier": "T4", "furigana": "大[おお]きな店[みせ]ができて、商店[しょうてん]の客[きゃく]が減[へ]ってしまった。", "sentence_source": "generated"}, {"text": "あの商店の主人は、いつも笑顔で迎えてくれる。", "target_word": "商店", "complexity_tier": "T4", "furigana": "あの商店[しょうてん]の主人[しゅじん]は、いつも笑顔[えがお]で迎[むか]えてくれる。", "sentence_source": "generated"}, {"text": "商店は夜八時までです。", "target_word": "商店", "complexity_tier": "T2", "furigana": "商店[しょうてん]は夜[よる]八時[はちじ]までです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "商店街", "label": "派生"}, {"form": "商店主", "label": "派生"}, {"form": "個人商店", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 商品を売る小さな店や店舗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c392ff-c6f7-45b1-9aa3-80ca467ce7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51836, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "商店", "is_correct": true, "explanation": "聞こえた語そのもの。「しょうてん」で正解。"}, {"text": "終点", "is_correct": false, "explanation": "「しゅうてん」。しょ→しゅの一拍だけが違う。"}, {"text": "重点", "is_correct": false, "explanation": "「じゅうてん」。しょ→じゅの一拍だけが違う。"}, {"text": "少年", "is_correct": false, "explanation": "「しょうねん」。て→ねの一拍だけが違う。"}, {"text": "商戦", "is_correct": false, "explanation": "「しょうせん」。て→せの一拍だけが違う。"}, {"text": "要点", "is_correct": false, "explanation": "「ようてん」。しょ→よの一拍だけが違う。"}], "explanations": {"商店": "聞こえた語そのもの。「しょうてん」で正解。", "終点": "「しゅうてん」。しょ→しゅの一拍だけが違う。", "重点": "「じゅうてん」。しょ→じゅの一拍だけが違う。", "少年": "「しょうねん」。て→ねの一拍だけが違う。", "商戦": "「しょうせん」。て→せの一拍だけが違う。", "要点": "「ようてん」。しょ→よの一拍だけが違う。"}, "sentence_index": null, "correct_answer": "商店"}, "level_3": {"options": [{"text": "商店", "is_correct": true, "explanation": "「商店街」という語になり、見慣れた町並みの絵として意味が通る。"}, {"text": "野菜", "is_correct": false, "explanation": "「野菜街」という語はなく、この文に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気街」という語はなく、この文に合わない。"}, {"text": "宿題", "is_correct": false, "explanation": "「宿題街」という語はなく、この文に合わない。"}], "explanations": {"商店": "「商店街」という語になり、見慣れた町並みの絵として意味が通る。", "野菜": "「野菜街」という語はなく、この文に合わない。", "天気": "「天気街」という語はなく、この文に合わない。", "宿題": "「宿題街」という語はなく、この文に合わない。"}, "sentence_index": 0, "correct_answer": "商店"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、商店を食べてから学校へ行く。", "explanation": "商店は物を売る店で、食べ物ではないので「食べる」の目的語にならない。"}, {"text": "商店が歌を歌いながら、道を歩いていた。", "explanation": "商店は建物や店舗であり、人のように歌ったり歩いたりしない。"}, {"text": "うちでは商店を犬と一緒に飼っている。", "explanation": "商店は店舗であり、動物のように「飼う」ことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
