INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51837, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「この仕事には」で、「に」の後に対比・主題を加える。"}, {"text": "を", "is_correct": false, "explanation": "「仕事にを」は助詞が重なり、文として成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「仕事にが」は助詞が重なり、文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「仕事にの」は助詞が重なり、文として成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「この仕事には」で、「に」の後に対比・主題を加える。", "を": "「仕事にを」は助詞が重なり、文として成り立たない。", "が": "「仕事にが」は助詞が重なり、文として成り立たない。", "の": "「仕事にの」は助詞が重なり、文として成り立たない。"}, "error_tags": {"を": "object_marker", "が": "subject_marker", "の": "possessive_misuse"}, "sentence_index": 2}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
