INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51837, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何度も同じことをすると、だんだんとそれがふつうになること。", "primary_collocate": null, "pronunciation": "なれる", "ipa": "nareɾɯ", "syllable_count": 3, "sentences": [{"text": "毎日やると、慣れます。", "target_word": "慣れます", "complexity_tier": "T2", "furigana": "毎日[まいにち]やると、慣[な]れます。", "sentence_source": "generated"}, {"text": "新しい学校に慣れました。", "target_word": "慣れました", "complexity_tier": "T2", "furigana": "新[あたら]しい学校[がっこう]に慣[な]れました。", "sentence_source": "generated"}, {"text": "この仕事には、もう慣れた。", "target_word": "慣れた", "complexity_tier": "T3", "furigana": "この仕事[しごと]には、もう慣[な]れた。", "sentence_source": "generated"}, {"text": "早起きに慣れるのは大変です。", "target_word": "慣れる", "complexity_tier": "T2", "furigana": "早起[はやお]きに慣[な]れるのは大変[たいへん]です。", "sentence_source": "generated"}, {"text": "日本の食べ物に慣れていません。", "target_word": "慣れて", "complexity_tier": "T2", "furigana": "日本[にほん]の食[た]べ物[もの]に慣[な]れていません。", "sentence_source": "generated"}, {"text": "慣れれば、むずかしくなくなるよ。", "target_word": "慣れれば", "complexity_tier": "T3", "furigana": "慣[な]れれば、むずかしくなくなるよ。", "sentence_source": "generated"}, {"text": "慣れた道なので、迷わない。", "target_word": "慣れた", "complexity_tier": "T3", "furigana": "慣[な]れた道[みち]なので、迷[まよ]わない。", "sentence_source": "generated"}, {"text": "だんだん慣れてきて、楽しくなった。", "target_word": "慣れて", "complexity_tier": "T3", "furigana": "だんだん慣[な]れてきて、楽[たの]しくなった。", "sentence_source": "generated"}, {"text": "まだ慣れないので、ゆっくり話してください。", "target_word": "慣れない", "complexity_tier": "T3", "furigana": "まだ慣[な]れないので、ゆっくり話[はな]してください。", "sentence_source": "generated"}, {"text": "クラスの友達と会って、すぐに慣れた。", "target_word": "慣れた", "complexity_tier": "T3", "furigana": "クラスの友達[ともだち]と会[あ]って、すぐに慣[な]れた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "慣れます", "label": "活用"}, {"form": "慣れた", "label": "活用"}, {"form": "慣れて", "label": "活用"}, {"form": "慣れない", "label": "活用"}, {"form": "慣れ", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 同じことを続けてふつうになる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c392ff-c6f7-45b1-9aa3-80ca467ce7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51837, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "慣れる", "is_correct": true, "explanation": "聞こえた語そのもの。「なれる」で正解。"}, {"text": "荒れる", "is_correct": false, "explanation": "「あれる」。な→あの一拍だけが違う。"}, {"text": "折れる", "is_correct": false, "explanation": "「おれる」。な→おの一拍だけが違う。"}, {"text": "切れる", "is_correct": false, "explanation": "「きれる」。な→きの一拍だけが違う。"}, {"text": "濡れる", "is_correct": false, "explanation": "「ぬれる」。な→ぬの一拍だけが違う。"}], "explanations": {"慣れる": "聞こえた語そのもの。「なれる」で正解。", "荒れる": "「あれる」。な→あの一拍だけが違う。", "折れる": "「おれる」。な→おの一拍だけが違う。", "切れる": "「きれる」。な→きの一拍だけが違う。", "濡れる": "「ぬれる」。な→ぬの一拍だけが違う。"}, "sentence_index": null, "correct_answer": "慣れる"}, "level_3": {"options": [{"text": "慣れます", "is_correct": true, "explanation": "「毎日やると慣れます」で、繰り返すうちにふつうになる意味になる。"}, {"text": "晴れます", "is_correct": false, "explanation": "形は合うが、毎日やると天気が晴れるという意味にならない。"}, {"text": "暮れます", "is_correct": false, "explanation": "形は合うが、毎日やると日が暮れるという意味にならない。"}, {"text": "生まれます", "is_correct": false, "explanation": "形は合うが、毎日やると生まれるという意味にならない。"}], "explanations": {"慣れます": "「毎日やると慣れます」で、繰り返すうちにふつうになる意味になる。", "晴れます": "形は合うが、毎日やると天気が晴れるという意味にならない。", "暮れます": "形は合うが、毎日やると日が暮れるという意味にならない。", "生まれます": "形は合うが、毎日やると生まれるという意味にならない。"}, "sentence_index": 0, "correct_answer": "慣れます"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風で木が慣れて、道をふさいでいる。", "explanation": "「慣れる」を木が「倒れる」意味で使っており、慣れの意味に合わない。"}, {"text": "私は昨日、友達と映画を慣れました。", "explanation": "「慣れる」を「見る」の意味で使っており、慣れの意味に合わない。"}, {"text": "この牛乳は冷蔵庫で慣れたので、飲めません。", "explanation": "「慣れる」を食品が「腐る」意味で使っており、慣れの意味に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51837, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "慣れる", "is_correct": true, "explanation": "聞こえた語そのもの。「なれる」で正解。"}, {"text": "割れる", "is_correct": false, "explanation": "「われる」。な→わの一拍だけが違う。"}, {"text": "触れる", "is_correct": false, "explanation": "「ふれる」。な→ふの一拍だけが違う。"}, {"text": "枯れる", "is_correct": false, "explanation": "「かれる」。な→かの一拍だけが違う。"}, {"text": "晴れる", "is_correct": false, "explanation": "「はれる」。な→はの一拍だけが違う。"}], "explanations": {"慣れる": "聞こえた語そのもの。「なれる」で正解。", "割れる": "「われる」。な→わの一拍だけが違う。", "触れる": "「ふれる」。な→ふの一拍だけが違う。", "枯れる": "「かれる」。な→かの一拍だけが違う。", "晴れる": "「はれる」。な→はの一拍だけが違う。"}, "sentence_index": null, "correct_answer": "慣れる"}, "level_3": {"options": [{"text": "慣れた", "is_correct": true, "explanation": "「慣れた道」で、よく通って迷わない道という意味になる。"}, {"text": "疲れた", "is_correct": false, "explanation": "形は合うが、「疲れた道なので迷わない」は意味が合わない。"}, {"text": "暮れた", "is_correct": false, "explanation": "形は合うが、「暮れた道なので迷わない」は意味が合わない。"}, {"text": "呆れた", "is_correct": false, "explanation": "形は合うが、「呆れた道なので迷わない」は意味が合わない。"}], "explanations": {"慣れた": "「慣れた道」で、よく通って迷わない道という意味になる。", "疲れた": "形は合うが、「疲れた道なので迷わない」は意味が合わない。", "暮れた": "形は合うが、「暮れた道なので迷わない」は意味が合わない。", "呆れた": "形は合うが、「呆れた道なので迷わない」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "慣れた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "電車の中で財布を慣れて、とても困った。", "explanation": "「慣れる」を財布を「なくす」意味で使っており、慣れの意味に合わない。"}, {"text": "晴れた日に、洗濯物が慣れてよかった。", "explanation": "「慣れる」を洗濯物が「乾く」意味で使っており、慣れの意味に合わない。"}, {"text": "机の上の水が慣れて、本がぬれた。", "explanation": "「慣れる」を水が「こぼれる」意味で使っており、慣れの意味に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_va