INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51837, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日使っているので、このパソコンを慣れました。", "corrected_sentence": "毎日使っているので、このパソコンに慣れました。", "error_description": "「慣れる」の対象は「を」ではなく「に」で示す。「このパソコンに慣れる」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "慣れました", "is_correct": true, "explanation": "「新しい学校に慣れました」で、丁寧な過去形として文が正しく終わる。"}, {"text": "慣れれば", "is_correct": false, "explanation": "仮定形は条件を表すため、文末では終われず不自然。"}, {"text": "慣れ", "is_correct": false, "explanation": "語幹だけでは文末として不自然。"}, {"text": "慣れさせ", "is_correct": false, "explanation": "使役の連用形で、この位置では文が成り立たない。"}], "correct_form": "慣れました", "base_form": "慣れる", "form_label": "ます形(過去)", "sentence_index": 1, "explanations": {"慣れました": "「新しい学校に慣れました」で、丁寧な過去形として文が正しく終わる。", "慣れれば": "仮定形は条件を表すため、文末では終われず不自然。", "慣れ": "語幹だけでは文末として不自然。", "慣れさせ": "使役の連用形で、この位置では文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51837, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道で慣れているので、迷いません。", "corrected_sentence": "この道に慣れているので、迷いません。", "error_description": "「慣れる」の対象は「で」ではなく「に」で示す。「この道に慣れている」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "慣れて", "is_correct": true, "explanation": "「慣れてきて」で、て形のあとに「きて」が続く。"}, {"text": "慣れた", "is_correct": false, "explanation": "「慣れたきて」は補助動詞「くる」につながらない。"}, {"text": "慣れる", "is_correct": false, "explanation": "「慣れるきて」は補助動詞「くる」につながらない。"}, {"text": "慣れれば", "is_correct": false, "explanation": "「慣れればきて」は補助動詞「くる」につながらない。"}], "correct_form": "慣れて", "base_form": "慣れる", "form_label": "て形", "sentence_index": 7, "explanations": {"慣れて": "「慣れてきて」で、て形のあとに「きて」が続く。", "慣れた": "「慣れたきて」は補助動詞「くる」につながらない。", "慣れる": "「慣れるきて」は補助動詞「くる」につながらない。", "慣れれば": "「慣れればきて」は補助動詞「くる」につながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
