INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51838, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何度も経験したり繰り返したりすることで、違和感や抵抗がなくなり、自然に感じられるようになること。", "primary_collocate": null, "pronunciation": "なれる", "ipa": "nareɾɯ", "syllable_count": 3, "sentences": [{"text": "彼が描いたのは、見慣れた商店街のグラフィックでした。", "target_word": "慣れ", "complexity_tier": "T4", "furigana": "彼[かれ]が描[えが]いたのは、見慣[みな]れた商店街[しょうてんがい]のグラフィックでした。", "sentence_source": "mined"}, {"text": "新しい仕事にやっと慣れました。", "target_word": "慣れました", "complexity_tier": "T2", "furigana": "新[あたら]しい仕事[しごと]にやっと慣[な]れました。", "sentence_source": "generated"}, {"text": "日本の生活に慣れるまで、時間がかかった。", "target_word": "慣れる", "complexity_tier": "T3", "furigana": "日本[にほん]の生活[せいかつ]に慣[な]れるまで、時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "最初は苦手だったが、もう慣れて、楽しい。", "target_word": "慣れて", "complexity_tier": "T4", "furigana": "最初[さいしょ]は苦手[にがて]だったが、もう慣[な]れて、楽[たの]しい。", "sentence_source": "generated"}, {"text": "まだ車の運転に慣れていない。", "target_word": "慣れて", "complexity_tier": "T3", "furigana": "まだ車[くるま]の運転[うんてん]に慣[な]れていない。", "sentence_source": "generated"}, {"text": "慣れるまで、少し時間がかかります。", "target_word": "慣れる", "complexity_tier": "T3", "furigana": "慣[な]れるまで、少[すこ]し時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "慣れれば、この機械は簡単に使えるよ。", "target_word": "慣れれば", "complexity_tier": "T4", "furigana": "慣[な]れれば、この機械[きかい]は簡単[かんたん]に使[つか]えるよ。", "sentence_source": "generated"}, {"text": "慣れた手つきで、彼は料理を作った。", "target_word": "慣れた", "complexity_tier": "T4", "furigana": "慣[な]れた手[て]つきで、彼[かれ]は料理[りょうり]を作[つく]った。", "sentence_source": "generated"}, {"text": "何度もやるうちに、だんだん慣れてきた。", "target_word": "慣れて", "complexity_tier": "T3", "furigana": "何度[なんど]もやるうちに、だんだん慣[な]れてきた。", "sentence_source": "generated"}, {"text": "慣れない仕事で、毎日とても疲れる。", "target_word": "慣れない", "complexity_tier": "T3", "furigana": "慣[な]れない仕事[しごと]で、毎日[まいにち]とても疲[つか]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "慣れます", "label": "活用"}, {"form": "慣れた", "label": "活用"}, {"form": "慣れて", "label": "活用"}, {"form": "慣れない", "label": "活用"}, {"form": "慣れ", "label": "派生"}], "register": "plain", "sense_fingerprint": "動詞 | 繰り返して違和感がなくなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c392ff-c6f7-45b1-9aa3-80ca467ce7d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51838, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "慣れる", "is_correct": true, "explanation": "聞こえた語そのもの。「なれる」で正解。"}, {"text": "荒れる", "is_correct": false, "explanation": "「あれる」。な→あの一拍だけが違う。"}, {"text": "折れる", "is_correct": false, "explanation": "「おれる」。な→おの一拍だけが違う。"}, {"text": "切れる", "is_correct": false, "explanation": "「きれる」。な→きの一拍だけが違う。"}, {"text": "投げる", "is_correct": false, "explanation": "「なげる」。れ→げの一拍だけが違う。"}, {"text": "濡れる", "is_correct": false, "explanation": "「ぬれる」。な→ぬの一拍だけが違う。"}], "explanations": {"慣れる": "聞こえた語そのもの。「なれる」で正解。", "荒れる": "「あれる」。な→あの一拍だけが違う。", "折れる": "「おれる」。な→おの一拍だけが違う。", "切れる": "「きれる」。な→きの一拍だけが違う。", "投げる": "「なげる」。れ→げの一拍だけが違う。", "濡れる": "「ぬれる」。な→ぬの一拍だけが違う。"}, "sentence_index": null, "correct_answer": "慣れる"}, "level_3": {"options": [{"text": "慣れ", "is_correct": true, "explanation": "「見慣れた」で、よく見て違和感がなくなった町並みを表す。"}, {"text": "疲れ", "is_correct": false, "explanation": "「見疲れた商店街」は、形は合うが意味が合わない。"}, {"text": "遅れ", "is_correct": false, "explanation": "「見遅れた商店街」は、形は合うが意味が合わない。"}, {"text": "汚れ", "is_correct": false, "explanation": "「見汚れた商店街」は、形は合うが意味が合わない。"}], "explanations": {"慣れ": "「見慣れた」で、よく見て違和感がなくなった町並みを表す。", "疲れ": "「見疲れた商店街」は、形は合うが意味が合わない。", "遅れ": "「見遅れた商店街」は、形は合うが意味が合わない。", "汚れ": "「見汚れた商店街」は、形は合うが意味が合わない。"}, "sentence_index": 0, "correct_answer": "慣れ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "テーブルの上のコップが慣れて、床に落ちた。", "explanation": "「慣れる」は人や動物が経験で違和感をなくすことで、コップが倒れる意味には使えない。"}, {"text": "朝ご飯を慣れてから、学校へ行った。", "explanation": "「慣れる」を「食べる」の意味で使っており、慣れの意味に合わない。"}, {"text": "宿題が終わって、とても慣れた。", "explanation": "「慣れる」を「疲れる」の意味で使っており、慣れの意味に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51838, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "慣れる", "is_correct": true, "explanation": "聞こえた語そのもの。「なれる」で正解。"}, {"text": "割れる", "is_correct": false, "explanation": "「われる」。な→わの一拍だけが違う。"}, {"text": "触れる", "is_correct": false, "explanation": "「ふれる」。な→ふの一拍だけが違う。"}, {"text": "枯れる", "is_correct": false, "explanation": "「かれる」。な→かの一拍だけが違う。"}, {"text": "晴れる", "is_correct": false, "explanation": "「はれる」。な→はの一拍だけが違う。"}], "explanations": {"慣れる": "聞こえた語そのもの。「なれる」で正解。", "割れる": "「われる」。な→わの一拍だけが違う。", "触れる": "「ふれる」。な→ふの一拍だけが違う。", "枯れる": "「かれる」。な→かの一拍だけが違う。", "晴れる": "「はれる」。な→はの一拍だけが違う。"}, "sentence_index": null, "correct_answer": "慣れる"}, "level_3": {"options": [{"text": "慣れれば", "is_correct": true, "explanation": "「慣れれば簡単に使える」で、繰り返せば楽になるという条件を表す。"}, {"text": "疲れれば", "is_correct": false, "explanation": "形は合うが、疲れると機械が簡単に使えるという意味にならない。"}, {"text": "遅れれば", "is_correct": false, "explanation": "形は合うが、遅れると機械が簡単に使えるという意味にならない。"}, {"text": "壊れれば", "is_correct": false, "explanation": "形は合うが、壊れると簡単に使えるという意味にならない。"}], "explanations": {"慣れれば": "「慣れれば簡単に使える」で、繰り返せば楽になるという条件を表す。", "疲れれば": "形は合うが、疲れると機械が簡単に使えるという意味にならない。", "遅れれば": "形は合うが、遅れると機械が簡単に使えるという意味にならない。", "壊れれば": "形は合うが、壊れると簡単に使えるという意味にならない。"}, "sentence_index": 6, "correct_answer": "慣れれば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山道を走ったので、足がとても慣れる。", "explanation": "「慣れる」を「疲れる」の意味で使っており、慣れの意味に合わない。"}, {"text": "この牛乳は慣れているので、飲まないほうがいい。", "explanation": "「慣れる」は食品が古くなる意味では使えない。"}, {"text": "春になると、雪が慣れて、川に流れた。", "explanation": "「慣れる」を雪が「溶ける」意味で使っており、慣れの意味に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51838, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "毎日歩くので、この道を慣れてきた。", "corrected_sentence": "毎日歩くので、この道に慣れてきた。", "error_description": "「慣れる」の対象を示す助詞は「を」ではなく「に」。「この道に慣れる」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "慣れました", "is_correct": true, "explanation": "「やっと慣れました」で、丁寧な過去形として文が正しく終わる。"}, {"text": "慣れれば", "is_correct": false, "explanation": "仮定形は条件を表すため、文末では終われず不自然。"}, {"text": "慣れて", "is_correct": false, "explanation": "て形は文が続く形で、文末では終われず不自然。"}, {"text": "慣れさせ", "is_correct": false, "explanation": "使役の連用形で、この位置では文が成り立たない。"}], "correct_form": "慣れました", "base_form": "慣れる", "form_label": "ます形(過去)", "sentence_index": 1, "explanations": {"慣れました": "「やっと慣れました」で、丁寧な過去形として文が正しく終わる。", "慣れれば": "仮定形は条件を表すため、文末では終われず不自然。", "慣れて": "て形は文が続く形で、文末では終われず不自然。", "慣れさせ": "使役の連用形で、この位置では文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51838, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "引っ越してから、新しい町が慣れるまで時間がかかった。", "corrected_sentence": "引っ越してから、新しい町に慣れるまで時間がかかった。", "error_description": "「慣れる」の対象は「が」ではなく「に」で示す。「新しい町に慣れる」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "慣れた", "is_correct": true, "explanation": "「慣れた手つき」で、名詞を修飾する連体形(た形)になる。"}, {"text": "慣れて", "is_correct": false, "explanation": "て形では「手つき」を直接修飾できない。"}, {"text": "慣れれば", "is_correct": false, "explanation": "仮定形は名詞を修飾できない。"}, {"text": "慣れます", "is_correct": false, "explanation": "「慣れます手つき」は名詞を修飾する形として不自然。"}], "correct_form": "慣れた", "base_form": "慣れる", "form_label": "連体形(た形)", "sentence_index": 7, "explanations": {"慣れた": "「慣れた手つき」で、名詞を修飾する連体形(た形)になる。", "慣れて": "て形では「手つき」を直接修飾できない。", "慣れれば": "仮定形は名詞を修飾できない。", "慣れます": "「慣れます手つき」は名詞を修飾する形として不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6a1df62-4da2-4529-808e-2a1af53126d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51839, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「色数の多いクレヨン」で、色数がクレヨンの性質を説明する。"}, {"text": "を", "is_correct": false, "explanation": "「色数を多い」は形容詞の前に「を」が付くので誤り。"}, {"text": "へ", "is_correct": false, "explanation": "「色数へ多い」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「色数と多いクレヨン」は文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「色数の多いクレヨン」で、色数がクレヨンの性質を説明する。", "を": "「色数を多い」は形容詞の前に「を」が付くので誤り。", "へ": "「色数へ多い」は意味が通らない。", "と": "「色数と多いクレヨン」は文として成り立たない。"}, "error_tags": {"を": "object marker misuse", "へ": "direction marker misuse", "と": "conjunction misuse"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51839, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「色えんぴつの色数」で、色えんぴつの色の数という所有・関係を表す。"}, {"text": "を", "is_correct": false, "explanation": "「色えんぴつを色数は」では名詞同士がつながらない。"}, {"text": "へ", "is_correct": false, "explanation": "「色えんぴつへ色数は」は意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「色えんぴつから色数は」では文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「色えんぴつの色数」で、色えんぴつの色の数という所有・関係を表す。", "を": "「色えんぴつを色数は」では名詞同士がつながらない。", "へ": "「色えんぴつへ色数は」は意味が通らない。", "から": "「色えんぴつから色数は」では文が成り立たない。"}, "error_tags": {"を": "object marker misuse", "へ": "direction marker misuse", "から": "source marker misuse"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51839, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いろの数。", "primary_collocate": null, "pronunciation": "いろかず", "ipa": "iɾokazɯ", "syllable_count": 4, "sentences": [{"text": "この虹は色数が七つです。", "target_word": "色数", "complexity_tier": "T2", "furigana": "この虹[にじ]は色数[いろかず]が七[なな]つです。", "sentence_source": "generated"}, {"text": "色数の多いクレヨンが欲しいです。", "target_word": "色数", "complexity_tier": "T2", "furigana": "色数[いろかず]の多[おお]いクレヨンが欲[ほ]しいです。", "sentence_source": "generated"}, {"text": "信号の色数は三つです。", "target_word": "色数", "complexity_tier": "T2", "furigana": "信号[しんごう]の色数[いろかず]は三[みっ]つです。", "sentence_source": "generated"}, {"text": "私は色数を数えました。", "target_word": "色数", "complexity_tier": "T2", "furigana": "私[わたし]は色数[いろかず]を数[かぞ]えました。", "sentence_source": "generated"}, {"text": "色数が少ない絵は、見やすいです。", "target_word": "色数", "complexity_tier": "T2", "furigana": "色数[いろかず]が少[すく]ない絵[え]は、見[み]やすいです。", "sentence_source": "generated"}, {"text": "子どもの絵は色数が多くて、にぎやかだ。", "target_word": "色数", "complexity_tier": "T3", "furigana": "子[こ]どもの絵[え]は色数[いろかず]が多[おお]くて、にぎやかだ。", "sentence_source": "generated"}, {"text": "色数を比べると、この花が一番多い。", "target_word": "色数", "complexity_tier": "T3", "furigana": "色数[いろかず]を比[くら]べると、この花[はな]が一番[いちばん]多[おお]い。", "sentence_source": "generated"}, {"text": "色えんぴつの色数は、箱に書いてあります。", "target_word": "色数", "complexity_tier": "T3", "furigana": "色[いろ]えんぴつの色数[いろかず]は、箱[はこ]に書[か]いてあります。", "sentence_source": "generated"}, {"text": "色数が同じなら、どちらを選んでもいいです。", "target_word": "色数", "complexity_tier": "T3", "furigana": "色数[いろかず]が同[おな]じなら、どちらを選[えら]んでもいいです。", "sentence_source": "generated"}, {"text": "先生は、絵の色数を決めてから描くように言った。", "target_word": "色数", "complexity_tier": "T4", "furigana": "先生[せんせい]は、絵[え]の色数[いろかず]を決[き]めてから描[か]くように言[い]った。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 絵や物に使われる色の数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bb56fb5-a3aa-427f-85df-afbf4101a571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51839, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "色数", "is_correct": true, "explanation": "「いろかず」で、色の数。"}, {"text": "色紙", "is_correct": false, "explanation": "「いろがみ」で、色紙のこと。語尾の音が違う。"}, {"text": "色柄", "is_correct": false, "explanation": "「いろがら」で、色と柄のこと。後半の音が違う。"}, {"text": "色気", "is_correct": false, "explanation": "「いろけ」で、色っぽさのこと。後半の音が違う。"}, {"text": "色目", "is_correct": false, "explanation": "「いろめ」で、色の具合のこと。後半の音が違う。"}], "explanations": {"色数": "「いろかず」で、色の数。", "色紙": "「いろがみ」で、色紙のこと。語尾の音が違う。", "色柄": "「いろがら」で、色と柄のこと。後半の音が違う。", "色気": "「いろけ」で、色っぽさのこと。後半の音が違う。", "色目": "「いろめ」で、色の具合のこと。後半の音が違う。"}, "sentence_index": null, "correct_answer": "色数"}, "level_3": {"options": [{"text": "色数", "is_correct": true, "explanation": "虹の色は七つなので、「色数が七つ」で意味が合う。"}, {"text": "高さ", "is_correct": false, "explanation": "形は合うが、「高さが七つ」とは言わず意味が合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "形は合うが、重さを「七つ」と数えられず意味が合わない。"}, {"text": "時間", "is_correct": false, "explanation": "形は合うが、虹の説明として意味が合わない。"}], "explanations": {"色数": "虹の色は七つなので、「色数が七つ」で意味が合う。", "高さ": "形は合うが、「高さが七つ」とは言わず意味が合わない。", "重さ": "形は合うが、重さを「七つ」と数えられず意味が合わない。", "時間": "形は合うが、虹の説明として意味が合わない。"}, "sentence_index": 0, "correct_answer": "色数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この箱の色数はとても重いです。", "explanation": "「色数」は数を表す語で、重さの性質は表せない。"}, {"text": "明日の色数は雨です。", "explanation": "「色数」は天気を表す語ではないので使い方が違う。"}, {"text": "毎朝、色数を飲んでいます。", "explanation": "「色数」は飲み物ではなく、「飲む」の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51839, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "色数", "is_correct": true, "explanation": "「いろかず」で、色の数。"}, {"text": "色分け", "is_correct": false, "explanation": "「いろわけ」で、色で分けること。後半の音が違う。"}, {"text": "色合い", "is_correct": false, "explanation": "「いろあい」で、色の調子のこと。後半の音が違う。"}, {"text": "色事", "is_correct": false, "explanation": "「いろごと」で、恋愛ごとのこと。後半の音が違う。"}, {"text": "色香", "is_correct": false, "explanation": "「いろか」で、色つやや香りのこと。音が短い。"}], "explanations": {"色数": "「いろかず」で、色の数。", "色分け": "「いろわけ」で、色で分けること。後半の音が違う。", "色合い": "「いろあい」で、色の調子のこと。後半の音が違う。", "色事": "「いろごと」で、恋愛ごとのこと。後半の音が違う。", "色香": "「いろか」で、色つやや香りのこと。音が短い。"}, "sentence_index": null, "correct_answer": "色数"}, "level_3": {"options": [{"text": "色数", "is_correct": true, "explanation": "花の色の数を比べて「一番多い」と言うので、意味が合う。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、値段は「多い」ではなく「高い」で、意味が合わない。"}, {"text": "背丈", "is_correct": false, "explanation": "形は合うが、背丈は「多い」とは言わず意味が合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "形は合うが、重さは「多い」とは言わず意味が合わない。"}], "explanations": {"色数": "花の色の数を比べて「一番多い」と言うので、意味が合う。", "値段": "形は合うが、値段は「多い」ではなく「高い」で、意味が合わない。", "背丈": "形は合うが、背丈は「多い」とは言わず意味が合わない。", "重さ": "形は合うが、重さは「多い」とは言わず意味が合わない。"}, "sentence_index": 6, "correct_answer": "色数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この絵の色数は赤と青です。", "explanation": "「色数」は色の数なので、赤と青のような色名を答えるのは誤り。"}, {"text": "色数が大きい声で歌いました。", "explanation": "「色数」は声や音を出すものではなく、主語として意味が合わない。"}, {"text": "色数に乗って旅行した。", "explanation": "「色数」は乗り物ではなく、「乗る」の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_er