INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51840, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "使われている色の種類の数。", "primary_collocate": null, "pronunciation": "いろかず", "ipa": "iɾokazɯ", "syllable_count": 4, "sentences": [{"text": "このポスターは、色数を抑えてすっきりさせた。", "target_word": "色数", "complexity_tier": "T4", "furigana": "このポスターは、色数[いろかず]を抑[おさ]えてすっきりさせた。", "sentence_source": "generated"}, {"text": "色数が多いと、印刷の費用が高くなります。", "target_word": "色数", "complexity_tier": "T3", "furigana": "色数[いろかず]が多[おお]いと、印刷[いんさつ]の費用[ひよう]が高[たか]くなります。", "sentence_source": "generated"}, {"text": "この版画は色数を三つに絞りました。", "target_word": "色数", "complexity_tier": "T3", "furigana": "この版画[はんが]は色数[いろかず]を三[みっ]つに絞[しぼ]りました。", "sentence_source": "generated"}, {"text": "デザイナーは色数を増やして、華やかな絵にした。", "target_word": "色数", "complexity_tier": "T4", "furigana": "デザイナーは色数[いろかず]を増[ふ]やして、華[はな]やかな絵[え]にした。", "sentence_source": "generated"}, {"text": "色数の違いで、二つのロゴは別物に見えます。", "target_word": "色数", "complexity_tier": "T3", "furigana": "色数[いろかず]の違[ちが]いで、二[ふた]つのロゴは別物[べつもの]に見[み]えます。", "sentence_source": "generated"}, {"text": "色数は四色までと決まっています。", "target_word": "色数", "complexity_tier": "T3", "furigana": "色数[いろかず]は四色[よんしょく]までと決[き]まっています。", "sentence_source": "generated"}, {"text": "壁の絵の色数を数えてみた。", "target_word": "色数", "complexity_tier": "T3", "furigana": "壁[かべ]の絵[え]の色数[いろかず]を数[かぞ]えてみた。", "sentence_source": "generated"}, {"text": "このシャツの魅力は、色数が少ないところです。", "target_word": "色数", "complexity_tier": "T3", "furigana": "このシャツの魅力[みりょく]は、色数[いろかず]が少[すく]ないところです。", "sentence_source": "generated"}, {"text": "色数を減らせば、もっと落ち着いた雰囲気になる。", "target_word": "色数", "complexity_tier": "T4", "furigana": "色数[いろかず]を減[へ]らせば、もっと落[お]ち着[つ]いた雰囲気[ふんいき]になる。", "sentence_source": "generated"}, {"text": "色数にこだわる職人が、新しい染め方を試している。", "target_word": "色数", "complexity_tier": "T4", "furigana": "色数[いろかず]にこだわる職人[しょくにん]が、新[あたら]しい染[そ]め方[かた]を試[ため]している。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 使われている色の種類の数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bb56fb5-a3aa-427f-85df-afbf4101a571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51840, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "色数", "is_correct": true, "explanation": "「いろかず」で、使われている色の種類の数を表す。"}, {"text": "色柄", "is_correct": false, "explanation": "「いろがら」で、色と模様のこと。「いろかず」とは音が違う。"}, {"text": "色紙", "is_correct": false, "explanation": "「いろがみ」で、色のついた紙のこと。語尾の音が違う。"}, {"text": "色気", "is_correct": false, "explanation": "「いろけ」で、色っぽさのこと。後半の音が違う。"}, {"text": "色目", "is_correct": false, "explanation": "「いろめ」で、色の具合や流し目のこと。後半の音が違う。"}], "explanations": {"色数": "「いろかず」で、使われている色の種類の数を表す。", "色柄": "「いろがら」で、色と模様のこと。「いろかず」とは音が違う。", "色紙": "「いろがみ」で、色のついた紙のこと。語尾の音が違う。", "色気": "「いろけ」で、色っぽさのこと。後半の音が違う。", "色目": "「いろめ」で、色の具合や流し目のこと。後半の音が違う。"}, "sentence_index": null, "correct_answer": "色数"}, "level_3": {"options": [{"text": "色数", "is_correct": true, "explanation": "「色数を抑える」は使う色の種類を少なくすることで、ポスターをすっきりさせる文意に合う。"}, {"text": "人数", "is_correct": false, "explanation": "形は合うが、ポスターで抑えるものとして意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、ポスターで抑えるものとして意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、ポスターで抑えるものとして意味が合わない。"}], "explanations": {"色数": "「色数を抑える」は使う色の種類を少なくすることで、ポスターをすっきりさせる文意に合う。", "人数": "形は合うが、ポスターで抑えるものとして意味が合わない。", "天気": "形は合うが、ポスターで抑えるものとして意味が合わない。", "季節": "形は合うが、ポスターで抑えるものとして意味が合わない。"}, "sentence_index": 0, "correct_answer": "色数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この版画の色数は赤です。", "explanation": "「色数」は色の種類の数で、赤のような個々の色を指す語ではないので、「色」を使うべき。"}, {"text": "この箱は色数が重くて、持ち上げるのが大変だった。", "explanation": "「色数」は数を表す語で、重さの性質を表せないので使い方が違う。"}, {"text": "色数を食べたら、とてもおいしかった。", "explanation": "「色数」は食べられるものではなく、「食べる」の目的語として意味が成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_us