INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51840, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "色数", "is_correct": true, "explanation": "「いろかず」で、色の種類の数。"}, {"text": "色分け", "is_correct": false, "explanation": "「いろわけ」で、色で区別すること。後半の音が違う。"}, {"text": "色合い", "is_correct": false, "explanation": "「いろあい」で、色の調子のこと。後半の音が違う。"}, {"text": "色事", "is_correct": false, "explanation": "「いろごと」で、恋愛ごとのこと。後半の音が違う。"}, {"text": "色香", "is_correct": false, "explanation": "「いろか」で、色つやや香りのこと。「いろかず」より短い。"}], "explanations": {"色数": "「いろかず」で、色の種類の数。", "色分け": "「いろわけ」で、色で区別すること。後半の音が違う。", "色合い": "「いろあい」で、色の調子のこと。後半の音が違う。", "色事": "「いろごと」で、恋愛ごとのこと。後半の音が違う。", "色香": "「いろか」で、色つやや香りのこと。「いろかず」より短い。"}, "sentence_index": null, "correct_answer": "色数"}, "level_3": {"options": [{"text": "色数", "is_correct": true, "explanation": "壁の絵の色の種類の数を「数える」ので、意味が合う。"}, {"text": "高さ", "is_correct": false, "explanation": "形は合うが、高さは「数える」ものではなく、意味が合わない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、値段は「数える」ものではなく、意味が合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "形は合うが、重さは「数える」ものではなく、意味が合わない。"}], "explanations": {"色数": "壁の絵の色の種類の数を「数える」ので、意味が合う。", "高さ": "形は合うが、高さは「数える」ものではなく、意味が合わない。", "値段": "形は合うが、値段は「数える」ものではなく、意味が合わない。", "重さ": "形は合うが、重さは「数える」ものではなく、意味が合わない。"}, "sentence_index": 6, "correct_answer": "色数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空の色数がきれいな青だった。", "explanation": "「色数」は色の数で、青という色そのものを表せない。「色」が正しい。"}, {"text": "彼の色数は百五十センチだ。", "explanation": "「色数」は身長のような長さを表す語ではなく、意味が違う。"}, {"text": "色数に乗って旅行した。", "explanation": "「色数」は乗り物ではないので、「乗る」の対象として成り立たない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EX