INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51840, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この版画の色数は赤と青です。", "corrected_sentence": "この版画の色数は二つです。", "error_description": "「色数」は色の種類の数なので、赤と青のように色そのものを答えるのは誤り。数を答える形にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51840, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このロゴは色数が明るくて、目立ちます。", "corrected_sentence": "このロゴは色が明るくて、目立ちます。", "error_description": "「明るい」は色そのものの性質で、色の数には使えない。「色数」を「色」に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
