INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51841, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "わざと、そうすることを選んでやることです。", "primary_collocate": null, "pronunciation": "あえて", "ipa": "aete", "syllable_count": 3, "sentences": [{"text": "あえて古い地図を使いました。", "target_word": "あえて", "complexity_tier": "T2", "furigana": "あえて古[ふる]い地図[ちず]を使[つか]いました。", "sentence_source": "generated"}, {"text": "私はあえて小さい声で話しました。", "target_word": "あえて", "complexity_tier": "T2", "furigana": "私[わたし]はあえて小[ちい]さい声[こえ]で話[はな]しました。", "sentence_source": "generated"}, {"text": "敢えて右の道を行きました。", "target_word": "敢えて", "complexity_tier": "T2", "furigana": "敢[あ]えて右[みぎ]の道[みち]を行[い]きました。", "sentence_source": "generated"}, {"text": "雨でしたが、あえて外に出ました。", "target_word": "あえて", "complexity_tier": "T2", "furigana": "雨[あめ]でしたが、あえて外[そと]に出[で]ました。", "sentence_source": "generated"}, {"text": "母はあえて何も聞きませんでした。", "target_word": "あえて", "complexity_tier": "T2", "furigana": "母[はは]はあえて何[なに]も聞[き]きませんでした。", "sentence_source": "generated"}, {"text": "あえてゆっくり歩いている。", "target_word": "あえて", "complexity_tier": "T3", "furigana": "あえてゆっくり歩[ある]いている。", "sentence_source": "generated"}, {"text": "友だちは、あえて黒い服を着てきた。", "target_word": "あえて", "complexity_tier": "T3", "furigana": "友[とも]だちは、あえて黒[くろ]い服[ふく]を着[き]てきた。", "sentence_source": "generated"}, {"text": "あえて言わないのは、やさしさだと思う。", "target_word": "あえて", "complexity_tier": "T3", "furigana": "あえて言[い]わないのは、やさしさだと思[おも]う。", "sentence_source": "generated"}, {"text": "テストの前に、あえて何もしないで休んだ。", "target_word": "あえて", "complexity_tier": "T3", "furigana": "テストの前[まえ]に、あえて何[なに]もしないで休[やす]んだ。", "sentence_source": "generated"}, {"text": "敢えて遠い店まで行ってみたいです。", "target_word": "敢えて", "complexity_tier": "T3", "furigana": "敢[あ]えて遠[とお]い店[みせ]まで行[い]ってみたいです。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "副詞 | わざと選んでそうする様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bb56fb5-a3aa-427f-85df-afbf4101a571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51841, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "敢えて", "is_correct": true, "explanation": "「あえて」で、わざとそうする様子。"}, {"text": "上げて", "is_correct": false, "explanation": "「あげて」で、二拍目の音が違う。"}, {"text": "当てて", "is_correct": false, "explanation": "「あてて」で、二拍目の音が違う。"}, {"text": "荒れて", "is_correct": false, "explanation": "「あれて」で、二拍目の音が違う。"}, {"text": "相手", "is_correct": false, "explanation": "「あいて」で、二拍目の音が違う。"}], "explanations": {"敢えて": "「あえて」で、わざとそうする様子。", "上げて": "「あげて」で、二拍目の音が違う。", "当てて": "「あてて」で、二拍目の音が違う。", "荒れて": "「あれて」で、二拍目の音が違う。", "相手": "「あいて」で、二拍目の音が違う。"}, "sentence_index": null, "correct_answer": "敢えて"}, "level_3": {"options": [{"text": "あえて", "is_correct": true, "explanation": "古い地図をわざと選んで使ったという意味で、文意に合う。"}, {"text": "思わず", "is_correct": false, "explanation": "形は合うが、無意識の動作では地図を使うことと意味が合わない。"}, {"text": "突然", "is_correct": false, "explanation": "形は合うが、急な出来事の意味で、地図を使う行為と意味が合わない。"}, {"text": "ぐっすり", "is_correct": false, "explanation": "形は合うが、よく眠る様子の語で、地図を使う意味と合わない。"}], "explanations": {"あえて": "古い地図をわざと選んで使ったという意味で、文意に合う。", "思わず": "形は合うが、無意識の動作では地図を使うことと意味が合わない。", "突然": "形は合うが、急な出来事の意味で、地図を使う行為と意味が合わない。", "ぐっすり": "形は合うが、よく眠る様子の語で、地図を使う意味と合わない。"}, "sentence_index": 0, "correct_answer": "あえて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "思わず、あえて大きな声が出てしまった。", "explanation": "「思わず」は無意識で、わざとの「あえて」と矛盾する。"}, {"text": "あえて犬は動物です。", "explanation": "事実の説明に「あえて」は使えず、選択の意味がない。"}, {"text": "かぜをひいて、あえて熱が出た。", "explanation": "熱が出るのは選べないので、「あえて」は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51841, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "敢えて", "is_correct": true, "explanation": "「あえて」で、わざと選んでする様子。"}, {"text": "開けて", "is_correct": false, "explanation": "「あけて」で、二拍目の音が違う。"}, {"text": "褪せて", "is_correct": false, "explanation": "「あせて」で、二拍目の音が違う。"}, {"text": "揚げて", "is_correct": false, "explanation": "「あげて」で、二拍目の音が違う。"}], "explanations": {"敢えて": "「あえて」で、わざと選んでする様子。", "開けて": "「あけて」で、二拍目の音が違う。", "褪せて": "「あせて」で、二拍目の音が違う。", "揚げて": "「あげて」で、二拍目の音が違う。"}, "sentence_index": null, "correct_answer": "敢えて"}, "level_3": {"options": [{"text": "あえて", "is_correct": true, "explanation": "友だちが黒い服をわざと選んで着てきたという意味で、文意に合う。"}, {"text": "すやすや", "is_correct": false, "explanation": "形は合うが、静かに眠る様子の語で、服を着てくる意味と合わない。"}, {"text": "一斉に", "is_correct": false, "explanation": "形は合うが、友だち一人の行動には意味が合わない。"}, {"text": "たちまち", "is_correct": false, "explanation": "形は合うが、すぐにの意味で、服を選ぶ意味と合わない。"}], "explanations": {"あえて": "友だちが黒い服をわざと選んで着てきたという意味で、文意に合う。", "すやすや": "形は合うが、静かに眠る様子の語で、服を着てくる意味と合わない。", "一斉に": "形は合うが、友だち一人の行動には意味が合わない。", "たちまち": "形は合うが、すぐにの意味で、服を選ぶ意味と合わない。"}, "sentence_index": 6, "correct_answer": "あえて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "道がわからなくて、あえて迷ってしまった。", "explanation": "迷うのは意図しない結果で、わざとの「あえて」は合わない。"}, {"text": "あえて三に二を足すと五です。", "explanation": "計算の結果に選択の意味はなく、「あえて」は使えない。"}, {"text": "あえて地震が起きて、みんな驚いた。", "explanation": "地震は人が選べないので、「あえて」は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51841, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寝坊して、あえて電車に乗り遅れた。", "corrected_sentence": "寝坊して、電車に乗り遅れた。", "error_description": "寝坊による乗り遅れは意図的でないため、「あえて」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51841, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "眠かったので、あえてあくびが出た。", "corrected_sentence": "眠かったので、思わずあくびが出た。", "error_description": "あくびは意図せず出るものなので、わざとの「あえて」は誤り。「思わず」にする。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
