INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51842, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "何かを特別に選んで、わざとそうする様子。他のやり方があるのに、あえてその方法を選ぶこと。", "primary_collocate": null, "pronunciation": "あえて", "ipa": "aete", "syllable_count": 3, "sentences": [{"text": "このポスターは、あえて色を少なくしてシンプルにした。", "target_word": "あえて", "complexity_tier": "T4", "furigana": "このポスターは、あえて色[いろ]を少[すく]なくしてシンプルにした。", "sentence_source": "generated"}, {"text": "彼はあえて難しい道を選んだ。", "target_word": "あえて", "complexity_tier": "T3", "furigana": "彼[かれ]はあえて難[むずか]しい道[みち]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "敢えて遠回りして、川沿いの道を歩いた。", "target_word": "敢えて", "complexity_tier": "T4", "furigana": "敢[あ]えて遠回[とおまわ]りして、川沿[かわぞ]いの道[みち]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "忙しいけれど、あえて自分で料理をします。", "target_word": "あえて", "complexity_tier": "T3", "furigana": "忙[いそが]しいけれど、あえて自分[じぶん]で料理[りょうり]をします。", "sentence_source": "generated"}, {"text": "電車があるのに、あえて歩いて帰った。", "target_word": "あえて", "complexity_tier": "T3", "furigana": "電車[でんしゃ]があるのに、あえて歩[ある]いて帰[かえ]った。", "sentence_source": "generated"}, {"text": "彼女は敢えて何も言わなかった。", "target_word": "敢えて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は敢[あ]えて何[なに]も言[い]わなかった。", "sentence_source": "generated"}, {"text": "あえて危ない場所に行く必要はありません。", "target_word": "あえて", "complexity_tier": "T3", "furigana": "あえて危[あぶ]ない場所[ばしょ]に行[い]く必要[ひつよう]はありません。", "sentence_source": "generated"}, {"text": "先生はあえて答えを教えず、生徒に考えさせた。", "target_word": "あえて", "complexity_tier": "T4", "furigana": "先生[せんせい]はあえて答[こた]えを教[おし]えず、生徒[せいと]に考[かんが]えさせた。", "sentence_source": "generated"}, {"text": "本当のことを、敢えて話さないほうがいい場合もある。", "target_word": "敢えて", "complexity_tier": "T4", "furigana": "本当[ほんとう]のことを、敢[あ]えて話[はな]さないほうがいい場合[ばあい]もある。", "sentence_source": "generated"}, {"text": "失敗するとわかっていて、あえて挑戦する人もいる。", "target_word": "あえて", "complexity_tier": "T4", "furigana": "失敗[しっぱい]するとわかっていて、あえて挑戦[ちょうせん]する人[ひと]もいる。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "副詞 | 他の方法がある中で、わざと選ぶ様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bb56fb5-a3aa-427f-85df-afbf4101a571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51842, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "敢えて", "is_correct": true, "explanation": "「あえて」で、わざと選んでする様子を表す副詞。"}, {"text": "開けて", "is_correct": false, "explanation": "「あけて」で、二拍目の音が違う。"}, {"text": "褪せて", "is_correct": false, "explanation": "「あせて」で、二拍目の音が違う。"}, {"text": "相手", "is_correct": false, "explanation": "「あいて」で、二拍目の音が違う。"}, {"text": "荒れて", "is_correct": false, "explanation": "「あれて」で、二拍目の音が違う。"}], "explanations": {"敢えて": "「あえて」で、わざと選んでする様子を表す副詞。", "開けて": "「あけて」で、二拍目の音が違う。", "褪せて": "「あせて」で、二拍目の音が違う。", "相手": "「あいて」で、二拍目の音が違う。", "荒れて": "「あれて」で、二拍目の音が違う。"}, "sentence_index": null, "correct_answer": "敢えて"}, "level_3": {"options": [{"text": "あえて", "is_correct": true, "explanation": "色を少なくすることをわざと選んだという意味で、文意に合う。"}, {"text": "たまたま", "is_correct": false, "explanation": "形は合うが、偶然では「シンプルにした」という意図的な工夫と意味が合わない。"}, {"text": "思わず", "is_correct": false, "explanation": "形は合うが、無意識の動作ではデザインを工夫する意味と合わない。"}, {"text": "うっかり", "is_correct": false, "explanation": "形は合うが、不注意ではわざとシンプルにする意味と合わない。"}], "explanations": {"あえて": "色を少なくすることをわざと選んだという意味で、文意に合う。", "たまたま": "形は合うが、偶然では「シンプルにした」という意図的な工夫と意味が合わない。", "思わず": "形は合うが、無意識の動作ではデザインを工夫する意味と合わない。", "うっかり": "形は合うが、不注意ではわざとシンプルにする意味と合わない。"}, "sentence_index": 0, "correct_answer": "あえて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "うっかり、あえて鍵を家に忘れてしまった。", "explanation": "「あえて」はわざとの意味なのに、不注意の「うっかり」と矛盾する使い方。"}, {"text": "明日はあえて雨が降るでしょう。", "explanation": "天気は選べないので、意図的に選ぶ「あえて」は使えない。"}, {"text": "あえて楽しいので、毎日この店に通っている。", "explanation": "「あえて」は他の選択肢から選ぶ意味で、自然な理由の文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51842, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "敢えて", "is_correct": true, "explanation": "「あえて」で、わざと選ぶ様子の副詞。"}, {"text": "上げて", "is_correct": false, "explanation": "「あげて」で、二拍目の音が違う。"}, {"text": "当てて", "is_correct": false, "explanation": "「あてて」で、二拍目の音が違う。"}, {"text": "明けて", "is_correct": false, "explanation": "「あけて」で、二拍目の音が違う。"}], "explanations": {"敢えて": "「あえて」で、わざと選ぶ様子の副詞。", "上げて": "「あげて」で、二拍目の音が違う。", "当てて": "「あてて」で、二拍目の音が違う。", "明けて": "「あけて」で、二拍目の音が違う。"}, "sentence_index": null, "correct_answer": "敢えて"}, "level_3": {"options": [{"text": "あえて", "is_correct": true, "explanation": "「あえて〜する必要はありません」で、わざわざする必要がないという意味に合う。"}, {"text": "ふと", "is_correct": false, "explanation": "形は合うが、突然の動作で「必要はない」と意味が合わない。"}, {"text": "つい", "is_correct": false, "explanation": "形は合うが、うっかりの意味で「必要はない」と意味が合わない。"}, {"text": "偶然", "is_correct": false, "explanation": "形は合うが、偶然では「必要はない」と意味が合わない。"}], "explanations": {"あえて": "「あえて〜する必要はありません」で、わざわざする必要がないという意味に合う。", "ふと": "形は合うが、突然の動作で「必要はない」と意味が合わない。", "つい": "形は合うが、うっかりの意味で「必要はない」と意味が合わない。", "偶然": "形は合うが、偶然では「必要はない」と意味が合わない。"}, "sentence_index": 6, "correct_answer": "あえて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "あえて転んでしまい、ひざをけがした。", "explanation": "転ぶのは事故で、わざと選ぶ意味の「あえて」は使えない。"}, {"text": "彼はあえて眠くなって、授業中に寝てしまった。", "explanation": "眠くなるのは自然な状態で、意図的に選ぶ「あえて」とは矛盾する。"}, {"text": "あえて時間がなくて、電車に乗り遅れた。", "explanation": "時間がないのは選んだことではないので、「あえて」は誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51842, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ぼんやりしていて、あえて信号を見落とした。", "corrected_sentence": "ぼんやりしていて、うっかり信号を見落とした。", "error_description": "見落としは意図的ではないので、わざとの意味の「あえて」は誤り。「うっかり」にする。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
