INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51843, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「頼んでおく」の目的語を示します。"}, {"text": "へ", "is_correct": false, "explanation": "「プリントへ」では動作の対象が示せず、文が不自然です。"}, {"text": "ので", "is_correct": false, "explanation": "名詞に直接「ので」は付けられません。"}, {"text": "ながら", "is_correct": false, "explanation": "名詞に「ながら」は付かず、文が成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「頼んでおく」の目的語を示します。", "へ": "「プリントへ」では動作の対象が示せず、文が不自然です。", "ので": "名詞に直接「ので」は付けられません。", "ながら": "名詞に「ながら」は付かず、文が成り立ちません。"}, "error_tags": {"へ": "direction", "ので": "reason", "ながら": "simultaneous"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51843, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "えや もじを かみに うつす こと です。", "primary_collocate": null, "pronunciation": "ぷりんと", "ipa": "puɾinto", "syllable_count": 4, "sentences": [{"text": "写真のプリントをお願いします。", "target_word": "プリント", "complexity_tier": "T2", "furigana": "写真[しゃしん]のプリントをお願[ねが]いします。", "sentence_source": "generated"}, {"text": "この絵のプリントは、すぐ終わります。", "target_word": "プリント", "complexity_tier": "T3", "furigana": "この絵[え]のプリントは、すぐ終[お]わります。", "sentence_source": "generated"}, {"text": "プリントには、少し時間がかかります。", "target_word": "プリント", "complexity_tier": "T3", "furigana": "プリントには、少[すこ]し時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "紙へのプリントは、この機械でします。", "target_word": "プリント", "complexity_tier": "T3", "furigana": "紙[かみ]へのプリントは、この機械[きかい]でします。", "sentence_source": "generated"}, {"text": "文字のプリントが、うまくできませんでした。", "target_word": "プリント", "complexity_tier": "T3", "furigana": "文字[もじ]のプリントが、うまくできませんでした。", "sentence_source": "generated"}, {"text": "写真のプリントを、駅前の店で頼みました。", "target_word": "プリント", "complexity_tier": "T3", "furigana": "写真[しゃしん]のプリントを、駅前[えきまえ]の店[みせ]で頼[たの]みました。", "sentence_source": "generated"}, {"text": "プリントが終わったら、紙を取ってください。", "target_word": "プリント", "complexity_tier": "T4", "furigana": "プリントが終[お]わったら、紙[かみ]を取[と]ってください。", "sentence_source": "generated"}, {"text": "古い写真のプリントを、店に頼んでおきました。", "target_word": "プリント", "complexity_tier": "T3", "furigana": "古[ふる]い写真[しゃしん]のプリントを、店[みせ]に頼[たの]んでおきました。", "sentence_source": "generated"}, {"text": "プリントは、紙に絵や文字をうつすことです。", "target_word": "プリント", "complexity_tier": "T3", "furigana": "プリントは、紙[かみ]に絵[え]や文字[もじ]をうつすことです。", "sentence_source": "generated"}, {"text": "機械のプリントがうまくいって、みんな喜んだ。", "target_word": "プリント", "complexity_tier": "T3", "furigana": "機械[きかい]のプリントがうまくいって、みんな喜[よろこ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プリントする", "label": "派生"}, {"form": "プリントされる", "label": "派生"}, {"form": "プリントアウト", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 絵や文字を紙に写すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bb56fb5-a3aa-427f-85df-afbf4101a571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51843, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "プリント", "is_correct": true, "explanation": "聞いた語そのもので、正解です。"}, {"text": "プラント", "is_correct": false, "explanation": "「リ」が「ラ」に変わった別の語です。"}, {"text": "プリンタ", "is_correct": false, "explanation": "「ト」が「タ」に変わった別の語です。"}, {"text": "プリンス", "is_correct": false, "explanation": "「ト」が「ス」に変わった別の語です。"}], "explanations": {"プリント": "聞いた語そのもので、正解です。", "プラント": "「リ」が「ラ」に変わった別の語です。", "プリンタ": "「ト」が「タ」に変わった別の語です。", "プリンス": "「ト」が「ス」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "プリント"}, "level_3": {"options": [{"text": "プリント", "is_correct": true, "explanation": "写真を紙に写したものを頼む文で意味が合います。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。写真の天気をお願いするとは言いません。"}, {"text": "野菜", "is_correct": false, "explanation": "形は合うが意味が合わない。写真の野菜を頼む場面はありません。"}, {"text": "昼寝", "is_correct": false, "explanation": "形は合うが意味が合わない。写真の昼寝は文脈に合いません。"}], "explanations": {"プリント": "写真を紙に写したものを頼む文で意味が合います。", "天気": "形は合うが意味が合わない。写真の天気をお願いするとは言いません。", "野菜": "形は合うが意味が合わない。写真の野菜を頼む場面はありません。", "昼寝": "形は合うが意味が合わない。写真の昼寝は文脈に合いません。"}, "sentence_index": 0, "correct_answer": "プリント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅までプリントで三十分かかりました。", "explanation": "プリントは乗り物ではなく、移動手段を表す「で」と合いません。"}, {"text": "この犬はプリントが好きで、毎日走っている。", "explanation": "プリントは絵や文字を紙に写すことで、犬が好む走る遊びではありません。"}, {"text": "プリントを食べたので、おなかがいっぱいです。", "explanation": "プリントは食べ物ではないので「食べる」の目的語になりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51843, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "プリント", "is_correct": true, "explanation": "聞いた語そのもので、正解です。"}, {"text": "フリント", "is_correct": false, "explanation": "「プ」が「フ」に変わった別の語です。"}, {"text": "プリン", "is_correct": false, "explanation": "最後の「ト」がない別の語（お菓子）です。"}, {"text": "プラント", "is_correct": false, "explanation": "「リ」が「ラ」に変わった別の語です。"}], "explanations": {"プリント": "聞いた語そのもので、正解です。", "フリント": "「プ」が「フ」に変わった別の語です。", "プリン": "最後の「ト」がない別の語（お菓子）です。", "プラント": "「リ」が「ラ」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "プリント"}, "level_3": {"options": [{"text": "プリント", "is_correct": true, "explanation": "印刷が終わってから紙を取る流れで意味が合います。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。季節が終わっても紙を取る理由になりません。"}, {"text": "梅雨", "is_correct": false, "explanation": "形は合うが意味が合わない。梅雨と紙を取る動作が結びつきません。"}, {"text": "台風", "is_correct": false, "explanation": "形は合うが意味が合わない。台風が終わることと紙は関係ありません。"}], "explanations": {"プリント": "印刷が終わってから紙を取る流れで意味が合います。", "季節": "形は合うが意味が合わない。季節が終わっても紙を取る理由になりません。", "梅雨": "形は合うが意味が合わない。梅雨と紙を取る動作が結びつきません。", "台風": "形は合うが意味が合わない。台風が終わることと紙は関係ありません。"}, "sentence_index": 6, "correct_answer": "プリント"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "プリントは、とても甘くておいしかった。", "explanation": "プリントは味のあるものではないので、「甘い」と評価できません。"}, {"text": "プリントに乗って、海を渡った。", "explanation": "プリントは乗り物ではないので「乗る」の対象になりません。"}, {"text": "空にプリントが三つ見えた。", "explanation": "プリントは空に浮かぶ物ではなく、この場面で使うと意味が合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51843, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この写真のプリントに、お願いします。", "corrected_sentence": "この写真のプリントを、お願いします。", "error_description": "「お願いする」対象には「に」ではなく「を」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51843, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "写真のプリントは、あの店をします。", "corrected_sentence": "写真のプリントは、あの店でします。", "error_description": "作業をする場所を表すのは「を」ではなく「で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51844, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「スカーフのプリント」と、持ち主・所属を表します。"}, {"text": "を", "is_correct": false, "explanation": "「を」では名詞同士がつながらず、文になりません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、ここでは使えません。"}, {"text": "が", "is_correct": false, "explanation": "「スカーフがプリントは」と主語が重なり、文になりません。"}], "correct_answer": "の", "explanations": {"の": "「スカーフのプリント」と、持ち主・所属を表します。", "を": "「を」では名詞同士がつながらず、文になりません。", "へ": "「へ」は方向を表し、ここでは使えません。", "が": "「スカーフがプリントは」と主語が重なり、文になりません。"}, "error_tags": {"を": "object", "へ": "direction", "が": "subject"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51844, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "ほど", "options": [{"text": "ほど", "is_correct": true, "explanation": "「細かいプリントほど」で程度に比例する意味になります。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、ここでは文が成り立ちません。"}, {"text": "ので", "is_correct": false, "explanation": "名詞に直接「ので」は付けられず（「なので」が必要）、不適切です。"}, {"text": "ながら", "is_correct": false, "explanation": "「ながら」は動詞の連用形に付き、名詞には付きません。"}], "correct_answer": "ほど", "explanations": {"ほど": "「細かいプリントほど」で程度に比例する意味になります。", "へ": "「へ」は方向を表し、ここでは文が成り立ちません。", "ので": "名詞に直接「ので」は付けられず（「なので」が必要）、不適切です。", "ながら": "「ながら」は動詞の連用形に付き、名詞には付きません。"}, "error_tags": {"へ": "direction", "ので": "reason", "ながら": "simultaneous"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51844, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "印刷（いんさつ）のこと。特に、布や紙に模様や文字を転写する技術やその結果できたもの。", "primary_collocate": null, "pronunciation": "ぷりんと", "ipa": "puɾinto", "syllable_count": 4, "sentences": [{"text": "このシャツは、色を少なくしたプリントがおしゃれだ。", "target_word": "プリント", "complexity_tier": "T4", "furigana": "このシャツは、色[いろ]を少[すく]なくしたプリントがおしゃれだ。", "sentence_source": "generated"}, {"text": "このスカーフのプリントは、花の模様です。", "target_word": "プリント", "complexity_tier": "T3", "furigana": "このスカーフのプリントは、花[はな]の模様[もよう]です。", "sentence_source": "generated"}, {"text": "夏はプリントのシャツを着る人が多い。", "target_word": "プリント", "complexity_tier": "T3", "furigana": "夏[なつ]はプリントのシャツを着[き]る人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "布にプリントを入れる作業を見学した。", "target_word": "プリント", "complexity_tier": "T3", "furigana": "布[ぬの]にプリントを入[い]れる作業[さぎょう]を見学[けんがく]した。", "sentence_source": "generated"}, {"text": "古い布のプリントが、洗濯で少し薄くなった。", "target_word": "プリント", "complexity_tier": "T3", "furigana": "古[ふる]い布[ぬの]のプリントが、洗濯[せんたく]で少[すこ]し薄[うす]くなった。", "sentence_source": "generated"}, {"text": "美術館で、昔の布のプリントを見ました。", "target_word": "プリント", "complexity_tier": "T3", "furigana": "美術館[びじゅつかん]で、昔[むかし]の布[ぬの]のプリントを見[み]ました。", "sentence_source": "generated"}, {"text": "このプリントは、手作業でひとつずつ仕上げています。", "target_word": "プリント", "complexity_tier": "T4", "furigana": "このプリントは、手作業[てさぎょう]でひとつずつ仕上[しあ]げています。", "sentence_source": "generated"}, {"text": "色が細かいプリントほど、作るのに時間がかかる。", "target_word": "プリント", "complexity_tier": "T4", "furigana": "色[いろ]が細[こま]かいプリントほど、作[つく]るのに時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "彼女は、動物のプリントがついた靴下を選んだ。", "target_word": "プリント", "complexity_tier": "T4", "furigana": "彼女[かのじょ]は、動物[どうぶつ]のプリントがついた靴下[くつした]を選[えら]んだ。", "sentence_source": "generated"}, {"text": "版を替えるだけで、同じ絵から別のプリントが作れる。", "target_word": "プリント", "complexity_tier": "T4", "furigana": "版[はん]を替[か]えるだけで、同[おな]じ絵[え]から別[べつ]のプリントが作[つく]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "プリントする", "label": "派生"}, {"form": "プリントされる", "label": "派生"}, {"form": "プリントアウト", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 布や紙に模様を写す技法とその作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bb56fb5-a3aa-427f-85df-afbf4101a571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51844, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "プリント", "is_correct": true, "explanation": "聞いた語そのもので、正解です。"}, {"text": "プラント", "is_correct": false, "explanation": "「リ」が「ラ」に変わった別の語（工場設備）です。"}, {"text": "プリンタ", "is_correct": false, "explanation": "最後の「ト」が「タ」に変わった別の語（印刷機）です。"}, {"text": "プリンス", "is_correct": false, "explanation": "最後の「ト」が「ス」に変わった別の語（王子）です。"}], "explanations": {"プリント": "聞いた語そのもので、正解です。", "プラント": "「リ」が「ラ」に変わった別の語（工場設備）です。", "プリンタ": "最後の「ト」が「タ」に変わった別の語（印刷機）です。", "プリンス": "最後の「ト」が「ス」に変わった別の語（王子）です。"}, "sentence_index": null, "correct_answer": "プリント"}, "level_3": {"options": [{"text": "プリント", "is_correct": true, "explanation": "シャツの模様として、色を少なくしたプリントがおしゃれだという意味で合います。"}, {"text": "作曲", "is_correct": false, "explanation": "形は合うが意味が合わない。作曲はシャツの見た目ではありません。"}, {"text": "録音", "is_correct": false, "explanation": "形は合うが意味が合わない。録音はシャツについているものではありません。"}, {"text": "水泳", "is_correct": false, "explanation": "形は合うが意味が合わない。水泳はシャツの模様ではありません。"}], "explanations": {"プリント": "シャツの模様として、色を少なくしたプリントがおしゃれだという意味で合います。", "作曲": "形は合うが意味が合わない。作曲はシャツの見た目ではありません。", "録音": "形は合うが意味が合わない。録音はシャツについているものではありません。", "水泳": "形は合うが意味が合わない。水泳はシャツの模様ではありません。"}, "sentence_index": 0, "correct_answer": "プリント"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんに、花のプリントを食べました。", "explanation": "プリントは模様の転写や作品で、食べ物ではないので「食べる」の目的語になりません。"}, {"text": "このシャツのプリントは、とても高い声で鳴いている。", "explanation": "プリントは模様のことで、生き物のように鳴くことはありません。"}, {"text": "雨の日に、プリントが空から降ってきた。", "explanation": "プリントは天気のように空から降るものではなく、主語として意味が合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51844, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "プリント", "is_correct": true, "explanation": "聞いた語そのもので、正解です。"}, {"text": "フリント", "is_correct": false, "explanation": "最初の「プ」が「フ」に変わった別の語（火打ち石）です。"}, {"text": "プリン", "is_correct": false, "explanation": "最後の「ト」がない別の語（お菓子）です。"}, {"text": "プリンタ", "is_correct": false, "explanation": "最後の「ト」が「タ」に変わった別の語です。"}], "explanations": {"プリント": "聞いた語そのもので、正解です。", "フリント": "最初の「プ」が「フ」に変わった別の語（火打ち石）です。", "プリン": "最後の「ト」がない別の語（お菓子）です。", "プリンタ": "最後の「ト」が「タ」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "プリント"}, "level_3": {"options": [{"text": "プリント", "is_correct": true, "explanation": "手作業で仕上げる模様の作品として意味が合います。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は手作業で仕上げられません。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。季節は手作業で仕上げるものではありません。"}, {"text": "景色", "is_correct": false, "explanation": "形は合うが意味が合わない。景色を一つずつ仕上げることはありません。"}], "explanations": {"プリント": "手作業で仕上げる模様の作品として意味が合います。", "天気": "形は合うが意味が合わない。天気は手作業で仕上げられません。", "季節": "形は合うが意味が合わない。季節は手作業で仕上げるものではありません。", "景色": "形は合うが意味が合わない。景色を一つずつ仕上げることはありません。"}, "sentence_index": 6, "correct_answer": "プリント"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "プリントを三匹、庭で飼っています。", "explanation": "プリントは模様のことで、動物ではないので飼えず「匹」でも数えません。"}, {"text": "この布のプリントは、毎日歩いて学校へ行く。", "explanation": "プリントは模様で、歩いて学校へ行く動作の主語になれません。"}, {"text": "夕食に、きれいなプリントを焼いて食べた。", "explanation": "プリントは食材ではないので、焼いて食べることはできません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_war