INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51845, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "色がうすくなること。", "primary_collocate": null, "pronunciation": "あせる", "ipa": "aseɾɯ", "syllable_count": 3, "sentences": [{"text": "古い服の色が褪せました。", "target_word": "褪せました", "complexity_tier": "T2", "furigana": "古[ふる]い服[ふく]の色[いろ]が褪[あ]せました。", "sentence_source": "generated"}, {"text": "この花の色は褪せません。", "target_word": "褪せません", "complexity_tier": "T2", "furigana": "この花[はな]の色[いろ]は褪[あ]せません。", "sentence_source": "generated"}, {"text": "日光で、ポスターが褪せた。", "target_word": "褪せた", "complexity_tier": "T3", "furigana": "日光[にっこう]で、ポスターが褪[あ]せた。", "sentence_source": "generated"}, {"text": "赤い旗の色が、少し褪せてきました。", "target_word": "褪せて", "complexity_tier": "T3", "furigana": "赤[あか]い旗[はた]の色[いろ]が、少[すこ]し褪[あ]せてきました。", "sentence_source": "generated"}, {"text": "褪せた青いかばんを、まだ使っています。", "target_word": "褪せた", "complexity_tier": "T3", "furigana": "褪[あ]せた青[あお]いかばんを、まだ使[つか]っています。", "sentence_source": "generated"}, {"text": "洗うたびに、シャツの色が褪せる。", "target_word": "褪せる", "complexity_tier": "T3", "furigana": "洗[あら]うたびに、シャツの色[いろ]が褪[あ]せる。", "sentence_source": "generated"}, {"text": "外に置いた木の板は、すぐ色が褪せてしまう。", "target_word": "褪せて", "complexity_tier": "T3", "furigana": "外[そと]に置[お]いた木[き]の板[いた]は、すぐ色[いろ]が褪[あ]せてしまう。", "sentence_source": "generated"}, {"text": "色が褪せないように、絵を暗い部屋に置いた。", "target_word": "褪せない", "complexity_tier": "T3", "furigana": "色[いろ]が褪[あ]せないように、絵[え]を暗[くら]い部屋[へや]に置[お]いた。", "sentence_source": "generated"}, {"text": "長い間、窓のそばに置くと、本の表紙も褪せる。", "target_word": "褪せる", "complexity_tier": "T3", "furigana": "長[なが]い間[あいだ]、窓[まど]のそばに置[お]くと、本[ほん]の表紙[ひょうし]も褪[あ]せる。", "sentence_source": "generated"}, {"text": "色が褪せれば、新しい布に取り替えるつもりです。", "target_word": "褪せれば", "complexity_tier": "T4", "furigana": "色[いろ]が褪[あ]せれば、新[あたら]しい布[ぬの]に取[と]り替[か]えるつもりです。", "sentence_source": "generated"}], "morphological_forms": [{"form": "褪せた", "label": "活用"}, {"form": "褪せて", "label": "活用"}, {"form": "褪せない", "label": "活用"}, {"form": "褪せます", "label": "活用"}, {"form": "褪せれば", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 時間がたって色が薄くなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bb56fb5-a3aa-427f-85df-afbf4101a571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51845, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "褪せる", "is_correct": true, "explanation": "聞いた語そのもので、正解です。"}, {"text": "痩せる", "is_correct": false, "explanation": "「あ」が「や」に変わった別の語です。"}, {"text": "伏せる", "is_correct": false, "explanation": "「あ」が「ふ」に変わった別の語です。"}, {"text": "開ける", "is_correct": false, "explanation": "「せ」が「け」に変わった別の語です。"}], "explanations": {"褪せる": "聞いた語そのもので、正解です。", "痩せる": "「あ」が「や」に変わった別の語です。", "伏せる": "「あ」が「ふ」に変わった別の語です。", "開ける": "「せ」が「け」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "褪せる"}, "level_3": {"options": [{"text": "褪せました", "is_correct": true, "explanation": "古い服の色が薄くなったという意味で合います。"}, {"text": "笑いました", "is_correct": false, "explanation": "形は合うが意味が合わない。色は笑いません。"}, {"text": "走りました", "is_correct": false, "explanation": "形は合うが意味が合わない。色は走りません。"}, {"text": "閉まりました", "is_correct": false, "explanation": "形は合うが意味が合わない。色は閉まりません。"}], "explanations": {"褪せました": "古い服の色が薄くなったという意味で合います。", "笑いました": "形は合うが意味が合わない。色は笑いません。", "走りました": "形は合うが意味が合わない。色は走りません。", "閉まりました": "形は合うが意味が合わない。色は閉まりません。"}, "sentence_index": 0, "correct_answer": "褪せました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達が部屋で静かに褪せている。", "explanation": "「褪せる」は物の色に使い、人の動作には使えません。"}, {"text": "水が褪せて、冷たくなった。", "explanation": "「褪せる」は色が薄くなることで、温度の変化には使えません。"}, {"text": "新しいくつを褪せて、会社に行った。", "explanation": "「褪せる」は自動詞で、くつを目的語にして身につける意味にはなりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51845, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "褪せる", "is_correct": true, "explanation": "聞いた語そのもので、正解です。"}, {"text": "押せる", "is_correct": false, "explanation": "「あ」が「お」に変わった別の語です。"}, {"text": "貸せる", "is_correct": false, "explanation": "「あ」が「か」に変わった別の語です。"}, {"text": "ませる", "is_correct": false, "explanation": "「あ」が「ま」に変わった別の語です。"}], "explanations": {"褪せる": "聞いた語そのもので、正解です。", "押せる": "「あ」が「お」に変わった別の語です。", "貸せる": "「あ」が「か」に変わった別の語です。", "ませる": "「あ」が「ま」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "褪せる"}, "level_3": {"options": [{"text": "褪せて", "is_correct": true, "explanation": "「しまう」に続いて、色が薄くなることを表します。"}, {"text": "笑って", "is_correct": false, "explanation": "形は合うが意味が合わない。板の色が笑うことはありません。"}, {"text": "走って", "is_correct": false, "explanation": "形は合うが意味が合わない。色は走りません。"}, {"text": "閉まって", "is_correct": false, "explanation": "形は合うが意味が合わない。色は閉まりません。"}], "explanations": {"褪せて": "「しまう」に続いて、色が薄くなることを表します。", "笑って": "形は合うが意味が合わない。板の色が笑うことはありません。", "走って": "形は合うが意味が合わない。色は走りません。", "閉まって": "形は合うが意味が合わない。色は閉まりません。"}, "sentence_index": 6, "correct_answer": "褪せて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が降ったあとで、空が高く褪せた。", "explanation": "「褪せる」は色が薄くなることで、空の高さには使えません。"}, {"text": "お茶を褪せたら、砂糖を入れます。", "explanation": "「褪せる」は自動詞で、お茶を作る意味の他動詞としては使えません。"}, {"text": "重い荷物が褪せて、二階に運んだ。", "explanation": "荷物の重さや位置の変化を、色が薄くなることとして表せません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51845, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "洗ったら、シャツの色を褪せました。", "corrected_sentence": "洗ったら、シャツの色が褪せました。", "error_description": "自動詞「褪せる」には、主体を示す「が」を使う。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "褪せません", "is_correct": true, "explanation": "丁寧な否定形で、文末に合います。"}, {"text": "褪せて", "is_correct": false, "explanation": "て形は文を終わらせられず、ここでは合いません。"}, {"text": "褪せれば", "is_correct": false, "explanation": "仮定形で文を終えることはできません。"}, {"text": "褪せろ", "is_correct": false, "explanation": "命令形で、色には使えず意味が合いません。"}], "correct_form": "褪せません", "base_form": "褪せる", "form_label": "丁寧否定形", "sentence_index": 1, "explanations": {"褪せません": "丁寧な否定形で、文末に合います。", "褪せて": "て形は文を終わらせられず、ここでは合いません。", "褪せれば": "仮定形で文を終えることはできません。", "褪せろ": "命令形で、色には使えず意味が合いません。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
