INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51846, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「色が褪せた」と、褪せる主体を示します。"}, {"text": "を", "is_correct": false, "explanation": "「褪せる」は自動詞なので「色を褪せた」とは言えません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、主体を示せません。"}, {"text": "と", "is_correct": false, "explanation": "「色と褪せた」では主体が示されず、文が成り立ちません。"}], "correct_answer": "が", "explanations": {"が": "「色が褪せた」と、褪せる主体を示します。", "を": "「褪せる」は自動詞なので「色を褪せた」とは言えません。", "へ": "「へ」は方向を表し、主体を示せません。", "と": "「色と褪せた」では主体が示されず、文が成り立ちません。"}, "error_tags": {"を": "object", "へ": "direction", "と": "quotation/with"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "色づく", "is_correct": true, "explanation": "色が付いて濃くなる意味で、「褪せる」の反対です。"}, {"text": "凍る", "is_correct": false, "explanation": "温度が下がる意味で、「褪せる」の反対ではありません。"}, {"text": "乾く", "is_correct": false, "explanation": "水分がなくなる意味で、反対の関係ではありません。"}, {"text": "流れる", "is_correct": false, "explanation": "動いて移る意味で、反対の関係ではありません。"}], "correct_answer": "色づく", "explanations": {"色づく": "色が付いて濃くなる意味で、「褪せる」の反対です。", "凍る": "温度が下がる意味で、「褪せる」の反対ではありません。", "乾く": "水分がなくなる意味で、反対の関係ではありません。", "流れる": "動いて移る意味で、反対の関係ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
