INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51846, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "色や光沢が時間とともに薄くなる。また、記憶などが薄れる。", "primary_collocate": null, "pronunciation": "あせる", "ipa": "aseɾɯ", "syllable_count": 3, "sentences": [{"text": "あの夏の褪せた記憶を、ときどき思い出す。", "target_word": "褪せた", "complexity_tier": "T4", "furigana": "あの夏[なつ]の褪[あ]せた記憶[きおく]を、ときどき思[おも]い出[だ]す。", "sentence_source": "generated"}, {"text": "色が褪せた写真を、そっと棚に戻した。", "target_word": "褪せた", "complexity_tier": "T3", "furigana": "色[いろ]が褪[あ]せた写真[しゃしん]を、そっと棚[たな]に戻[もど]した。", "sentence_source": "generated"}, {"text": "日に当たると、カーテンの色が褪せる。", "target_word": "褪せる", "complexity_tier": "T3", "furigana": "日[ひ]に当[あ]たると、カーテンの色[いろ]が褪[あ]せる。", "sentence_source": "generated"}, {"text": "この青いシャツは、洗っても褪せません。", "target_word": "褪せません", "complexity_tier": "T3", "furigana": "この青[あお]いシャツは、洗[あら]っても褪[あ]せません。", "sentence_source": "generated"}, {"text": "時間がたっても、あの日の思い出は褪せない。", "target_word": "褪せない", "complexity_tier": "T3", "furigana": "時間[じかん]がたっても、あの日[ひ]の思[おも]い出[で]は褪[あ]せない。", "sentence_source": "generated"}, {"text": "看板の赤い文字が、だんだん褪せてきた。", "target_word": "褪せて", "complexity_tier": "T3", "furigana": "看板[かんばん]の赤[あか]い文字[もじ]が、だんだん褪[あ]せてきた。", "sentence_source": "generated"}, {"text": "褪せた壁の色を、きれいに塗り直しました。", "target_word": "褪せた", "complexity_tier": "T3", "furigana": "褪[あ]せた壁[かべ]の色[いろ]を、きれいに塗[ぬ]り直[なお]しました。", "sentence_source": "generated"}, {"text": "古い布は、使うほど色が褪せていくものだ。", "target_word": "褪せて", "complexity_tier": "T3", "furigana": "古[ふる]い布[ぬの]は、使[つか]うほど色[いろ]が褪[あ]せていくものだ。", "sentence_source": "generated"}, {"text": "年をとっても、あの感動は褪せることがなかった。", "target_word": "褪せる", "complexity_tier": "T4", "furigana": "年[とし]をとっても、あの感動[かんどう]は褪[あ]せることがなかった。", "sentence_source": "generated"}, {"text": "褪せない染料を使えば、作品は長く美しいままだ。", "target_word": "褪せない", "complexity_tier": "T4", "furigana": "褪[あ]せない染料[せんりょう]を使[つか]えば、作品[さくひん]は長[なが]く美[うつく]しいままだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "褪せた", "label": "活用"}, {"form": "褪せて", "label": "活用"}, {"form": "褪せない", "label": "活用"}, {"form": "褪せます", "label": "活用"}, {"form": "褪せれば", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 色や記憶が時間とともに薄くなる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bb56fb5-a3aa-427f-85df-afbf4101a571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51846, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "褪せる", "is_correct": true, "explanation": "聞いた語そのもので、正解です。"}, {"text": "痩せる", "is_correct": false, "explanation": "最初の「あ」が「や」に変わった別の語です。"}, {"text": "伏せる", "is_correct": false, "explanation": "最初の「あ」が「ふ」に変わった別の語です。"}, {"text": "開ける", "is_correct": false, "explanation": "「せ」が「け」に変わった別の語です。"}, {"text": "和える", "is_correct": false, "explanation": "「せ」が「え」に変わった別の語です。"}], "explanations": {"褪せる": "聞いた語そのもので、正解です。", "痩せる": "最初の「あ」が「や」に変わった別の語です。", "伏せる": "最初の「あ」が「ふ」に変わった別の語です。", "開ける": "「せ」が「け」に変わった別の語です。", "和える": "「せ」が「え」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "褪せる"}, "level_3": {"options": [{"text": "褪せた", "is_correct": true, "explanation": "薄れた記憶を表し、意味が合います。"}, {"text": "光った", "is_correct": false, "explanation": "形は合うが意味が合わない。「光った記憶」では薄れた記憶になりません。"}, {"text": "割れた", "is_correct": false, "explanation": "形は合うが意味が合わない。記憶が割れるのは意味が合いません。"}, {"text": "曲がった", "is_correct": false, "explanation": "形は合うが意味が合わない。記憶には曲がるという性質がありません。"}], "explanations": {"褪せた": "薄れた記憶を表し、意味が合います。", "光った": "形は合うが意味が合わない。「光った記憶」では薄れた記憶になりません。", "割れた": "形は合うが意味が合わない。記憶が割れるのは意味が合いません。", "曲がった": "形は合うが意味が合わない。記憶には曲がるという性質がありません。"}, "sentence_index": 0, "correct_answer": "褪せた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お湯が褪せるまで、少し待ちます。", "explanation": "「褪せる」は色や記憶が薄れることで、お湯の温度には使えません。"}, {"text": "ケーキが褪せて、とてもおいしくなった。", "explanation": "「褪せる」は色や記憶が薄れることで、ケーキの味がよくなることには使えません。"}, {"text": "雨が褪せて、道がぬれた。", "explanation": "雨は色や記憶ではなく、褪せるの主語になりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51846, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "褪せる", "is_correct": true, "explanation": "聞いた語そのもので、正解です。"}, {"text": "押せる", "is_correct": false, "explanation": "最初の「あ」が「お」に変わった別の語です。"}, {"text": "貸せる", "is_correct": false, "explanation": "最初の「あ」が「か」に変わった別の語です。"}, {"text": "ませる", "is_correct": false, "explanation": "最初の「あ」が「ま」に変わった別の語です。"}, {"text": "当たる", "is_correct": false, "explanation": "「せ」が「た」に変わった別の語です。"}], "explanations": {"褪せる": "聞いた語そのもので、正解です。", "押せる": "最初の「あ」が「お」に変わった別の語です。", "貸せる": "最初の「あ」が「か」に変わった別の語です。", "ませる": "最初の「あ」が「ま」に変わった別の語です。", "当たる": "「せ」が「た」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "褪せる"}, "level_3": {"options": [{"text": "褪せた", "is_correct": true, "explanation": "壁の色が薄くなった状態を表し、意味が合います。"}, {"text": "揺れた", "is_correct": false, "explanation": "形は合うが意味が合わない。壁の色が揺れるという言い方は合いません。"}, {"text": "走った", "is_correct": false, "explanation": "形は合うが意味が合わない。壁は走りません。"}, {"text": "笑った", "is_correct": false, "explanation": "形は合うが意味が合わない。壁は笑いません。"}], "explanations": {"褪せた": "壁の色が薄くなった状態を表し、意味が合います。", "揺れた": "形は合うが意味が合わない。壁の色が揺れるという言い方は合いません。", "走った": "形は合うが意味が合わない。壁は走りません。", "笑った": "形は合うが意味が合わない。壁は笑いません。"}, "sentence_index": 6, "correct_answer": "褪せた"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎日走ったので、足がだんだん褪せてきた。", "explanation": "「褪せる」は色や記憶に使い、足の疲れには使えません。"}, {"text": "スープを褪せたら、塩を入れてください。", "explanation": "「褪せる」は自動詞で、料理をする動作の他動詞としては使えません。"}, {"text": "犬が庭で元気に褪せている。", "explanation": "犬の動作を表す語ではないので、生き物の様子には使えません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDE