INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51847, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "お店で売っているものです。例えば、おもちゃやTシャツなどです。", "primary_collocate": null, "pronunciation": "ぐっず", "ipa": "ɡɯzzɯ", "syllable_count": 3, "sentences": [{"text": "この店には、かわいいグッズがあります。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "この店[みせ]には、かわいいグッズがあります。", "sentence_source": "generated"}, {"text": "グッズは、二階で売っています。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "グッズは、二階[にかい]で売[う]っています。", "sentence_source": "generated"}, {"text": "弟はアニメのグッズを買いました。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "弟[おとうと]はアニメのグッズを買[か]いました。", "sentence_source": "generated"}, {"text": "私はねこのグッズが欲しいです。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "私[わたし]はねこのグッズが欲[ほ]しいです。", "sentence_source": "generated"}, {"text": "動物園で、パンダのグッズを買った。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]で、パンダのグッズを買[か]った。", "sentence_source": "generated"}, {"text": "このグッズは、いくらですか。", "target_word": "グッズ", "complexity_tier": "T2", "furigana": "このグッズは、いくらですか。", "sentence_source": "generated"}, {"text": "店の入り口に、新しいグッズが並んでいます。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "店[みせ]の入[い]り口[ぐち]に、新[あたら]しいグッズが並[なら]んでいます。", "sentence_source": "generated"}, {"text": "祖母に、かわいいグッズを送ってあげたい。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "祖母[そぼ]に、かわいいグッズを送[おく]ってあげたい。", "sentence_source": "generated"}, {"text": "グッズを選ぶのは、楽しい時間です。", "target_word": "グッズ", "complexity_tier": "T2", "furigana": "グッズを選[えら]ぶのは、楽[たの]しい時間[じかん]です。", "sentence_source": "generated"}, {"text": "友だちと、お店でグッズを見てから、昼ごはんを食べた。", "target_word": "グッズ", "complexity_tier": "T4", "furigana": "友[とも]だちと、お店[みせ]でグッズを見[み]てから、昼[ひる]ごはんを食[た]べた。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | お店で売っているおもちゃや服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bb56fb5-a3aa-427f-85df-afbf4101a571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51847, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "グッズ", "is_correct": true, "explanation": "見出し語の「ぐっず」で、音声と一致します。"}, {"text": "グッド", "is_correct": false, "explanation": "「ぐっど」で、最後の「ず」が「ど」に変わった別の語です。"}, {"text": "ぐっと", "is_correct": false, "explanation": "「ぐっと」で、最後の「ず」が「と」に変わった別の語（副詞）です。"}, {"text": "ゴッズ", "is_correct": false, "explanation": "「ごっず」で、最初の「ぐ」が「ご」に変わった別の語です。"}], "explanations": {"グッズ": "見出し語の「ぐっず」で、音声と一致します。", "グッド": "「ぐっど」で、最後の「ず」が「ど」に変わった別の語です。", "ぐっと": "「ぐっと」で、最後の「ず」が「と」に変わった別の語（副詞）です。", "ゴッズ": "「ごっず」で、最初の「ぐ」が「ご」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "グッズ"}, "level_3": {"options": [{"text": "グッズ", "is_correct": true, "explanation": "お店にあるかわいい商品なので、意味が合います。"}, {"text": "歴史", "is_correct": false, "explanation": "形は合うが意味が合わない。かわいい歴史が店にあるとは言いません。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は店にあるものではありません。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが意味が合わない。季節は店の中にありません。"}], "explanations": {"グッズ": "お店にあるかわいい商品なので、意味が合います。", "歴史": "形は合うが意味が合わない。かわいい歴史が店にあるとは言いません。", "天気": "形は合うが意味が合わない。天気は店にあるものではありません。", "季節": "形は合うが意味が合わない。季節は店の中にありません。"}, "sentence_index": 0, "correct_answer": "グッズ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "グッズを食べて、おなかがいっぱいになりました。", "explanation": "グッズはおもちゃや服などの商品で、食べ物ではないので「食べる」と合いません。"}, {"text": "私のグッズは、高校の先生です。", "explanation": "人である先生をグッズと言うのは、商品という意味と合いません。"}, {"text": "駅の前で、グッズが走っています。", "explanation": "グッズは売り物で、自分で走るものではないので意味が合いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51847, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "グッズ", "is_correct": true, "explanation": "見出し語の「ぐっず」で、音声と一致します。"}, {"text": "キッズ", "is_correct": false, "explanation": "「きっず」で、最初の「ぐ」が「き」に変わっています。"}, {"text": "グース", "is_correct": false, "explanation": "「ぐーす」で、促音「っ」が長音「ー」に、「ず」が「す」に変わった別の語（ガチョウ）です。"}, {"text": "ガッツ", "is_correct": false, "explanation": "「がっつ」で、「ぐ」が「が」に、「ず」が「つ」に変わった別の語です。"}], "explanations": {"グッズ": "見出し語の「ぐっず」で、音声と一致します。", "キッズ": "「きっず」で、最初の「ぐ」が「き」に変わっています。", "グース": "「ぐーす」で、促音「っ」が長音「ー」に、「ず」が「す」に変わった別の語（ガチョウ）です。", "ガッツ": "「がっつ」で、「ぐ」が「が」に、「ず」が「つ」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "グッズ"}, "level_3": {"options": [{"text": "グッズ", "is_correct": true, "explanation": "店の入り口に並ぶ新しい商品なので、意味が合います。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気は店に並びません。"}, {"text": "気持ち", "is_correct": false, "explanation": "形は合うが意味が合わない。気持ちは入り口に並ぶものではありません。"}, {"text": "歌", "is_correct": false, "explanation": "形は合うが意味が合わない。歌は店の入り口に並べられません。"}], "explanations": {"グッズ": "店の入り口に並ぶ新しい商品なので、意味が合います。", "天気": "形は合うが意味が合わない。天気は店に並びません。", "気持ち": "形は合うが意味が合わない。気持ちは入り口に並ぶものではありません。", "歌": "形は合うが意味が合わない。歌は店の入り口に並べられません。"}, "sentence_index": 6, "correct_answer": "グッズ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日、グッズに乗って、海へ行きました。", "explanation": "グッズは売り物で、乗り物ではないので「乗る」と合いません。"}, {"text": "この川のグッズは、とても冷たくてきれいです。", "explanation": "水の様子を言う場面でグッズは使えず、意味が合いません。"}, {"text": "兄はグッズを泳ぐのが上手です。", "explanation": "グッズは泳ぐ場所ではないので、「を泳ぐ」の対象にはなりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_er