INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51848, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "特定のブランドやイベントに関連して販売される商品。特にファン向けの記念品や雑貨。", "primary_collocate": null, "pronunciation": "ぐっず", "ipa": "ɡɯzzɯ", "syllable_count": 3, "sentences": [{"text": "このTシャツは、ライブで買ったグッズです。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "このTシャツは、ライブで買[か]ったグッズです。", "sentence_source": "generated"}, {"text": "好きな歌手のグッズを集めています。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "好[す]きな歌手[かしゅ]のグッズを集[あつ]めています。", "sentence_source": "generated"}, {"text": "会場では、限定のグッズが売られていた。", "target_word": "グッズ", "complexity_tier": "T4", "furigana": "会場[かいじょう]では、限定[げんてい]のグッズが売[う]られていた。", "sentence_source": "generated"}, {"text": "映画のグッズは、すぐに売り切れました。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "映画[えいが]のグッズは、すぐに売[う]り切[き]れました。", "sentence_source": "generated"}, {"text": "このカフェには、猫のグッズがたくさんある。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "このカフェには、猫[ねこ]のグッズがたくさんある。", "sentence_source": "generated"}, {"text": "姉はライブに行くたびに、グッズを買ってくる。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "姉[あね]はライブに行[い]くたびに、グッズを買[か]ってくる。", "sentence_source": "generated"}, {"text": "人気のグッズを買うために、朝早くから並んだ。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "人気[にんき]のグッズを買[か]うために、朝[あさ]早[はや]くから並[なら]んだ。", "sentence_source": "generated"}, {"text": "手作りのグッズなら、世界に一つだけの特別な記念になる。", "target_word": "グッズ", "complexity_tier": "T4", "furigana": "手作[てづく]りのグッズなら、世界[せかい]に一[ひと]つだけの特別[とくべつ]な記念[きねん]になる。", "sentence_source": "generated"}, {"text": "彼はグッズの収益を、地域の活動に寄付した。", "target_word": "グッズ", "complexity_tier": "T3", "furigana": "彼[かれ]はグッズの収益[しゅうえき]を、地域[ちいき]の活動[かつどう]に寄付[きふ]した。", "sentence_source": "generated"}, {"text": "ファンの中には、公式のグッズしか買わない人もいる。", "target_word": "グッズ", "complexity_tier": "T4", "furigana": "ファンの中[なか]には、公式[こうしき]のグッズしか買[か]わない人[ひと]もいる。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | ファン向けの記念品や雑貨の商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bb56fb5-a3aa-427f-85df-afbf4101a571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51848, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "グッズ", "is_correct": true, "explanation": "見出し語の「ぐっず」で、音声と一致します。"}, {"text": "グッド", "is_correct": false, "explanation": "「ぐっど」で、最後の「ず」が「ど」に変わった別の語です。"}, {"text": "ぐっと", "is_correct": false, "explanation": "「ぐっと」で、最後の「ず」が「と」に変わった別の語（副詞）です。"}, {"text": "ゴッズ", "is_correct": false, "explanation": "「ごっず」で、最初の「ぐ」が「ご」に変わった別の語です。"}], "explanations": {"グッズ": "見出し語の「ぐっず」で、音声と一致します。", "グッド": "「ぐっど」で、最後の「ず」が「ど」に変わった別の語です。", "ぐっと": "「ぐっと」で、最後の「ず」が「と」に変わった別の語（副詞）です。", "ゴッズ": "「ごっず」で、最初の「ぐ」が「ご」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "グッズ"}, "level_3": {"options": [{"text": "グッズ", "is_correct": true, "explanation": "ライブで買ったTシャツはファン向けの商品なので、意味が合います。"}, {"text": "ゲーム", "is_correct": false, "explanation": "形は合うが意味が合わない。Tシャツはゲームではありません。"}, {"text": "ルール", "is_correct": false, "explanation": "形は合うが意味が合わない。Tシャツをルールとは言いません。"}, {"text": "ニュース", "is_correct": false, "explanation": "形は合うが意味が合わない。Tシャツはニュースではありません。"}], "explanations": {"グッズ": "ライブで買ったTシャツはファン向けの商品なので、意味が合います。", "ゲーム": "形は合うが意味が合わない。Tシャツはゲームではありません。", "ルール": "形は合うが意味が合わない。Tシャツをルールとは言いません。", "ニュース": "形は合うが意味が合わない。Tシャツはニュースではありません。"}, "sentence_index": 0, "correct_answer": "グッズ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "グッズを飲んで、体が元気になりました。", "explanation": "グッズは売られる商品で、飲み物ではないので「飲む」と合いません。"}, {"text": "グッズは、毎朝七時に起きます。", "explanation": "グッズは物なので、人のように「起きる」の主語にはなれません。"}, {"text": "東京は、日本のグッズです。", "explanation": "都市である東京を、ファン向けの商品であるグッズと言うのは意味の誤用です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51848, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "グッズ", "is_correct": true, "explanation": "見出し語の「ぐっず」で、音声と一致します。"}, {"text": "キッズ", "is_correct": false, "explanation": "「きっず」で、最初の「ぐ」が「き」に変わっています。"}, {"text": "グース", "is_correct": false, "explanation": "「ぐーす」で、促音「っ」が長音「ー」に、「ず」が「す」に変わった別の語（ガチョウ）です。"}, {"text": "ガッツ", "is_correct": false, "explanation": "「がっつ」で、「ぐ」が「が」に、「ず」が「つ」に変わった別の語です。"}], "explanations": {"グッズ": "見出し語の「ぐっず」で、音声と一致します。", "キッズ": "「きっず」で、最初の「ぐ」が「き」に変わっています。", "グース": "「ぐーす」で、促音「っ」が長音「ー」に、「ず」が「す」に変わった別の語（ガチョウ）です。", "ガッツ": "「がっつ」で、「ぐ」が「が」に、「ず」が「つ」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "グッズ"}, "level_3": {"options": [{"text": "グッズ", "is_correct": true, "explanation": "人気の商品を買うために並ぶので、意味が合います。"}, {"text": "ニュース", "is_correct": false, "explanation": "形は合うが意味が合わない。ニュースは並んで買うものではありません。"}, {"text": "歌", "is_correct": false, "explanation": "形は合うが意味が合わない。歌を買うために朝から並ぶ文脈ではありません。"}, {"text": "景色", "is_correct": false, "explanation": "形は合うが意味が合わない。景色は買えません。"}], "explanations": {"グッズ": "人気の商品を買うために並ぶので、意味が合います。", "ニュース": "形は合うが意味が合わない。ニュースは並んで買うものではありません。", "歌": "形は合うが意味が合わない。歌を買うために朝から並ぶ文脈ではありません。", "景色": "形は合うが意味が合わない。景色は買えません。"}, "sentence_index": 6, "correct_answer": "グッズ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨日の試合は、とても大きなグッズでした。", "explanation": "試合という出来事をグッズと呼ぶのは、商品という意味から外れています。"}, {"text": "この山の頂上からは、美しいグッズが見える。", "explanation": "景色を指す場面でグッズは使えず、意味が合いません。"}, {"text": "彼女はグッズを歌って、みんなを楽しませた。", "explanation": "グッズは商品で歌えるものではないので、「歌う」の目的語になりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
