INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51849, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分が生まれた場所や、家族の始まりのこと。", "primary_collocate": null, "pronunciation": "るーつ", "ipa": "ɾɯːtsɯ", "syllable_count": 3, "sentences": [{"text": "私のルーツは、九州です。", "target_word": "ルーツ", "complexity_tier": "T2", "furigana": "私[わたし]のルーツは、九州[きゅうしゅう]です。", "sentence_source": "generated"}, {"text": "母のルーツは、小さな島です。", "target_word": "ルーツ", "complexity_tier": "T2", "furigana": "母[はは]のルーツは、小[ちい]さな島[しま]です。", "sentence_source": "generated"}, {"text": "家族のルーツを調べました。", "target_word": "ルーツ", "complexity_tier": "T2", "furigana": "家族[かぞく]のルーツを調[しら]べました。", "sentence_source": "generated"}, {"text": "先生は、自分のルーツについて話してくれた。", "target_word": "ルーツ", "complexity_tier": "T3", "furigana": "先生[せんせい]は、自分[じぶん]のルーツについて話[はな]してくれた。", "sentence_source": "generated"}, {"text": "ルーツを知りたくて、祖母に聞いてみた。", "target_word": "ルーツ", "complexity_tier": "T3", "furigana": "ルーツを知[し]りたくて、祖母[そぼ]に聞[き]いてみた。", "sentence_source": "generated"}, {"text": "私たちのルーツは、同じ村にあるそうです。", "target_word": "ルーツ", "complexity_tier": "T3", "furigana": "私[わたし]たちのルーツは、同[おな]じ村[むら]にあるそうです。", "sentence_source": "generated"}, {"text": "父は、ルーツのある町を、久しぶりに訪れた。", "target_word": "ルーツ", "complexity_tier": "T3", "furigana": "父[ちち]は、ルーツのある町[まち]を、久[ひさ]しぶりに訪[おとず]れた。", "sentence_source": "generated"}, {"text": "家のルーツをたどると、昔は農家だったとわかった。", "target_word": "ルーツ", "complexity_tier": "T4", "furigana": "家[いえ]のルーツをたどると、昔[むかし]は農家[のうか]だったとわかった。", "sentence_source": "generated"}, {"text": "友だちのルーツは、遠い国の小さな町だ。", "target_word": "ルーツ", "complexity_tier": "T3", "furigana": "友[とも]だちのルーツは、遠[とお]い国[くに]の小[ちい]さな町[まち]だ。", "sentence_source": "generated"}, {"text": "ルーツが外国にある人は、この町にも多い。", "target_word": "ルーツ", "complexity_tier": "T3", "furigana": "ルーツが外国[がいこく]にある人[ひと]は、この町[まち]にも多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 生まれた場所や家族の始まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bb56fb5-a3aa-427f-85df-afbf4101a571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51849, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ルーツ", "is_correct": true, "explanation": "見出し語の「るーつ」で、音声と一致します。"}, {"text": "ブーツ", "is_correct": false, "explanation": "「ぶーつ」で、最初の「る」が「ぶ」に変わった別の語です。"}, {"text": "スーツ", "is_correct": false, "explanation": "「すーつ」で、最初の「る」が「す」に変わった別の語です。"}, {"text": "ルート", "is_correct": false, "explanation": "「るーと」で、最後の「つ」が「と」に変わった別の語です。"}, {"text": "ルーズ", "is_correct": false, "explanation": "「るーず」で、最後の「つ」が「ず」に変わった別の語です。"}], "explanations": {"ルーツ": "見出し語の「るーつ」で、音声と一致します。", "ブーツ": "「ぶーつ」で、最初の「る」が「ぶ」に変わった別の語です。", "スーツ": "「すーつ」で、最初の「る」が「す」に変わった別の語です。", "ルート": "「るーと」で、最後の「つ」が「と」に変わった別の語です。", "ルーズ": "「るーず」で、最後の「つ」が「ず」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "ルーツ"}, "level_3": {"options": [{"text": "ルーツ", "is_correct": true, "explanation": "生まれた場所を答えているので、意味が合います。"}, {"text": "趣味", "is_correct": false, "explanation": "形は合うが意味が合わない。趣味が九州という答えは不自然です。"}, {"text": "仕事", "is_correct": false, "explanation": "形は合うが意味が合わない。仕事が九州という答えは不自然です。"}, {"text": "誕生日", "is_correct": false, "explanation": "形は合うが意味が合わない。誕生日が場所の九州というのは成り立ちません。"}], "explanations": {"ルーツ": "生まれた場所を答えているので、意味が合います。", "趣味": "形は合うが意味が合わない。趣味が九州という答えは不自然です。", "仕事": "形は合うが意味が合わない。仕事が九州という答えは不自然です。", "誕生日": "形は合うが意味が合わない。誕生日が場所の九州というのは成り立ちません。"}, "sentence_index": 0, "correct_answer": "ルーツ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ルーツを洗って、きれいに片づけた。", "explanation": "ルーツは生まれた場所や家族の始まりなので、洗うことはできません。"}, {"text": "ルーツは、昼ごはんにとてもおいしいです。", "explanation": "ルーツは食べ物ではないので、「おいしい」と言えません。"}, {"text": "私のルーツは、昨日の夜に走って行った。", "explanation": "ルーツは人ではないので、「走って行く」の主語になりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51849, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "ルーツ", "is_correct": true, "explanation": "見出し語の「るーつ」で、音声と一致します。"}, {"text": "ルーム", "is_correct": false, "explanation": "「るーむ」で、最後の「つ」が「む」に変わっています。"}, {"text": "ルッツ", "is_correct": false, "explanation": "「るっつ」で、長音「ー」が促音「っ」に変わっています。"}, {"text": "ルーペ", "is_correct": false, "explanation": "「るーぺ」で、最後の「つ」が「ぺ」に変わっています。"}], "explanations": {"ルーツ": "見出し語の「るーつ」で、音声と一致します。", "ルーム": "「るーむ」で、最後の「つ」が「む」に変わっています。", "ルッツ": "「るっつ」で、長音「ー」が促音「っ」に変わっています。", "ルーペ": "「るーぺ」で、最後の「つ」が「ぺ」に変わっています。"}, "sentence_index": null, "correct_answer": "ルーツ"}, "level_3": {"options": [{"text": "ルーツ", "is_correct": true, "explanation": "父が久しぶりに訪れたのは、自分の始まりの町なので意味が合います。"}, {"text": "約束", "is_correct": false, "explanation": "形は合うが意味が合わない。約束のある町を訪れる文脈ではありません。"}, {"text": "趣味", "is_correct": false, "explanation": "形は合うが意味が合わない。趣味のある町と言っても久しぶりに訪れる理由が通りません。"}, {"text": "失敗", "is_correct": false, "explanation": "形は合うが意味が合わない。失敗のある町という言い方は不自然です。"}], "explanations": {"ルーツ": "父が久しぶりに訪れたのは、自分の始まりの町なので意味が合います。", "約束": "形は合うが意味が合わない。約束のある町を訪れる文脈ではありません。", "趣味": "形は合うが意味が合わない。趣味のある町と言っても久しぶりに訪れる理由が通りません。", "失敗": "形は合うが意味が合わない。失敗のある町という言い方は不自然です。"}, "sentence_index": 6, "correct_answer": "ルーツ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ルーツを着て、寒い外へ出かけた。", "explanation": "ルーツは服ではなく家族の始まりの意味なので、「着る」と合いません。"}, {"text": "このルーツは、一つ五百円です。", "explanation": "ルーツは商品ではないので、値段をつけることはできません。"}, {"text": "明日、ルーツが雨で降るそうです。", "explanation": "ルーツは天気とは関係がなく、「降る」の主語になりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_error