INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51850, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在の場所を示す「にあります」です。"}, {"text": "を", "is_correct": false, "explanation": "「北海道をあります」は文法的に成り立ちません。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、存在の「ある」とは合いません。"}, {"text": "から", "is_correct": false, "explanation": "「北海道からあります」は存在の場所として成り立ちません。"}], "correct_answer": "に", "explanations": {"に": "存在の場所を示す「にあります」です。", "を": "「北海道をあります」は文法的に成り立ちません。", "へ": "「へ」は方向を表し、存在の「ある」とは合いません。", "から": "「北海道からあります」は存在の場所として成り立ちません。"}, "error_tags": {"を": "object_marker", "へ": "direction", "から": "source"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
