INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51850, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の起源や、自分が育った環境や背景を指す言葉。特に、自分自身のアイデンティティの基盤となるもの。", "primary_collocate": null, "pronunciation": "るーつ", "ipa": "ɾɯːtsɯ", "syllable_count": 3, "sentences": [{"text": "このTシャツは、彼らのルーツへの敬意を表している。", "target_word": "ルーツ", "complexity_tier": "T5", "furigana": "このTシャツは、彼[かれ]らのルーツへの敬意[けいい]を表[あらわ]している。", "sentence_source": "generated"}, {"text": "私のルーツは、北海道にあります。", "target_word": "ルーツ", "complexity_tier": "T2", "furigana": "私[わたし]のルーツは、北海道[ほっかいどう]にあります。", "sentence_source": "generated"}, {"text": "祖父は、自分のルーツを調べるのが好きだ。", "target_word": "ルーツ", "complexity_tier": "T3", "furigana": "祖父[そふ]は、自分[じぶん]のルーツを調[しら]べるのが好[す]きだ。", "sentence_source": "generated"}, {"text": "この料理は、日本のルーツを持つ食べ物だそうです。", "target_word": "ルーツ", "complexity_tier": "T4", "furigana": "この料理[りょうり]は、日本[にほん]のルーツを持[も]つ食[た]べ物[もの]だそうです。", "sentence_source": "generated"}, {"text": "彼は、移民としてのルーツを誇りに思っている。", "target_word": "ルーツ", "complexity_tier": "T3", "furigana": "彼[かれ]は、移民[いみん]としてのルーツを誇[ほこ]りに思[おも]っている。", "sentence_source": "generated"}, {"text": "自分のルーツを知ると、今の自分がよくわかる。", "target_word": "ルーツ", "complexity_tier": "T4", "furigana": "自分[じぶん]のルーツを知[し]ると、今[いま]の自分[じぶん]がよくわかる。", "sentence_source": "generated"}, {"text": "彼女の音楽には、アフリカのルーツが感じられる。", "target_word": "ルーツ", "complexity_tier": "T4", "furigana": "彼女[かのじょ]の音楽[おんがく]には、アフリカのルーツが感[かん]じられる。", "sentence_source": "generated"}, {"text": "ルーツをたどる旅に、家族みんなで出かけた。", "target_word": "ルーツ", "complexity_tier": "T3", "furigana": "ルーツをたどる旅[たび]に、家族[かぞく]みんなで出[で]かけた。", "sentence_source": "generated"}, {"text": "この祭りのルーツは、千年前の農村にさかのぼる。", "target_word": "ルーツ", "complexity_tier": "T4", "furigana": "この祭[まつ]りのルーツは、千年前[せんねんまえ]の農村[のうそん]にさかのぼる。", "sentence_source": "generated"}, {"text": "育った町が、私のルーツだと言ってもいい。", "target_word": "ルーツ", "complexity_tier": "T3", "furigana": "育[そだ]った町[まち]が、私[わたし]のルーツだと言[い]ってもいい。", "sentence_source": "generated"}], "morphological_forms": [], "register": "plain", "sense_fingerprint": "名詞 | 自分の起源や育った背景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bb56fb5-a3aa-427f-85df-afbf4101a571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51850, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "ルーツ", "is_correct": true, "explanation": "見出し語の「るーつ」で、音声と一致します。"}, {"text": "ブーツ", "is_correct": false, "explanation": "「ぶーつ」で、最初の「る」が「ぶ」に変わった別の語です。"}, {"text": "スーツ", "is_correct": false, "explanation": "「すーつ」で、最初の「る」が「す」に変わった別の語です。"}, {"text": "ルート", "is_correct": false, "explanation": "「るーと」で、最後の「つ」が「と」に変わった別の語です。"}, {"text": "ルーズ", "is_correct": false, "explanation": "「るーず」で、最後の「つ」が「ず」に変わった別の語です。"}], "explanations": {"ルーツ": "見出し語の「るーつ」で、音声と一致します。", "ブーツ": "「ぶーつ」で、最初の「る」が「ぶ」に変わった別の語です。", "スーツ": "「すーつ」で、最初の「る」が「す」に変わった別の語です。", "ルート": "「るーと」で、最後の「つ」が「と」に変わった別の語です。", "ルーズ": "「るーず」で、最後の「つ」が「ず」に変わった別の語です。"}, "sentence_index": null, "correct_answer": "ルーツ"}, "level_3": {"options": [{"text": "ルーツ", "is_correct": true, "explanation": "彼らの起源や背景への敬意なので、意味が合います。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが意味が合わない。値段への敬意をTシャツで表す文脈ではありません。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが意味が合わない。天気への敬意とは言いません。"}, {"text": "荷物", "is_correct": false, "explanation": "形は合うが意味が合わない。荷物への敬意は文脈に合いません。"}], "explanations": {"ルーツ": "彼らの起源や背景への敬意なので、意味が合います。", "値段": "形は合うが意味が合わない。値段への敬意をTシャツで表す文脈ではありません。", "天気": "形は合うが意味が合わない。天気への敬意とは言いません。", "荷物": "形は合うが意味が合わない。荷物への敬意は文脈に合いません。"}, "sentence_index": 0, "correct_answer": "ルーツ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ルーツを食べたら、とてもおいしかった。", "explanation": "ルーツは起源や背景という抽象的な意味なので、食べることはできません。"}, {"text": "明日のルーツは、雨が降るでしょう。", "explanation": "ルーツを天気の意味で使っており、起源という意味から外れています。"}, {"text": "彼はルーツに乗って、会社へ行った。", "explanation": "ルーツは乗り物ではないので、「乗る」の対象になりません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUD