INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51850, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "ルーツ", "is_correct": true, "explanation": "見出し語の「るーつ」で、音声と一致します。"}, {"text": "ルーム", "is_correct": false, "explanation": "「るーむ」で、最後の「つ」が「む」に変わっています。"}, {"text": "ルッツ", "is_correct": false, "explanation": "「るっつ」で、長音「ー」が促音「っ」に変わっています。"}, {"text": "ルーペ", "is_correct": false, "explanation": "「るーぺ」で、最後の「つ」が「ぺ」に変わっています。"}], "explanations": {"ルーツ": "見出し語の「るーつ」で、音声と一致します。", "ルーム": "「るーむ」で、最後の「つ」が「む」に変わっています。", "ルッツ": "「るっつ」で、長音「ー」が促音「っ」に変わっています。", "ルーペ": "「るーぺ」で、最後の「つ」が「ぺ」に変わっています。"}, "sentence_index": null, "correct_answer": "ルーツ"}, "level_3": {"options": [{"text": "ルーツ", "is_correct": true, "explanation": "音楽の背景にあるアフリカの起源が感じられるので、意味が合います。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが意味が合わない。音楽から値段が感じられるとは言いません。"}, {"text": "荷物", "is_correct": false, "explanation": "形は合うが意味が合わない。音楽から荷物は感じられません。"}, {"text": "電話", "is_correct": false, "explanation": "形は合うが意味が合わない。アフリカの電話が感じられる文脈ではありません。"}], "explanations": {"ルーツ": "音楽の背景にあるアフリカの起源が感じられるので、意味が合います。", "値段": "形は合うが意味が合わない。音楽から値段が感じられるとは言いません。", "荷物": "形は合うが意味が合わない。音楽から荷物は感じられません。", "電話": "形は合うが意味が合わない。アフリカの電話が感じられる文脈ではありません。"}, "sentence_index": 6, "correct_answer": "ルーツ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ルーツは、あの店で一つ三百円で売られている。", "explanation": "ルーツは商品ではなく起源という抽象的な意味なので、「売られる」と合いません。"}, {"text": "彼はルーツを飲んで、のどの渇きを癒した。", "explanation": "ルーツは飲み物ではないので、「飲む」の目的語になりません。"}, {"text": "来週のルーツは、かなり忙しそうだ。", "explanation": "ルーツを予定の意味で使っており、起源という意味から外れています。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4528ae-a7ff-41dd-b4fc-f8d48215a2dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
