INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51851, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「敬意を感じる」で、敬意は感じる対象です。"}, {"text": "へ", "is_correct": false, "explanation": "「敬意へ感じます」は文法的に成り立ちません。"}, {"text": "で", "is_correct": false, "explanation": "「敬意で感じます」は意味が通らず、ここでは成り立ちません。"}, {"text": "が", "is_correct": false, "explanation": "「敬意が感じます」は「感じます」の対象を示せず、文法的に成り立ちません。"}], "correct_answer": "を", "explanations": {"を": "「敬意を感じる」で、敬意は感じる対象です。", "へ": "「敬意へ感じます」は文法的に成り立ちません。", "で": "「敬意で感じます」は意味が通らず、ここでは成り立ちません。", "が": "「敬意が感じます」は「感じます」の対象を示せず、文法的に成り立ちません。"}, "error_tags": {"へ": "direction", "で": "means", "が": "subject"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "軽蔑", "is_correct": true, "explanation": "他人を見下す気持ちで、敬意の反対です。"}, {"text": "尊重", "is_correct": false, "explanation": "大切に扱うことで、敬意に近い意味です。"}, {"text": "好意", "is_correct": false, "explanation": "好ましく思う気持ちで、敬意の反対ではありません。"}, {"text": "感動", "is_correct": false, "explanation": "心を動かされることで、敬意の反対ではありません。"}], "correct_answer": "軽蔑", "explanations": {"軽蔑": "他人を見下す気持ちで、敬意の反対です。", "尊重": "大切に扱うことで、敬意に近い意味です。", "好意": "好ましく思う気持ちで、敬意の反対ではありません。", "感動": "心を動かされることで、敬意の反対ではありません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
