entence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 他人を大切に思う気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d94e4e-9169-4547-91bc-074c7abed4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51851, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "敬意", "is_correct": true, "explanation": "「けいい」は、聞いた音と同じ見出し語です。"}, {"text": "決意", "is_correct": false, "explanation": "「けつい」は2音目が違う別の語です。"}, {"text": "誠意", "is_correct": false, "explanation": "「せいい」は1音目が違う別の語です。"}, {"text": "軽視", "is_correct": false, "explanation": "「けいし」は最後の音が違う別の語です。"}, {"text": "経費", "is_correct": false, "explanation": "「けいひ」は最後の音が違う別の語です。"}], "explanations": {"敬意": "「けいい」は、聞いた音と同じ見出し語です。", "決意": "「けつい」は2音目が違う別の語です。", "誠意": "「せいい」は1音目が違う別の語です。", "軽視": "「けいし」は最後の音が違う別の語です。", "経費": "「けいひ」は最後の音が違う別の語です。"}, "sentence_index": null, "correct_answer": "敬意"}, "level_3": {"options": [{"text": "敬意", "is_correct": true, "explanation": "人を大切に思う気持ちを持って話すので、意味が合います。"}, {"text": "空腹", "is_correct": false, "explanation": "形は合うが、空腹を持って人と話すのは意味が合わない。"}, {"text": "身長", "is_correct": false, "explanation": "形は合うが、身長を持って人と話すのは意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、季節を持って人と話すのは意味が合わない。"}], "explanations": {"敬意": "人を大切に思う気持ちを持って話すので、意味が合います。", "空腹": "形は合うが、空腹を持って人と話すのは意味が合わない。", "身長": "形は合うが、身長を持って人と話すのは意味が合わない。", "季節": "形は合うが、季節を持って人と話すのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "敬意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "敬意を飲む前に、手を洗いましょう。", "explanation": "「敬意」は気持ちであり、飲み物ではないので「飲む」は誤りです。"}, {"text": "朝、窓を開けたら、きれいな敬意が見えた。", "explanation": "「敬意」は目で見える景色ではなく、心の中の気持ちです。"}, {"text": "敬意をかばんに入れて、学校へ持っていった。", "explanation": "「敬意」は心の中の気持ちで、かばんに入れて運べる物ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLU