INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51852, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "相手の立場や気持ちを尊重し、大切に思う気持ちや態度。", "primary_collocate": null, "pronunciation": "けいい", "ipa": "keːi", "syllable_count": 3, "sentences": [{"text": "このTシャツは、単なるグッズではなく、彼らのルーツへの敬意を形にしたものです。", "target_word": "敬意", "complexity_tier": "T5", "furigana": "このTシャツは、単[たん]なるグッズではなく、彼[かれ]らのルーツへの敬意[けいい]を形[かたち]にしたものです。", "sentence_source": "mined"}, {"text": "先生に敬意を払って、深く頭を下げました。", "target_word": "敬意", "complexity_tier": "T3", "furigana": "先生[せんせい]に敬意[けいい]を払[はら]って、深[ふか]く頭[あたま]を下[さ]げました。", "sentence_source": "generated"}, {"text": "敬意を込めて手紙を書きます。", "target_word": "敬意", "complexity_tier": "T2", "furigana": "敬意[けいい]を込[こ]めて手紙[てがみ]を書[か]きます。", "sentence_source": "generated"}, {"text": "彼の努力には敬意しかない。", "target_word": "敬意", "complexity_tier": "T2", "furigana": "彼[かれ]の努力[どりょく]には敬意[けいい]しかない。", "sentence_source": "generated"}, {"text": "祖父への敬意は、今も変わりません。", "target_word": "敬意", "complexity_tier": "T3", "furigana": "祖父[そふ]への敬意[けいい]は、今[いま]も変[か]わりません。", "sentence_source": "generated"}, {"text": "年上の人への敬意が足りないと注意された。", "target_word": "敬意", "complexity_tier": "T4", "furigana": "年上[としうえ]の人[ひと]への敬意[けいい]が足[た]りないと注意[ちゅうい]された。", "sentence_source": "generated"}, {"text": "敬意のない言い方は、相手を傷つけます。", "target_word": "敬意", "complexity_tier": "T3", "furigana": "敬意[けいい]のない言[い]い方[かた]は、相手[あいて]を傷[きず]つけます。", "sentence_source": "generated"}, {"text": "この賞は、長年の功績への敬意の印です。", "target_word": "敬意", "complexity_tier": "T3", "furigana": "この賞[しょう]は、長年[ながねん]の功績[こうせき]への敬意[けいい]の印[しるし]です。", "sentence_source": "generated"}, {"text": "敬意と愛情は、どちらも大切だと思う。", "target_word": "敬意", "complexity_tier": "T3", "furigana": "敬意[けいい]と愛情[あいじょう]は、どちらも大切[たいせつ]だと思[おも]う。", "sentence_source": "generated"}, {"text": "たとえ意見が違っても、相手への敬意を忘れてはいけません。", "target_word": "敬意", "complexity_tier": "T4", "furigana": "たとえ意見[いけん]が違[ちが]っても、相手[あいて]への敬意[けいい]を忘[わす]れてはいけません。", "sentence_source": "generated"}], "morphological_forms": [], "register": "formal", "sense_fingerprint": "名詞 | 相手を尊重し大切に思う気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42d94e4e-9169-4547-91bc-074c7abed4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51852, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "敬意", "is_correct": true, "explanation": "「けいい」は、聞いた音と同じ見出し語です。"}, {"text": "決意", "is_correct": false, "explanation": "「けつい」は2音目が違う別の語です。"}, {"text": "誠意", "is_correct": false, "explanation": "「せいい」は1音目が違う別の語です。"}, {"text": "軽視", "is_correct": false, "explanation": "「けいし」は最後の音が違う別の語です。"}, {"text": "経費", "is_correct": false, "explanation": "「けいひ」は最後の音が違う別の語です。"}, {"text": "景気", "is_correct": false, "explanation": "「けいき」は最後の音が違う別の語です。"}], "explanations": {"敬意": "「けいい」は、聞いた音と同じ見出し語です。", "決意": "「けつい」は2音目が違う別の語です。", "誠意": "「せいい」は1音目が違う別の語です。", "軽視": "「けいし」は最後の音が違う別の語です。", "経費": "「けいひ」は最後の音が違う別の語です。", "景気": "「けいき」は最後の音が違う別の語です。"}, "sentence_index": null, "correct_answer": "敬意"}, "level_3": {"options": [{"text": "敬意", "is_correct": true, "explanation": "ルーツを大切に思う気持ちを形にしたので、意味が合います。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、ルーツへの値段を形にするのは意味が合わない。"}, {"text": "疲労", "is_correct": false, "explanation": "形は合うが、ルーツへの疲労を形にするのは意味が合わない。"}, {"text": "失敗", "is_correct": false, "explanation": "形は合うが、グッズに込める気持ちとして意味が合わない。"}], "explanations": {"敬意": "ルーツを大切に思う気持ちを形にしたので、意味が合います。", "値段": "形は合うが、ルーツへの値段を形にするのは意味が合わない。", "疲労": "形は合うが、ルーツへの疲労を形にするのは意味が合わない。", "失敗": "形は合うが、グッズに込める気持ちとして意味が合わない。"}, "sentence_index": 0, "correct_answer": "敬意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は朝ごはんに敬意を入れて、パンを焼いた。", "explanation": "「敬意」は食材のような物ではないので、「入れて焼く」という使い方は誤りです。"}, {"text": "雨がひどくて、今日は敬意がたくさん降っている。", "explanation": "「敬意」は気持ちであり、雨のように降るものではありません。"}, {"text": "彼の敬意は三十度もあるので、上着はいらない。", "explanation": "「敬意」は気持ちであり、温度で測るものではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51852, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "敬意", "is_correct": true, "explanation": "「けいい」は、聞いた音と同じ見出し語です。"}, {"text": "権威", "is_correct": false, "explanation": "「けんい」は2音目が違う別の語です。"}, {"text": "経理", "is_correct": false, "explanation": "「けいり」は最後の音が違う別の語です。"}, {"text": "稽古", "is_correct": false, "explanation": "「けいこ」は最後の音が違う別の語です。"}, {"text": "警備", "is_correct": false, "explanation": "「けいび」は最後の音が違う別の語です。"}, {"text": "掲示", "is_correct": false, "explanation": "「けいじ」は最後の音が違う別の語です。"}], "explanations": {"敬意": "「けいい」は、聞いた音と同じ見出し語です。", "権威": "「けんい」は2音目が違う別の語です。", "経理": "「けいり」は最後の音が違う別の語です。", "稽古": "「けいこ」は最後の音が違う別の語です。", "警備": "「けいび」は最後の音が違う別の語です。", "掲示": "「けいじ」は最後の音が違う別の語です。"}, "sentence_index": null, "correct_answer": "敬意"}, "level_3": {"options": [{"text": "敬意", "is_correct": true, "explanation": "敬意のない言い方は相手を傷つけるので、意味が合います。"}, {"text": "予算", "is_correct": false, "explanation": "形は合うが、「予算のない言い方」は意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「天気のない言い方」は意味が合わない。"}, {"text": "体重", "is_correct": false, "explanation": "形は合うが、「体重のない言い方」は意味が合わない。"}], "explanations": {"敬意": "敬意のない言い方は相手を傷つけるので、意味が合います。", "予算": "形は合うが、「予算のない言い方」は意味が合わない。", "天気": "形は合うが、「天気のない言い方」は意味が合わない。", "体重": "形は合うが、「体重のない言い方」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "敬意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅まで敬意で歩くと、十分かかります。", "explanation": "「敬意」は移動の手段や速さではなく、気持ちを表す語です。"}, {"text": "彼の敬意は重いので、箱を二人で運んだ。", "explanation": "「敬意」は気持ちであり、重さのある物ではありません。"}, {"text": "彼は敬意を冷蔵庫に入れて、冷やしておいた。", "explanation": "「敬意」は気持ちであり、冷蔵庫に入れて冷やせる物ではありません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51852, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父に敬意を落として、静かに手を合わせた。", "corrected_sentence": "祖父に敬意を払って、静かに手を合わせた。", "error_description": "「敬意を落とす」という言い方はなく、「敬意を払う」が正しい組み合わせです。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51852, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女の勇気に敬意が行って、拍手を送った。", "corrected_sentence": "彼女の勇気に敬意を表して、拍手を送った。", "error_description": "「敬意が行く」という言い方はなく、「敬意を表す」が正しい組み合わせです。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba4152e-71e4-4baf-bf6e-d4d28133816a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51853, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「工芸の教室」で、工芸に関する教室という所属・修飾の「の」。"}, {"text": "を", "is_correct": false, "explanation": "「工芸を教室で」は、工芸を目的語にして教室で作る形になり、意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「工芸と教室で」は共同の相手を示すが、教室を修飾する形にはならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「工芸へ教室で」は方向を示す「へ」になり、教室の修飾には合わない。"}], "correct_answer": "の", "explanations": {"の": "「工芸の教室」で、工芸に関する教室という所属・修飾の「の」。", "を": "「工芸を教室で」は、工芸を目的語にして教室で作る形になり、意味が通らない。", "と": "「工芸と教室で」は共同の相手を示すが、教室を修飾する形にはならず不自然。", "へ": "「工芸へ教室で」は方向を示す「へ」になり、教室の修飾には合わない。"}, "error_tags": {"を": "対象（目的語）", "と": "共同・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
