INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51853, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "「工芸」は、手でじょうずにものをつくることです。", "primary_collocate": null, "pronunciation": "こうげい", "ipa": "koːɡeː", "syllable_count": 4, "sentences": [{"text": "祖父は工芸が得意で、木の箱を手で作ります。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "祖父[そふ]は工芸[こうげい]が得意[とくい]で、木[き]の箱[はこ]を手[て]で作[つく]ります。", "sentence_source": "generated"}, {"text": "工芸の教室で、小さな皿を作りました。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "工芸[こうげい]の教室[きょうしつ]で、小[ちい]さな皿[さら]を作[つく]りました。", "sentence_source": "generated"}, {"text": "彼女は手先が器用なので、工芸が上手です。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は手先[てさき]が器用[きよう]なので、工芸[こうげい]が上手[じょうず]です。", "sentence_source": "generated"}, {"text": "工芸が好きな姉は、休みの日に布で小物を作っています。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "工芸[こうげい]が好[す]きな姉[あね]は、休[やす]みの日[ひ]に布[ぬの]で小物[こもの]を作[つく]っています。", "sentence_source": "generated"}, {"text": "子どもたちは、工芸の時間に紙で動物を作りました。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "子[こ]どもたちは、工芸[こうげい]の時間[じかん]に紙[かみ]で動物[どうぶつ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "工芸には、時間と根気が必要です。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "工芸[こうげい]には、時間[じかん]と根気[こんき]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "父は工芸を趣味にして、竹のかごを編んでいます。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "父[ちち]は工芸[こうげい]を趣味[しゅみ]にして、竹[たけ]のかごを編[あ]んでいます。", "sentence_source": "generated"}, {"text": "この村では、冬になると工芸に取り組む人が増えます。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "この村[むら]では、冬[ふゆ]になると工芸[こうげい]に取[と]り組[く]む人[ひと]が増[ふ]えます。", "sentence_source": "generated"}, {"text": "工芸を習いたい人のために、無料の体験会を開きます。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "工芸[こうげい]を習[なら]いたい人[ひと]のために、無料[むりょう]の体験会[たいけんかい]を開[ひら]きます。", "sentence_source": "generated"}, {"text": "彼の工芸の腕前は、プロの職人にも負けません。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "彼[かれ]の工芸[こうげい]の腕前[うでまえ]は、プロの職人[しょくにん]にも負[ま]けません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工芸", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "手を使って上手にものを作ること、手作りの技(名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d75d5cb-9168-42ec-b5c5-aaf58a772dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51853, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工芸", "is_correct": true, "explanation": "「工芸が得意」で、手で上手にものを作る技を指し、木の箱を手で作る文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気が得意」は、手作りの話の文脈に合わない。"}, {"text": "病院", "is_correct": false, "explanation": "「病院が得意」は、木の箱を作る文脈に合わない。"}, {"text": "地震", "is_correct": false, "explanation": "「地震が得意」は意味が通らない。"}], "explanations": {"工芸": "「工芸が得意」で、手で上手にものを作る技を指し、木の箱を手で作る文に合う。", "天気": "「天気が得意」は、手作りの話の文脈に合わない。", "病院": "「病院が得意」は、木の箱を作る文脈に合わない。", "地震": "「地震が得意」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "工芸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場では、毎日工芸で部品を大量に作っています。", "explanation": "ここは「製造」の意味。機械で部品を大量に作るのは製造で、手で上手に作る工芸には合わない。"}, {"text": "映画の工芸には、多くの人が関わります。", "explanation": "ここは「製作」の意味。映画のように分業で作るものは製作で、一人の手の技を指す工芸には合わない。"}, {"text": "姉は宿題で、長い工芸を書きました。", "explanation": "ここは〈作文〉の意味。文章を書くことは作文で、手で物を作る工芸とは違うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51853, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工芸", "is_correct": true, "explanation": "「工芸を趣味にする」で、手で作る技を趣味にする意味になり、竹のかごを編む文に合う。"}, {"text": "天井", "is_correct": false, "explanation": "「天井を趣味にする」は趣味の対象にならず、竹のかごを編む文の内容とも合わない。"}, {"text": "会議", "is_correct": false, "explanation": "「会議を趣味にする」は趣味として不自然で、竹のかごの話にも合わない。"}, {"text": "画面", "is_correct": false, "explanation": "「画面を趣味にする」は趣味の対象として不自然で、竹のかごを編む文脈にも合わない。"}], "explanations": {"工芸": "「工芸を趣味にする」で、手で作る技を趣味にする意味になり、竹のかごを編む文に合う。", "天井": "「天井を趣味にする」は趣味の対象にならず、竹のかごを編む文の内容とも合わない。", "会議": "「会議を趣味にする」は趣味として不自然で、竹のかごの話にも合わない。", "画面": "「画面を趣味にする」は趣味の対象として不自然で、竹のかごを編む文脈にも合わない。"}, "sentence_index": 6, "correct_answer": "工芸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の工芸の腕前は、プロの作曲家にも負けません。", "explanation": "ここは「作曲」の意味。工芸は手で上手に作る技で、曲を書く能力には使わない。"}, {"text": "彼は工芸が上手で、夜の高速道路を安全に運転します。", "explanation": "ここは「運転」の意味。工芸は手で物を作る技術で、車の運転の技能には使わない。"}, {"text": "彼は英語の工芸が得意で、留学生と話せます。", "explanation": "ここは「会話」の意味。英語で話す能力は会話で、手で作る技術を指す工芸では言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51853, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は工芸を道具を大切にしています。", "corrected_sentence": "父は工芸の道具を大切にしています。", "error_description": "誤りは「工芸」に続く助詞。「工芸の道具」（工芸に使う道具）と言うべきところを「工芸を」としており、所属・修飾の「の」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51853, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "父は工芸に腕前を友人に自慢しています。", "corrected_sentence": "父は工芸の腕前を友人に自慢しています。", "error_description": "誤りは「工芸」に続く助詞。「工芸の腕前」と言うべきところを「工芸に」としており、所属・修飾の「の」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
