INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51854, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "工芸とは、実用的な品物に美しさや芸術性を加えたもの、またはその技術のことです。", "primary_collocate": null, "pronunciation": "こうげい", "ipa": "koːɡeː", "syllable_count": 4, "sentences": [{"text": "漆器は、日本で発展した独自の工芸であり、世界的に評価される芸術です。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "漆器[しっき]は、日本[にほん]で発展[はってん]した独自[どくじ]の工芸[こうげい]であり、世界的[せかいてき]に評価[ひょうか]される芸術[げいじゅつ]です。", "sentence_source": "generated"}, {"text": "工芸は、毎日使う道具に美しさを加えたものです。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "工芸[こうげい]は、毎日[まいにち]使[つか]う道具[どうぐ]に美[うつく]しさを加[くわ]えたものです。", "sentence_source": "generated"}, {"text": "この町は、陶器などの工芸で有名です。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "この町[まち]は、陶器[とうき]などの工芸[こうげい]で有名[ゆうめい]です。", "sentence_source": "generated"}, {"text": "祖母は若いころ、工芸を学んで漆の器を作っていました。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "祖母[そぼ]は若[わか]いころ、工芸[こうげい]を学[まな]んで漆[うるし]の器[うつわ]を作[つく]っていました。", "sentence_source": "generated"}, {"text": "工芸の技術を守るため、若い職人を育てています。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "工芸[こうげい]の技術[ぎじゅつ]を守[まも]るため、若[わか]い職人[しょくにん]を育[そだ]てています。", "sentence_source": "generated"}, {"text": "博物館で、江戸時代の工芸を集めた展示を見ました。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]で、江戸時代[えどじだい]の工芸[こうげい]を集[あつ]めた展示[てんじ]を見[み]ました。", "sentence_source": "generated"}, {"text": "実用的な茶碗も、美しければ工芸として評価されます。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "実用的[じつようてき]な茶碗[ちゃわん]も、美[うつく]しければ工芸[こうげい]として評価[ひょうか]されます。", "sentence_source": "generated"}, {"text": "工芸は使うための物なので、絵画とは少し違います。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "工芸[こうげい]は使[つか]うための物[もの]なので、絵画[かいが]とは少[すこ]し違[ちが]います。", "sentence_source": "generated"}, {"text": "彼は大学で、織物や染物などの工芸を研究しています。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "彼[かれ]は大学[だいがく]で、織物[おりもの]や染物[そめもの]などの工芸[こうげい]を研究[けんきゅう]しています。", "sentence_source": "generated"}, {"text": "この店では、地元の工芸を学ぶ教室を開いています。", "target_word": "工芸", "complexity_tier": "T3", "furigana": "この店[みせ]では、地元[じもと]の工芸[こうげい]を学[まな]ぶ教室[きょうしつ]を開[ひら]いています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "工芸", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "実用的な品物に美しさや芸術性を加えたもの、またはその技術(名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 美しけれ (Zipf 1.38)']::text[], '9d75d5cb-9168-42ec-b5c5-aaf58a772dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51854, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工芸", "is_correct": true, "explanation": "「独自の工芸」として、実用品に美しさを加えたものを指し、文の内容に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「独自の天気であり、芸術です」は意味が通らない。"}, {"text": "会議", "is_correct": false, "explanation": "「独自の会議であり、世界的に評価される芸術」は文脈に合わない。"}, {"text": "病院", "is_correct": false, "explanation": "「独自の病院であり」は、芸術と並ぶ文化の説明にならない。"}], "explanations": {"工芸": "「独自の工芸」として、実用品に美しさを加えたものを指し、文の内容に合う。", "天気": "「独自の天気であり、芸術です」は意味が通らない。", "会議": "「独自の会議であり、世界的に評価される芸術」は文脈に合わない。", "病院": "「独自の病院であり」は、芸術と並ぶ文化の説明にならない。"}, "sentence_index": 0, "correct_answer": "工芸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "絵画は、見て楽しむだけの工芸です。", "explanation": "ここは「芸術」の意味。工芸は実用的な品物に美しさを加えたものなので、鑑賞だけを目的とする絵画は含まれない。"}, {"text": "この町は、自動車などの工芸で有名です。", "explanation": "ここは「工業」の意味。自動車を大量に生産するのは工業で、工芸は手仕事や美しさを加えた品物を指すので合わない。"}, {"text": "大学で工芸を学んで、橋を設計しました。", "explanation": "ここは「工学」の意味。橋の設計は工学の分野で、工芸は実用品の美しさや技術を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51854, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工芸", "is_correct": true, "explanation": "「工芸として評価される」で、美しさを備えた実用品の位置づけとして文に合う。"}, {"text": "数学", "is_correct": false, "explanation": "「数学として評価される」は、茶碗の評価の文脈に合わない。"}, {"text": "地震", "is_correct": false, "explanation": "「地震として評価される」は、自然現象が茶碗の評価に当てはまらず、文の内容に合わない。"}, {"text": "電車", "is_correct": false, "explanation": "「電車として評価される」は、実用的な茶碗を評価する文脈に合わない。"}], "explanations": {"工芸": "「工芸として評価される」で、美しさを備えた実用品の位置づけとして文に合う。", "数学": "「数学として評価される」は、茶碗の評価の文脈に合わない。", "地震": "「地震として評価される」は、自然現象が茶碗の評価に当てはまらず、文の内容に合わない。", "電車": "「電車として評価される」は、実用的な茶碗を評価する文脈に合わない。"}, "sentence_index": 6, "correct_answer": "工芸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工芸は、木で家を建てる仕事をします。", "explanation": "ここは「大工」の意味。家を建てる仕事は大工で、工芸は実用品に美しさを加える技術を指すので合わない。"}, {"text": "この店では、毎日の食事を工芸で作っています。", "explanation": "ここは「料理」の意味。食事の調理は料理で、工芸は実用品に美しさを加える手仕事を指すので合わない。"}, {"text": "彼は道路の工芸を担当し、毎日現場で働いています。", "explanation": "ここは〈工事〉の意味。道路を造る作業は工事で、工芸は実用品に美しさを加える技術を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51854, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は工芸に品を集めて売っています。", "corrected_sentence": "この店は工芸の品を集めて売っています。", "error_description": "誤りは「工芸」に続く助詞。「工芸の品」（工芸の品物）と言うべきところを「工芸に」としており、所属・修飾の「の」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51854, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟は工芸を作品を友だちに贈りました。", "corrected_sentence": "弟は工芸の作品を友だちに贈りました。", "error_description": "誤りは「工芸」に続く助詞。「工芸の作品」と言うべきところを「工芸を」としており、所属・修飾の「の」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
