INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51855, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ほかのものとちがって、自分だけのもの。", "primary_collocate": null, "pronunciation": "どくじ", "ipa": "dokɯdʑi", "syllable_count": 3, "sentences": [{"text": "この店は独自の方法でパンを焼いている。", "target_word": "独自", "complexity_tier": "T3", "furigana": "この店[みせ]は独自[どくじ]の方法[ほうほう]でパンを焼[や]いている。", "sentence_source": "generated"}, {"text": "会社は独自に調べて、原因を見つけた。", "target_word": "独自", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は独自[どくじ]に調[しら]べて、原因[げんいん]を見[み]つけた。", "sentence_source": "generated"}, {"text": "日本には、地域ごとに独自の文化がある。", "target_word": "独自", "complexity_tier": "T3", "furigana": "日本[にほん]には、地域[ちいき]ごとに独自[どくじ]の文化[ぶんか]がある。", "sentence_source": "generated"}, {"text": "彼は独自の考えを持っていて、人のまねをしない。", "target_word": "独自", "complexity_tier": "T3", "furigana": "彼[かれ]は独自[どくじ]の考[かんが]えを持[も]っていて、人[ひと]のまねをしない。", "sentence_source": "generated"}, {"text": "他の国とちがい、この国は独自の法律を作った。", "target_word": "独自", "complexity_tier": "T3", "furigana": "他[ほか]の国[くに]とちがい、この国[くに]は独自[どくじ]の法律[ほうりつ]を作[つく]った。", "sentence_source": "generated"}, {"text": "独自の味を出すために、材料を何度も変えた。", "target_word": "独自", "complexity_tier": "T3", "furigana": "独自[どくじ]の味[あじ]を出[だ]すために、材料[ざいりょう]を何度[なんど]も変[か]えた。", "sentence_source": "generated"}, {"text": "作家は独自のスタイルで小説を書き続けている。", "target_word": "独自", "complexity_tier": "T3", "furigana": "作家[さっか]は独自[どくじ]のスタイルで小説[しょうせつ]を書[か]き続[つづ]けている。", "sentence_source": "generated"}, {"text": "学校が独自に決めたルールで、制服は自由だ。", "target_word": "独自", "complexity_tier": "T3", "furigana": "学校[がっこう]が独自[どくじ]に決[き]めたルールで、制服[せいふく]は自由[じゆう]だ。", "sentence_source": "generated"}, {"text": "動物は島ごとに独自の進化をとげた。", "target_word": "独自", "complexity_tier": "T3", "furigana": "動物[どうぶつ]は島[しま]ごとに独自[どくじ]の進化[しんか]をとげた。", "sentence_source": "generated"}, {"text": "このアプリは独自の機能が多く、人気がある。", "target_word": "独自", "complexity_tier": "T3", "furigana": "このアプリは独自[どくじ]の機能[きのう]が多[おお]く、人気[にんき]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "独自", "label": "語幹"}, {"form": "独自の", "label": "連体形"}, {"form": "独自に", "label": "連用形"}, {"form": "独自だ", "label": "終止形"}, {"form": "独自で", "label": "連用形（で）"}], "register": "neutral", "sense_fingerprint": "他とちがう、そのもの自身だけの特有さ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb6837b5-37ea-42d1-91e7-d13681740b4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51855, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独自", "is_correct": true, "explanation": "ほかの店とちがう、この店だけの方法を表すので、文の空所に合う。"}, {"text": "派手", "is_correct": false, "explanation": "派手は見た目が華やかで目立つ様子を指す。方法がほかとちがう点を言う文脈には合わず、「派手の方法」ともつながりにくい。"}, {"text": "静か", "is_correct": false, "explanation": "静かは音や様子が穏やかなことを指す。パンを焼く方法の特徴を表す語としては意味が合わない。"}, {"text": "大切", "is_correct": false, "explanation": "大切は大事だという評価を表す。方法がほかとちがう点を述べる文では意味が合わない。"}], "explanations": {"独自": "ほかの店とちがう、この店だけの方法を表すので、文の空所に合う。", "派手": "派手は見た目が華やかで目立つ様子を指す。方法がほかとちがう点を言う文脈には合わず、「派手の方法」ともつながりにくい。", "静か": "静かは音や様子が穏やかなことを指す。パンを焼く方法の特徴を表す語としては意味が合わない。", "大切": "大切は大事だという評価を表す。方法がほかとちがう点を述べる文では意味が合わない。"}, "sentence_index": 0, "correct_answer": "独自"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は四十代になっても独自だ。", "explanation": "ここは〈独身〉の意味。結婚していない状態は〈独身〉と言い、独自はほかとちがう特徴を表すので合わない。"}, {"text": "夜、彼女は独自で泣いていた。", "explanation": "ここは〈独りで〉（ひとりで）の意味。誰もいない所で一人で泣くことは〈独りで〉と言い、独自はほかとちがう方法や特徴を表すので合わない。"}, {"text": "父は独自赴任で九州にいる。", "explanation": "ここは〈単身赴任〉の意味。家族と離れて一人で勤務地に住むことは〈単身赴任〉と言い、独自はほかとちがう特徴を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51855, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独自", "is_correct": true, "explanation": "ほかとちがう、この作家だけのスタイルを表すので、文の空所に合う。"}, {"text": "穏やか", "is_correct": false, "explanation": "穏やかは性格や雰囲気が落ち着いていることを指す。スタイルの独自性を言う文では意味が合わない。"}, {"text": "不便", "is_correct": false, "explanation": "不便は使いにくい状態を指す。小説の書き方の特徴を表す語としては合わない。"}, {"text": "丁寧", "is_correct": false, "explanation": "丁寧は注意深く行う様子を指す。ほかとちがう特徴を示す文脈には意味が合わない。"}], "explanations": {"独自": "ほかとちがう、この作家だけのスタイルを表すので、文の空所に合う。", "穏やか": "穏やかは性格や雰囲気が落ち着いていることを指す。スタイルの独自性を言う文では意味が合わない。", "不便": "不便は使いにくい状態を指す。小説の書き方の特徴を表す語としては合わない。", "丁寧": "丁寧は注意深く行う様子を指す。ほかとちがう特徴を示す文脈には意味が合わない。"}, "sentence_index": 6, "correct_answer": "独自"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は独自欲が強く、何でも一人で持ちたがる。", "explanation": "ここは〈独占欲〉の意味。何でも一人で持ちたがる気持ちは〈独占欲〉と言い、独自はほかとちがう特徴を表すので合わない。"}, {"text": "この店の入口は、人が近づくと独自ドアで開く。", "explanation": "ここは〈自動ドア〉の意味。人が近づくと自然に開く扉は〈自動ドア〉と言い、独自はほかとちがう特徴を表すので合わない。"}, {"text": "彼は独自心が強く、人に頼らない。", "explanation": "ここは〈独立心〉の意味。人に頼らず自分で立とうとする気持ちは〈独立心〉と言い、独自はほかとちがう特徴を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51855, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その村は独自を祭りを毎年行っている。", "corrected_sentence": "その村は独自の祭りを毎年行っている。", "error_description": "形状詞「独自」が名詞「祭り」を修飾するときは「の」が必要。「を」は目的語を示すので、「独自を祭り」は文として合わない。正しくは「独自の祭り」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "独自", "is_correct": true, "explanation": "語幹。「に」などが付く前の形で、「独自に」の「独自」にあたり、「会社は独自に調べて」の語幹として合う。"}, {"text": "独自の", "is_correct": false, "explanation": "連体形。名詞の前に付く形で、「会社は独自のに調べて」は文が成り立たない。"}, {"text": "独自だ", "is_correct": false, "explanation": "終止形。「だ」で文を終える形で、「独自だに調べて」は成り立たない。"}, {"text": "独自で", "is_correct": false, "explanation": "連用形（で）。「で」で終わる形なので、後ろの「に」と続けると「独自でに調べて」となり、文が成り立たない。"}], "correct_form": "独自", "base_form": "独自", "form_label": "語幹", "sentence_index": 1, "explanations": {"独自": "語幹。「に」などが付く前の形で、「独自に」の「独自」にあたり、「会社は独自に調べて」の語幹として合う。", "独自の": "連体形。名詞の前に付く形で、「会社は独自のに調べて」は文が成り立たない。", "独自だ": "終止形。「だ」で文を終える形で、「独自だに調べて」は成り立たない。", "独自で": "連用形（で）。「で」で終わる形なので、後ろの「に」と続けると「独自でに調べて」となり、文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51855, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この会社は独自だ機能を作った。", "corrected_sentence": "この会社は独自の機能を作った。", "error_description": "形状詞「独自」が名詞「機能」を修飾するときは「の」（または「な」）が必要。「だ」は文末の形で、名詞の前には使えない。正しくは「独自の機能」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "独自", "is_correct": true, "explanation": "語幹。「に」などが付く前の形で、「独自に決めた」の「独自」にあたり、「学校が独自に決めた」の語幹として合う。"}, {"text": "独自な", "is_correct": false, "explanation": "連体形（な）。名詞の前に付く形なので、「に」の前に置くと「独自なに決めた」となり成り立たない。"}, {"text": "独自だった", "is_correct": false, "explanation": "過去の断定形。「だった」で文が区切れるので、「学校が独自だった決めた」は「決めた」とつながらない。"}, {"text": "独自では", "is_correct": false, "explanation": "「では」の形。「に」の位置に「では」が入るので、「学校が独自では決めた」は文が成り立たない。"}], "correct_form": "独自", "base_form": "独自", "form_label": "語幹", "sentence_index": 7, "explanations": {"独自": "語幹。「に」などが付く前の形で、「独自に決めた」の「独自」にあたり、「学校が独自に決めた」の語幹として合う。", "独自な": "連体形（な）。名詞の前に付く形なので、「に」の前に置くと「独自なに決めた」となり成り立たない。", "独自だった": "過去の断定形。「だった」で文が区切れるので、「学校が独自だった決めた」は「決めた」とつながらない。", "独自では": "「では」の形。「に」の位置に「では」が入るので、「学校が独自では決めた」は文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51857, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「人気の絵師が担当する」で、担当する主体を示す正しい助詞。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すため、「絵師で担当する」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」では連体修飾になり、「担当する」と続かず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「絵師へ担当する」は成立しない。"}], "correct_answer": "が", "explanations": {"が": "「人気の絵師が担当する」で、担当する主体を示す正しい助詞。", "で": "「で」は手段を示すため、「絵師で担当する」は不自然。", "の": "「の」では連体修飾になり、「担当する」と続かず文が成り立たない。", "へ": "「へ」は方向を示すため、「絵師へ担当する」は成立しない。"}, "error_tags": {"で": "手段", "の": "連体", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51857, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「絵師が住んでいました」で、住む主体を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「絵師を住んでいました」は目的語になり、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「絵師で住んでいました」は不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」では動詞に続かず、「絵師の住んでいました」は文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「絵師が住んでいました」で、住む主体を示す正しい助詞。", "を": "「絵師を住んでいました」は目的語になり、意味が通らない。", "で": "「で」は手段や場所を示すため、「絵師で住んでいました」は不自然。", "の": "「の」では動詞に続かず、「絵師の住んでいました」は文が成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51857, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "絵をかく人。", "primary_collocate": null, "pronunciation": "えし", "ipa": "eɕi", "syllable_count": 2, "sentences": [{"text": "この絵師は、物語の登場人物を優しい色で描くのが上手です。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "この絵師[えし]は、物語[ものがたり]の登場人物[とうじょうじんぶつ]を優[やさ]しい色[いろ]で描[えが]くのが上手[じょうず]です。", "sentence_source": "generated"}, {"text": "ゲームのキャラクターは、人気の絵師が担当することになりました。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "ゲームのキャラクターは、人気[にんき]の絵師[えし]が担当[たんとう]することになりました。", "sentence_source": "generated"}, {"text": "絵師が描いた表紙のおかげで、その本はよく売れました。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "絵師[えし]が描[えが]いた表紙[ひょうし]のおかげで、その本[ほん]はよく売[う]れました。", "sentence_source": "generated"}, {"text": "公園で、一人の絵師が観光客の顔を描いていました。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "公園[こうえん]で、一人[ひとり]の絵師[えし]が観光客[かんこうきゃく]の顔[かお]を描[か]いていました。", "sentence_source": "generated"}, {"text": "彼女は有名な絵師に弟子入りして、絵の基本を学びました。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は有名[ゆうめい]な絵師[えし]に弟子入[でしい]りして、絵[え]の基本[きほん]を学[まな]びました。", "sentence_source": "generated"}, {"text": "絵師は一日中机に向かい、細かい線を丁寧に描き続けました。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "絵師[えし]は一日中[いちにちじゅう]机[つくえ]に向[む]かい、細[こま]かい線[せん]を丁寧[ていねい]に描[えが]き続[つづ]けました。", "sentence_source": "generated"}, {"text": "小説の挿絵は、若い絵師にお願いするつもりです。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "小説[しょうせつ]の挿絵[さしえ]は、若[わか]い絵師[えし]にお願[ねが]いするつもりです。", "sentence_source": "generated"}, {"text": "この町には昔、お寺の壁に絵を描く絵師が住んでいました。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "この町[まち]には昔[むかし]、お寺[てら]の壁[かべ]に絵[え]を描[か]く絵師[えし]が住[す]んでいました。", "sentence_source": "generated"}, {"text": "絵師が筆を置いたとき、大きな龍の絵がやっと完成しました。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "絵師[えし]が筆[ふで]を置[お]いたとき、大[おお]きな龍[りゅう]の絵[え]がやっと完成[かんせい]しました。", "sentence_source": "generated"}, {"text": "絵師になるためには、毎日たくさん練習することが大切です。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "絵師[えし]になるためには、毎日[まいにち]たくさん練習[れんしゅう]することが大切[たいせつ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絵師", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "絵を描く人一般（挿絵・キャラクター・似顔絵なども含む）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d75d5cb-9168-42ec-b5c5-aaf58a772dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51857, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絵師", "is_correct": true, "explanation": "絵を描く人を指し、物語の登場人物を色で描く人に当たる。"}, {"text": "役者", "is_correct": false, "explanation": "役者は演じる人で、色で絵を描く人の意味には合わない。"}, {"text": "作曲家", "is_correct": false, "explanation": "作曲家は曲を作る人で、絵を描く人の意味には合わない。"}, {"text": "彫刻家", "is_correct": false, "explanation": "彫刻家は立体を作る人で、色で描くという内容に合わない。"}], "explanations": {"絵師": "絵を描く人を指し、物語の登場人物を色で描く人に当たる。", "役者": "役者は演じる人で、色で絵を描く人の意味には合わない。", "作曲家": "作曲家は曲を作る人で、絵を描く人の意味には合わない。", "彫刻家": "彫刻家は立体を作る人で、色で描くという内容に合わない。"}, "sentence_index": 0, "correct_answer": "絵師"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は花を撮る絵師として、写真集を出版した。", "explanation": "ここは〈写真家〉の意味。絵師は絵をかく人で、写真を撮る人には合わない。"}, {"text": "彼は大理石を彫って天使の像を作る絵師だ。", "explanation": "ここは〈彫刻家〉の意味。絵師は絵をかく人で、石を彫って立体を作る人には合わない。"}, {"text": "彼は筆で半紙に文字を書く絵師として、賞を取った。", "explanation": "ここは〈書道家〉の意味。絵師は絵をかく人で、文字を書く人を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51857, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絵師", "is_correct": true, "explanation": "挿絵を描く人を指し、小説の挿絵を依頼する文に合う。"}, {"text": "歌手", "is_correct": false, "explanation": "歌手は歌う人で、挿絵を描く依頼の相手にはならない。"}, {"text": "大工", "is_correct": false, "explanation": "大工は建物を造る人で、挿絵を描く依頼の相手には合わない。"}, {"text": "船長", "is_correct": false, "explanation": "船長は船を指揮する人で、挿絵の依頼には合わない。"}], "explanations": {"絵師": "挿絵を描く人を指し、小説の挿絵を依頼する文に合う。", "歌手": "歌手は歌う人で、挿絵を描く依頼の相手にはならない。", "大工": "大工は建物を造る人で、挿絵を描く依頼の相手には合わない。", "船長": "船長は船を指揮する人で、挿絵の依頼には合わない。"}, "sentence_index": 6, "correct_answer": "絵師"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は音楽を作る絵師として、新しい曲を発表した。", "explanation": "ここは〈作曲家〉の意味。絵師は絵をかく人で、曲を作る人を指さないので合わない。"}, {"text": "彼女は料理を作る絵師として、人気の店を開いた。", "explanation": "ここは〈料理人〉の意味。絵師は絵をかく人で、料理を作る人には合わない。"}, {"text": "彼は家を設計する絵師として、大きな建物を手がけた。", "explanation": "ここは〈建築家〉の意味。絵師は絵をかく人で、建物を設計する人には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51857, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祭りの夜、若い絵師を屋台の前で似顔絵を描いていました。", "corrected_sentence": "祭りの夜、若い絵師が屋台の前で似顔絵を描いていました。", "error_description": "「絵師」に続く助詞が誤り。似顔絵を描く主体なので主語を示す「が」が正しく、「を」では目的語になり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51857, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昔の絵師の、紙と墨だけで風景を描いていました。", "corrected_sentence": "昔の絵師は、紙と墨だけで風景を描いていました。", "error_description": "「絵師」に続く助詞が誤り。「の」では連体修飾になり文が続かないため、主題を示す「は」（主語の「が」も可）に直す。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51858, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「絵師の描いた下絵」で、後ろの名詞を修飾する正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "「に」は描く相手を示せず、「絵師に描いた下絵」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すため、「絵師で描いた下絵」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「絵師へ描いた下絵」は成立しない。"}], "correct_answer": "の", "explanations": {"の": "「絵師の描いた下絵」で、後ろの名詞を修飾する正しい助詞。", "に": "「に」は描く相手を示せず、「絵師に描いた下絵」は不自然。", "で": "「で」は手段を示すため、「絵師で描いた下絵」は意味が通らない。", "へ": "「へ」は方向を示すため、「絵師へ描いた下絵」は成立しない。"}, "error_tags": {"に": "相手", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51858, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「絵師になりたい」で、なる対象を示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「絵師をなりたい」は目的語になり、「なりたい」と結びつかない。"}, {"text": "が", "is_correct": false, "explanation": "「絵師がなりたい」は主語になり、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「絵師でなりたい」は成立しない。"}], "correct_answer": "に", "explanations": {"に": "「絵師になりたい」で、なる対象を示す正しい助詞。", "を": "「絵師をなりたい」は目的語になり、「なりたい」と結びつかない。", "が": "「絵師がなりたい」は主語になり、意味が通らない。", "で": "「で」は手段や場所を示すため、「絵師でなりたい」は成立しない。"}, "error_tags": {"を": "目的語", "が": "主語", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51858, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "絵を描くことを職業とする人。特に、浮世絵や日本画などの伝統的な絵画を制作する専門家。", "primary_collocate": null, "pronunciation": "えし", "ipa": "eɕi", "syllable_count": 2, "sentences": [{"text": "制作は、絵師、彫師、摺師の役割分担によって進められます。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "制作[せいさく]は、絵師[えし]、彫師[ほりし]、摺師[すりし]の役割分担[やくわりぶんたん]によって進[すす]められます。", "sentence_source": "mined"}, {"text": "絵師の描いた下絵を彫師が版木に彫り、摺師が紙に印刷するという複雑な工程を経ます。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "絵師[えし]の描[えが]いた下絵[したえ]を彫師[ほりし]が版木[はんぎ]に彫[ほ]り、摺師[すりし]が紙[かみ]に印刷[いんさつ]するという複雑[ふくざつ]な工程[こうてい]を経[へ]ます。", "sentence_source": "mined"}, {"text": "浮世絵の世界では、人気のある絵師が役者や美人を描いて評判になりました。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "浮世絵[うきよえ]の世界[せかい]では、人気[にんき]のある絵師[えし]が役者[やくしゃ]や美人[びじん]を描[えが]いて評判[ひょうばん]になりました。", "sentence_source": "generated"}, {"text": "江戸時代の絵師は、注文を受けて下絵を描き、版元に渡していました。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "江戸時代[えどじだい]の絵師[えし]は、注文[ちゅうもん]を受[う]けて下絵[したえ]を描[か]き、版元[はんもと]に渡[わた]していました。", "sentence_source": "generated"}, {"text": "この絵師は、風景を得意とする日本画の専門家で、弟子も多くいます。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "この絵師[えし]は、風景[ふうけい]を得意[とくい]とする日本画[にほんが]の専門家[せんもんか]で、弟子[でし]も多[おお]くいます。", "sentence_source": "generated"}, {"text": "絵師が筆で細い線を描くと、美人の髪の毛まで生き生きと見えます。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "絵師[えし]が筆[ふで]で細[ほそ]い線[せん]を描[えが]くと、美人[びじん]の髪[かみ]の毛[け]まで生[い]き生[い]きと見[み]えます。", "sentence_source": "generated"}, {"text": "有名な絵師の作品なので、美術館では特別な部屋に飾られています。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "有名[ゆうめい]な絵師[えし]の作品[さくひん]なので、美術館[びじゅつかん]では特別[とくべつ]な部屋[へや]に飾[かざ]られています。", "sentence_source": "generated"}, {"text": "彼は子どものころから絵が好きで、将来は伝統的な絵師になりたいと思っています。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "彼[かれ]は子[こ]どものころから絵[え]が好[す]きで、将来[しょうらい]は伝統的[でんとうてき]な絵師[えし]になりたいと思[おも]っています。", "sentence_source": "generated"}, {"text": "絵師の技術が高かったので、彫師は一本の線も間違えないよう慎重に彫りました。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "絵師[えし]の技術[ぎじゅつ]が高[たか]かったので、彫師[ほりし]は一本[いっぽん]の線[せん]も間違[まちが]えないよう慎重[しんちょう]に彫[ほ]りました。", "sentence_source": "generated"}, {"text": "私の祖父は日本画の絵師で、毎日朝から筆を握っていました。", "target_word": "絵師", "complexity_tier": "T3", "furigana": "私[わたし]の祖父[そふ]は日本画[にほんが]の絵師[えし]で、毎日[まいにち]朝[あさ]から筆[ふで]を握[にぎ]っていました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "絵師", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "浮世絵・日本画など伝統絵画を専門に描く職業画家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T3: 5 words above tier T3 (max 3): 下絵 (Zipf 2.67), 彫 (Zipf 2.88), 版木 (Zipf 2.03), 彫り (Zipf 3.17), 摺 (Zipf 2.54)']::text[], '9d75d5cb-9168-42ec-b5c5-aaf58a772dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51858, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "絵師", "is_correct": true, "explanation": "役割分担の一つとして、絵を描く担当者を表す正しい語。"}, {"text": "版木", "is_correct": false, "explanation": "版木は彫る材料で、役割分担の担当者としては並べられない。"}, {"text": "墨", "is_correct": false, "explanation": "墨は描く材料で、役割分担の担当者を表す語ではない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は印刷の材料で、役割分担の担当者としては入らない。"}], "explanations": {"絵師": "役割分担の一つとして、絵を描く担当者を表す正しい語。", "版木": "版木は彫る材料で、役割分担の担当者としては並べられない。", "墨": "墨は描く材料で、役割分担の担当者を表す語ではない。", "紙": "紙は印刷の材料で、役割分担の担当者としては入らない。"}, "sentence_index": 0, "correct_answer": "絵師"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は版木を彫る絵師として、力強い線を刻んだ。", "explanation": "ここは〈彫師〉の意味。絵師は描く人を指し、版木を彫る人には使えない。"}, {"text": "彼は紙に色を重ねて刷る絵師として働いた。", "explanation": "ここは〈摺師〉の意味。絵師は刷る作業を担当しないので、刷り師の役割には合わない。"}, {"text": "彼は髪を整える絵師として、美容院で働いている。", "explanation": "ここは〈美容師〉の意味。絵師は絵をかく人で、髪を整える人には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51858, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "絵師", "is_correct": true, "explanation": "有名な画家を表し、その作品が美術館に飾られる文脈に合う。"}, {"text": "額縁", "is_correct": false, "explanation": "額縁は作品を入れる枠で、作者を表す語としては合わない。"}, {"text": "絵具", "is_correct": false, "explanation": "絵具は描く材料で、「有名な絵具の作品」は作者を表さない。"}, {"text": "硯", "is_correct": false, "explanation": "硯は墨をする道具で、作者を表す語としては合わない。"}], "explanations": {"絵師": "有名な画家を表し、その作品が美術館に飾られる文脈に合う。", "額縁": "額縁は作品を入れる枠で、作者を表す語としては合わない。", "絵具": "絵具は描く材料で、「有名な絵具の作品」は作者を表さない。", "硯": "硯は墨をする道具で、作者を表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "絵師"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は山を撮る絵師として、写真展を開いた。", "explanation": "ここは〈写真家〉の意味。絵師は筆で描く人を指し、写真を撮る人には合わない。"}, {"text": "彼は石を彫って像を作る絵師だった。", "explanation": "ここは〈彫刻家〉の意味。絵師は絵を描く人で、石や木で立体を作る人には合わない。"}, {"text": "彼は墨で文字を書く絵師として名を残した。", "explanation": "ここは〈書道家〉の意味。絵師は絵を描く人で、文字を書く人を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51858, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "浮世絵では、絵師を下絵を描きます。", "corrected_sentence": "浮世絵では、絵師が下絵を描きます。", "error_description": "「絵師」に続く助詞が誤り。下絵を描くのは絵師なので主語を示す「が」が正しく、「を」では目的語になり文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51858, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "江戸の版元は、絵師で下絵を注文していました。", "corrected_sentence": "江戸の版元は、絵師に下絵を注文していました。", "error_description": "「絵師」に続く助詞が誤り。注文の相手を示すには「に」が正しく、「で」では手段や場所の意味になり不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51859, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「制作は、思ったより時間がかかります」と主題を示し、後ろで時間の話題を述べる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「制作を、時間がかかります」では文の主題にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、時間がかかるという述べ方には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「制作の、時間がかかります」と続けると文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「制作は、思ったより時間がかかります」と主題を示し、後ろで時間の話題を述べる。", "を": "「を」は目的語を示すが、「制作を、時間がかかります」では文の主題にならない。", "へ": "「へ」は方向を示すので、時間がかかるという述べ方には合わない。", "の": "「制作の、時間がかかります」と続けると文が成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51859, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「制作で」と場面を示し、制作の最中に形がゆがんだという文脈に合う。"}, {"text": "に", "is_correct": false, "explanation": "「制作に」は時点を示すが、形がゆがんだ原因の説明としては自然につながらない。"}, {"text": "と", "is_correct": false, "explanation": "「制作と」は並列を示すので、形が崩れた理由の説明にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を続けるだけで、「制作の、形が」と文が続かず不自然。"}], "correct_answer": "で", "explanations": {"で": "「制作で」と場面を示し、制作の最中に形がゆがんだという文脈に合う。", "に": "「制作に」は時点を示すが、形がゆがんだ原因の説明としては自然につながらない。", "と": "「制作と」は並列を示すので、形が崩れた理由の説明にはならない。", "の": "「の」は名詞を続けるだけで、「制作の、形が」と文が続かず不自然。"}, "error_tags": {"に": "時点", "と": "並列", "の": "連体"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51859, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ものをつくること。", "primary_collocate": null, "pronunciation": "せいさく", "ipa": "seːsakɯ", "syllable_count": 4, "sentences": [{"text": "夏休みの宿題で、木の箱の制作に挑戦しました。", "target_word": "制作", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの宿題[しゅくだい]で、木[き]の箱[はこ]の制作[せいさく]に挑戦[ちょうせん]しました。", "sentence_source": "generated"}, {"text": "手作りの人形の制作は、思ったより時間がかかります。", "target_word": "制作", "complexity_tier": "T3", "furigana": "手作[てづく]りの人形[にんぎょう]の制作[せいさく]は、思[おも]ったより時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "彼女はアクセサリーの制作が趣味で、休日はいつも部屋にこもっています。", "target_word": "制作", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はアクセサリーの制作[せいさく]が趣味[しゅみ]で、休日[きゅうじつ]はいつも部屋[へや]にこもっています。", "sentence_source": "generated"}, {"text": "工作教室では、子どもたちが紙で動物の制作を楽しみました。", "target_word": "制作", "complexity_tier": "T3", "furigana": "工作教室[こうさくきょうしつ]では、子[こ]どもたちが紙[かみ]で動物[どうぶつ]の制作[せいさく]を楽[たの]しみました。", "sentence_source": "generated"}, {"text": "家具の制作には、正確に測る技術が必要です。", "target_word": "制作", "complexity_tier": "T3", "furigana": "家具[かぐ]の制作[せいさく]には、正確[せいかく]に測[はか]る技術[ぎじゅつ]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "制作するときは部屋が散らかるので、床に新聞紙を敷きます。", "target_word": "制作", "complexity_tier": "T3", "furigana": "制作[せいさく]するときは部屋[へや]が散[ち]らかるので、床[ゆか]に新聞紙[しんぶんし]を敷[し]きます。", "sentence_source": "generated"}, {"text": "先生は、制作の手順を黒板にわかりやすく書きました。", "target_word": "制作", "complexity_tier": "T3", "furigana": "先生[せんせい]は、制作[せいさく]の手順[てじゅん]を黒板[こくばん]にわかりやすく書[か]きました。", "sentence_source": "generated"}, {"text": "初めての陶器の制作で、形がゆがんでしまいました。", "target_word": "制作", "complexity_tier": "T3", "furigana": "初[はじ]めての陶器[とうき]の制作[せいさく]で、形[かたち]がゆがんでしまいました。", "sentence_source": "generated"}, {"text": "兄は模型の制作に夢中で、食事の時間も忘れていました。", "target_word": "制作", "complexity_tier": "T3", "furigana": "兄[あに]は模型[もけい]の制作[せいさく]に夢中[むちゅう]で、食事[しょくじ]の時間[じかん]も忘[わす]れていました。", "sentence_source": "generated"}, {"text": "制作した作品を友達に見せて、感想を聞きました。", "target_word": "制作", "complexity_tier": "T3", "furigana": "制作[せいさく]した作品[さくひん]を友達[ともだち]に見[み]せて、感想[かんそう]を聞[き]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "制作", "label": "基本形"}, {"form": "制作する", "label": "動詞（する）"}, {"form": "制作した", "label": "過去形"}, {"form": "制作して", "label": "て形"}], "register": "丁寧", "sense_fingerprint": "手作業で品物や工作物などをつくること一般", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: contains vocabulary far above tier T2: 散らかる (Zipf 1.94)']::text[], '9d75d5cb-9168-42ec-b5c5-aaf58a772dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51859, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制作", "is_correct": true, "explanation": "「木の箱の制作に挑戦しました」の目的語として、ものを手でつくる意味で合う。"}, {"text": "作曲", "is_correct": false, "explanation": "作曲は曲をつくることで、木の箱をつくる宿題の文脈には合わない。"}, {"text": "脱水", "is_correct": false, "explanation": "脱水は水分を抜くことで、工作の挑戦とは結びつかない。"}, {"text": "点滴", "is_correct": false, "explanation": "点滴は薬液を体に入れる医療行為で、夏休みの宿題の文脈には合わない。"}], "explanations": {"制作": "「木の箱の制作に挑戦しました」の目的語として、ものを手でつくる意味で合う。", "作曲": "作曲は曲をつくることで、木の箱をつくる宿題の文脈には合わない。", "脱水": "脱水は水分を抜くことで、工作の挑戦とは結びつかない。", "点滴": "点滴は薬液を体に入れる医療行為で、夏休みの宿題の文脈には合わない。"}, "sentence_index": 0, "correct_answer": "制作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもの発表会の進行を制作して、先生に確認してもらいました。", "explanation": "ここは〈進行〉の意味。行事の流れを進めて管理することは進行と言い、制作は何かをつくることを指すので合わない。"}, {"text": "壊れた椅子を制作して、もとどおりにしました。", "explanation": "ここは〈修理〉の意味。壊れたものを直すことは修理と言い、制作は新たにものをつくることを指すので合わない。"}, {"text": "古い机を制作して、部品に分けました。", "explanation": "ここは〈解体〉の意味。ばらして部品にすることは解体と言い、制作は新しくつくることを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51859, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制作", "is_correct": true, "explanation": "「制作の手順」として、ものをつくる工程の手順を指し、黒板に書く内容に合う。"}, {"text": "睡眠", "is_correct": false, "explanation": "睡眠は眠ることで、黒板に書く作業の手順とは結びつかない。"}, {"text": "停電", "is_correct": false, "explanation": "停電は電気が止まる現象で、授業で手順を書く文脈には合わない。"}, {"text": "通学", "is_correct": false, "explanation": "通学は学校へ通うことで、手順を黒板に書く内容とは合わない。"}], "explanations": {"制作": "「制作の手順」として、ものをつくる工程の手順を指し、黒板に書く内容に合う。", "睡眠": "睡眠は眠ることで、黒板に書く作業の手順とは結びつかない。", "停電": "停電は電気が止まる現象で、授業で手順を書く文脈には合わない。", "通学": "通学は学校へ通うことで、手順を黒板に書く内容とは合わない。"}, "sentence_index": 6, "correct_answer": "制作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "床に散らばった紙くずを制作して、ごみ箱に捨てました。", "explanation": "ここは〈掃除〉の意味。散らかったものを片づけることは掃除と言い、制作は新たにつくる意味なので合わない。"}, {"text": "洗った器を日陰で制作しました。", "explanation": "ここは〈乾燥〉の意味。濡れたものを乾かすことは乾燥と言い、制作は何かをつくることを指すので合わない。"}, {"text": "先生は夜遅くまで答案を制作し、翌日クラスに返しました。", "explanation": "ここは〈採点〉の意味。答案に点数をつけることは採点と言い、制作は作品をつくることに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51859, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "木の箱を制作されるため、材料を買いに行きました。", "corrected_sentence": "木の箱を制作するため、材料を買いに行きました。", "error_description": "「制作する」は他動詞なので「木の箱を制作する」が正しい。「制作される」は受身で、「木の箱が制作される」と言うべきところを「木の箱を」のまま使っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51859, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "陶器の制作を必要な道具をそろえます。", "corrected_sentence": "陶器の制作に必要な道具をそろえます。", "error_description": "「必要」は「〜に必要」の形で「に」を取るので、「制作に必要な道具」が正しい。「制作を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51860, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「必要」は「〜に必要」の形で「に」を取り、「には」で条件を示す。"}, {"text": "を", "is_correct": false, "explanation": "「必要」は目的語の「を」を取らないので、「必要です」の前に「を」を置くと文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「必要」が求める対象を表す場面には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしを結ぶだけで、「制作の、多くの人と」と続かず不自然。"}], "correct_answer": "に", "explanations": {"に": "「必要」は「〜に必要」の形で「に」を取り、「には」で条件を示す。", "を": "「必要」は目的語の「を」を取らないので、「必要です」の前に「を」を置くと文が成り立たない。", "へ": "「へ」は方向を示すが、「必要」が求める対象を表す場面には合わない。", "の": "「の」は名詞どうしを結ぶだけで、「制作の、多くの人と」と続かず不自然。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51860, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「制作の途中で」と続き、「の」で作業の途中という状態を示す。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「制作と途中で計画が変わり」では意味がつながらない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は時点や相手を示すが、「制作に途中で」と続けると不自然になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、「制作で途中で」では文の流れが成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「制作の途中で」と続き、「の」で作業の途中という状態を示す。", "と": "「と」は並列や相手を示すので、「制作と途中で計画が変わり」では意味がつながらない。", "に": "「に」は時点や相手を示すが、「制作に途中で」と続けると不自然になる。", "で": "「で」は場所や手段を示すが、「制作で途中で」では文の流れが成り立たない。"}, "error_tags": {"と": "並列", "に": "時点", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51860, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "作品や物品を作り出すこと。特に、芸術作品や出版物などを計画的に作り上げること。", "primary_collocate": null, "pronunciation": "せいさく", "ipa": "seːsakɯ", "syllable_count": 4, "sentences": [{"text": "制作は、絵師、彫師、摺師の役割分担によって進められます。", "target_word": "制作", "complexity_tier": "T3", "furigana": "制作[せいさく]は、絵師[えし]、彫師[ほりし]、摺師[すりし]の役割分担[やくわりぶんたん]によって進[すす]められます。", "sentence_source": "mined"}, {"text": "映画の制作には、多くの人と長い時間が必要です。", "target_word": "制作", "complexity_tier": "T3", "furigana": "映画[えいが]の制作[せいさく]には、多[おお]くの人[ひと]と長[なが]い時間[じかん]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "この雑誌の制作は、編集者とデザイナーが協力して進めています。", "target_word": "制作", "complexity_tier": "T3", "furigana": "この雑誌[ざっし]の制作[せいさく]は、編集者[へんしゅうしゃ]とデザイナーが協力[きょうりょく]して進[すす]めています。", "sentence_source": "generated"}, {"text": "彼は新しい彫刻の制作に半年かけて取り組みました。", "target_word": "制作", "complexity_tier": "T3", "furigana": "彼[かれ]は新[あたら]しい彫刻[ちょうこく]の制作[せいさく]に半年[はんとし]かけて取[と]り組[く]みました。", "sentence_source": "generated"}, {"text": "展覧会に向けて、学生たちは作品の制作に集中しています。", "target_word": "制作", "complexity_tier": "T3", "furigana": "展覧会[てんらんかい]に向[む]けて、学生[がくせい]たちは作品[さくひん]の制作[せいさく]に集中[しゅうちゅう]しています。", "sentence_source": "generated"}, {"text": "番組の制作が遅れたので、放送は来月に延期されました。", "target_word": "制作", "complexity_tier": "T3", "furigana": "番組[ばんぐみ]の制作[せいさく]が遅[おく]れたので、放送[ほうそう]は来月[らいげつ]に延期[えんき]されました。", "sentence_source": "generated"}, {"text": "絵本の制作を担当した画家は、色の選び方にとても気を使いました。", "target_word": "制作", "complexity_tier": "T3", "furigana": "絵本[えほん]の制作[せいさく]を担当[たんとう]した画家[がか]は、色[いろ]の選[えら]び方[かた]にとても気[き]を使[つか]いました。", "sentence_source": "generated"}, {"text": "制作の途中で計画が変わり、完成が少し遅れてしまいました。", "target_word": "制作", "complexity_tier": "T3", "furigana": "制作[せいさく]の途中[とちゅう]で計画[けいかく]が変[か]わり、完成[かんせい]が少[すこ]し遅[おく]れてしまいました。", "sentence_source": "generated"}, {"text": "このアニメは三年がかりで制作されました。", "target_word": "制作", "complexity_tier": "T3", "furigana": "このアニメは三年[さんねん]がかりで制作[せいさく]されました。", "sentence_source": "generated"}, {"text": "記念の写真集を制作するため、出版社は資金を集めています。", "target_word": "制作", "complexity_tier": "T3", "furigana": "記念[きねん]の写真集[しゃしんしゅう]を制作[せいさく]するため、出版社[しゅっぱんしゃ]は資金[しきん]を集[あつ]めています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "制作", "label": "基本形"}, {"form": "制作する", "label": "動詞（する）"}, {"form": "制作した", "label": "過去形"}, {"form": "制作される", "label": "受身形"}], "register": "丁寧", "sense_fingerprint": "芸術作品・映像・出版物などを計画的に作り上げること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: 4 words above tier T2 (max 3): 絵師 (Zipf 3.68), 彫 (Zipf 2.88), 摺 (Zipf 2.54), 分担 (Zipf 3.64)']::text[], '9d75d5cb-9168-42ec-b5c5-aaf58a772dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51860, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制作", "is_correct": true, "explanation": "「制作は、絵師、彫師、摺師の役割分担によって進められます」の主語として、作品をつくる工程を指すので文脈に合う。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏は音楽を奏でることで、絵師・彫師・摺師が分担して進める工程とは結びつかない。"}, {"text": "測量", "is_correct": false, "explanation": "測量は土地や距離を測る作業で、版画づくりの工程には当てはまらない。"}, {"text": "清掃", "is_correct": false, "explanation": "清掃は掃除のことで、役割分担によって作品を仕上げていく流れとは合わない。"}], "explanations": {"制作": "「制作は、絵師、彫師、摺師の役割分担によって進められます」の主語として、作品をつくる工程を指すので文脈に合う。", "演奏": "演奏は音楽を奏でることで、絵師・彫師・摺師が分担して進める工程とは結びつかない。", "測量": "測量は土地や距離を測る作業で、版画づくりの工程には当てはまらない。", "清掃": "清掃は掃除のことで、役割分担によって作品を仕上げていく流れとは合わない。"}, "sentence_index": 0, "correct_answer": "制作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月の社員旅行を制作して、上司に相談しました。", "explanation": "ここは〈企画〉の意味。旅行や催しの計画を立てることは企画と言い、制作は作品や物品をつくることを指すので合わない。"}, {"text": "この工場では毎月三千台の自動車を制作しています。", "explanation": "ここは〈製造〉の意味。工場で大量に生産する場合は製造と言い、制作は一点ものの作品に使う。"}, {"text": "エンジンの温度を制作するセンサーが故障しました。", "explanation": "ここは〈制御〉の意味。温度などを調節する場合は制御と言い、制作は作品や物をつくることを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51860, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制作", "is_correct": true, "explanation": "「絵本の制作を担当した」の目的語として、絵本をつくる工程を指し、色の選び方に気を使う文脈に合う。"}, {"text": "通勤", "is_correct": false, "explanation": "通勤は職場へ通うことで、絵本の仕事を担当する文脈とは結びつかない。"}, {"text": "睡眠", "is_correct": false, "explanation": "睡眠は眠ることで、担当した仕事の内容とは関係がない。"}, {"text": "停電", "is_correct": false, "explanation": "停電は電気が止まることで、色の選び方に気を使う絵本の仕事には合わない。"}], "explanations": {"制作": "「絵本の制作を担当した」の目的語として、絵本をつくる工程を指し、色の選び方に気を使う文脈に合う。", "通勤": "通勤は職場へ通うことで、絵本の仕事を担当する文脈とは結びつかない。", "睡眠": "睡眠は眠ることで、担当した仕事の内容とは関係がない。", "停電": "停電は電気が止まることで、色の選び方に気を使う絵本の仕事には合わない。"}, "sentence_index": 6, "correct_answer": "制作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は夜遅くまで答案を制作し、翌日クラスに返しました。", "explanation": "ここは〈採点〉の意味。答案に点数をつけることは採点と言い、制作は作品をつくる場合に使う。"}, {"text": "父は毎朝、車を制作して出勤します。", "explanation": "ここは〈運転〉の意味。車を操って走らせることは運転と言い、制作は作品をつくることを指すので合わない。"}, {"text": "新しい薬の制作には十年以上かかります。", "explanation": "ここは〈開発〉の意味。新薬や技術を新たに生み出すことは開発と言い、制作は芸術作品や映像などに使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51860, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ドラマを制作されるため、多くの人が集まりました。", "corrected_sentence": "ドラマを制作するため、多くの人が集まりました。", "error_description": "「制作する」は他動詞なので「ドラマを制作する」が正しい。「制作される」は受身で、「ドラマが制作される」とすべきところを「ドラマを」のまま使っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51860, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "番組の制作を関わる人は、朝早くから準備します。", "corrected_sentence": "番組の制作に関わる人は、朝早くから準備します。", "error_description": "「関わる」は「〜に関わる」の形で「に」を取るので、「制作」の後は「に」が正しい。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51861, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51861, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "名詞を修飾する「の」。「彫り師の仕事場」で、彫り師の職場を表し、文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「彫り師を仕事場には」となり、後ろの「には」と続けると文の流れに合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「彫り師へ仕事場には」となり、名詞同士をつなぐ用法として成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "帰着点や相手を示す。「彫り師に仕事場には」となり、名詞同士を結ぶ文の意味に合わない。"}], "correct_answer": "の", "explanations": {"の": "名詞を修飾する「の」。「彫り師の仕事場」で、彫り師の職場を表し、文の意味に合う。", "を": "目的語を示す。「彫り師を仕事場には」となり、後ろの「には」と続けると文の流れに合わない。", "へ": "方向を示す。「彫り師へ仕事場には」となり、名詞同士をつなぐ用法として成り立たない。", "に": "帰着点や相手を示す。「彫り師に仕事場には」となり、名詞同士を結ぶ文の意味に合わない。"}, "error_tags": {"を": "目的語を示す", "へ": "方向を示す", "に": "帰着点や相手を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51861, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "絵を木の板に彫る職人。", "primary_collocate": null, "pronunciation": "ほりし", "ipa": "horiɕi", "syllable_count": 3, "sentences": [{"text": "彫り師は、絵を木の板に丁寧に彫ります。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "彫[ほ]り師[し]は、絵[え]を木[き]の板[いた]に丁寧[ていねい]に彫[ほ]ります。", "sentence_source": "generated"}, {"text": "祖父は彫り師で、毎日小さなナイフを使っている。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "祖父[そふ]は彫[ほ]り師[し]で、毎日[まいにち]小[ちい]さなナイフを使[つか]っている。", "sentence_source": "generated"}, {"text": "彫り師の手は、細かい線もまちがえずに動く。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "彫[ほ]り師[し]の手[て]は、細[こま]かい線[せん]もまちがえずに動[うご]く。", "sentence_source": "generated"}, {"text": "彫り師になりたくて、弟子入りした。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "彫[ほ]り師[し]になりたくて、弟子入[でしい]りした。", "sentence_source": "generated"}, {"text": "絵を板に彫る彫り師は、とても集中している。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "絵[え]を板[いた]に彫[ほ]る彫[ほ]り師[し]は、とても集中[しゅうちゅう]している。", "sentence_source": "generated"}, {"text": "この板は、有名な彫り師が三日かけて彫った。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "この板[いた]は、有名[ゆうめい]な彫[ほ]り師[し]が三日[みっか]かけて彫[ほ]った。", "sentence_source": "generated"}, {"text": "彫り師が使う道具は、刃の形がいろいろある。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "彫[ほ]り師[し]が使[つか]う道具[どうぐ]は、刃[は]の形[かたち]がいろいろある。", "sentence_source": "generated"}, {"text": "彫り師の仕事場には、木のにおいが広がっている。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "彫[ほ]り師[し]の仕事場[しごとば]には、木[き]のにおいが広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "木が好きな彼は、将来は彫り師になるのが夢だ。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "木[き]が好[す]きな彼[かれ]は、将来[しょうらい]は彫[ほ]り師[し]になるのが夢[ゆめ]だ。", "sentence_source": "generated"}, {"text": "彫り師は、まちがえると板を直せないので慎重だ。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "彫[ほ]り師[し]は、まちがえると板[いた]を直[なお]せないので慎重[しんちょう]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "彫り師", "label": "基本形"}, {"form": "彫り師の", "label": "連体修飾（の）"}, {"form": "彫り師が", "label": "主格"}, {"form": "彫り師に", "label": "与格"}], "register": "neutral", "sense_fingerprint": "絵を木の板に彫る職人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb6837b5-37ea-42d1-91e7-d13681740b4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51861, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彫り師", "is_correct": true, "explanation": "絵を木の板に彫る職人を指すので、文の主語として合う。"}, {"text": "漁師", "is_correct": false, "explanation": "魚をとる人を指す。木の板に絵を彫る文には合わない。"}, {"text": "歌手", "is_correct": false, "explanation": "歌をうたう人を指す。絵を彫る仕事とは関係がない。"}, {"text": "郵便配達員", "is_correct": false, "explanation": "手紙や荷物を届ける人を指す。絵を彫る文の主語にはならない。"}], "explanations": {"彫り師": "絵を木の板に彫る職人を指すので、文の主語として合う。", "漁師": "魚をとる人を指す。木の板に絵を彫る文には合わない。", "歌手": "歌をうたう人を指す。絵を彫る仕事とは関係がない。", "郵便配達員": "手紙や荷物を届ける人を指す。絵を彫る文の主語にはならない。"}, "sentence_index": 0, "correct_answer": "彫り師"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は木で家具の枠を組む彫り師だ。", "explanation": "ここは〈大工〉の意味。木で家具の枠を組む仕事は大工の仕事で、彫り師は絵を木の板に彫る人なので合わない。"}, {"text": "この会社の彫り師は、紙に文字を印刷している。", "explanation": "ここは〈印刷工〉の意味。紙に文字を刷るのは印刷工で、彫り師は木の板に絵を彫る職人なので合わない。"}, {"text": "彼は粘土で器を形作る彫り師だ。", "explanation": "ここは〈陶芸家〉の意味。粘土で器を作るのは陶芸家で、彫り師は木の板に絵を彫る人なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51861, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彫り師", "is_correct": true, "explanation": "刃の形がいろいろある道具を使う職人で、文の主語として合う。"}, {"text": "写真家", "is_correct": false, "explanation": "写真を撮る人で、刃の形がいろいろある道具は使わない。"}, {"text": "薬剤師", "is_correct": false, "explanation": "薬を調合する人で、刃の形の道具とは結びつかない。"}, {"text": "作曲家", "is_correct": false, "explanation": "曲を作る人で、刃の形がいろいろある道具を使う文には合わない。"}], "explanations": {"彫り師": "刃の形がいろいろある道具を使う職人で、文の主語として合う。", "写真家": "写真を撮る人で、刃の形がいろいろある道具は使わない。", "薬剤師": "薬を調合する人で、刃の形の道具とは結びつかない。", "作曲家": "曲を作る人で、刃の形がいろいろある道具を使う文には合わない。"}, "sentence_index": 6, "correct_answer": "彫り師"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は漆を塗る彫り師で、塗り直しが得意だ。", "explanation": "ここは〈塗師〉の意味。漆を塗って仕上げる職人は塗師で、彫り師は木に彫る人なので合わない。"}, {"text": "彼は写真を現像する彫り師で、暗室にこもって仕事をしている。", "explanation": "ここは〈写真現像師〉の意味。写真を現像する人は別の職で、彫り師は木の板に絵を彫る職人なので合わない。"}, {"text": "彼は彫り師の顔立ちで、目鼻がはっきりしている。", "explanation": "ここは〈彫りが深い〉（顔の凹凸が深い）の意味。彫り師は職業を指す語で、顔立ちの特徴には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51861, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は彫り師を道具を大切に使う。", "corrected_sentence": "父は彫り師の道具を大切に使う。", "error_description": "名詞「彫り師」が「道具」を修飾するときは「の」が必要。「を」は目的語を示すので、「彫り師を道具」は文として合わない。正しくは「彫り師の道具」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51861, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は彫り師な、道具を毎日手入れしている。", "corrected_sentence": "祖母は彫り師で、道具を毎日手入れしている。", "error_description": "名詞「彫り師」を述語にするときは「で」（だの連用形）が必要。「な」は形状詞の形で、名詞の彫り師には付かない。正しくは「彫り師で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
