INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51862, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "彫り師とは、浮世絵などの版画制作において、絵師が描いた下絵を木版に彫り込む職人のことです。", "primary_collocate": null, "pronunciation": "ほりし", "ipa": "horiɕi", "syllable_count": 3, "sentences": [{"text": "浮世絵は、絵師、彫り師、摺り師の三人で作られた。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "浮世絵[うきよえ]は、絵師[えし]、彫[ほ]り師[し]、摺[す]り師[し]の三人[さんにん]で作[つく]られた。", "sentence_source": "generated"}, {"text": "彫り師は、絵師の下絵を桜の板に彫り込んでいく。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "彫[ほ]り師[し]は、絵師[えし]の下絵[したえ]を桜[さくら]の板[いた]に彫[ほ]り込[こ]んでいく。", "sentence_source": "generated"}, {"text": "髪の毛ほどの細い線を彫る技は、優れた彫り師にしかできない。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "髪[かみ]の毛[け]ほどの細[ほそ]い線[せん]を彫[ほ]る技[わざ]は、優[すぐ]れた彫[ほ]り師[し]にしかできない。", "sentence_source": "generated"}, {"text": "江戸時代の彫り師は、版元に雇われて仕事をした。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "江戸時代[えどじだい]の彫[ほ]り師[し]は、版元[はんもと]に雇[やと]われて仕事[しごと]をした。", "sentence_source": "generated"}, {"text": "彫り師の腕が悪いと、絵師の線の美しさは出ない。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "彫[ほ]り師[し]の腕[うで]が悪[わる]いと、絵師[えし]の線[せん]の美[うつく]しさは出[で]ない。", "sentence_source": "generated"}, {"text": "展示会で、彫り師が使った彫刻刀と版木を見た。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "展示会[てんじかい]で、彫[ほ]り師[し]が使[つか]った彫刻刀[ちょうこくとう]と版木[はんぎ]を見[み]た。", "sentence_source": "generated"}, {"text": "現代でも、浮世絵の復刻をおこなう彫り師がいる。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "現代[げんだい]でも、浮世絵[うきよえ]の復刻[ふっこく]をおこなう彫[ほ]り師[し]がいる。", "sentence_source": "generated"}, {"text": "彫り師は下絵を裏返して版木に貼り、彫り進める。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "彫[ほ]り師[し]は下絵[したえ]を裏返[うらがえ]して版木[はんぎ]に貼[は]り、彫[ほ]り進[すす]める。", "sentence_source": "generated"}, {"text": "絵師と彫り師の協力で、色あざやかな版画ができた。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "絵師[えし]と彫[ほ]り師[し]の協力[きょうりょく]で、色[いろ]あざやかな版画[はんが]ができた。", "sentence_source": "generated"}, {"text": "北斎の絵も、彫り師の技術があって世に広まった。", "target_word": "彫り師", "complexity_tier": "T3", "furigana": "北斎[ほくさい]の絵[え]も、彫[ほ]り師[し]の技術[ぎじゅつ]があって世[よ]に広[ひろ]まった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "彫り師", "label": "基本形"}, {"form": "彫り師の", "label": "連体形（の）"}, {"form": "彫り師は", "label": "主題"}, {"form": "彫り師と", "label": "並列"}], "register": "neutral", "sense_fingerprint": "浮世絵版画で、絵師の下絵を版木に彫る職人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb6837b5-37ea-42d1-91e7-d13681740b4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51862, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彫り師", "is_correct": true, "explanation": "版木に絵を彫る職人で、浮世絵を作った三人の一人として文に合う。"}, {"text": "陶工", "is_correct": false, "explanation": "陶器を作る職人で、浮世絵の制作には関わらないので合わない。"}, {"text": "染物師", "is_correct": false, "explanation": "布を染める職人で、浮世絵の制作の担い手ではないので合わない。"}, {"text": "漁師", "is_correct": false, "explanation": "魚をとる人で、浮世絵の制作とは無関係なので合わない。"}], "explanations": {"彫り師": "版木に絵を彫る職人で、浮世絵を作った三人の一人として文に合う。", "陶工": "陶器を作る職人で、浮世絵の制作には関わらないので合わない。", "染物師": "布を染める職人で、浮世絵の制作の担い手ではないので合わない。", "漁師": "魚をとる人で、浮世絵の制作とは無関係なので合わない。"}, "sentence_index": 0, "correct_answer": "彫り師"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "江戸時代の彫り師は、紙に色を重ねて刷る仕事をした。", "explanation": "ここは〈摺り師〉の意味。紙に色を重ねて刷るのは摺り師で、彫り師は版木に絵を彫る人なので合わない。"}, {"text": "江戸時代の彫り師は、下絵を描いて版元に渡した。", "explanation": "ここは〈絵師〉の意味。下絵を描くのは絵師で、彫り師は描かれた下絵を版木に彫る人なので合わない。"}, {"text": "江戸時代の彫り師は、川で網を打って魚を獲っていた。", "explanation": "ここは〈漁師〉の意味。魚を獲る仕事は漁師で、彫り師は版木に絵を彫る職人なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51862, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彫り師", "is_correct": true, "explanation": "浮世絵の復刻を行う、版木を彫る職人で、文の主語として合う。"}, {"text": "鍛冶師", "is_correct": false, "explanation": "金属を打って道具を作る職人で、浮世絵の復刻には関わらないので合わない。"}, {"text": "庭師", "is_correct": false, "explanation": "庭木を手入れする人で、版画の復刻とは関係がないので合わない。"}, {"text": "歌手", "is_correct": false, "explanation": "歌をうたう人で、浮世絵の復刻を行う文には合わない。"}], "explanations": {"彫り師": "浮世絵の復刻を行う、版木を彫る職人で、文の主語として合う。", "鍛冶師": "金属を打って道具を作る職人で、浮世絵の復刻には関わらないので合わない。", "庭師": "庭木を手入れする人で、版画の復刻とは関係がないので合わない。", "歌手": "歌をうたう人で、浮世絵の復刻を行う文には合わない。"}, "sentence_index": 6, "correct_answer": "彫り師"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "北斎の絵も、彫り師の宣伝で世に広まった。", "explanation": "ここは〈版元〉の意味。宣伝や売り出しを担うのは版元で、彫り師は版木を彫る職人なので合わない。"}, {"text": "彫り師は山で一日中木を切り倒している。", "explanation": "ここは〈木こり〉の意味。山で木を切り倒す仕事は〈木こり〉と言い、彫り師は版木に絵を彫る職人なので合わない。"}, {"text": "北斎の絵も、よい和紙を仕入れた彫り師のおかげで世に広まった。", "explanation": "ここは〈紙問屋〉の意味。和紙を仕入れて売るのは紙問屋で、彫り師は版木を彫る人なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51862, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "版元は彫り師を下絵を渡して、版木を彫ってもらった。", "corrected_sentence": "版元は彫り師に下絵を渡して、版木を彫ってもらった。", "error_description": "「渡す」の相手は「に」で示す。「彫り師を」とすると目的語になり、「下絵を渡す」と合わない。正しくは「彫り師に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51862, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彫り師な技が細かく、線がそろっている。", "corrected_sentence": "彫り師の技が細かく、線がそろっている。", "error_description": "名詞「彫り師」が「技」を修飾するときは「の」が必要。「な」は形状詞の形で、名詞の彫り師には付かない。正しくは「彫り師の技」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51863, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す格で、「丁寧だ」の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の格。状態を述べる「丁寧だ」の文には目的語が入らない。"}, {"text": "に", "is_correct": false, "explanation": "方向・相手の格で、状態の主語にはならない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の格で、状態を述べる文に入らない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す格で、「丁寧だ」の主語になる。", "を": "目的語の格。状態を述べる「丁寧だ」の文には目的語が入らない。", "に": "方向・相手の格で、状態の主語にはならない。", "で": "手段・場所の格で、状態を述べる文に入らない。"}, "error_tags": {"を": "目的語の格で、状態の文に合わない", "に": "方向・相手の格", "で": "手段・場所の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51863, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "連体修飾の「の」で、「刷りの回数」となって「回数」を修飾する。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手の格で、「回数」を修飾できない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の格で、「回数」に続けると意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の格で、形容詞「多い」の主語にならない。"}], "correct_answer": "の", "explanations": {"の": "連体修飾の「の」で、「刷りの回数」となって「回数」を修飾する。", "と": "並列・相手の格で、「回数」を修飾できない。", "へ": "方向の格で、「回数」に続けると意味が通らない。", "を": "目的語の格で、形容詞「多い」の主語にならない。"}, "error_tags": {"と": "並列・相手の格で、修飾にならない", "へ": "方向の格で、修飾にならない", "を": "目的語の格で、「多い」の主語にならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51863, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "紙に絵や文字をうつすこと。", "primary_collocate": null, "pronunciation": "すり", "ipa": "sɯɾi", "syllable_count": 2, "sentences": [{"text": "木版画は刷りの具合で、絵の印象が大きく変わります。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "木版画[もくはんが]は刷[す]りの具合[ぐあい]で、絵[え]の印象[いんしょう]が大[おお]きく変[か]わります。", "sentence_source": "generated"}, {"text": "この版画は色の刷りが丁寧で、とても美しい。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "この版画[はんが]は色[いろ]の刷[す]りが丁寧[ていねい]で、とても美[うつく]しい。", "sentence_source": "generated"}, {"text": "一枚ずつ手で刷りを行うので、同じ作品はできません。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "一枚[いちまい]ずつ手[て]で刷[す]りを行[おこな]うので、同[おな]じ作品[さくひん]はできません。", "sentence_source": "generated"}, {"text": "刷りがずれてしまい、絵の線が二重に見えた。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "刷[す]りがずれてしまい、絵[え]の線[せん]が二重[にじゅう]に見[み]えた。", "sentence_source": "generated"}, {"text": "先生は刷りの前に、紙を水で湿らせるよう教えてくれた。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "先生[せんせい]は刷[す]りの前[まえ]に、紙[かみ]を水[みず]で湿[しめ]らせるよう教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "インクが多すぎたので、刷りが濃くなりすぎた。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "インクが多[おお]すぎたので、刷[す]りが濃[こ]くなりすぎた。", "sentence_source": "generated"}, {"text": "彼は彫りより刷りのほうが得意だと言う。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "彼[かれ]は彫[ほ]りより刷[す]りのほうが得意[とくい]だと言[い]う。", "sentence_source": "generated"}, {"text": "刷りの回数が多いほど、版画の色は深くなる。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "刷[す]りの回数[かいすう]が多[おお]いほど、版画[はんが]の色[いろ]は深[ふか]くなる。", "sentence_source": "generated"}, {"text": "初めての刷りは失敗したが、二回目はうまくいった。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "初[はじ]めての刷[す]りは失敗[しっぱい]したが、二回目[にかいめ]はうまくいった。", "sentence_source": "generated"}, {"text": "刷りを終えた作品を、風通しのよい場所で乾かした。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "刷[す]りを終[お]えた作品[さくひん]を、風通[かぜとお]しのよい場所[ばしょ]で乾[かわ]かした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "刷り", "label": "基本形"}, {"form": "刷りが", "label": "主格"}, {"form": "刷りを", "label": "目的格"}, {"form": "刷りの", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "版画などで、版に絵や文字をのせて紙にうつす作業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b529da0-c293-4bbe-a253-08b550ddb095') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51863, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刷り", "is_correct": true, "explanation": "紙に写す作業の意味で、その具合が絵の印象を左右すると読める。"}, {"text": "時計", "is_correct": false, "explanation": "機械の名詞で、木版画の出来の具合を左右する要素として入らない。"}, {"text": "電話", "is_correct": false, "explanation": "通信機器の名詞で、絵の印象を左右する具合の対象として不自然。"}, {"text": "版元", "is_correct": false, "explanation": "出版社を指す語で、作品の具合を左右する要素として入らない。"}], "explanations": {"刷り": "紙に写す作業の意味で、その具合が絵の印象を左右すると読める。", "時計": "機械の名詞で、木版画の出来の具合を左右する要素として入らない。", "電話": "通信機器の名詞で、絵の印象を左右する具合の対象として不自然。", "版元": "出版社を指す語で、作品の具合を左右する要素として入らない。"}, "sentence_index": 0, "correct_answer": "刷り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "胡麻の刷りを、すり鉢で香ばしく仕上げた。", "explanation": "ここは〈摺り〉（こすって細かくすること）の意味。同じ「すり」でも胡麻をすり潰す作業なので、紙に写す刷りとは合わない。"}, {"text": "転んで膝に刷り傷ができたので、消毒した。", "explanation": "ここは〈擦り傷〉の「擦り」（皮膚をこすってできた傷）の意味。刷りは紙に写す作業なので、傷の名には合わない。"}, {"text": "刷りは木でできていて、使うほどに線が太くなる。", "explanation": "ここは〈版〉の意味。刷りは作業であって、木の板ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51863, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刷り", "is_correct": true, "explanation": "紙に写す作業の意味で、彫りと比べて得意かどうかを言える。"}, {"text": "雨", "is_correct": false, "explanation": "天気を表す名詞で、作業の得意不得意を比べる文に入らない。"}, {"text": "墨", "is_correct": false, "explanation": "材料の名詞で、彫りと対比して得意さを表す対象にならない。"}, {"text": "画用紙", "is_correct": false, "explanation": "材料の名詞で、作業の得意不得意を比べる文に入らない。"}], "explanations": {"刷り": "紙に写す作業の意味で、彫りと比べて得意かどうかを言える。", "雨": "天気を表す名詞で、作業の得意不得意を比べる文に入らない。", "墨": "材料の名詞で、彫りと対比して得意さを表す対象にならない。", "画用紙": "材料の名詞で、作業の得意不得意を比べる文に入らない。"}, "sentence_index": 6, "correct_answer": "刷り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "刷りは作家が一枚だけ描くもので、複製はできない。", "explanation": "ここは〈原画〉の意味。刷りは版から写す作業で、作家が一枚ずつ描くものではないので合わない。"}, {"text": "刷りは松の煤から作り、長く使うほど香りが深くなる。", "explanation": "ここは〈墨〉の意味。刷りは紙に写す作業で、材料として作られるものではないので合わない。"}, {"text": "刷りで細い線を描くと、筆の跡が残る。", "explanation": "ここは〈絵筆〉の意味。刷りは線を描く道具ではなく、筆跡を残す行為でもないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51863, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "刷りを丁寧で、絵がきれいに出る。", "corrected_sentence": "刷りが丁寧で、絵がきれいに出る。", "error_description": "正しくは「刷りが」（主語）。「丁寧だ」は状態を表す形容動詞で、主語に「が」を取る。「刷りを」は目的語の形で誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51863, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "刷りに後、版は乾かさないとゆがみやすい。", "corrected_sentence": "刷りの後、版は乾かさないとゆがみやすい。", "error_description": "正しくは「刷りの後」（連体修飾の「の」）。「刷りに」は方向・相手の格で、「後」を修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51864, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」で、完成の時期という話題を立てる文の主題になる。"}, {"text": "を", "is_correct": false, "explanation": "目的語の格。「できあがる」は目的語を取らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段・場所の格で、完成の時期を述べる文の主題にはならない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手の格で、「できあがる」の文に合わない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」で、完成の時期という話題を立てる文の主題になる。", "を": "目的語の格。「できあがる」は目的語を取らないので合わない。", "で": "手段・場所の格で、完成の時期を述べる文の主題にはならない。", "と": "並列・相手の格で、「できあがる」の文に合わない。"}, "error_tags": {"を": "目的語の格で、できあがる文に合わない", "で": "手段・場所の格", "と": "並列・相手の格"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51864, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主語を示す格で、「悪い」の主語になる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の格で、状態を述べる「悪い」の主語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "起点の格で、「悪い」の主語を示せない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の格で、主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "主語を示す格で、「悪い」の主語になる。", "へ": "方向の格で、状態を述べる「悪い」の主語にはならない。", "から": "起点の格で、「悪い」の主語を示せない。", "の": "連体修飾の格で、主語にはならない。"}, "error_tags": {"へ": "方向の格で、主語にならない", "から": "起点の格で、主語にならない", "の": "連体修飾の格で、主語にならない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51864, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "印刷すること。また、その印刷物。", "primary_collocate": null, "pronunciation": "すり", "ipa": "sɯɾi", "syllable_count": 2, "sentences": [{"text": "この本は刷りが新しいので、文字がはっきり読める。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "この本[ほん]は刷[す]りが新[あたら]しいので、文字[もじ]がはっきり読[よ]める。", "sentence_source": "generated"}, {"text": "年賀状の刷りは、来週の月曜日にできあがります。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "年賀状[ねんがじょう]の刷[す]りは、来週[らいしゅう]の月曜日[げつようび]にできあがります。", "sentence_source": "generated"}, {"text": "刷りの色が見本と違うので、会社に連絡した。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "刷[す]りの色[いろ]が見本[みほん]と違[ちが]うので、会社[かいしゃ]に連絡[れんらく]した。", "sentence_source": "generated"}, {"text": "刷りに間違いがないか、もう一度確かめてください。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "刷[す]りに間違[まちが]いがないか、もう一度[いちど]確[たし]かめてください。", "sentence_source": "generated"}, {"text": "店に頼んだ名刺の刷りが、予定より早く届いた。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "店[みせ]に頼[たの]んだ名刺[めいし]の刷[す]りが、予定[よてい]より早[はや]く届[とど]いた。", "sentence_source": "generated"}, {"text": "このポスターは刷りが少ないため、手に入りにくい。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "このポスターは刷[す]りが少[すく]ないため、手[て]に入[はい]りにくい。", "sentence_source": "generated"}, {"text": "工場では、一日に何千枚もの刷りを仕上げている。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、一日[いちにち]に何千枚[なんぜんまい]もの刷[す]りを仕上[しあ]げている。", "sentence_source": "generated"}, {"text": "刷りが悪くて、写真の部分がぼやけて見える。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "刷[す]りが悪[わる]くて、写真[しゃしん]の部分[ぶぶん]がぼやけて見[み]える。", "sentence_source": "generated"}, {"text": "校正が終わったので、すぐに刷りに回します。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "校正[こうせい]が終[お]わったので、すぐに刷[す]りに回[まわ]します。", "sentence_source": "generated"}, {"text": "二つの刷りを並べると、紙の白さが少し違う。", "target_word": "刷り", "complexity_tier": "T3", "furigana": "二[ふた]つの刷[す]りを並[なら]べると、紙[かみ]の白[しろ]さが少[すこ]し違[ちが]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "刷り", "label": "基本形"}, {"form": "刷りが", "label": "主格"}, {"form": "刷りに", "label": "与格"}, {"form": "刷りの", "label": "連体形"}], "register": "neutral", "sense_fingerprint": "本やポスターなどを機械で印刷すること、またその刷られた物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b529da0-c293-4bbe-a253-08b550ddb095') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51864, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刷り", "is_correct": true, "explanation": "印刷された本や物の意味で、その新しさを言える。"}, {"text": "誤字", "is_correct": false, "explanation": "誤りの字を指し、「新しい」の主語にはならない。"}, {"text": "余白", "is_correct": false, "explanation": "紙の空いた部分で、新しさの主語としては不自然。"}, {"text": "行間", "is_correct": false, "explanation": "行の間隔で、新しいかどうかを言う対象にならない。"}], "explanations": {"刷り": "印刷された本や物の意味で、その新しさを言える。", "誤字": "誤りの字を指し、「新しい」の主語にはならない。", "余白": "紙の空いた部分で、新しさの主語としては不自然。", "行間": "行の間隔で、新しいかどうかを言う対象にならない。"}, "sentence_index": 0, "correct_answer": "刷り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "胡麻の刷りを、すり鉢で香ばしく仕上げた。", "explanation": "ここは〈摺り〉（こすって細かくすること）の意味。胡麻をすり潰す作業なので、印刷の刷りとは合わない。"}, {"text": "刷りは、誤字がないか一行ずつ読み返す作業だ。", "explanation": "ここは〈校正〉の意味。刷りは印刷された物で、読み返す作業ではないので合わない。"}, {"text": "刷りは木や金属で作り、何度も使える。", "explanation": "ここは〈版〉の意味。刷りは印刷された物で、材料として作るものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51864, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刷り", "is_correct": true, "explanation": "数えられる印刷物の意味で、「何千枚もの」を受けて仕上げる対象になる。"}, {"text": "字体", "is_correct": false, "explanation": "字の形を指し、枚数で数えないので「何千枚もの」を受けられない。"}, {"text": "季節", "is_correct": false, "explanation": "時の流れを表す語で、枚数で数えて仕上げる対象にならない。"}, {"text": "欄外", "is_correct": false, "explanation": "ページの余白部分で、何千枚もの対象として仕上げる文に合わない。"}], "explanations": {"刷り": "数えられる印刷物の意味で、「何千枚もの」を受けて仕上げる対象になる。", "字体": "字の形を指し、枚数で数えないので「何千枚もの」を受けられない。", "季節": "時の流れを表す語で、枚数で数えて仕上げる対象にならない。", "欄外": "ページの余白部分で、何千枚もの対象として仕上げる文に合わない。"}, "sentence_index": 6, "correct_answer": "刷り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "刷りは、画家が一枚ずつ心を込めて描く。", "explanation": "ここは〈絵画〉の意味。刷りは版から写して多く作るもので、一枚ずつ描くものではないので合わない。"}, {"text": "刷りは、修道士が一冊ずつ手で書き写して作った。", "explanation": "ここは〈写本〉の意味。刷りは機械で印刷するもので、手で書き写すものではないので合わない。"}, {"text": "刷りで糊を塗ってから、紙を貼る。", "explanation": "ここは〈刷毛〉の意味。刷りは印刷する行為や印刷物で、糊を塗る道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51864, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "刷りを届いたら、すぐに確認してください。", "corrected_sentence": "刷りが届いたら、すぐに確認してください。", "error_description": "正しくは「刷りが」（主語）。「届く」は到着するものを主語に取る自動詞で、「刷りを」は目的語の形なので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51864, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "刷りを数を確認してから、箱に詰める。", "corrected_sentence": "刷りの数を確認してから、箱に詰める。", "error_description": "正しくは「刷りの数」（連体修飾の「の」）。「刷りを」と「数を」が並び、目的語の「を」が重なっていて不自然。「刷り」に付く助詞が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2ca1b-2693-4db5-938b-706898029cb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51865, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「浮き世の苦労」の「の」。浮き世と苦労を修飾関係で結ぶ。"}, {"text": "か", "is_correct": false, "explanation": "「か」は選択を表し、「浮き世か苦労は多いね」は二者択一の形にならず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「浮き世を苦労は」は目的語の関係が成り立たず、文が壊れる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「浮き世へ苦労は多いね」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「浮き世の苦労」の「の」。浮き世と苦労を修飾関係で結ぶ。", "か": "「か」は選択を表し、「浮き世か苦労は多いね」は二者択一の形にならず不自然。", "を": "「浮き世を苦労は」は目的語の関係が成り立たず、文が壊れる。", "へ": "「へ」は方向を示すため、「浮き世へ苦労は多いね」は意味が通らない。"}, "error_tags": {"か": "選択・疑問", "を": "目的語（格の誤用）", "へ": "方向（行き先）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51865, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「浮き世を離れて」の「を」。離れる対象として浮き世を示す。"}, {"text": "に", "is_correct": false, "explanation": "「浮き世に離れて」は到達点の意味になり、離れる対象として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同や並列を示すため、「浮き世と離れて」は意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すため、「浮き世で離れて」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「浮き世を離れて」の「を」。離れる対象として浮き世を示す。", "に": "「浮き世に離れて」は到達点の意味になり、離れる対象として不自然。", "と": "「と」は共同や並列を示すため、「浮き世と離れて」は意味が通らない。", "で": "「で」は場所や手段を示すため、「浮き世で離れて」は意味が通らない。"}, "error_tags": {"に": "到達点・相手", "と": "共同・並列", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51865, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "浮き世は、人の世の中のことです。変わることが多い世界です。", "primary_collocate": null, "pronunciation": "うきよ", "ipa": "ɯkijo", "syllable_count": 3, "sentences": [{"text": "浮き世は変わりやすく、昨日の常識が今日は通じない。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "浮[う]き世[よ]は変[か]わりやすく、昨日[きのう]の常識[じょうしき]が今日[きょう]は通[つう]じない。", "sentence_source": "generated"}, {"text": "祖母は「浮き世の苦労は多いね」とよく言っていた。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "祖母[そぼ]は「浮[う]き世[よ]の苦労[くろう]は多[おお]いね」とよく言[い]っていた。", "sentence_source": "generated"}, {"text": "長く浮き世を生きてきた老人の話には重みがある。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "長[なが]く浮[う]き世[よ]を生[い]きてきた老人[ろうじん]の話[はなし]には重[おも]みがある。", "sentence_source": "generated"}, {"text": "浮き世の人づきあいにつかれて、山の寺に入った。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "浮[う]き世[よ]の人[ひと]づきあいにつかれて、山[やま]の寺[てら]に入[はい]った。", "sentence_source": "generated"}, {"text": "浮き世は、思うようにならないことばかりだ。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "浮[う]き世[よ]は、思[おも]うようにならないことばかりだ。", "sentence_source": "generated"}, {"text": "彼は浮き世の義理を重んじて、人との約束を守った。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "彼[かれ]は浮[う]き世[よ]の義理[ぎり]を重[おも]んじて、人[ひと]との約束[やくそく]を守[まも]った。", "sentence_source": "generated"}, {"text": "浮き世は広いもので、いろいろな人が暮らしている。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "浮[う]き世[よ]は広[ひろ]いもので、いろいろな人[ひと]が暮[く]らしている。", "sentence_source": "generated"}, {"text": "都会の浮き世をはなれて、静かな村で暮らしたい。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "都会[とかい]の浮[う]き世[よ]をはなれて、静[しず]かな村[むら]で暮[く]らしたい。", "sentence_source": "generated"}, {"text": "浮き世のうわさは、すぐに変わっていく。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "浮[う]き世[よ]のうわさは、すぐに変[か]わっていく。", "sentence_source": "generated"}, {"text": "浮き世に生まれたからには、人のために働きたい。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "浮[う]き世[よ]に生[う]まれたからには、人[ひと]のために働[はたら]きたい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "浮き世", "label": "基本形"}, {"form": "浮き世の", "label": "連体形（の）"}, {"form": "浮き世を", "label": "目的格"}, {"form": "浮き世に", "label": "与格"}], "register": "literary", "sense_fingerprint": "人が暮らす、変わりやすい世の中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb6837b5-37ea-42d1-91e7-d13681740b4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51865, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浮き世", "is_correct": true, "explanation": "「変わりやすく、常識が通じない」世の中を指し、文の主語に自然に入る。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は世の中の変化を表す主語にならず、文が成り立たない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝具は世の中の変化を表す主語にならず、「常識が通じない」の文脈に合わない。"}, {"text": "盆栽", "is_correct": false, "explanation": "盆栽は世の中の変化を表す主語にならず、文の意味が通らない。"}], "explanations": {"浮き世": "「変わりやすく、常識が通じない」世の中を指し、文の主語に自然に入る。", "石鹸": "石鹸は世の中の変化を表す主語にならず、文が成り立たない。", "寝具": "寝具は世の中の変化を表す主語にならず、「常識が通じない」の文脈に合わない。", "盆栽": "盆栽は世の中の変化を表す主語にならず、文の意味が通らない。"}, "sentence_index": 0, "correct_answer": "浮き世"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海で浮き世につかまって、岸まで泳いだ。", "explanation": "〈浮き袋〉の意味。浮き世は世の中を指すので、泳ぐときに体を支える道具にはならない。"}, {"text": "酒で浮き世を晴らした。", "explanation": "〈憂さ〉（つらさ）の意味。浮き世は世の中を指すので、晴らす対象にはならない。"}, {"text": "池の水面に浮き世が一面に広がった。", "explanation": "〈浮き草〉の意味。浮き世は世の中を指すので、水面に広がる植物にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51865, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浮き世", "is_correct": true, "explanation": "「広いもので、いろいろな人が暮らしている」世の中を指し、文に自然に入る。"}, {"text": "海流", "is_correct": false, "explanation": "海流に人が暮らすという文脈は成り立たず、意味が通らない。"}, {"text": "教室", "is_correct": false, "explanation": "教室に人が暮らすという文脈は成り立たず、文が不自然になる。"}, {"text": "農具", "is_correct": false, "explanation": "農具に人が暮らすという文脈は成り立たず、意味が通らない。"}], "explanations": {"浮き世": "「広いもので、いろいろな人が暮らしている」世の中を指し、文に自然に入る。", "海流": "海流に人が暮らすという文脈は成り立たず、意味が通らない。", "教室": "教室に人が暮らすという文脈は成り立たず、文が不自然になる。", "農具": "農具に人が暮らすという文脈は成り立たず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "浮き世"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夫が浮き世をして、家を出ていった。", "explanation": "〈浮気〉（不誠実な恋愛）の意味。「浮気をする」の代わりに「浮き世をする」とは言えない。浮き世は世の中を指す。"}, {"text": "空に浮き世がかかっている。", "explanation": "〈浮き雲〉の意味。浮き世は世の中を指すので、空にかかる雲にはならない。"}, {"text": "この木の板は浮き世が大きいので、沈まない。", "explanation": "〈浮力〉（水に浮く力）の意味。浮き世は世の中を指すので、物を浮かせる力の大きさは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51865, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "浮き世を苦労を笑い飛ばした。", "corrected_sentence": "浮き世の苦労を笑い飛ばした。", "error_description": "「浮き世の苦労」の「の」が正しい。「を」を使うと、苦労が二つの目的語になり文が壊れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51865, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "浮き世を盗んで、山にこもった。", "corrected_sentence": "浮き世を捨てて、山にこもった。", "error_description": "「浮き世を捨てる」は世の中から離れる意味で自然。「盗む」は浮き世と組まず、意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51866, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51866, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「浮き世を夢と見て」の「を」。見る対象として浮き世を示す。"}, {"text": "に", "is_correct": false, "explanation": "「浮き世に夢と見て」は到達点の意味になり、見る対象として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すため、「浮き世で夢と見て」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は「浮き世より夢と見て」と続かず、見る対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「浮き世を夢と見て」の「を」。見る対象として浮き世を示す。", "に": "「浮き世に夢と見て」は到達点の意味になり、見る対象として不自然。", "で": "「で」は場所や手段を示すため、「浮き世で夢と見て」は意味が通らない。", "より": "比較の「より」は「浮き世より夢と見て」と続かず、見る対象にならない。"}, "error_tags": {"に": "到達点・相手", "で": "場所・手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51866, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "浮き世とは、はかない現世、または世の中のことを指します。特に江戸時代の文化では、遊びや楽しみを重視する世界観を表しました。", "primary_collocate": null, "pronunciation": "うきよ", "ipa": "ɯkijo", "syllable_count": 3, "sentences": [{"text": "江戸時代の人々は、はかない浮き世を楽しく生きようとした。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "江戸時代[えどじだい]の人々[ひとびと]は、はかない浮[う]き世[よ]を楽[たの]しく生[い]きようとした。", "sentence_source": "generated"}, {"text": "浮き世は夢のようなものだと、江戸の人々は考えた。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "浮[う]き世[よ]は夢[ゆめ]のようなものだと、江戸[えど]の人々[ひとびと]は考[かんが]えた。", "sentence_source": "generated"}, {"text": "歌舞伎や遊びは、浮き世を楽しむ町人の文化だった。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "歌舞伎[かぶき]や遊[あそ]びは、浮[う]き世[よ]を楽[たの]しむ町人[ちょうにん]の文化[ぶんか]だった。", "sentence_source": "generated"}, {"text": "江戸の町人は、芝居見物や花見に出かけて浮き世を楽しんだ。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "江戸[えど]の町人[ちょうにん]は、芝居[しばい]見物[けんぶつ]や花見[はなみ]に出[で]かけて浮[う]き世[よ]を楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "江戸の町人は、一度きりの浮き世を笑って過ごした。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "江戸[えど]の町人[ちょうにん]は、一度[いちど]きりの浮[う]き世[よ]を笑[わら]って過[す]ごした。", "sentence_source": "generated"}, {"text": "浮き世の楽しみを描いた絵が、人々に人気だった。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "浮[う]き世[よ]の楽[たの]しみを描[えが]いた絵[え]が、人々[ひとびと]に人気[にんき]だった。", "sentence_source": "generated"}, {"text": "井原西鶴は、浮き世の人々の暮らしを小説に書いた。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "井原西鶴[いはらさいかく]は、浮[う]き世[よ]の人々[ひとびと]の暮[く]らしを小説[しょうせつ]に書[か]いた。", "sentence_source": "generated"}, {"text": "浮き世を夢と見て、今を楽しめという考え方が広まった。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "浮[う]き世[よ]を夢[ゆめ]と見[み]て、今[いま]を楽[たの]しめという考[かんが]え方[かた]が広[ひろ]まった。", "sentence_source": "generated"}, {"text": "吉原は、浮き世の遊びの中心として知られていた。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "吉原[よしわら]は、浮[う]き世[よ]の遊[あそ]びの中心[ちゅうしん]として知[し]られていた。", "sentence_source": "generated"}, {"text": "展覧会で、浮き世の風俗を伝える資料を見た。", "target_word": "浮き世", "complexity_tier": "T3", "furigana": "展覧会[てんらんかい]で、浮[う]き世[よ]の風俗[ふうぞく]を伝[つた]える資料[しりょう]を見[み]た。", "sentence_source": "generated"}], "morphological_forms": [{"form": "浮き世", "label": "基本形"}, {"form": "浮き世の", "label": "連体形（の）"}, {"form": "浮き世を", "label": "目的格"}, {"form": "浮き世は", "label": "主題"}], "register": "literary", "sense_fingerprint": "江戸時代の、はかなく楽しみを求める現世", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb6837b5-37ea-42d1-91e7-d13681740b4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51866, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浮き世", "is_correct": true, "explanation": "江戸の人々が楽しむ、はかない現世を指し、「楽しく生きようとした」に自然に入る。"}, {"text": "果物", "is_correct": false, "explanation": "果物は人が生きる世界を指さず、「はかない果物を楽しく生きよう」は意味が通らない。"}, {"text": "寝具", "is_correct": false, "explanation": "寝具は人が生きる世界を指さず、「楽しく生きようとした」の対象にならない。"}, {"text": "農具", "is_correct": false, "explanation": "農具は人が生きる世界を指さず、「はかない農具を楽しく生きよう」は意味が通らない。"}], "explanations": {"浮き世": "江戸の人々が楽しむ、はかない現世を指し、「楽しく生きようとした」に自然に入る。", "果物": "果物は人が生きる世界を指さず、「はかない果物を楽しく生きよう」は意味が通らない。", "寝具": "寝具は人が生きる世界を指さず、「楽しく生きようとした」の対象にならない。", "農具": "農具は人が生きる世界を指さず、「はかない農具を楽しく生きよう」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "浮き世"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "沼の表面に浮き世がびっしり広がった。", "explanation": "〈浮き草〉の意味。浮き世は現世を指すので、水面に広がる植物にはならない。"}, {"text": "友人と酒を飲んで浮き世を晴らした。", "explanation": "〈憂さ〉（つらさ）の意味。浮き世は現世を指すので、晴らす対象にはならない。"}, {"text": "会社の業績の浮き世に悩んだ。", "explanation": "〈浮き沈み〉の意味。浮き世は現世を指すので、業績の上下を表す語にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51866, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浮き世", "is_correct": true, "explanation": "井原西鶴が描いた、人々の暮らす現世を指し、「人々の暮らし」に自然に入る。"}, {"text": "海流", "is_correct": false, "explanation": "海流は人々の暮らしを指さず、「海流の人々の暮らし」は意味が通らない。"}, {"text": "石鹸", "is_correct": false, "explanation": "石鹸は人々の暮らしを指さず、「石鹸の人々の暮らし」は成り立たない。"}, {"text": "盆栽", "is_correct": false, "explanation": "盆栽は人々の暮らしを指さず、「盆栽の人々の暮らし」は意味が通らない。"}], "explanations": {"浮き世": "井原西鶴が描いた、人々の暮らす現世を指し、「人々の暮らし」に自然に入る。", "海流": "海流は人々の暮らしを指さず、「海流の人々の暮らし」は意味が通らない。", "石鹸": "石鹸は人々の暮らしを指さず、「石鹸の人々の暮らし」は成り立たない。", "盆栽": "盆栽は人々の暮らしを指さず、「盆栽の人々の暮らし」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "浮き世"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空に浮き世が流れていた。", "explanation": "〈浮き雲〉の意味。浮き世は現世を指すので、空を流れる雲にはならない。"}, {"text": "夏の川で浮き世につかまって流された。", "explanation": "〈浮き輪〉の意味。浮き世は現世を指すので、流されるときにつかまる道具にはならない。"}, {"text": "死後は浮き世に行けると信じた。", "explanation": "〈極楽〉（死後の浄土）の意味。浮き世は今の現世を指すので、死後に行く場所にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51866, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町人の文化は、浮き世を楽しみを映した。", "corrected_sentence": "町人の文化は、浮き世の楽しみを映した。", "error_description": "「浮き世の楽しみ」の「の」が正しい。「を」を使うと、楽しみが二つの目的語になり文が壊れる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51866, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "江戸の人々は、浮き世を盗んで暮らした。", "corrected_sentence": "江戸の人々は、浮き世を楽しんで暮らした。", "error_description": "「浮き世を楽しむ」が自然な組み合わせ。「盗む」は浮き世と組まず、意味が通らない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '416a6a12-46e1-464e-8834-b57ddf66e678') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51867, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「版木は木でできている」と主題を示し、材質を説明する文として続く。"}, {"text": "に", "is_correct": false, "explanation": "「版木に木でできている」では位置の意味になり、材質の説明として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「版木の木でできている」では、連体の関係が材質の説明に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「版木で木でできている」では手段の意味になり、材質の説明として不自然になる。"}], "correct_answer": "は", "explanations": {"は": "「版木は木でできている」と主題を示し、材質を説明する文として続く。", "に": "「版木に木でできている」では位置の意味になり、材質の説明として成り立たない。", "の": "「版木の木でできている」では、連体の関係が材質の説明に合わない。", "で": "「版木で木でできている」では手段の意味になり、材質の説明として不自然になる。"}, "error_tags": {"に": "位置", "の": "連体", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51867, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「版木を彫る」の形で、彫る動作の直接の対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、彫る動作の対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、彫る動作の対象とは結びつかない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、彫る動作の対象を表す役割はない。"}], "correct_answer": "を", "explanations": {"を": "「版木を彫る」の形で、彫る動作の直接の対象を示す。", "へ": "「へ」は方向を示すが、彫る動作の対象にはならない。", "と": "「と」は並列や相手を示すので、彫る動作の対象とは結びつかない。", "から": "「から」は起点を示すが、彫る動作の対象を表す役割はない。"}, "error_tags": {"へ": "方向", "と": "並列・相手", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51867, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "印刷するために使う、木でできた板です。", "primary_collocate": null, "pronunciation": "はんぎ", "ipa": "haŋɡi", "syllable_count": 3, "sentences": [{"text": "学校の図工の授業で、版木に動物の絵を彫りました。", "target_word": "版木", "complexity_tier": "T3", "furigana": "学校[がっこう]の図工[ずこう]の授業[じゅぎょう]で、版木[はんぎ]に動物[どうぶつ]の絵[え]を彫[ほ]りました。", "sentence_source": "generated"}, {"text": "版木は木でできているため、水に濡れると膨らんでしまいます。", "target_word": "版木", "complexity_tier": "T3", "furigana": "版木[はんぎ]は木[き]でできているため、水[みず]に濡[ぬ]れると膨[ふく]らんでしまいます。", "sentence_source": "generated"}, {"text": "このお寺には、昔のお経を刷った版木が大量に残っています。", "target_word": "版木", "complexity_tier": "T3", "furigana": "このお寺[てら]には、昔[むかし]のお経[きょう]を刷[す]った版木[はんぎ]が大量[たいりょう]に残[のこ]っています。", "sentence_source": "generated"}, {"text": "版木を削る道具は、先がとがっていて危ないので気をつけてください。", "target_word": "版木", "complexity_tier": "T3", "furigana": "版木[はんぎ]を削[けず]る道具[どうぐ]は、先[さき]がとがっていて危[あぶ]ないので気[き]をつけてください。", "sentence_source": "generated"}, {"text": "年賀状を作るために、小さな版木に干支の絵を彫りました。", "target_word": "版木", "complexity_tier": "T3", "furigana": "年賀状[ねんがじょう]を作[つく]るために、小[ちい]さな版木[はんぎ]に干支[えと]の絵[え]を彫[ほ]りました。", "sentence_source": "generated"}, {"text": "版木の表面が平らでないと、きれいに印刷できません。", "target_word": "版木", "complexity_tier": "T3", "furigana": "版木[はんぎ]の表面[ひょうめん]が平[たい]らでないと、きれいに印刷[いんさつ]できません。", "sentence_source": "generated"}, {"text": "祖父の家の倉には、昔の本を刷った版木が積んでありました。", "target_word": "版木", "complexity_tier": "T3", "furigana": "祖父[そふ]の家[いえ]の倉[くら]には、昔[むかし]の本[ほん]を刷[す]った版木[はんぎ]が積[つ]んでありました。", "sentence_source": "generated"}, {"text": "版木を彫る前に、鉛筆で絵の形を写しておきます。", "target_word": "版木", "complexity_tier": "T3", "furigana": "版木[はんぎ]を彫[ほ]る前[まえ]に、鉛筆[えんぴつ]で絵[え]の形[かたち]を写[うつ]しておきます。", "sentence_source": "generated"}, {"text": "印刷が終わった版木を洗って、日陰で乾かしました。", "target_word": "版木", "complexity_tier": "T3", "furigana": "印刷[いんさつ]が終[お]わった版木[はんぎ]を洗[あら]って、日陰[ひかげ]で乾[かわ]かしました。", "sentence_source": "generated"}, {"text": "職人は新しい版木に、墨で文字を書き始めました。", "target_word": "版木", "complexity_tier": "T3", "furigana": "職人[しょくにん]は新[あたら]しい版木[はんぎ]に、墨[すみ]で文字[もじ]を書[か]き始[はじ]めました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "版木", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "印刷や版画に使う木製の板", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d75d5cb-9168-42ec-b5c5-aaf58a772dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51867, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "版木", "is_correct": true, "explanation": "「学校の図工の授業で、版木に動物の絵を彫りました」の形で、彫って絵を作る木の板として合う。"}, {"text": "画用紙", "is_correct": false, "explanation": "画用紙は描くための紙で、彫って絵を作る対象ではない。"}, {"text": "包装紙", "is_correct": false, "explanation": "包装紙は物を包むための紙で、絵を彫る素材にはならない。"}, {"text": "黒板", "is_correct": false, "explanation": "黒板は書いたり描いたりする板で、彫る素材としては合わない。"}], "explanations": {"版木": "「学校の図工の授業で、版木に動物の絵を彫りました」の形で、彫って絵を作る木の板として合う。", "画用紙": "画用紙は描くための紙で、彫って絵を作る対象ではない。", "包装紙": "包装紙は物を包むための紙で、絵を彫る素材にはならない。", "黒板": "黒板は書いたり描いたりする板で、彫る素材としては合わない。"}, "sentence_index": 0, "correct_answer": "版木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "石膏像の型を作るため、版木を水に溶かします。", "explanation": "ここは〈石膏〉の意味。水に溶かして固める材料は石膏と言い、版木は彫って刷るための板を指すので合わない。"}, {"text": "印鑑を作るため、版木を細かく彫ります。", "explanation": "ここは〈印材〉の意味。印鑑を彫る材料は印材と言い、版木は刷るための板を指すので合わない。"}, {"text": "パン生地を伸ばすため、版木を転がします。", "explanation": "ここは〈麺棒〉の意味。生地を伸ばす道具は麺棒と言い、版木は彫って刷るための板なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51867, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "版木", "is_correct": true, "explanation": "「昔の本を刷った版木が積んであった」として、印刷に使った板を指し、倉に積まれた様子に合う。"}, {"text": "墨", "is_correct": false, "explanation": "墨は書画に使う材料で、本を刷った道具にはならない。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は料理の道具で、倉に積んである印刷用の板とは結びつかない。"}, {"text": "障子", "is_correct": false, "explanation": "障子は建具で、本を刷るための板とは合わない。"}], "explanations": {"版木": "「昔の本を刷った版木が積んであった」として、印刷に使った板を指し、倉に積まれた様子に合う。", "墨": "墨は書画に使う材料で、本を刷った道具にはならない。", "包丁": "包丁は料理の道具で、倉に積んである印刷用の板とは結びつかない。", "障子": "障子は建具で、本を刷るための板とは合わない。"}, "sentence_index": 6, "correct_answer": "版木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い版木の椅子を、居間に置きました。", "explanation": "ここは〈木製〉の意味。椅子などの家具の素材は木製と言い、版木は印刷用に彫った板を指すので合わない。"}, {"text": "料理のために、版木で野菜を細かく切りました。", "explanation": "ここは〈包丁〉の意味。野菜を切る道具は包丁と言い、版木は彫って刷るための板を指すので合わない。"}, {"text": "引っ越しの日、本を大量の版木に詰めました。", "explanation": "ここは〈段ボール〉の意味。本を詰める箱は段ボールと言い、版木は印刷に使う木の板なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51867, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "版木を紙やすりで磨かれてから、絵を彫ります。", "corrected_sentence": "版木を紙やすりで磨いてから、絵を彫ります。", "error_description": "「磨く」は他動詞なので「版木を磨く」が正しい。「磨かれる」は受身で、「版木が磨かれる」とすべきところを「版木を」のまま使っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51867, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "版木を乾くまで、しばらく待ちます。", "corrected_sentence": "版木が乾くまで、しばらく待ちます。", "error_description": "「乾く」は自動詞なので「版木が乾く」が正しい。「版木を乾く」は目的語を取れないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51868, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「版木を使い分ける」の形で、「使い分ける」の直接の目的語を示す。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「使い分ける」の対象にはならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「使い分ける」の対象としては成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「版木の使い分ける」では動詞と結びつかず、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「版木を使い分ける」の形で、「使い分ける」の直接の目的語を示す。", "から": "「から」は起点を示すが、「使い分ける」の対象にはならない。", "と": "「と」は並列や相手を示すので、「使い分ける」の対象としては成り立たない。", "の": "「版木の使い分ける」では動詞と結びつかず、文が成り立たない。"}, "error_tags": {"から": "起点", "と": "相手・並列", "の": "連体"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51868, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「版木が湿る」と主語を示し、湿気で形が変わるという文脈に合う。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すが、「湿る」の主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、湿るという状態変化には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「版木で湿ると」では、湿るという状態の主語を示せず不自然になる。"}], "correct_answer": "が", "explanations": {"が": "「版木が湿る」と主語を示し、湿気で形が変わるという文脈に合う。", "に": "「に」は位置や相手を示すが、「湿る」の主語にはならない。", "へ": "「へ」は方向を示すが、湿るという状態変化には合わない。", "で": "「版木で湿ると」では、湿るという状態の主語を示せず不自然になる。"}, "error_tags": {"に": "位置", "へ": "方向", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51868, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "木版印刷に用いる、表面に文字や絵を彫った木の板。", "primary_collocate": null, "pronunciation": "はんぎ", "ipa": "haŋɡi", "syllable_count": 3, "sentences": [{"text": "絵師の描いた下絵を彫師が版木に彫り、摺師が紙に印刷するという複雑な工程を経ます。", "target_word": "版木", "complexity_tier": "T3", "furigana": "絵師[えし]の描[えが]いた下絵[したえ]を彫師[ほりし]が版木[はんぎ]に彫[ほ]り、摺師[すりし]が紙[かみ]に印刷[いんさつ]するという複雑[ふくざつ]な工程[こうてい]を経[へ]ます。", "sentence_source": "mined"}, {"text": "特に多色印刷の場合、色ごとに異なる版木を使い分ける必要があり、職人たちの高度な技術と協力が不可欠です。", "target_word": "版木", "complexity_tier": "T3", "furigana": "特[とく]に多色印刷[たしょくいんさつ]の場合[ばあい]、色[いろ]ごとに異[こと]なる版木[はんぎ]を使[つか]い分[わ]ける必要[ひつよう]があり、職人[しょくにん]たちの高度[こうど]な技術[ぎじゅつ]と協力[きょうりょく]が不可欠[ふかけつ]です。", "sentence_source": "mined"}, {"text": "版木は桜の木で作られることが多く、硬くて彫りやすいのが特徴です。", "target_word": "版木", "complexity_tier": "T3", "furigana": "版木[はんぎ]は桜[さくら]の木[き]で作[つく]られることが多[おお]く、硬[かた]くて彫[ほ]りやすいのが特徴[とくちょう]です。", "sentence_source": "generated"}, {"text": "彫師は小さな刀で、版木の表面に細い線を残して彫っていきます。", "target_word": "版木", "complexity_tier": "T3", "furigana": "彫師[ほりし]は小[ちい]さな刀[かたな]で、版木[はんぎ]の表面[ひょうめん]に細[ほそ]い線[せん]を残[のこ]して彫[ほ]っていきます。", "sentence_source": "generated"}, {"text": "使い終わった版木は、乾かしてから倉庫に大切にしまいます。", "target_word": "版木", "complexity_tier": "T3", "furigana": "使[つか]い終[お]わった版木[はんぎ]は、乾[かわ]かしてから倉庫[そうこ]に大切[たいせつ]にしまいます。", "sentence_source": "generated"}, {"text": "版木に墨を塗り、その上に紙を置いて、バレンでこすると絵が写ります。", "target_word": "版木", "complexity_tier": "T3", "furigana": "版木[はんぎ]に墨[すみ]を塗[ぬ]り、その上[うえ]に紙[かみ]を置[お]いて、バレンでこすると絵[え]が写[うつ]ります。", "sentence_source": "generated"}, {"text": "古い版木が見つかったおかげで、江戸時代の絵を同じように刷ることができました。", "target_word": "版木", "complexity_tier": "T3", "furigana": "古[ふる]い版木[はんぎ]が見[み]つかったおかげで、江戸時代[えどじだい]の絵[え]を同[おな]じように刷[す]ることができました。", "sentence_source": "generated"}, {"text": "版木が湿ると形が変わるので、保管する場所に注意が必要です。", "target_word": "版木", "complexity_tier": "T3", "furigana": "版木[はんぎ]が湿[しめ]ると形[かたち]が変[か]わるので、保管[ほかん]する場所[ばしょ]に注意[ちゅうい]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "博物館には、有名な浮世絵の版木が展示されています。", "target_word": "版木", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]には、有名[ゆうめい]な浮世絵[うきよえ]の版木[はんぎ]が展示[てんじ]されています。", "sentence_source": "generated"}, {"text": "版木を何度も使うと、細かい線が少しずつすり減ってしまいます。", "target_word": "版木", "complexity_tier": "T3", "furigana": "版木[はんぎ]を何度[なんど]も使[つか]うと、細[こま]かい線[せん]が少[すこ]しずつすり減[へ]ってしまいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "版木", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "木版画・木版印刷で、絵や文字を彫り込んだ木の板", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d75d5cb-9168-42ec-b5c5-aaf58a772dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51868, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "版木", "is_correct": true, "explanation": "「彫師が版木に彫り」の形で、絵や文字を彫り込む木の板として工程に合う。"}, {"text": "墨", "is_correct": false, "explanation": "墨は書くための材料で、彫る対象にはならないので文が成り立たない。"}, {"text": "刷毛", "is_correct": false, "explanation": "刷毛は塗る道具で、彫り込む対象にはならない。"}, {"text": "バレン", "is_correct": false, "explanation": "バレンは紙をこすって刷る道具で、彫る対象にはならない。"}], "explanations": {"版木": "「彫師が版木に彫り」の形で、絵や文字を彫り込む木の板として工程に合う。", "墨": "墨は書くための材料で、彫る対象にはならないので文が成り立たない。", "刷毛": "刷毛は塗る道具で、彫り込む対象にはならない。", "バレン": "バレンは紙をこすって刷る道具で、彫る対象にはならない。"}, "sentence_index": 0, "correct_answer": "版木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この家具は、丈夫な版木を使って組み立てました。", "explanation": "ここは〈木材〉の意味。家具の材料となる木は木材と言い、版木は印刷用に彫った板を指すので合わない。"}, {"text": "書道の練習には、版木を一枚ずつ使います。", "explanation": "ここは〈半紙〉の意味。墨で文字を書く紙は半紙と言い、版木は彫って刷るための板なので合わない。"}, {"text": "雨の日は、洗濯物を版木に干します。", "explanation": "ここは〈物干し〉の意味。洗濯物を掛けて乾かす道具は物干しと言い、版木は印刷用に彫った板を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51868, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "版木", "is_correct": true, "explanation": "「古い版木が見つかった」の形で、絵を刷るために使った板として文脈に合う。"}, {"text": "硯", "is_correct": false, "explanation": "硯は墨をすりおろす道具で、絵を刷るための版にはならない。"}, {"text": "座布団", "is_correct": false, "explanation": "座布団は座るための敷物で、絵を刷る版にはならない。"}, {"text": "糊", "is_correct": false, "explanation": "糊は貼るための材料で、絵を刷る版にはならない。"}], "explanations": {"版木": "「古い版木が見つかった」の形で、絵を刷るために使った板として文脈に合う。", "硯": "硯は墨をすりおろす道具で、絵を刷るための版にはならない。", "座布団": "座布団は座るための敷物で、絵を刷る版にはならない。", "糊": "糊は貼るための材料で、絵を刷る版にはならない。"}, "sentence_index": 6, "correct_answer": "版木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い版木の椅子を、居間に置きました。", "explanation": "ここは〈木製〉の意味。椅子などの家具の素材は木製と言い、版木は印刷用に彫った板を指すので合わない。"}, {"text": "引っ越しの日、本を大量の版木に詰めました。", "explanation": "ここは〈段ボール〉の意味。本を詰める箱は段ボールと言い、版木は印刷に使う木の板なので合わない。"}, {"text": "料理のために、版木で野菜を細かく切りました。", "explanation": "ここは〈包丁〉の意味。野菜を切る道具は包丁と言い、版木は彫って刷るための板を指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51868, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "版木を彫られてから、墨を塗ります。", "corrected_sentence": "版木を彫ってから、墨を塗ります。", "error_description": "「彫る」は他動詞なので「版木を彫る」が正しい。「彫られる」は受身で、「版木が彫られる」とすべきところを「版木を」のまま使っている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51868, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "版木を湿らないように、保管場所を選びます。", "corrected_sentence": "版木が湿らないように、保管場所を選びます。", "error_description": "「湿る」は自動詞なので「版木が湿る」が正しい。「版木を湿る」は目的語を取れないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
