INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51869, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "いろがいくつもあること。", "primary_collocate": null, "pronunciation": "たしょく", "ipa": "taɕokɯ", "syllable_count": 3, "sentences": [{"text": "多色の電球を飾ったので、部屋が祭りのようににぎやかになりました。", "target_word": "多色", "complexity_tier": "T3", "furigana": "多色[たしょく]の電球[でんきゅう]を飾[かざ]ったので、部屋[へや]が祭[まつ]りのようににぎやかになりました。", "sentence_source": "generated"}, {"text": "単色ではさびしいので、壁を多色にしてみました。", "target_word": "多色", "complexity_tier": "T3", "furigana": "単色[たんしょく]ではさびしいので、壁[かべ]を多色[たしょく]にしてみました。", "sentence_source": "generated"}, {"text": "この鳥の羽は多色で、森の中でもすぐに見つけられます。", "target_word": "多色", "complexity_tier": "T3", "furigana": "この鳥[とり]の羽[はね]は多色[たしょく]で、森[もり]の中[なか]でもすぐに見[み]つけられます。", "sentence_source": "generated"}, {"text": "多色の旗が風にゆれて、広場が明るくなりました。", "target_word": "多色", "complexity_tier": "T3", "furigana": "多色[たしょく]の旗[はた]が風[かぜ]にゆれて、広場[ひろば]が明[あか]るくなりました。", "sentence_source": "generated"}, {"text": "多色のノートは、教科ごとに分けて使えるので便利です。", "target_word": "多色", "complexity_tier": "T3", "furigana": "多色[たしょく]のノートは、教科[きょうか]ごとに分[わ]けて使[つか]えるので便利[べんり]です。", "sentence_source": "generated"}, {"text": "多色のチョークを使って、黒板に図を描きました。", "target_word": "多色", "complexity_tier": "T3", "furigana": "多色[たしょく]のチョークを使[つか]って、黒板[こくばん]に図[ず]を描[か]きました。", "sentence_source": "generated"}, {"text": "多色のセーターは派手ですが、あたたかくて気に入っています。", "target_word": "多色", "complexity_tier": "T3", "furigana": "多色[たしょく]のセーターは派手[はで]ですが、あたたかくて気[き]に入[い]っています。", "sentence_source": "generated"}, {"text": "この絵は単色ではなく、多色で描かれています。", "target_word": "多色", "complexity_tier": "T3", "furigana": "この絵[え]は単色[たんしょく]ではなく、多色[たしょく]で描[えが]かれています。", "sentence_source": "generated"}, {"text": "秋の山は多色で、赤や黄色や緑が混ざり合っています。", "target_word": "多色", "complexity_tier": "T3", "furigana": "秋[あき]の山[やま]は多色[たしょく]で、赤[あか]や黄色[きいろ]や緑[みどり]が混[ま]ざり合[あ]っています。", "sentence_source": "generated"}, {"text": "多色のビーズでつくった腕輪を、友達にプレゼントしました。", "target_word": "多色", "complexity_tier": "T3", "furigana": "多色[たしょく]のビーズでつくった腕輪[うでわ]を、友達[ともだち]にプレゼントしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多色", "label": "基本形"}, {"form": "多色の", "label": "連体形"}], "register": "標準", "sense_fingerprint": "色の数が多いこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb8eaf-a2e4-432a-a0a2-3afa20c9c998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51869, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多色", "is_correct": true, "explanation": "「多色の電球」は色が複数ある電球を指し、ここに自然に入る。"}, {"text": "海苔", "is_correct": false, "explanation": "「海苔の電球」とは言わない。海苔は食品で、電球の色の数を表せない。"}, {"text": "陶器", "is_correct": false, "explanation": "「陶器の電球」は言わない。陶器は焼き物で、電球の説明にはならない。"}, {"text": "寺院", "is_correct": false, "explanation": "「寺院の電球」とは言わない。寺院は建物を指し、電球の性質を表せない。"}], "explanations": {"多色": "「多色の電球」は色が複数ある電球を指し、ここに自然に入る。", "海苔": "「海苔の電球」とは言わない。海苔は食品で、電球の色の数を表せない。", "陶器": "「陶器の電球」は言わない。陶器は焼き物で、電球の説明にはならない。", "寺院": "「寺院の電球」とは言わない。寺院は建物を指し、電球の性質を表せない。"}, "sentence_index": 0, "correct_answer": "多色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議には多色の人が集まり、部屋がいっぱいになった。", "explanation": "ここは〈多数〉（数が多いこと）の意味。多色は色が複数あることなので、人数には使えない。"}, {"text": "彼は多色の仕事を同時に抱えていて、休む暇がない。", "explanation": "ここは〈大量〉（量が多いこと）の意味。多色は色について言う語なので、仕事の量には使えない。"}, {"text": "彼女は多色な人で、ピアノも料理も絵も得意だ。", "explanation": "ここは〈多才〉（才能が多いこと）の意味。多色は色の数なので、人の才能の多さには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51869, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多色", "is_correct": true, "explanation": "「多色のセーター」は色が複数あるセーターを指し、ここに自然に入る。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「夕焼けのセーター」とは言わない。夕焼けは空の現象で、服の色の数を表せない。"}, {"text": "天井", "is_correct": false, "explanation": "「天井のセーター」は言わない。天井は建物の上面を指し、服の性質を表せない。"}, {"text": "大理石", "is_correct": false, "explanation": "「大理石のセーター」は不自然。大理石は石材で、服の性質の説明にはならない。"}], "explanations": {"多色": "「多色のセーター」は色が複数あるセーターを指し、ここに自然に入る。", "夕焼け": "「夕焼けのセーター」とは言わない。夕焼けは空の現象で、服の色の数を表せない。", "天井": "「天井のセーター」は言わない。天井は建物の上面を指し、服の性質を表せない。", "大理石": "「大理石のセーター」は不自然。大理石は石材で、服の性質の説明にはならない。"}, "sentence_index": 6, "correct_answer": "多色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は多色な視点から、問題を一つずつ検討した。", "explanation": "ここは〈多角的〉（いろいろな方面から見ること）の意味。多色は色の数なので、物の見方には使えない。"}, {"text": "彼は多色で活躍し、テレビにも舞台にも出ている。", "explanation": "ここは〈多方面〉（分野が広いこと）の意味。多色は色について言うので、活躍の分野には使えない。"}, {"text": "この大学には多色の学部があり、学生が自分に合う分野を選べる。", "explanation": "ここは〈多種〉（種類が多いこと）の意味。多色は色の数なので、学部の種類の多さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51869, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この包み紙は多色がリボンで飾られていて、とても華やかです。", "corrected_sentence": "この包み紙は多色のリボンで飾られていて、とても華やかです。", "error_description": "「多色」は「リボン」を修飾するので連体助詞「の」が必要。「が」は主語を示すため、「多色が飾られる」と色が主語になって不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51869, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このクッションは多色を糸で刺繍されていて、部屋が明るくなります。", "corrected_sentence": "このクッションは多色の糸で刺繍されていて、部屋が明るくなります。", "error_description": "「多色」は「糸」を修飾するので「の」が必要。「を」は目的語を示すため、「多色を糸で刺繍」は成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
