INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51870, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "一つの物に、いくつかの色が混ざっていること。また、さまざまな色があること。", "primary_collocate": null, "pronunciation": "たしょく", "ipa": "taɕokɯ", "syllable_count": 3, "sentences": [{"text": "特に多色印刷の場合、色ごとに異なる版木を使い分ける必要があり、職人たちの高度な技術と協力が不可欠です。", "target_word": "多色", "complexity_tier": "T3", "furigana": "特[とく]に多色[たしょく]印刷[いんさつ]の場合[ばあい]、色[いろ]ごとに異[こと]なる版木[はんぎ]を使[つか]い分[わ]ける必要[ひつよう]があり、職人[しょくにん]たちの高度[こうど]な技術[ぎじゅつ]と協力[きょうりょく]が不可欠[ふかけつ]です。", "sentence_source": "mined"}, {"text": "この着物は多色の糸で織られていて、光に当たると表情が変わります。", "target_word": "多色", "complexity_tier": "T3", "furigana": "この着物[きもの]は多色[たしょく]の糸[いと]で織[お]られていて、光[ひかり]に当[あ]たると表情[ひょうじょう]が変[か]わります。", "sentence_source": "generated"}, {"text": "多色の絵の具を使うと、風景がいっそう華やかに見えます。", "target_word": "多色", "complexity_tier": "T3", "furigana": "多色[たしょく]の絵[え]の具[ぐ]を使[つか]うと、風景[ふうけい]がいっそう華[はな]やかに見[み]えます。", "sentence_source": "generated"}, {"text": "子どもたちは多色のペンで、地図を楽しく塗り分けました。", "target_word": "多色", "complexity_tier": "T3", "furigana": "子[こ]どもたちは多色[たしょく]のペンで、地図[ちず]を楽[たの]しく塗[ぬ]り分[わ]けました。", "sentence_source": "generated"}, {"text": "展示された陶器は多色で、一つひとつ模様が違います。", "target_word": "多色", "complexity_tier": "T3", "furigana": "展示[てんじ]された陶器[とうき]は多色[たしょく]で、一[ひと]つひとつ模様[もよう]が違[ちが]います。", "sentence_source": "generated"}, {"text": "多色の版画は、単色のものより制作に時間がかかります。", "target_word": "多色", "complexity_tier": "T3", "furigana": "多色[たしょく]の版画[はんが]は、単色[たんしょく]のものより制作[せいさく]に時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "このポスターは多色なので、遠くからでもよく目立ちます。", "target_word": "多色", "complexity_tier": "T3", "furigana": "このポスターは多色[たしょく]なので、遠[とお]くからでもよく目立[めだ]ちます。", "sentence_source": "generated"}, {"text": "多色のガラスを組み合わせて、教会の窓が作られました。", "target_word": "多色", "complexity_tier": "T3", "furigana": "多色[たしょく]のガラスを組[く]み合[あ]わせて、教会[きょうかい]の窓[まど]が作[つく]られました。", "sentence_source": "generated"}, {"text": "単色の服が好きな人もいれば、多色の柄を好む人もいます。", "target_word": "多色", "complexity_tier": "T3", "furigana": "単色[たんしょく]の服[ふく]が好[す]きな人[ひと]もいれば、多色[たしょく]の柄[がら]を好[この]む人[ひと]もいます。", "sentence_source": "generated"}, {"text": "多色の花が咲く庭を、毎朝ゆっくり散歩しています。", "target_word": "多色", "complexity_tier": "T3", "furigana": "多色[たしょく]の花[はな]が咲[さ]く庭[にわ]を、毎朝[まいあさ]ゆっくり散歩[さんぽ]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多色", "label": "基本形"}, {"form": "多色の", "label": "連体修飾（名詞＋の）"}], "register": "標準", "sense_fingerprint": "一つの物に複数の色が使われている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb8eaf-a2e4-432a-a0a2-3afa20c9c998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51870, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多色", "is_correct": true, "explanation": "「多色印刷」は色ごとに版を使い分けて刷る印刷のこと。ここには「多色」が入る。"}, {"text": "陶器", "is_correct": false, "explanation": "「陶器印刷」とは言わない。陶器は焼き物を指す名詞で、印刷の方式は表せない。"}, {"text": "夕焼け", "is_correct": false, "explanation": "「夕焼け印刷」は不自然。夕焼けは空の現象を指すので、印刷の方式には使えない。"}, {"text": "天井", "is_correct": false, "explanation": "「天井印刷」とは言わない。天井は建物の上面を指し、印刷の方式を表せない。"}], "explanations": {"多色": "「多色印刷」は色ごとに版を使い分けて刷る印刷のこと。ここには「多色」が入る。", "陶器": "「陶器印刷」とは言わない。陶器は焼き物を指す名詞で、印刷の方式は表せない。", "夕焼け": "「夕焼け印刷」は不自然。夕焼けは空の現象を指すので、印刷の方式には使えない。", "天井": "「天井印刷」とは言わない。天井は建物の上面を指し、印刷の方式を表せない。"}, "sentence_index": 0, "correct_answer": "多色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の料理は多色で、毎日まったく違う献立になる。", "explanation": "ここは〈多彩〉（種類が豊富なこと）の意味。多色は色が複数あることなので、料理の種類の多さには合わない。"}, {"text": "試験会場には多色の受験者が集まり、列が長く続いた。", "explanation": "ここは〈多数〉（数が多いこと）の意味。多色は色について言う語なので、人の数には使えない。"}, {"text": "この店には多色の専門書があり、どの分野の本でも探せる。", "explanation": "ここは〈多種〉（種類が多いこと）の意味。多色は色の数を表すので、本の分野の多さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51870, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多色", "is_correct": true, "explanation": "「多色なので」は色が複数あることを表し、ポスターの性質として自然。ここには「多色」が入る。"}, {"text": "砂利", "is_correct": false, "explanation": "「砂利なので目立つ」とは言わない。砂利は小石を指し、ポスターの性質としては合わない。"}, {"text": "大理石", "is_correct": false, "explanation": "大理石は石材で、ポスターの性質としては言えない。「大理石なので目立つ」は不自然。"}, {"text": "寺院", "is_correct": false, "explanation": "寺院はお寺を指す名詞で、ポスターの性質の説明にはならない。"}], "explanations": {"多色": "「多色なので」は色が複数あることを表し、ポスターの性質として自然。ここには「多色」が入る。", "砂利": "「砂利なので目立つ」とは言わない。砂利は小石を指し、ポスターの性質としては合わない。", "大理石": "大理石は石材で、ポスターの性質としては言えない。「大理石なので目立つ」は不自然。", "寺院": "寺院はお寺を指す名詞で、ポスターの性質の説明にはならない。"}, "sentence_index": 6, "correct_answer": "多色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この大学は多色の分野で研究をしていて、専門家が多い。", "explanation": "ここは〈多岐〉（分野が幅広いこと）の意味。多色は色の数なので、研究分野の広さには使えない。"}, {"text": "あの人は多色で、ギターも書道も料理もこなす。", "explanation": "ここは〈多芸〉（芸や技が多いこと）の意味。多色は色について言うので、人の技能の多さには合わない。"}, {"text": "このチームは多色な意見が集まって、話し合いがまとまらない。", "explanation": "ここは〈多様〉（さまざまであること）の意味。多色は色の数なので、意見の幅の広さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51870, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このマフラーは多色が毛糸で編まれていて、角度によって色の見え方が変わります。", "corrected_sentence": "このマフラーは多色の毛糸で編まれていて、角度によって色の見え方が変わります。", "error_description": "「多色」は後ろの「毛糸」を修飾するので連体助詞「の」が必要。「が」は主語を示すため、「多色が編まれる」と色が主語になって不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51870, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この手提げは多色を糸で編まれていて、とても華やかです。", "corrected_sentence": "この手提げは多色の糸で編まれていて、とても華やかです。", "error_description": "「多色」は「糸」を修飾するので「の」が必要。「を」は目的語を示すため、「多色を糸で」は文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51871, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「猫の顔を」は彫る動作の対象を示すので、ここに入る。"}, {"text": "と", "is_correct": false, "explanation": "「猫の顔と彫って遊ぶ」は並列や相手を表し、彫る対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「猫の顔より彫って」は比較になり、ここでは合わない。"}, {"text": "から", "is_correct": false, "explanation": "「猫の顔から彫って」は起点を表し、彫る対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「猫の顔を」は彫る動作の対象を示すので、ここに入る。", "と": "「猫の顔と彫って遊ぶ」は並列や相手を表し、彫る対象を示せない。", "より": "「猫の顔より彫って」は比較になり、ここでは合わない。", "から": "「猫の顔から彫って」は起点を表し、彫る対象を示せない。"}, "error_tags": {"と": "並列", "より": "比較", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51871, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「日付を」は彫る動作の対象を示すので、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「日付が彫って」は日付を主語にして彫る行為と合わず、不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「日付へ彫って」は方向を表し、彫る対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「日付で彫って」は手段を表すが、彫る対象が示せず文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「日付を」は彫る動作の対象を示すので、ここに入る。", "が": "「日付が彫って」は日付を主語にして彫る行為と合わず、不自然。", "へ": "「日付へ彫って」は方向を表し、彫る対象を示せない。", "で": "「日付で彫って」は手段を表すが、彫る対象が示せず文が成り立たない。"}, "error_tags": {"が": "主語", "へ": "方向", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51871, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ナイフなどの刃物で、木や石の表面を削って絵や字を刻むこと。", "primary_collocate": null, "pronunciation": "ほる", "ipa": "horɯ", "syllable_count": 2, "sentences": [{"text": "公園の木に、ナイフで名前を彫ってはいけません。", "target_word": "彫って", "complexity_tier": "T3", "furigana": "公園[こうえん]の木[き]に、ナイフで名前[なまえ]を彫[ほ]ってはいけません。", "sentence_source": "generated"}, {"text": "兄は小さな石に、猫の顔を彫って遊んでいます。", "target_word": "彫って", "complexity_tier": "T3", "furigana": "兄[あに]は小[ちい]さな石[いし]に、猫[ねこ]の顔[かお]を彫[ほ]って遊[あそ]んでいます。", "sentence_source": "generated"}, {"text": "彼女は机の端に、好きな言葉を彫った。", "target_word": "彫った", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は机[つくえ]の端[はし]に、好[す]きな言葉[ことば]を彫[ほ]った。", "sentence_source": "generated"}, {"text": "子どもたちは木の板に、自分の絵を彫りました。", "target_word": "彫り", "complexity_tier": "T3", "furigana": "子[こ]どもたちは木[き]の板[いた]に、自分[じぶん]の絵[え]を彫[ほ]りました。", "sentence_source": "generated"}, {"text": "洞窟の壁には、昔の人が彫った動物の絵が残っています。", "target_word": "彫った", "complexity_tier": "T3", "furigana": "洞窟[どうくつ]の壁[かべ]には、昔[むかし]の人[ひと]が彫[ほ]った動物[どうぶつ]の絵[え]が残[のこ]っています。", "sentence_source": "generated"}, {"text": "先生は、ナイフで木に字を彫るときは気をつけるように言いました。", "target_word": "彫る", "complexity_tier": "T3", "furigana": "先生[せんせい]は、ナイフで木[き]に字[じ]を彫[ほ]るときは気[き]をつけるように言[い]いました。", "sentence_source": "generated"}, {"text": "彼は消しゴムにハートを彫って、はんこを作りました。", "target_word": "彫って", "complexity_tier": "T3", "furigana": "彼[かれ]は消[け]しゴムにハートを彫[ほ]って、はんこを作[つく]りました。", "sentence_source": "generated"}, {"text": "海辺で拾った石に、日付を彫っておきました。", "target_word": "彫って", "complexity_tier": "T3", "furigana": "海辺[うみべ]で拾[ひろ]った石[いし]に、日付[ひづけ]を彫[ほ]っておきました。", "sentence_source": "generated"}, {"text": "父はベンチの背に、家族の名前を彫ってくれました。", "target_word": "彫って", "complexity_tier": "T3", "furigana": "父[ちち]はベンチの背[せ]に、家族[かぞく]の名前[なまえ]を彫[ほ]ってくれました。", "sentence_source": "generated"}, {"text": "木の箱にイニシャルを彫ると、特別な贈り物になります。", "target_word": "彫る", "complexity_tier": "T3", "furigana": "木[き]の箱[はこ]にイニシャルを彫[ほ]ると、特別[とくべつ]な贈[おく]り物[もの]になります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "彫る", "label": "終止形"}, {"form": "彫り", "label": "連用形"}, {"form": "彫った", "label": "夕形"}, {"form": "彫って", "label": "テ形"}, {"form": "彫らない", "label": "否定形"}, {"form": "彫れる", "label": "可能形"}], "register": "標準", "sense_fingerprint": "ナイフなどで木や石に絵や字をかく", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb8eaf-a2e4-432a-a0a2-3afa20c9c998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51871, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彫って", "is_correct": true, "explanation": "「〜てはいけません」に続くテ形。「名前を彫ってはいけません」となり、ここに入る。"}, {"text": "彫る", "is_correct": false, "explanation": "終止形。「彫ってはいけません」の形にならず、ここでは合わない。"}, {"text": "彫り", "is_correct": false, "explanation": "連用形。「〜てはいけません」には続かず、文が成り立たない。"}, {"text": "彫らず", "is_correct": false, "explanation": "否定の連用形。「〜てはいけません」と続かず、文が成り立たない。"}], "explanations": {"彫って": "「〜てはいけません」に続くテ形。「名前を彫ってはいけません」となり、ここに入る。", "彫る": "終止形。「彫ってはいけません」の形にならず、ここでは合わない。", "彫り": "連用形。「〜てはいけません」には続かず、文が成り立たない。", "彫らず": "否定の連用形。「〜てはいけません」と続かず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "彫って"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公園に深い溝を彫って、水を流した。", "explanation": "ここは〈掘る〉（地面に穴や溝をあける）の意味。彫るは表面に絵や字をかく動作なので、溝をあける作業には合わない。"}, {"text": "にんじんを細かく彫って、カレーに入れた。", "explanation": "ここは〈刻む〉（細かく切る）の意味。彫るは材料の表面に絵や字をかく動作で、食材を切ることには使わない。"}, {"text": "魚を彫って、朝ごはんにした。", "explanation": "ここは〈焼く〉（火で加熱する）の意味。彫るは表面に絵や字をかく動作で、魚を調理する動作には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51871, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彫って", "is_correct": true, "explanation": "テ形。「彫ってはんこを作りました」と続き、ここに入る。"}, {"text": "彫ろう", "is_correct": false, "explanation": "意向形。「彫ろう、」と文を区切れず、ここでは合わない。"}, {"text": "彫られ", "is_correct": false, "explanation": "受身の連用形。消しゴムが彫られる形になり、主語の「彼」と合わない。"}, {"text": "彫れる", "is_correct": false, "explanation": "可能形。「彫れる、」では「彫ることができる」の意味になり、はんこを作る流れに合わない。"}], "explanations": {"彫って": "テ形。「彫ってはんこを作りました」と続き、ここに入る。", "彫ろう": "意向形。「彫ろう、」と文を区切れず、ここでは合わない。", "彫られ": "受身の連用形。消しゴムが彫られる形になり、主語の「彼」と合わない。", "彫れる": "可能形。「彫れる、」では「彫ることができる」の意味になり、はんこを作る流れに合わない。"}, "sentence_index": 6, "correct_answer": "彫って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は毛糸で花の模様を彫りました。", "explanation": "ここは〈織る〉（糸を組んで布を作る）の意味。彫るは刃物で材料を削る動作なので、糸で模様を作る作業には使わない。"}, {"text": "スケッチブックに絵の具で花を彫った。", "explanation": "ここは〈描く〉（絵の具などで絵をかく）の意味。彫るは刃物で表面を削る動作なので、絵の具で絵を描く場面には合わない。"}, {"text": "かつお節を彫ってだしを取った。", "explanation": "ここは〈削る〉（薄く表面を取る）の意味。かつお節を薄く削る動作は彫るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51871, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は、ナイフで石に名前が彫るときは手を切らないように言いました。", "corrected_sentence": "先生は、ナイフで石に名前を彫るときは手を切らないように言いました。", "error_description": "「彫る」の対象は「名前」なので目的語を示す「を」が正しい。「が」では名前が主語になり、「名前が彫る」は不自然。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "彫って", "is_correct": true, "explanation": "テ形。「〜て遊んでいます」と続き、彫る動作を表す。"}, {"text": "彫る", "is_correct": false, "explanation": "終止形。「彫る遊んでいます」とは続かず、ここでは合わない。"}, {"text": "彫れ", "is_correct": false, "explanation": "命令形。「〜て遊んでいます」と続かず、ここでは合わない。"}, {"text": "彫らない", "is_correct": false, "explanation": "否定形。「彫らない遊んでいます」とは続かず、ここでは合わない。"}], "correct_form": "彫って", "base_form": "彫る", "form_label": "テ形（〜て遊んでいます）", "sentence_index": 1, "explanations": {"彫って": "テ形。「〜て遊んでいます」と続き、彫る動作を表す。", "彫る": "終止形。「彫る遊んでいます」とは続かず、ここでは合わない。", "彫れ": "命令形。「〜て遊んでいます」と続かず、ここでは合わない。", "彫らない": "否定形。「彫らない遊んでいます」とは続かず、ここでは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51871, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は木のまな板の裏に、名前で彫りました。", "corrected_sentence": "彼は木のまな板の裏に、名前を彫りました。", "error_description": "「彫る」の対象は「名前」なので目的語の「を」が正しい。「で」は手段や場所を表すため、「名前で彫る」は意味が通らない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "彫って", "is_correct": true, "explanation": "テ形。「〜ておきました」と続き、前もって彫っておいたことを表す。"}, {"text": "彫ろう", "is_correct": false, "explanation": "意向形。「〜ておきました」には続かず、ここでは合わない。"}, {"text": "彫った", "is_correct": false, "explanation": "夕形。「彫ったておきました」とはならず、ここでは使えない。"}, {"text": "彫れる", "is_correct": false, "explanation": "可能形。「〜ておきました」の意味に合わず、ここでは使えない。"}], "correct_form": "彫って", "base_form": "彫る", "form_label": "テ形（〜ておきました）", "sentence_index": 7, "explanations": {"彫って": "テ形。「〜ておきました」と続き、前もって彫っておいたことを表す。", "彫ろう": "意向形。「〜ておきました」には続かず、ここでは合わない。", "彫った": "夕形。「彫ったておきました」とはならず、ここでは使えない。", "彫れる": "可能形。「〜ておきました」の意味に合わず、ここでは使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51872, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「模様を」は彫る動作の対象を示すので、ここに入る。"}, {"text": "が", "is_correct": false, "explanation": "「模様が丁寧に彫っています」は模様を主語にする形になり、彫る主体の職人と合わない。"}, {"text": "で", "is_correct": false, "explanation": "「模様で」では彫る対象が示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「模様へ」は方向を示すが、彫る対象を表すには合わない。"}], "correct_answer": "を", "explanations": {"を": "「模様を」は彫る動作の対象を示すので、ここに入る。", "が": "「模様が丁寧に彫っています」は模様を主語にする形になり、彫る主体の職人と合わない。", "で": "「模様で」では彫る対象が示せず、文が成り立たない。", "へ": "「模様へ」は方向を示すが、彫る対象を表すには合わない。"}, "error_tags": {"が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51872, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「名前を」は彫る動作の対象を示すので、ここに入る。"}, {"text": "と", "is_correct": false, "explanation": "「名前と深く彫って」は並列や相手を表し、彫る対象を示せない。"}, {"text": "より", "is_correct": false, "explanation": "「名前より深く」は比較になり、彫る対象を表さない。"}, {"text": "から", "is_correct": false, "explanation": "「名前から深く彫って」は起点を表し、彫る対象を示せない。"}], "correct_answer": "を", "explanations": {"を": "「名前を」は彫る動作の対象を示すので、ここに入る。", "と": "「名前と深く彫って」は並列や相手を表し、彫る対象を示せない。", "より": "「名前より深く」は比較になり、彫る対象を表さない。", "から": "「名前から深く彫って」は起点を表し、彫る対象を示せない。"}, "error_tags": {"と": "並列", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51872, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "刃物などで材料の表面を削り取って、文字や絵、模様を表すこと。", "primary_collocate": null, "pronunciation": "ほる", "ipa": "horɯ", "syllable_count": 2, "sentences": [{"text": "絵師の描いた下絵を彫師が版木に彫り、摺師が紙に印刷するという複雑な工程を経ます。", "target_word": "彫り", "complexity_tier": "T3", "furigana": "絵師[えし]の描[えが]いた下絵[したえ]を彫師[ほりし]が版木[はんぎ]に彫[ほ]り、摺師[すりし]が紙[かみ]に印刷[いんさつ]するという複雑[ふくざつ]な工程[こうてい]を経[へ]ます。", "sentence_source": "mined"}, {"text": "職人は木の板に、細かい模様を丁寧に彫っています。", "target_word": "彫っ", "complexity_tier": "T3", "furigana": "職人[しょくにん]は木[き]の板[いた]に、細[こま]かい模様[もよう]を丁寧[ていねい]に彫[ほ]っています。", "sentence_source": "generated"}, {"text": "祖父は退職後、仏像を彫る趣味を始めました。", "target_word": "彫る", "complexity_tier": "T3", "furigana": "祖父[そふ]は退職後[たいしょくご]、仏像[ぶつぞう]を彫[ほ]る趣味[しゅみ]を始[はじ]めました。", "sentence_source": "generated"}, {"text": "石に名前を彫ってもらって、記念碑が完成しました。", "target_word": "彫って", "complexity_tier": "T3", "furigana": "石[いし]に名前[なまえ]を彫[ほ]ってもらって、記念碑[きねんひ]が完成[かんせい]しました。", "sentence_source": "generated"}, {"text": "版木に文字を彫るときは、左右を逆にしなければなりません。", "target_word": "彫る", "complexity_tier": "T3", "furigana": "版木[はんぎ]に文字[もじ]を彫[ほ]るときは、左右[さゆう]を逆[ぎゃく]にしなければなりません。", "sentence_source": "generated"}, {"text": "彼は指輪の内側に、二人の名前を彫った。", "target_word": "彫った", "complexity_tier": "T3", "furigana": "彼[かれ]は指輪[ゆびわ]の内側[うちがわ]に、二人[ふたり]の名前[なまえ]を彫[ほ]った。", "sentence_source": "generated"}, {"text": "彫刻家は大きな木の幹から、鳥の姿を彫りました。", "target_word": "彫り", "complexity_tier": "T3", "furigana": "彫刻家[ちょうこくか]は大[おお]きな木[き]の幹[みき]から、鳥[とり]の姿[すがた]を彫[ほ]りました。", "sentence_source": "generated"}, {"text": "この印鑑は、名前を深く彫ってあるので長く使えます。", "target_word": "彫って", "complexity_tier": "T3", "furigana": "この印鑑[いんかん]は、名前[なまえ]を深[ふか]く彫[ほ]ってあるので長[なが]く使[つか]えます。", "sentence_source": "generated"}, {"text": "彫刻刀がよく切れるので、細い線も彫れます。", "target_word": "彫れ", "complexity_tier": "T3", "furigana": "彫刻刀[ちょうこくとう]がよく切[き]れるので、細[ほそ]い線[せん]も彫[ほ]れます。", "sentence_source": "generated"}, {"text": "弟は夏休みに、木のスプーンに花の絵を彫りました。", "target_word": "彫り", "complexity_tier": "T3", "furigana": "弟[おとうと]は夏休[なつやす]みに、木[き]のスプーンに花[はな]の絵[え]を彫[ほ]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "彫る", "label": "終止形"}, {"form": "彫り", "label": "連用形"}, {"form": "彫った", "label": "夕形"}, {"form": "彫って", "label": "テ形"}, {"form": "彫らない", "label": "否定形"}, {"form": "彫れる", "label": "可能形"}], "register": "標準", "sense_fingerprint": "刃物で材料を削って文字や模様を作る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb8eaf-a2e4-432a-a0a2-3afa20c9c998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51872, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彫り", "is_correct": true, "explanation": "版木に刃物で彫る動作を連用形（中止形）でつないでおり、ここに入る。"}, {"text": "織り", "is_correct": false, "explanation": "織るは糸を組んで布を作る動作。版木の工程には合わない。"}, {"text": "煮", "is_correct": false, "explanation": "煮るは食材を熱で調理する動作。版木の工程には合わない。"}, {"text": "焼き", "is_correct": false, "explanation": "焼くは熱を加える動作で、版木に彫る工程とは合わない。"}], "explanations": {"彫り": "版木に刃物で彫る動作を連用形（中止形）でつないでおり、ここに入る。", "織り": "織るは糸を組んで布を作る動作。版木の工程には合わない。", "煮": "煮るは食材を熱で調理する動作。版木の工程には合わない。", "焼き": "焼くは熱を加える動作で、版木に彫る工程とは合わない。"}, "sentence_index": 0, "correct_answer": "彫り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭に大きな穴を彫って、池にした。", "explanation": "ここは〈掘る〉（地面に穴をあける）の意味。彫るは表面に文字や模様を作る動作で、穴をあける作業には合わない。"}, {"text": "ネギを細かく彫って、味噌汁に入れた。", "explanation": "ここは〈刻む〉（細かく切る）の意味。彫るは材料の表面を削って文字や模様を作る動作で、食材を切ることには使わない。"}, {"text": "鉛筆を彫って、先を細くした。", "explanation": "ここは〈削る〉（表面を薄く取る）の意味。鉛筆の先を削る動作は彫るとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51872, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "彫り", "is_correct": true, "explanation": "「彫りました」の連用形で、木を刃物で彫る動作を表す。ここに入る。"}, {"text": "漬け", "is_correct": false, "explanation": "漬けるは材料を液体に浸す動作。鳥の姿を作る工程には合わない。"}, {"text": "蒸し", "is_correct": false, "explanation": "蒸すは蒸気で加熱する動作で、彫る動作の意味とは違う。"}, {"text": "搾り", "is_correct": false, "explanation": "搾るは押して液体を出す動作で、鳥の姿を作る動作とは合わない。"}], "explanations": {"彫り": "「彫りました」の連用形で、木を刃物で彫る動作を表す。ここに入る。", "漬け": "漬けるは材料を液体に浸す動作。鳥の姿を作る工程には合わない。", "蒸し": "蒸すは蒸気で加熱する動作で、彫る動作の意味とは違う。", "搾り": "搾るは押して液体を出す動作で、鳥の姿を作る動作とは合わない。"}, "sentence_index": 6, "correct_answer": "彫り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "キャンバスに絵の具で花を彫った。", "explanation": "ここは〈描く〉（絵の具などで絵をかく）の意味。彫るは刃物で材料を削る動作なので、絵の具を使う作業には合わない。"}, {"text": "祖母は布に花の模様を彫った。", "explanation": "ここは〈縫う〉（糸で布を縫い合わせる）の意味。彫るは刃物で材料を削る動作なので、糸を使う作業には合わない。"}, {"text": "野菜を彫って、夕食にした。", "explanation": "ここは〈炒める〉（油で火を通す）の意味。彫るは材料の表面を削る動作で、野菜を調理するときには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51872, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その職人は木の板に、小さな花の模様を丁寧に彫られています。", "corrected_sentence": "その職人は木の板に、小さな花の模様を丁寧に彫っています。", "error_description": "動作主の「職人」が主語なので能動形「彫っています」が正しい。「彫られています」は受身で、彫られる対象が主語になる形なので、この文では合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "彫って", "is_correct": true, "explanation": "テ形で、「彫っています」の形で動作が進行中であることを表す。"}, {"text": "彫る", "is_correct": false, "explanation": "終止形。「彫る」だけでは「彫っています」の形にならず、テ形が必要。"}, {"text": "彫れ", "is_correct": false, "explanation": "命令形。「〜ています」に続く形ではなく、ここでは合わない。"}, {"text": "彫った", "is_correct": false, "explanation": "夕形。「彫ったています」とはならず、ここでは使えない。"}], "correct_form": "彫って", "base_form": "彫る", "form_label": "テ形（〜ています）", "sentence_index": 1, "explanations": {"彫って": "テ形で、「彫っています」の形で動作が進行中であることを表す。", "彫る": "終止形。「彫る」だけでは「彫っています」の形にならず、テ形が必要。", "彫れ": "命令形。「〜ています」に続く形ではなく、ここでは合わない。", "彫った": "夕形。「彫ったています」とはならず、ここでは使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51872, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この箱のふたには、小さな鳥の模様が彫れてあります。", "corrected_sentence": "この箱のふたには、小さな鳥の模様が彫ってあります。", "error_description": "模様が彫られている状態は「彫ってあります」（〜てある）。「彫れてあります」は可能形を使うことになり、「彫ることができる」の意味になって状態を表せない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "彫って", "is_correct": true, "explanation": "テ形。「〜てあります」と続き、彫られた状態を表す。"}, {"text": "彫らず", "is_correct": false, "explanation": "否定の連用形（〜ず）。「〜てある」の形にはならず、ここでは合わない。"}, {"text": "彫れる", "is_correct": false, "explanation": "可能形。「彫れてあります」は「彫ることができる」の意味になり、彫られた状態を表さない。"}, {"text": "彫ろう", "is_correct": false, "explanation": "意向形。「〜てある」には続かず、ここでは合わない。"}], "correct_form": "彫って", "base_form": "彫る", "form_label": "テ形（〜てあります）", "sentence_index": 7, "explanations": {"彫って": "テ形。「〜てあります」と続き、彫られた状態を表す。", "彫らず": "否定の連用形（〜ず）。「〜てある」の形にはならず、ここでは合わない。", "彫れる": "可能形。「彫れてあります」は「彫ることができる」の意味になり、彫られた状態を表さない。", "彫ろう": "意向形。「〜てある」には続かず、ここでは合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51873, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「下絵がうまくかける」の形で、かける主語を示す。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を示す。うまくかけることの主語にはならない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を示す。うまくかける主語を示す形としては合わない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。うまくかける主語を示す形としては合わない。"}], "correct_answer": "が", "explanations": {"が": "「下絵がうまくかける」の形で、かける主語を示す。", "と": "共同や引用を示す。うまくかけることの主語にはならない。", "の": "所属や修飾を示す。うまくかける主語を示す形としては合わない。", "で": "手段や場所を示す。うまくかける主語を示す形としては合わない。"}, "error_tags": {"と": "共同・引用", "の": "連体修飾", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51873, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「この下絵に色をぬる」の形で、色をぬる場所や対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「この下絵が」は主語になり、命令文「ぬってください」の対象と合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。色をぬる場所を導けない。"}, {"text": "を", "is_correct": false, "explanation": "「下絵を、色を」と「を」が二つ並び、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「この下絵に色をぬる」の形で、色をぬる場所や対象を示す。", "が": "「この下絵が」は主語になり、命令文「ぬってください」の対象と合わない。", "より": "比較を示す。色をぬる場所を導けない。", "を": "「下絵を、色を」と「を」が二つ並び、文が成り立たない。"}, "error_tags": {"が": "主語", "より": "比較", "を": "二重の「を」"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51873, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "絵をかく前に、かんたんに下書きをした絵のことです。", "primary_collocate": null, "pronunciation": "したえ", "ipa": "ɕitae", "syllable_count": 3, "sentences": [{"text": "絵をかく前に、えんぴつで下絵をかきました。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "絵(え)をかく前(まえ)に、えんぴつで下絵(したえ)をかきました。", "sentence_source": "generated"}, {"text": "弟は下絵がうまくかけて、うれしそうでした。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "弟(おとうと)は下絵(したえ)がうまくかけて、うれしそうでした。", "sentence_source": "generated"}, {"text": "下絵を消しゴムで消してから、色をぬりました。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "下絵(したえ)を消(け)しゴムで消(け)してから、色(いろ)をぬりました。", "sentence_source": "generated"}, {"text": "先生に下絵を見せたら、「いい形だね」と言われました。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "先生(せんせい)に下絵(したえ)を見(み)せたら、「いい形(かたち)だね」と言(い)われました。", "sentence_source": "generated"}, {"text": "ポスターを作るときは、まず紙に下絵をかきます。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "ポスターを作(つく)るときは、まず紙(かみ)に下絵(したえ)をかきます。", "sentence_source": "generated"}, {"text": "下絵がへただったので、もう一度かき直しました。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "下絵(したえ)がへただったので、もう一度(いちど)かき直(なお)しました。", "sentence_source": "generated"}, {"text": "姉は下絵をかかずに、いきなり絵の具をぬり始めました。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "姉(あね)は下絵(したえ)をかかずに、いきなり絵(え)の具(ぐ)をぬり始(はじ)めました。", "sentence_source": "generated"}, {"text": "この下絵に、好きな色をぬってください。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "この下絵(したえ)に、好(す)きな色(いろ)をぬってください。", "sentence_source": "generated"}, {"text": "下絵の線をうすくかくと、あとできれいに見えます。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "下絵(したえ)の線(せん)をうすくかくと、あとできれいに見(み)えます。", "sentence_source": "generated"}, {"text": "下絵ができたら、次は色をえらびましょう。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "下絵(したえ)ができたら、次(つぎ)は色(いろ)をえらびましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下絵", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "絵をかく前にかんたんに下書きした絵(学校・日常の場面)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb8eaf-a2e4-432a-a0a2-3afa20c9c998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51873, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下絵", "is_correct": true, "explanation": "えんぴつで絵をかく前にかくものとして自然。かんたんな下書きを指す。"}, {"text": "消しゴム", "is_correct": false, "explanation": "消すための道具。えんぴつでかく対象にはならない。"}, {"text": "絵の具", "is_correct": false, "explanation": "色をつけるための絵の材料。えんぴつでかくものとしては合わない。"}, {"text": "色紙", "is_correct": false, "explanation": "色のついた紙。えんぴつでかくものとしては不自然。"}], "explanations": {"下絵": "えんぴつで絵をかく前にかくものとして自然。かんたんな下書きを指す。", "消しゴム": "消すための道具。えんぴつでかく対象にはならない。", "絵の具": "色をつけるための絵の材料。えんぴつでかくものとしては合わない。", "色紙": "色のついた紙。えんぴつでかくものとしては不自然。"}, "sentence_index": 0, "correct_answer": "下絵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "先生は生徒の作文の下絵に赤いペンで直しを入れた。", "explanation": "ここは〈下書き（文章）〉の意味。下絵は絵の下描きで、作文の下書きには使わない。"}, {"text": "ピアニストは、下絵の楽譜を見ながら曲を練習した。", "explanation": "ここは〈楽譜〉の意味。下絵は絵の下描きで、音符で書かれた楽譜の意味では使わない。"}, {"text": "旅行の下絵として、地図を広げて道順を決めた。", "explanation": "ここは〈地図〉の意味。下絵は絵の下描きで、道順を示す地図の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51873, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下絵", "is_correct": true, "explanation": "いきなり絵の具をぬる前にかくものとして自然。かんたんな下書きを指す。"}, {"text": "筆", "is_correct": false, "explanation": "絵の具をぬるための道具。かくものとしては合わない。"}, {"text": "糸", "is_correct": false, "explanation": "布などを縫う材料。絵をかく対象にはならない。"}, {"text": "帯", "is_correct": false, "explanation": "着物に締める布。絵をかくものとしては不自然。"}], "explanations": {"下絵": "いきなり絵の具をぬる前にかくものとして自然。かんたんな下書きを指す。", "筆": "絵の具をぬるための道具。かくものとしては合わない。", "糸": "布などを縫う材料。絵をかく対象にはならない。", "帯": "着物に締める布。絵をかくものとしては不自然。"}, "sentence_index": 6, "correct_answer": "下絵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社は、この下絵の見積書を客に出した。", "explanation": "ここは〈見積書〉の意味。下絵は絵の下描きで、金額を示す見積書の意味では使わない。"}, {"text": "新作の色見本として、下絵を店頭に並べた。", "explanation": "ここは〈色見本〉の意味。下絵は色を選ぶための見本ではない。"}, {"text": "昆虫の下絵を標本箱に並べて、保存した。", "explanation": "ここは〈標本〉の意味。下絵は絵の下描きで、昆虫を保存する標本の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51873, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先に下絵で描いてから、色をぬりましょう。", "corrected_sentence": "先に下絵を描いてから、色をぬりましょう。", "error_description": "描く対象を示すには「を」を使う。「で」は誤りで、正しくは「を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51873, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下絵を読んでから、色をぬりました。", "corrected_sentence": "下絵をかいてから、色をぬりました。", "error_description": "下絵とつながる動詞は「かく」。「読む」は誤りで、絵をかく工程を表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51874, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「下絵を描く」の形で、描く対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "場所や対象を示す。描く対象を示す形としては不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同や引用を示す。描く対象を導く形としては合わない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「紙に下絵が描き」では下絵が描く主体になり、文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「下絵を描く」の形で、描く対象を示す。", "に": "場所や対象を示す。描く対象を示す形としては不自然。", "と": "共同や引用を示す。描く対象を導く形としては合わない。", "が": "主語を示す。「紙に下絵が描き」では下絵が描く主体になり、文が成り立たない。"}, "error_tags": {"に": "場所・対象", "と": "共同・引用", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51874, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「下絵を何枚も描き直す」の形で、描き直す対象を示す。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。描き直す対象を示す形としては合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。描き直す対象を導けない。"}, {"text": "の", "is_correct": false, "explanation": "所属や修飾を示す。描き直す対象を示す形としては合わない。"}], "correct_answer": "を", "explanations": {"を": "「下絵を何枚も描き直す」の形で、描き直す対象を示す。", "へ": "方向を示す。描き直す対象を示す形としては合わない。", "より": "比較を示す。描き直す対象を導けない。", "の": "所属や修飾を示す。描き直す対象を示す形としては合わない。"}, "error_tags": {"へ": "方向", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51874, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "絵画やイラストなどの完成作品の元となる、下書きの段階の絵。", "primary_collocate": null, "pronunciation": "したえ", "ipa": "ɕitae", "syllable_count": 3, "sentences": [{"text": "絵師の描いた下絵を彫師が版木に彫り、摺師が紙に印刷するという複雑な工程を経ます。", "target_word": "下絵", "complexity_tier": "T4", "furigana": "絵師(えし)の描(か)いた下絵(したえ)を彫師(ほりし)が版木(はんぎ)に彫(ほ)り、摺師(すりし)が紙(かみ)に印刷(いんさつ)するという複雑(ふくざつ)な工程(こうてい)を経(へ)ます。", "sentence_source": "mined"}, {"text": "画家はまず紙に下絵を描き、そのあとで色をのせていきました。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "画家(がか)はまず紙(かみ)に下絵(したえ)を描(か)き、そのあとで色(いろ)をのせていきました。", "sentence_source": "generated"}, {"text": "下絵がうまくできたので、安心して絵の具を使い始めました。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "下絵(したえ)がうまくできたので、安心(あんしん)して絵(え)の具(ぐ)を使(つか)い始(はじ)めました。", "sentence_source": "generated"}, {"text": "先生は私の下絵を見て、人物の位置を少し直すように言いました。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "先生(せんせい)は私(わたし)の下絵(したえ)を見(み)て、人物(じんぶつ)の位置(いち)を少(すこ)し直(なお)すように言(い)いました。", "sentence_source": "generated"}, {"text": "壁画を描く前に、小さな紙に下絵を作って全体の形を確かめます。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "壁画(へきが)を描(えが)く前(まえ)に、小(ちい)さな紙(かみ)に下絵(したえ)を作(つく)って全体(ぜんたい)の形(かたち)を確(たし)かめます。", "sentence_source": "generated"}, {"text": "下絵の線が濃すぎて、完成した絵にも黒く残ってしまいました。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "下絵(したえ)の線(せん)が濃(こ)すぎて、完成(かんせい)した絵(え)にも黒(くろ)く残(のこ)ってしまいました。", "sentence_source": "generated"}, {"text": "着物の模様は、まず下絵を描いてから布を染めます。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "着物(きもの)の模様(もよう)は、まず下絵(したえ)を描(か)いてから布(ぬの)を染(そ)めます。", "sentence_source": "generated"}, {"text": "彼女は下絵を何枚も描き直して、ようやく構図を決めました。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は下絵(したえ)を何枚(なんまい)も描(か)き直(なお)して、ようやく構図(こうず)を決(き)めました。", "sentence_source": "generated"}, {"text": "展覧会では、有名な画家の下絵も見ることができます。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "展覧会(てんらんかい)では、有名(ゆうめい)な画家(がか)の下絵(したえ)も見(み)ることができます。", "sentence_source": "generated"}, {"text": "下絵に色をつけただけで、まだ完成ではありません。", "target_word": "下絵", "complexity_tier": "T3", "furigana": "下絵(したえ)に色(いろ)をつけただけで、まだ完成(かんせい)ではありません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下絵", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "完成作品の元になる下書き段階の絵(美術・版画・染織の制作工程)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb8eaf-a2e4-432a-a0a2-3afa20c9c998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51874, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下絵", "is_correct": true, "explanation": "絵師が描いたものを彫師が版木に彫る流れに合う。完成前の下描きを指す語。"}, {"text": "墨", "is_correct": false, "explanation": "書画に使う黒い塊。描いたものを彫るという流れに合わない。"}, {"text": "硯", "is_correct": false, "explanation": "墨をする道具。描いたものとして彫る対象にはならない。"}, {"text": "色紙", "is_correct": false, "explanation": "装飾用の小さな紙。描いたものを版木に彫る文脈に合わない。"}], "explanations": {"下絵": "絵師が描いたものを彫師が版木に彫る流れに合う。完成前の下描きを指す語。", "墨": "書画に使う黒い塊。描いたものを彫るという流れに合わない。", "硯": "墨をする道具。描いたものとして彫る対象にはならない。", "色紙": "装飾用の小さな紙。描いたものを版木に彫る文脈に合わない。"}, "sentence_index": 0, "correct_answer": "下絵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "手紙を清書する前に、下絵を一通書いた。", "explanation": "ここは〈下書き（文章）〉の意味。下絵は絵の下描きで、手紙の下書きには使わない。"}, {"text": "博物館は、昆虫の下絵を標本として並べた。", "explanation": "ここは〈標本〉の意味。下絵は絵の下描きで、昆虫を保存する標本の意味では使わない。"}, {"text": "作曲家は、曲の下絵を楽譜として三日かけて書いた。", "explanation": "ここは〈楽譜〉の意味。下絵は絵の下描きで、音符で書いた楽譜の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (51874, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下絵", "is_correct": true, "explanation": "まず描いてから布を染める流れに合う。染める前の下描きを指す語。"}, {"text": "糸", "is_correct": false, "explanation": "布を織る材料。まず描いてから染める流れには合わない。"}, {"text": "帯", "is_correct": false, "explanation": "着物に締める布。描いてから布を染める工程の対象にはならない。"}, {"text": "釘", "is_correct": false, "explanation": "金属の留め具。模様を描くという工程に合わない。"}], "explanations": {"下絵": "まず描いてから布を染める流れに合う。染める前の下描きを指す語。", "糸": "布を織る材料。まず描いてから染める流れには合わない。", "帯": "着物に締める布。描いてから布を染める工程の対象にはならない。", "釘": "金属の留め具。模様を描くという工程に合わない。"}, "sentence_index": 6, "correct_answer": "下絵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作詞家は、この下絵の歌詞を三回書き直した。", "explanation": "ここは〈歌詞〉の意味。下絵は絵の下描きで、言葉で書いた歌詞の意味では使わない。"}, {"text": "新作の色見本として、下絵を店頭に並べた。", "explanation": "ここは〈色見本〉の意味。下絵は色を選ぶための見本ではない。"}, {"text": "政府は新しい法律の下絵を国会に提出した。", "explanation": "ここは〈草案〉の意味。下絵は絵の下描きで、法律の文案には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
